        private static void PositionCloseReviewCamera(Camera camera, Vector3 anchor, Vector3 offset, Vector3 lookOffset)
        {
            var position = anchor + offset;
            var lookAt = anchor + lookOffset;
            camera.transform.SetPositionAndRotation(position, Quaternion.LookRotation(lookAt - position, Vector3.up));
        }

        private static void ValidateCloseReviewOutputExists(string outputDirectory, string fileName)
        {
            var outputPath = Path.Combine(outputDirectory, fileName);
            if (!File.Exists(outputPath))
            {
                throw new InvalidOperationException($"Fast VS close-review screenshot capture failed: missing output file {outputPath}");
            }

            ValidateScreenshotOpaqueAlpha(outputPath);
        }

        private static void ValidateScreenshotOutputExists(string outputDirectory, string fileName)
        {
            var outputPath = Path.Combine(outputDirectory, fileName);
            if (!File.Exists(outputPath))
            {
                throw new InvalidOperationException($"Fast VS screenshot capture failed: missing output file {outputPath}");
            }

            ValidateScreenshotOpaqueAlpha(outputPath);
        }

        private static void PositionReviewCamera(Camera camera, Vector3 anchor)
        {
            var position = anchor + new Vector3(0f, 2.75f, -4.55f);
            var lookAt = anchor + new Vector3(0f, 0.72f, 0.45f);
            camera.transform.SetPositionAndRotation(position, Quaternion.LookRotation(lookAt - position, Vector3.up));
        }

        private static void PositionChapter1AllMapsCamera(Camera camera, Vector3 anchor)
        {
            var position = anchor + new Vector3(0f, 13.80f, -18.20f);
            var lookAt = anchor + new Vector3(0f, 0.20f, 1.55f);
            camera.transform.SetPositionAndRotation(position, Quaternion.LookRotation(lookAt - position, Vector3.up));
        }

        private static void PositionChapter1AllMapsCamera(Camera camera, Vector3 anchor, Vector3 positionOffset, Vector3 lookAtOffset)
        {
            var position = anchor + positionOffset;
            var lookAt = anchor + lookAtOffset;
            camera.transform.SetPositionAndRotation(position, Quaternion.LookRotation(lookAt - position, Vector3.up));
        }

        private static void PositionChapter1EndSideViewCamera(Camera camera, Vector3 anchor)
        {
            camera.orthographic = true;
            camera.orthographicSize = Chapter1EndSideViewOrthographicSize;
            camera.transform.SetPositionAndRotation(anchor + new Vector3(0f, 0f, -13.0f), Quaternion.LookRotation(Vector3.forward, Vector3.up));
        }

        private static void SaveCameraPng(Camera camera, string outputPath)
        {
            EnsureCoreBlitD3d11CaptureWorkaround();
            var previousTarget = camera.targetTexture;
            var previousActive = RenderTexture.active;
            var renderTexture = new RenderTexture(1280, 720, 24, RenderTextureFormat.ARGB32);
            var texture = new Texture2D(1280, 720, TextureFormat.RGBA32, false);
            try
            {
                camera.targetTexture = renderTexture;
                RenderTexture.active = renderTexture;
                Canvas.ForceUpdateCanvases();
                camera.Render();
                texture.ReadPixels(new Rect(0f, 0f, renderTexture.width, renderTexture.height), 0, 0);
                texture.Apply(false, false);
                ForceOpaqueAlpha(texture);
                File.WriteAllBytes(outputPath, texture.EncodeToPNG());
            }
            finally
            {
                camera.targetTexture = previousTarget;
                RenderTexture.active = previousActive;
                renderTexture.Release();
                UnityEngine.Object.DestroyImmediate(renderTexture);
                UnityEngine.Object.DestroyImmediate(texture);
            }
        }

        private static void ForceOpaqueAlpha(Texture2D texture)
        {
            var pixels = texture.GetPixels32();
            for (var i = 0; i < pixels.Length; i++)
            {
                pixels[i].a = 255;
            }

            texture.SetPixels32(pixels);
            texture.Apply(false, false);
        }

        private static void ValidateScreenshotOpaqueAlpha(string outputPath)
        {
            if (!string.Equals(Path.GetExtension(outputPath), ".png", StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            var texture = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            try
            {
                if (!ImageConversion.LoadImage(texture, File.ReadAllBytes(outputPath)))
                {
                    throw new InvalidOperationException($"Fast VS screenshot capture failed: could not decode output file {outputPath}");
                }

                var pixels = texture.GetPixels32();
                for (var i = 0; i < pixels.Length; i++)
                {
                    if (pixels[i].a != 255)
                    {
                        throw new InvalidOperationException($"Fast VS screenshot capture failed: output file {outputPath} has transparent alpha at pixel {i}.");
                    }
                }
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(texture);
            }
        }

        private static void WarmUpCameraRender(Camera camera)
        {
            EnsureCoreBlitD3d11CaptureWorkaround();
            var previousTarget = camera.targetTexture;
            var previousActive = RenderTexture.active;
            var renderTexture = RenderTexture.GetTemporary(64, 36, 16, RenderTextureFormat.ARGB32);
            try
            {
                camera.targetTexture = renderTexture;
                RenderTexture.active = renderTexture;
                Canvas.ForceUpdateCanvases();
                camera.Render();
            }
            finally
            {
                camera.targetTexture = previousTarget;
                RenderTexture.active = previousActive;
                RenderTexture.ReleaseTemporary(renderTexture);
            }
        }

        private static void EnsureCoreBlitD3d11CaptureWorkaround()
        {
            if (coreBlitD3d11CaptureWorkaroundChecked)
            {
                return;
            }

            coreBlitD3d11CaptureWorkaroundChecked = true;
            var packageCacheDirectory = Path.Combine("Library", "PackageCache");
            if (!Directory.Exists(packageCacheDirectory))
            {
                return;
            }

            foreach (var corePackageDirectory in Directory.GetDirectories(packageCacheDirectory, "com.unity.render-pipelines.core@*"))
            {
                var commonPath = Path.Combine(corePackageDirectory, "ShaderLibrary", "Common.hlsl");
                if (!File.Exists(commonPath))
                {
                    continue;
                }

                var lines = File.ReadAllLines(commonPath);
                var changed = false;
                for (var i = 0; i < lines.Length; i++)
                {
                    var trimmedLine = lines[i].TrimStart();
                    if (string.Equals(trimmedLine, "TEMPLATE_2_HALF(SafePositivePow, base, power, return pow(max(abs(base), min16float(HALF_EPS)), power))", StringComparison.Ordinal))
                    {
                        var indentation = lines[i].Substring(0, lines[i].Length - trimmedLine.Length);
                        lines[i] = indentation + "// TEMPLATE_2_HALF(SafePositivePow, base, power, return pow(max(abs(base), min16float(HALF_EPS)), power))";
                        Array.Resize(ref lines, lines.Length + 1);
                        Array.Copy(lines, i, lines, i + 1, lines.Length - i - 1);
                        lines[i] = indentation + "// Local batch-capture workaround: Unity 6000.3.14f1/URP can fail to compile this min16float overload while compiling CoreBlit debug passes.";
                        changed = true;
                        i++;
                        continue;
                    }

                    if (string.Equals(trimmedLine, "TEMPLATE_2_HALF(SafePositivePow_half, base, power, return pow(max(abs(base), min16float(HALF_EPS)), power))", StringComparison.Ordinal))
                    {
                        var indentation = lines[i].Substring(0, lines[i].Length - trimmedLine.Length);
                        lines[i] = indentation + "// TEMPLATE_2_HALF(SafePositivePow_half, base, power, return pow(max(abs(base), min16float(HALF_EPS)), power))";
                        changed = true;
                    }
                }

                if (changed)
                {
                    File.WriteAllLines(commonPath, lines);
                    AssetDatabase.Refresh(ImportAssetOptions.ForceUpdate);
                    Debug.LogWarning($"Applied local URP CoreBlit D3D11 capture workaround: {commonPath}");
                }

                return;
            }
        }

