            CreateLandmarkCube($"{prefix}_{objectToken}_PixelFloor", root, c, new Vector3(6.40f, 0.12f, 5.42f), Quaternion.identity, floor, true, TimeWindowPairedSpaceLandmarkKind.PathOrFloor, $"{prefix}.{landmarkToken}.floor");
