        private static void HideChildIfPresent(Transform root, string childName)
        {
            var child = root.Find(childName);
            if (child != null)
            {
                child.gameObject.SetActive(false);
            }
        }

        private static void HideSceneObjectsIfPresent(string objectName)
        {
            foreach (var candidate in Resources.FindObjectsOfTypeAll<GameObject>())
            {
                if (candidate.name == objectName && candidate.scene.IsValid())
                {
                    candidate.SetActive(false);
                }
            }
        }

        private static void HideFarmNutTreeCanopyAndNuts(Transform root, string treeName)
        {
            HideChildIfPresent(root, $"{treeName}_Crown");
            HideChildIfPresent(root, $"{treeName}_NutA");
            HideChildIfPresent(root, $"{treeName}_NutB");
            HideChildIfPresent(root, $"{treeName}_NutC");
        }

        private static void HideFarmNutTree(Transform root, string treeName)
        {
            HideChildIfPresent(root, $"{treeName}_Trunk");
            HideFarmNutTreeCanopyAndNuts(root, treeName);
        }

