        private static GameObject CreateAuthoredVegetationMesh(string objectName, Transform root, Vector3 localPosition, Vector3 localScale, Quaternion localRotation, Material material, TimeWindowPairedSpaceLandmarkKind kind, string landmarkId, Mesh mesh)
        {
            var sceneObject = new GameObject(objectName);
            sceneObject.transform.SetParent(root, false);
            sceneObject.transform.localPosition = localPosition;
            sceneObject.transform.localRotation = localRotation;
            sceneObject.transform.localScale = localScale;

            var filter = sceneObject.AddComponent<MeshFilter>();
            filter.sharedMesh = mesh;
            var renderer = sceneObject.AddComponent<MeshRenderer>();
            renderer.sharedMaterial = material;
            renderer.shadowCastingMode = ShadowCastingMode.On;
            renderer.receiveShadows = false;

            var landmark = sceneObject.AddComponent<TimeWindowPairedSpaceLandmark>();
            SerializedSet(landmark, "landmarkId", landmarkId);
            SerializedSet(landmark, "kind", kind);
            SerializedSet(landmark, "countsForArrival", true);
            return sceneObject;
        }

        private static Mesh CreateAuthoredVegetationTrunkMesh(string meshName, string seedKey)
        {
            const int sideCount = 7;
            const int ringCount = 3;
            var bottomRadius = 0.42f + AuthoredVegetationSigned(seedKey, 21, 0.035f);
            var midRadius = 0.32f + AuthoredVegetationSigned(seedKey, 22, 0.030f);
            var topRadius = 0.25f + AuthoredVegetationSigned(seedKey, 23, 0.025f);
            var midBendX = AuthoredVegetationSigned(seedKey, 25, 0.028f);
            var midBendZ = AuthoredVegetationSigned(seedKey, 27, 0.028f);
            var bendX = AuthoredVegetationSigned(seedKey, 29, 0.035f);
            var bendZ = AuthoredVegetationSigned(seedKey, 31, 0.035f);
            var vertices = new Vector3[sideCount * ringCount + 2];
            var uvs = new Vector2[vertices.Length];

            for (var ring = 0; ring < ringCount; ring++)
            {
                var t = ring / (float)(ringCount - 1);
                var radius = ring == 0 ? bottomRadius : (ring == 1 ? midRadius : topRadius);
                var y = Mathf.Lerp(-0.50f, 0.50f, t);
                var centerX = ring == 0 ? 0f : (ring == 1 ? midBendX : bendX);
                var centerZ = ring == 0 ? 0f : (ring == 1 ? midBendZ : bendZ);
                for (var i = 0; i < sideCount; i++)
                {
                    var angle = (i / (float)sideCount) * Mathf.PI * 2f + AuthoredVegetationSigned(seedKey, 33 + ring, 0.035f);
                    var facetPulse = 0.92f + AuthoredVegetationHash01(seedKey, 41 + ring * 17 + i) * 0.18f;
                    var index = ring * sideCount + i;
                    vertices[index] = new Vector3(Mathf.Cos(angle) * radius * facetPulse + centerX, y, Mathf.Sin(angle) * radius * facetPulse + centerZ);
                    uvs[index] = new Vector2(i / (float)sideCount, t);
                }
            }

            var bottomCenter = sideCount * ringCount;
            var topCenter = bottomCenter + 1;
            vertices[bottomCenter] = new Vector3(0f, -0.50f, 0f);
            vertices[topCenter] = new Vector3(bendX, 0.50f, bendZ);
            uvs[bottomCenter] = new Vector2(0.5f, 0f);
            uvs[topCenter] = new Vector2(0.5f, 1f);

            var triangles = new List<int>(sideCount * 18);
            for (var ring = 0; ring < ringCount - 1; ring++)
            {
                var currentOffset = ring * sideCount;
                var nextOffset = (ring + 1) * sideCount;
                for (var i = 0; i < sideCount; i++)
                {
                    var next = (i + 1) % sideCount;
                    var a = currentOffset + i;
                    var b = currentOffset + next;
                    var c = nextOffset + i;
                    var d = nextOffset + next;
                    triangles.Add(a);
                    triangles.Add(b);
                    triangles.Add(c);
                    triangles.Add(c);
                    triangles.Add(b);
                    triangles.Add(d);
                }
            }

            var topOffset = (ringCount - 1) * sideCount;
            for (var i = 0; i < sideCount; i++)
            {
                var next = (i + 1) % sideCount;
                triangles.Add(bottomCenter);
                triangles.Add(i);
                triangles.Add(next);
                triangles.Add(topCenter);
                triangles.Add(topOffset + next);
                triangles.Add(topOffset + i);
            }

            return CreateAuthoredVegetationMeshAsset(meshName, vertices, uvs, triangles);
        }

        private static Mesh CreateAuthoredVegetationCanopyMesh(string meshName, string seedKey, float upperRadius, float lowerRadius)
        {
            const int sideCount = 16;
            const int ringCount = 6;
            var vertices = new Vector3[sideCount * ringCount + 2];
            var uvs = new Vector2[vertices.Length];
            var topIndex = sideCount * ringCount;
            var bottomIndex = topIndex + 1;

            for (var ring = 0; ring < ringCount; ring++)
            {
                var t = ring / (float)(ringCount - 1);
                var y = Mathf.Lerp(-0.46f, 0.46f, t) + AuthoredVegetationSigned(seedKey, 53 + ring, 0.026f);
                var baseRadius = ring == 0
                    ? lowerRadius * 0.64f
                    : (ring == 1
                        ? lowerRadius * 1.26f
                        : (ring == 2
                            ? Mathf.Lerp(lowerRadius, upperRadius, 0.48f) * 1.20f
                            : (ring == 3
                                ? upperRadius * 1.02f
                                : (ring == 4 ? upperRadius * 0.72f : upperRadius * 0.34f))));
                var angleOffset = AuthoredVegetationSigned(seedKey, 61 + ring, 0.14f);
                for (var i = 0; i < sideCount; i++)
                {
                    var angle = (i / (float)sideCount) * Mathf.PI * 2f + angleOffset;
                    var lobe = Mathf.Sin(angle * 3f + AuthoredVegetationSigned(seedKey, 67 + ring, 0.35f)) * 0.070f;
                    var fineLobe = Mathf.Sin(angle * 7f + AuthoredVegetationSigned(seedKey, 73 + ring, 0.45f)) * 0.026f;
                    var jitter = 0.80f + AuthoredVegetationHash01(seedKey, 71 + ring * 23 + i) * 0.34f + lobe + fineLobe;
                    var skirtSag = ring <= 1 ? AuthoredVegetationHash01(seedKey, 117 + ring * 29 + i) * 0.070f : 0f;
                    var centerDrift = new Vector2(
                        AuthoredVegetationSigned(seedKey, 101 + ring, 0.048f) * t,
                        AuthoredVegetationSigned(seedKey, 107 + ring, 0.048f) * t);
                    var index = ring * sideCount + i;
                    vertices[index] = new Vector3(
                        Mathf.Cos(angle) * baseRadius * jitter + centerDrift.x,
                        y - skirtSag,
                        Mathf.Sin(angle) * baseRadius * jitter + centerDrift.y);
                    uvs[index] = new Vector2(i / (float)sideCount, t);
                }
            }

            vertices[topIndex] = new Vector3(AuthoredVegetationSigned(seedKey, 83, 0.044f), 0.56f, AuthoredVegetationSigned(seedKey, 89, 0.044f));
            vertices[bottomIndex] = new Vector3(AuthoredVegetationSigned(seedKey, 97, 0.032f), -0.55f, AuthoredVegetationSigned(seedKey, 101, 0.032f));
            uvs[topIndex] = new Vector2(0.5f, 1f);
            uvs[bottomIndex] = new Vector2(0.5f, 0f);

            var triangles = new List<int>(sideCount * 30);
            for (var ring = 0; ring < ringCount - 1; ring++)
            {
                var currentOffset = ring * sideCount;
                var nextOffset = (ring + 1) * sideCount;
                for (var i = 0; i < sideCount; i++)
                {
                    var next = (i + 1) % sideCount;
                    var a = currentOffset + i;
                    var b = currentOffset + next;
                    var c = nextOffset + i;
                    var d = nextOffset + next;
                    triangles.Add(a);
                    triangles.Add(c);
                    triangles.Add(b);
                    triangles.Add(b);
                    triangles.Add(c);
                    triangles.Add(d);
                }
            }

            var topRingOffset = (ringCount - 1) * sideCount;
            for (var i = 0; i < sideCount; i++)
            {
                var next = (i + 1) % sideCount;
                triangles.Add(topIndex);
                triangles.Add(topRingOffset + i);
                triangles.Add(topRingOffset + next);
                triangles.Add(bottomIndex);
                triangles.Add(next);
                triangles.Add(i);
            }

            return CreateAuthoredVegetationMeshAsset(meshName, vertices, uvs, triangles);
        }

        private static Mesh CreateAuthoredVegetationRootFlareMesh(string meshName, string seedKey)
        {
            var vertices = new List<Vector3>(72);
            var uvs = new List<Vector2>(72);
            var triangles = new List<int>(240);
            const int rootCount = 6;

            for (var root = 0; root < rootCount; root++)
            {
                var t = root / (float)rootCount;
                var angle = t * Mathf.PI * 2f + AuthoredVegetationSigned(seedKey, 503 + root * 13, 0.22f);
                var right = new Vector3(Mathf.Cos(angle), 0f, Mathf.Sin(angle));
                var start = right * Mathf.Lerp(0.03f, 0.08f, AuthoredVegetationHash01(seedKey, 509 + root * 17)) +
                    Vector3.up * Mathf.Lerp(-0.10f, 0.08f, AuthoredVegetationHash01(seedKey, 521 + root * 19));
                var end = right * Mathf.Lerp(0.42f, 0.62f, AuthoredVegetationHash01(seedKey, 523 + root * 23)) +
                    Vector3.up * Mathf.Lerp(-0.32f, -0.18f, AuthoredVegetationHash01(seedKey, 541 + root * 29)) +
                    new Vector3(0f, 0f, AuthoredVegetationSigned(seedKey, 547 + root * 31, 0.04f));
                AddAuthoredVegetationBranchSegment(
                    vertices,
                    uvs,
                    triangles,
                    start,
                    end,
                    Mathf.Lerp(0.070f, 0.095f, AuthoredVegetationHash01(seedKey, 557 + root * 37)),
                    Mathf.Lerp(0.022f, 0.038f, AuthoredVegetationHash01(seedKey, 563 + root * 41)));
            }

            return CreateAuthoredVegetationMeshAsset(meshName, vertices.ToArray(), uvs.ToArray(), triangles);
        }

        private static Mesh CreateAuthoredVegetationBranchLaceMesh(string meshName, string seedKey)
        {
            var vertices = new List<Vector3>(96);
            var uvs = new List<Vector2>(96);
            var triangles = new List<int>(300);
            const int branchCount = 5;

            for (var branch = 0; branch < branchCount; branch++)
            {
                var t = branch / (float)(branchCount - 1);
                var side = Mathf.Lerp(-0.42f, 0.42f, t) + AuthoredVegetationSigned(seedKey, 601 + branch * 13, 0.08f);
                var start = new Vector3(
                    side * 0.38f,
                    Mathf.Lerp(-0.36f, 0.08f, AuthoredVegetationHash01(seedKey, 607 + branch * 17)),
                    AuthoredVegetationSigned(seedKey, 613 + branch * 19, 0.12f));
                var end = new Vector3(
                    side + AuthoredVegetationSigned(seedKey, 617 + branch * 23, 0.12f),
                    Mathf.Lerp(0.18f, 0.46f, AuthoredVegetationHash01(seedKey, 619 + branch * 29)),
                    AuthoredVegetationSigned(seedKey, 631 + branch * 31, 0.16f));
                AddAuthoredVegetationBranchSegment(
                    vertices,
                    uvs,
                    triangles,
                    start,
                    end,
                    Mathf.Lerp(0.038f, 0.060f, AuthoredVegetationHash01(seedKey, 641 + branch * 37)),
                    Mathf.Lerp(0.012f, 0.022f, AuthoredVegetationHash01(seedKey, 643 + branch * 41)));

                if ((branch & 1) == 0)
                {
                    var twigEnd = end + new Vector3(
                        AuthoredVegetationSigned(seedKey, 647 + branch * 43, 0.22f),
                        Mathf.Lerp(0.06f, 0.18f, AuthoredVegetationHash01(seedKey, 653 + branch * 47)),
                        AuthoredVegetationSigned(seedKey, 659 + branch * 53, 0.10f));
                    AddAuthoredVegetationBranchSegment(
                        vertices,
                        uvs,
                        triangles,
                        Vector3.Lerp(start, end, 0.58f),
                        twigEnd,
                        0.024f,
                        0.010f);
                }
            }

            return CreateAuthoredVegetationMeshAsset(meshName, vertices.ToArray(), uvs.ToArray(), triangles);
        }

        private static Mesh CreateAuthoredVegetationGrassBladeMesh(string meshName, string seedKey)
        {
            var tipBend = AuthoredVegetationSigned(seedKey, 131, 0.14f);
            var sideBend = AuthoredVegetationSigned(seedKey, 137, 0.08f);
            var vertices = new[]
            {
                new Vector3(-0.34f, -0.50f, 0f),
                new Vector3(0.34f, -0.50f, 0f),
                new Vector3(0.08f + sideBend, 0.05f, 0.03f),
                new Vector3(tipBend, 0.50f, 0.06f),
                new Vector3(-0.08f + sideBend * 0.5f, -0.05f, -0.03f)
            };
            var uvs = new[]
            {
                new Vector2(0f, 0f),
                new Vector2(1f, 0f),
                new Vector2(0.65f, 0.55f),
                new Vector2(0.5f, 1f),
                new Vector2(0.35f, 0.45f)
            };
            var triangles = new List<int>
            {
                0, 2, 4,
                1, 3, 2,
                0, 4, 2,
                1, 2, 3,
                0, 1, 2,
                0, 2, 1
            };
            return CreateAuthoredVegetationMeshAsset(meshName, vertices, uvs, triangles);
        }

        private static Mesh CreateAuthoredVegetationLeafClusterMesh(string meshName, string seedKey)
        {
            var sideLean = AuthoredVegetationSigned(seedKey, 151, 0.08f);
            var frontLean = AuthoredVegetationSigned(seedKey, 157, 0.06f);
            const int outerCount = 10;
            var vertices = new Vector3[outerCount + 3];
            var uvs = new Vector2[vertices.Length];
            var triangles = new List<int>(outerCount * 9);

            vertices[0] = new Vector3(sideLean * 0.25f, -0.18f, frontLean * 0.25f);
            uvs[0] = new Vector2(0.5f, 0.5f);
            for (var i = 0; i < outerCount; i++)
            {
                var angle = (i / (float)outerCount) * Mathf.PI * 2f + AuthoredVegetationSigned(seedKey, 161, 0.12f);
                var radial = 0.36f + AuthoredVegetationHash01(seedKey, 163 + i * 7) * 0.16f;
                var height = Mathf.Lerp(-0.40f, 0.16f, AuthoredVegetationHash01(seedKey, 167 + i * 11));
                if ((i & 1) == 0)
                {
                    height -= 0.08f;
                }

                vertices[i + 1] = new Vector3(
                    Mathf.Cos(angle) * radial + sideLean,
                    height,
                    Mathf.Sin(angle) * radial * 0.88f + frontLean);
                uvs[i + 1] = new Vector2(0.5f + Mathf.Cos(angle) * 0.45f, 0.5f + Mathf.Sin(angle) * 0.45f);
            }

            var topIndex = outerCount + 1;
            var bottomIndex = outerCount + 2;
            vertices[topIndex] = new Vector3(-0.12f + sideLean * 0.8f, 0.28f, 0.10f + frontLean);
            vertices[bottomIndex] = new Vector3(0.10f - sideLean * 0.4f, -0.48f, -0.04f - frontLean * 0.6f);
            uvs[topIndex] = new Vector2(0.40f, 0.92f);
            uvs[bottomIndex] = new Vector2(0.60f, 0.08f);

            for (var i = 0; i < outerCount; i++)
            {
                var current = i + 1;
                var next = i == outerCount - 1 ? 1 : i + 2;
                triangles.Add(0);
                triangles.Add(current);
                triangles.Add(next);
                if ((i & 1) == 0)
                {
                    triangles.Add(topIndex);
                    triangles.Add(next);
                    triangles.Add(current);
                }
                else
                {
                    triangles.Add(bottomIndex);
                    triangles.Add(current);
                    triangles.Add(next);
                }
            }

            return CreateAuthoredVegetationMeshAsset(meshName, vertices, uvs, triangles);
        }

        private static Mesh CreateAuthoredVegetationBlossomMesh(string meshName, string seedKey)
        {
            const int sideCount = 6;
            var centerLift = AuthoredVegetationSigned(seedKey, 167, 0.035f);
            var vertices = new Vector3[sideCount + 2];
            var uvs = new Vector2[vertices.Length];
            vertices[0] = new Vector3(0f, centerLift, 0f);
            vertices[sideCount + 1] = new Vector3(0f, -0.32f, 0f);
            uvs[0] = new Vector2(0.5f, 0.5f);
            uvs[sideCount + 1] = new Vector2(0.5f, 0.1f);

            for (var i = 0; i < sideCount; i++)
            {
                var angle = (i / (float)sideCount) * Mathf.PI * 2f + AuthoredVegetationSigned(seedKey, 173, 0.08f);
                var radius = 0.38f + AuthoredVegetationHash01(seedKey, 181 + i) * 0.12f;
                vertices[i + 1] = new Vector3(Mathf.Cos(angle) * radius, 0.04f + (i % 2) * 0.035f, Mathf.Sin(angle) * radius);
                uvs[i + 1] = new Vector2(0.5f + Mathf.Cos(angle) * 0.42f, 0.5f + Mathf.Sin(angle) * 0.42f);
            }

            var triangles = new List<int>(sideCount * 6);
            for (var i = 0; i < sideCount; i++)
            {
                var current = i + 1;
                var next = i == sideCount - 1 ? 1 : i + 2;
                triangles.Add(0);
                triangles.Add(current);
                triangles.Add(next);
                triangles.Add(sideCount + 1);
                triangles.Add(next);
                triangles.Add(current);
            }

            return CreateAuthoredVegetationMeshAsset(meshName, vertices, uvs, triangles);
        }

        private static Mesh CreateAuthoredVegetationBranchForkMesh(string meshName, string seedKey)
        {
            var vertices = new List<Vector3>(48);
            var uvs = new List<Vector2>(48);
            var triangles = new List<int>(180);
            var joint = new Vector3(
                AuthoredVegetationSigned(seedKey, 231, 0.045f),
                0.02f + AuthoredVegetationSigned(seedKey, 233, 0.035f),
                AuthoredVegetationSigned(seedKey, 239, 0.045f));

            AddAuthoredVegetationBranchSegment(
                vertices,
                uvs,
                triangles,
                new Vector3(AuthoredVegetationSigned(seedKey, 241, 0.025f), -0.50f, AuthoredVegetationSigned(seedKey, 251, 0.025f)),
                joint,
                0.130f,
                0.078f);
            AddAuthoredVegetationBranchSegment(
                vertices,
                uvs,
                triangles,
                joint,
                new Vector3(-0.48f + AuthoredVegetationSigned(seedKey, 257, 0.055f), 0.50f, 0.14f + AuthoredVegetationSigned(seedKey, 263, 0.050f)),
                0.070f,
                0.034f);
            AddAuthoredVegetationBranchSegment(
                vertices,
                uvs,
                triangles,
                joint,
                new Vector3(0.43f + AuthoredVegetationSigned(seedKey, 269, 0.060f), 0.44f + AuthoredVegetationSigned(seedKey, 271, 0.035f), -0.13f + AuthoredVegetationSigned(seedKey, 277, 0.050f)),
                0.064f,
                0.030f);

            return CreateAuthoredVegetationMeshAsset(meshName, vertices.ToArray(), uvs.ToArray(), triangles);
        }

        private static void AddAuthoredVegetationBranchSegment(List<Vector3> vertices, List<Vector2> uvs, List<int> triangles, Vector3 start, Vector3 end, float startRadius, float endRadius)
        {
            const int sideCount = 6;
            var direction = (end - start).normalized;
            var side = Vector3.Cross(Vector3.up, direction);
            if (side.sqrMagnitude < 0.0001f)
            {
                side = Vector3.Cross(Vector3.right, direction);
            }

            side.Normalize();
            var up = Vector3.Cross(direction, side).normalized;
            var firstIndex = vertices.Count;

            for (var i = 0; i < sideCount; i++)
            {
                var angle = (i / (float)sideCount) * Mathf.PI * 2f;
                var radial = side * Mathf.Cos(angle) + up * Mathf.Sin(angle);
                vertices.Add(start + radial * startRadius);
                vertices.Add(end + radial * endRadius);
                uvs.Add(new Vector2(i / (float)sideCount, 0f));
                uvs.Add(new Vector2(i / (float)sideCount, 1f));
            }

            var startCenter = vertices.Count;
            vertices.Add(start);
            uvs.Add(new Vector2(0.5f, 0f));
            var endCenter = vertices.Count;
            vertices.Add(end);
            uvs.Add(new Vector2(0.5f, 1f));

            for (var i = 0; i < sideCount; i++)
            {
                var next = (i + 1) % sideCount;
                var a0 = firstIndex + i * 2;
                var a1 = firstIndex + next * 2;
                var b0 = a0 + 1;
                var b1 = a1 + 1;

                triangles.Add(a0);
                triangles.Add(a1);
                triangles.Add(b0);
                triangles.Add(b0);
                triangles.Add(a1);
                triangles.Add(b1);
                triangles.Add(startCenter);
                triangles.Add(a0);
                triangles.Add(a1);
                triangles.Add(endCenter);
                triangles.Add(b1);
                triangles.Add(b0);
            }
        }

        private static Mesh CreateAuthoredVegetationLeafFanMesh(string meshName, string seedKey)
        {
            const int fanCount = 7;
            var vertices = new Vector3[fanCount * 4];
            var uvs = new Vector2[vertices.Length];
            var triangles = new List<int>(fanCount * 12);

            for (var i = 0; i < fanCount; i++)
            {
                var baseIndex = i * 4;
                var yaw = ((i / (float)fanCount) * Mathf.PI * 2f) + AuthoredVegetationSigned(seedKey, 281 + i * 7, 0.26f);
                var right = new Vector3(Mathf.Cos(yaw), 0f, Mathf.Sin(yaw));
                var forward = new Vector3(-right.z, 0f, right.x);
                var center = new Vector3(
                    AuthoredVegetationSigned(seedKey, 293 + i * 11, 0.16f),
                    Mathf.Lerp(-0.18f, 0.42f, i / (float)(fanCount - 1)) + AuthoredVegetationSigned(seedKey, 307 + i * 13, 0.035f),
                    AuthoredVegetationSigned(seedKey, 317 + i * 17, 0.16f));
                var width = Mathf.Lerp(0.22f, 0.40f, AuthoredVegetationHash01(seedKey, 331 + i * 19));
                var height = Mathf.Lerp(0.32f, 0.54f, AuthoredVegetationHash01(seedKey, 353 + i * 23));
                var lean = forward * AuthoredVegetationSigned(seedKey, 359 + i * 29, 0.09f);

                vertices[baseIndex] = center - right * width * 0.50f - Vector3.up * height * 0.36f - lean * 0.35f;
                vertices[baseIndex + 1] = center + right * width * 0.50f - Vector3.up * height * 0.34f + lean * 0.20f;
                vertices[baseIndex + 2] = center + right * width * 0.18f + Vector3.up * height * 0.52f + lean;
                vertices[baseIndex + 3] = center - right * width * 0.34f + Vector3.up * height * 0.44f - lean * 0.25f;
                uvs[baseIndex] = new Vector2(0f, 0f);
                uvs[baseIndex + 1] = new Vector2(1f, 0f);
                uvs[baseIndex + 2] = new Vector2(0.72f, 1f);
                uvs[baseIndex + 3] = new Vector2(0.20f, 0.92f);

                triangles.Add(baseIndex);
                triangles.Add(baseIndex + 1);
                triangles.Add(baseIndex + 2);
                triangles.Add(baseIndex);
                triangles.Add(baseIndex + 2);
                triangles.Add(baseIndex + 3);
                triangles.Add(baseIndex + 2);
                triangles.Add(baseIndex + 1);
                triangles.Add(baseIndex);
                triangles.Add(baseIndex + 3);
                triangles.Add(baseIndex + 2);
                triangles.Add(baseIndex);
            }

            return CreateAuthoredVegetationMeshAsset(meshName, vertices, uvs, triangles);
        }

        private static Mesh CreateAuthoredVegetationLeafSprayMesh(string meshName, string seedKey)
        {
            const int leafCount = 18;
            var vertices = new Vector3[leafCount * 4];
            var uvs = new Vector2[vertices.Length];
            var triangles = new List<int>(leafCount * 12);

            for (var i = 0; i < leafCount; i++)
            {
                var baseIndex = i * 4;
                var t = i / (float)(leafCount - 1);
                var yaw = t * Mathf.PI * 2f + AuthoredVegetationSigned(seedKey, 401 + i * 11, 0.32f);
                var right = new Vector3(Mathf.Cos(yaw), 0f, Mathf.Sin(yaw));
                var forward = new Vector3(-right.z, 0f, right.x);
                var radius = Mathf.Lerp(0.24f, 0.62f, AuthoredVegetationHash01(seedKey, 421 + i * 13));
                var height = Mathf.Lerp(-0.34f, 0.46f, AuthoredVegetationHash01(seedKey, 431 + i * 17));
                var center = right * radius +
                    forward * AuthoredVegetationSigned(seedKey, 443 + i * 19, 0.18f) +
                    Vector3.up * height;
                var width = Mathf.Lerp(0.11f, 0.27f, AuthoredVegetationHash01(seedKey, 457 + i * 23));
                var bladeHeight = Mathf.Lerp(0.20f, 0.40f, AuthoredVegetationHash01(seedKey, 467 + i * 29));
                var lean = forward * AuthoredVegetationSigned(seedKey, 479 + i * 31, 0.14f);
                var lift = Vector3.up * bladeHeight;

                vertices[baseIndex] = center - right * width - lift * 0.38f - lean * 0.24f;
                vertices[baseIndex + 1] = center + right * width - lift * 0.30f + lean * 0.14f;
                vertices[baseIndex + 2] = center + right * width * 0.22f + lift * 0.58f + lean;
                vertices[baseIndex + 3] = center - right * width * 0.46f + lift * 0.48f - lean * 0.30f;
                uvs[baseIndex] = new Vector2(0f, 0f);
                uvs[baseIndex + 1] = new Vector2(1f, 0f);
                uvs[baseIndex + 2] = new Vector2(0.66f, 1f);
                uvs[baseIndex + 3] = new Vector2(0.18f, 0.88f);

                triangles.Add(baseIndex);
                triangles.Add(baseIndex + 1);
                triangles.Add(baseIndex + 2);
                triangles.Add(baseIndex);
                triangles.Add(baseIndex + 2);
                triangles.Add(baseIndex + 3);
                triangles.Add(baseIndex + 2);
                triangles.Add(baseIndex + 1);
                triangles.Add(baseIndex);
                triangles.Add(baseIndex + 3);
                triangles.Add(baseIndex + 2);
                triangles.Add(baseIndex);
            }

            return CreateAuthoredVegetationMeshAsset(meshName, vertices, uvs, triangles);
        }

        private static Mesh CreateAuthoredVegetationFruitMesh(string meshName, string seedKey)
        {
            var sideLean = AuthoredVegetationSigned(seedKey, 191, 0.04f);
            var vertices = new[]
            {
                new Vector3(sideLean, 0.50f, 0f),
                new Vector3(-sideLean * 0.5f, -0.50f, 0f),
                new Vector3(-0.42f, 0.00f, 0f),
                new Vector3(0.42f, 0.02f, 0f),
                new Vector3(0f, 0.00f, 0.42f),
                new Vector3(0f, -0.02f, -0.42f)
            };
            var uvs = new[]
            {
                new Vector2(0.5f, 1.0f),
                new Vector2(0.5f, 0.0f),
                new Vector2(0.1f, 0.5f),
                new Vector2(0.9f, 0.5f),
                new Vector2(0.5f, 0.9f),
                new Vector2(0.5f, 0.1f)
            };
            var triangles = new List<int>
            {
                0, 2, 4,
                0, 4, 3,
                0, 3, 5,
                0, 5, 2,
                1, 4, 2,
                1, 3, 4,
                1, 5, 3,
                1, 2, 5
            };
            return CreateAuthoredVegetationMeshAsset(meshName, vertices, uvs, triangles);
        }

        private static Mesh CreateAuthoredVegetationMeshAsset(string meshName, Vector3[] vertices, Vector2[] uvs, List<int> triangles)
        {
            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static float AuthoredVegetationHash01(string seedKey, int salt)
        {
            unchecked
            {
                var hash = 2166136261u ^ (uint)salt;
                for (var i = 0; i < seedKey.Length; i++)
                {
                    hash ^= seedKey[i];
                    hash *= 16777619u;
                }

                hash ^= hash >> 13;
                hash *= 1274126177u;
                return (hash & 0x00FFFFFFu) / 16777215f;
            }
        }

        private static float AuthoredVegetationSigned(string seedKey, int salt, float magnitude)
        {
            return (AuthoredVegetationHash01(seedKey, salt) * 2f - 1f) * magnitude;
        }

