                    Quaternion.Euler(0f, past ? -10f : -8f, 0f),
                    material,
                    $"{prefix}.house_exterior.outdoor_void_background.north_silhouette_left");

                CreateOutdoorVoidBackgroundSlab(
                    $"{prefix}_HouseExterior_OutdoorVoidBackground_NorthSilhouetteCenter",
                    root,
