                    c + new Vector3(8.06f, 0.52f, 5.08f),
                    new Vector3(0.42f, 0.28f, 0.06f),
                    Quaternion.Euler(0f, -18f, 0f),
                    material,
                    $"{prefix}.house_exterior.outdoor_void_background.east_edge_wash");
            }
            else
            {
                CreateOutdoorVoidBackgroundSlab(
