            SerializedSet(landmark, "countsForArrival", false);
        }

        private static Mesh CreateHouseExteriorMapEdgeTerrainApronMesh(string meshName, int seed, float length, float depth)
        {
            const int columnCount = 9;
            const int rowCount = 5;
            var vertices = new Vector3[columnCount * rowCount];
            var uvs = new Vector2[vertices.Length];

            for (var row = 0; row < rowCount; row++)
            {
                var v = row / (float)(rowCount - 1);
                var rowLength = length * Mathf.Lerp(0.70f, 1.08f, Mathf.Sin(v * Mathf.PI * 0.82f));
                var rowDrift = DistantPanoramaVistaSigned(seed + row * 31 + 5, length * 0.045f);
                var z = Mathf.Lerp(-depth * 0.50f, depth * 0.50f, v) +
                    DistantPanoramaVistaSigned(seed + row * 37 + 11, depth * 0.055f);

                for (var column = 0; column < columnCount; column++)
                {
                    var u = column / (float)(columnCount - 1);
                    var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                    var endNotch = (column == 0 || column == columnCount - 1)
                        ? DistantPanoramaVistaSigned(seed + row * 43 + column * 17, length * 0.070f)
                        : 0f;
                    var lateralBreak = DistantPanoramaVistaSigned(seed + row * 53 + column * 19, length * 0.035f) * edgeFalloff;
                    var y = 0.012f +
                        Mathf.Sin(v * Mathf.PI) * 0.044f +
                        DistantPanoramaVistaSigned(seed + row * 59 + column * 23, 0.012f) * edgeFalloff;
                    var index = row * columnCount + column;
                    vertices[index] = new Vector3(
                        Mathf.Lerp(-rowLength * 0.5f, rowLength * 0.5f, u) + rowDrift + lateralBreak + endNotch,
                        y,
                        z);
                    uvs[index] = new Vector2(u, v);
                }
            }

            var triangles = new List<int>((columnCount - 1) * (rowCount - 1) * 12);
            for (var row = 0; row < rowCount - 1; row++)
            {
                for (var column = 0; column < columnCount - 1; column++)
                {
                    var a = row * columnCount + column;
                    var b = row * columnCount + column + 1;
                    var c = (row + 1) * columnCount + column;
                    var d = (row + 1) * columnCount + column + 1;
                    triangles.Add(a);
                    triangles.Add(c);
                    triangles.Add(b);
                    triangles.Add(b);
                    triangles.Add(c);
                    triangles.Add(d);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static void ApplyMapEdgeTerrainApronRendererPolicy(Transform parent)
        {
            var expectedLayer = parent.gameObject.layer;
            foreach (var transform in parent.GetComponentsInChildren<Transform>(true))
            {
                transform.gameObject.layer = expectedLayer;
            }

            foreach (var renderer in parent.GetComponentsInChildren<Renderer>(true))
            {
                renderer.shadowCastingMode = ShadowCastingMode.Off;
                renderer.receiveShadows = false;
            }
        }

        private static void CreateChapter1PhaseEMidDistanceLandformClosureForOutdoorMaps(
            Transform exteriorRoot,
            Transform plazaRoot,
            Transform miaHouseRoot,
            Transform ariaStreetRoot,
            Transform kaiaFarmRoot,
            Transform ruinsRoot,
            string prefix,
            bool past,
            Materials materials)
        {
            _ = materials;

            CreateChapter1PhaseEMidDistanceLandformClosure(exteriorRoot, prefix, past, FastVsHouseArea.Exterior);
            CreateChapter1PhaseEMidDistanceLandformClosure(plazaRoot, prefix, past, FastVsHouseArea.CentralPlaza);
            CreateChapter1PhaseEMidDistanceLandformClosure(miaHouseRoot, prefix, past, FastVsHouseArea.MiaHouse);
            CreateChapter1PhaseEMidDistanceLandformClosure(ariaStreetRoot, prefix, past, FastVsHouseArea.AriaStreet);
            CreateChapter1PhaseEMidDistanceLandformClosure(kaiaFarmRoot, prefix, past, FastVsHouseArea.KaiaFarm);
            CreateChapter1PhaseEMidDistanceLandformClosure(ruinsRoot, prefix, past, FastVsHouseArea.Ruins);
        }

        private static void CreateChapter1PhaseEMidDistanceLandformClosure(Transform mapRoot, string prefix, bool past, FastVsHouseArea area)
        {
            var areaToken = GetDistantPanoramaVistaAreaToken(area);
            var center = GetDistantPanoramaVistaCenter(area);
            var parent = new GameObject($"{prefix}_{areaToken}_MidDistanceLandformClosure").transform;
            parent.SetParent(mapRoot, false);
            parent.localPosition = Vector3.zero;
            parent.localRotation = Quaternion.identity;
            parent.localScale = Vector3.one;
            parent.gameObject.layer = past ? OtherTimeSpaceRenderLayer : CurrentSpaceRenderLayer;

            var radiusScale = GetMidDistanceLandformClosureRadiusScale(area);
            var phase = GetMidDistanceLandformClosureAreaPhase(area);
            var shelfMaterial = EnsureMidDistanceLandformClosureTerrainMaterial(past);
            var bankMaterial = EnsureMidDistanceLandformClosureBankMaterial(past);
            var pathMaterial = EnsureMidDistanceLandformClosurePathMaterial(past);
            var coppiceMaterial = EnsureMidDistanceLandformClosureCoppiceMaterial(past);
            var scope = $"{prefix}.{areaToken.ToLowerInvariant()}.mid_distance_landform_closure";

            for (var segment = 0; segment < MidDistanceLandformClosureSegmentCount; segment++)
            {
                var seed = 6211 + (int)area * 337 + (past ? 1459 : 0) + segment * 71;
                var angle = ((segment + 0.5f) / MidDistanceLandformClosureSegmentCount) * Mathf.PI * 2f + phase;
                var radial = new Vector3(Mathf.Sin(angle), 0f, Mathf.Cos(angle));
                var tangent = new Vector3(radial.z, 0f, -radial.x);

                var shelfRadius = (18.6f + DistantPanoramaVistaSigned(seed + 5, 1.75f)) * radiusScale;
                var shelfPosition = center +
                    radial * shelfRadius +
                    tangent * DistantPanoramaVistaSigned(seed + 11, 1.10f) +
                    new Vector3(0f, 0.045f + DistantPanoramaVistaHash01(seed + 17) * 0.030f, 0f);
                var shelfRotation = MidDistanceLandformClosureFacingRotation(center, shelfPosition, -radial);
                var shelfWidth = 2f * shelfRadius * Mathf.Tan(Mathf.PI / MidDistanceLandformClosureSegmentCount) *
                    Mathf.Lerp(1.20f, 1.62f, DistantPanoramaVistaHash01(seed + 23));
                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_MidDistanceLandformClosure_TerrainShelf_S{segment + 1:00}",
                    parent,
                    shelfPosition,
                    shelfRotation,
                    CreateMidDistanceLandformClosureShelfMesh(
                        $"{prefix}_{areaToken}_MidDistanceLandformClosure_TerrainShelf_S{segment + 1:00}_Mesh",
                        seed,
                        shelfWidth,
                        Mathf.Lerp(4.6f, 7.2f, DistantPanoramaVistaHash01(seed + 29)) * radiusScale,
                        Mathf.Lerp(0.16f, 0.32f, DistantPanoramaVistaHash01(seed + 31))),
                    shelfMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PathOrFloor,
                    $"{scope}.terrain_shelf.s{segment + 1:00}");

                var bankSeed = seed + 4009;
                var bankRadius = (27.5f + DistantPanoramaVistaSigned(bankSeed + 5, 2.30f)) * radiusScale;
                var bankPosition = center +
                    radial * bankRadius +
                    tangent * DistantPanoramaVistaSigned(bankSeed + 11, 1.85f) +
                    new Vector3(0f, 0.12f + DistantPanoramaVistaHash01(bankSeed + 17) * 0.12f, 0f);
                var bankWidth = 2f * bankRadius * Mathf.Tan(Mathf.PI / MidDistanceLandformClosureSegmentCount) *
                    Mathf.Lerp(1.04f, 1.40f, DistantPanoramaVistaHash01(bankSeed + 23));
                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_MidDistanceLandformClosure_LowBank_S{segment + 1:00}",
                    parent,
                    bankPosition,
                    MidDistanceLandformClosureFacingRotation(center, bankPosition, -radial),
                    CreateMidDistanceLandformClosureLowBankMesh(
                        $"{prefix}_{areaToken}_MidDistanceLandformClosure_LowBank_S{segment + 1:00}_Mesh",
                        bankSeed,
                        bankWidth,
                        Mathf.Lerp(1.25f, 2.55f, DistantPanoramaVistaHash01(bankSeed + 31)) * (past ? 1.08f : 1f),
                        Mathf.Lerp(1.10f, 1.75f, DistantPanoramaVistaHash01(bankSeed + 37))),
                    bankMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{scope}.low_bank.s{segment + 1:00}");

                var coppiceSeed = seed + 8011;
                var coppiceRadius = (23.0f + DistantPanoramaVistaSigned(coppiceSeed + 5, 1.80f)) * radiusScale;
                var coppicePosition = center +
                    radial * coppiceRadius +
                    tangent * DistantPanoramaVistaSigned(coppiceSeed + 11, 1.65f) +
                    new Vector3(0f, 0.18f + DistantPanoramaVistaHash01(coppiceSeed + 17) * 0.18f, 0f);
                var coppiceWidth = 2f * coppiceRadius * Mathf.Tan(Mathf.PI / MidDistanceLandformClosureSegmentCount) *
                    Mathf.Lerp(0.82f, 1.24f, DistantPanoramaVistaHash01(coppiceSeed + 23));
                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_MidDistanceLandformClosure_CoppiceFold_S{segment + 1:00}",
                    parent,
                    coppicePosition,
                    MidDistanceLandformClosureFacingRotation(center, coppicePosition, -radial),
                    CreateDistantPanoramaVistaTreelineFoldMesh(
                        $"{prefix}_{areaToken}_MidDistanceLandformClosure_CoppiceFold_S{segment + 1:00}_Mesh",
                        coppiceSeed,
                        coppiceWidth,
                        Mathf.Lerp(2.2f, 4.4f, DistantPanoramaVistaHash01(coppiceSeed + 31)) * (past ? 1.08f : 1f),
                        0.78f),
                    coppiceMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{scope}.coppice_fold.s{segment + 1:00}");
            }

            var pathCenter = GetMidDistanceLandformClosurePathCenterAngle(area);
            for (var index = 0; index < MidDistanceLandformClosurePathThreadCount; index++)
            {
                var seed = 14891 + (int)area * 379 + (past ? 1609 : 0) + index * 83;
                var angle = pathCenter +
                    (index - (MidDistanceLandformClosurePathThreadCount - 1) * 0.5f) * 5.2f * Mathf.Deg2Rad +
                    DistantPanoramaVistaSigned(seed + 5, 1.25f) * Mathf.Deg2Rad;
                var radial = new Vector3(Mathf.Sin(angle), 0f, Mathf.Cos(angle));
                var tangent = new Vector3(radial.z, 0f, -radial.x);
                var radius = (16.2f + index * 1.95f + DistantPanoramaVistaSigned(seed + 11, 0.55f)) *
                    GetMidDistanceLandformClosurePathRadiusScale(area);
                var position = center +
                    radial * radius +
                    tangent * DistantPanoramaVistaSigned(seed + 13, 0.62f) +
                    new Vector3(0f, 0.082f + index * 0.006f, 0f);

                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_MidDistanceLandformClosure_PathThread_S{index + 1:00}",
                    parent,
                    position,
                    MidDistanceLandformClosureFacingRotation(center, position, -radial),
                    CreateMidDistanceLandformClosureShelfMesh(
                        $"{prefix}_{areaToken}_MidDistanceLandformClosure_PathThread_S{index + 1:00}_Mesh",
                        seed,
                        Mathf.Lerp(3.4f, 5.6f, DistantPanoramaVistaHash01(seed + 23)) * GetMidDistanceLandformClosurePathRadiusScale(area),
                        Mathf.Lerp(2.8f, 4.8f, DistantPanoramaVistaHash01(seed + 29)),
                        Mathf.Lerp(0.07f, 0.16f, DistantPanoramaVistaHash01(seed + 31))),
                    pathMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PathOrFloor,
                    $"{scope}.path_thread.s{index + 1:00}");
            }

            ApplyMidDistanceLandformClosureRendererPolicy(parent);
        }

        private static void CreateMidDistanceLandformClosurePiece(
            string objectName,
            Transform parent,
            Vector3 localPosition,
            Quaternion localRotation,
            Mesh mesh,
            Material material,
            TimeWindowPairedSpaceLandmarkKind kind,
            string landmarkId)
        {
            var sceneObject = new GameObject(objectName);
            sceneObject.transform.SetParent(parent, false);
            sceneObject.transform.localPosition = localPosition;
            sceneObject.transform.localRotation = localRotation;
            sceneObject.transform.localScale = Vector3.one;
            sceneObject.layer = parent.gameObject.layer;

            var filter = sceneObject.AddComponent<MeshFilter>();
            filter.sharedMesh = mesh;

            var renderer = sceneObject.AddComponent<MeshRenderer>();
            renderer.sharedMaterial = material;
            renderer.shadowCastingMode = ShadowCastingMode.Off;
            renderer.receiveShadows = false;

            var landmark = sceneObject.AddComponent<TimeWindowPairedSpaceLandmark>();
            SerializedSet(landmark, "landmarkId", landmarkId);
            SerializedSet(landmark, "kind", kind);
            SerializedSet(landmark, "countsForArrival", false);
        }

        private static Quaternion MidDistanceLandformClosureFacingRotation(Vector3 center, Vector3 localPosition, Vector3 fallbackDirection)
        {
            var faceDirection = center - localPosition;
            faceDirection.y = 0f;
            if (faceDirection.sqrMagnitude < 0.01f)
            {
                faceDirection = fallbackDirection;
            }

            return Quaternion.LookRotation(faceDirection.normalized, Vector3.up);
        }

        private static Mesh CreateMidDistanceLandformClosureShelfMesh(string meshName, int seed, float width, float depth, float relief)
        {
            const int columnCount = 13;
            const int rowCount = 6;
            var vertices = new Vector3[columnCount * rowCount];
            var uvs = new Vector2[vertices.Length];

            for (var row = 0; row < rowCount; row++)
            {
                var v = row / (float)(rowCount - 1);
                var rowWidth = width * Mathf.Lerp(0.72f, 1.12f, Mathf.Sin(v * Mathf.PI * 0.92f));
                var rowDrift = DistantPanoramaVistaSigned(seed + row * 37 + 5, width * 0.048f);
                var z = Mathf.Lerp(-depth * 0.52f, depth * 0.52f, v) +
                    DistantPanoramaVistaSigned(seed + row * 41 + 11, depth * 0.052f);

                for (var column = 0; column < columnCount; column++)
                {
                    var u = column / (float)(columnCount - 1);
                    var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                    var centerLift = Mathf.Sin(v * Mathf.PI) * relief;
                    var terrace = (row == 1 || row == rowCount - 2) ? relief * 0.38f : 0f;
                    var notch = (column == 0 || column == columnCount - 1)
                        ? DistantPanoramaVistaSigned(seed + row * 47 + column * 17, width * 0.065f)
                        : 0f;
                    var x = Mathf.Lerp(-rowWidth * 0.5f, rowWidth * 0.5f, u) +
                        rowDrift +
                        DistantPanoramaVistaSigned(seed + row * 53 + column * 19, width * 0.030f) * edgeFalloff +
                        notch;
                    var y = 0.010f + centerLift + terrace +
                        DistantPanoramaVistaSigned(seed + row * 59 + column * 23, relief * 0.34f) * edgeFalloff;
                    var index = row * columnCount + column;
                    vertices[index] = new Vector3(x, y, z);
                    uvs[index] = new Vector2(u, v);
                }
            }

            var triangles = new List<int>((columnCount - 1) * (rowCount - 1) * 12);
            for (var row = 0; row < rowCount - 1; row++)
            {
                for (var column = 0; column < columnCount - 1; column++)
                {
                    var a = row * columnCount + column;
                    var b = row * columnCount + column + 1;
                    var c = (row + 1) * columnCount + column;
                    var d = (row + 1) * columnCount + column + 1;
                    AddDoubleSidedQuad(triangles, a, b, c, d);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateMidDistanceLandformClosureLowBankMesh(string meshName, int seed, float width, float height, float thickness)
        {
            const int columnCount = 14;
            const int rowCount = 4;
            const int sideCount = 2;
            var vertices = new Vector3[columnCount * rowCount * sideCount];
            var uvs = new Vector2[vertices.Length];
            var frontZ = -thickness * 0.5f;
            var backZ = thickness * 0.5f;

            for (var column = 0; column < columnCount; column++)
            {
                var u = column / (float)(columnCount - 1);
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.5f, width * 0.5f, u) +
                    DistantPanoramaVistaSigned(seed + column * 23 + 5, 0.18f) * edgeFalloff;
                var moundA = Mathf.Clamp01(1f - Mathf.Abs(u - 0.26f) * 4.6f);
                var moundB = Mathf.Clamp01(1f - Mathf.Abs(u - 0.58f) * 5.0f);
                var moundC = Mathf.Clamp01(1f - Mathf.Abs(u - 0.82f) * 5.4f);
                var mound = Mathf.Max(moundA * 0.76f, Mathf.Max(moundB, moundC * 0.70f));
                var crown = height * Mathf.Clamp(0.42f + edgeFalloff * 0.22f + mound * 0.44f, 0.34f, 1.08f);
                var shoulder = crown * Mathf.Lerp(0.42f, 0.64f, DistantPanoramaVistaHash01(seed + column * 37 + 11));
                if (column == 0 || column == columnCount - 1)
                {
                    crown *= 0.42f;
                    shoulder *= 0.48f;
                }

                for (var side = 0; side < sideCount; side++)
                {
                    var z = side == 0 ? frontZ : backZ;
                    var sideHeightScale = side == 0 ? 1f : Mathf.Lerp(0.86f, 0.96f, DistantPanoramaVistaHash01(seed + column * 43 + 17));
                    for (var row = 0; row < rowCount; row++)
                    {
                        var v = row / (float)(rowCount - 1);
                        var y = 0f;
                        if (row == 1)
                        {
                            y = Mathf.Max(0.04f, shoulder * 0.54f);
                        }
                        else if (row == 2)
                        {
                            y = Mathf.Max(0.08f, shoulder);
                        }
                        else if (row == 3)
                        {
                            y = crown * sideHeightScale;
                        }

                        var vertexIndex = ((side * rowCount) + row) * columnCount + column;
                        vertices[vertexIndex] = new Vector3(x, y, z);
                        uvs[vertexIndex] = new Vector2(u, v);
                    }
                }
            }

            var triangles = new List<int>((columnCount - 1) * (rowCount - 1) * 24);
            for (var column = 0; column < columnCount - 1; column++)
            {
                for (var row = 0; row < rowCount - 1; row++)
                {
                    var a = row * columnCount + column;
                    var b = row * columnCount + column + 1;
                    var c = (row + 1) * columnCount + column;
                    var d = (row + 1) * columnCount + column + 1;
                    AddDoubleSidedQuad(triangles, a, b, c, d);

                    var backOffset = rowCount * columnCount;
                    AddDoubleSidedQuad(triangles, backOffset + a, backOffset + c, backOffset + b, backOffset + d);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static float GetMidDistanceLandformClosureRadiusScale(FastVsHouseArea area)
        {
            switch (area)
            {
                case FastVsHouseArea.CentralPlaza:
                    return 1.12f;
                case FastVsHouseArea.MiaHouse:
                    return 0.96f;
                case FastVsHouseArea.AriaStreet:
                    return 1.24f;
                case FastVsHouseArea.KaiaFarm:
                    return 1.26f;
                case FastVsHouseArea.Ruins:
                    return 1.52f;
                case FastVsHouseArea.Exterior:
                default:
                    return 1.00f;
            }
        }

        private static float GetMidDistanceLandformClosurePathRadiusScale(FastVsHouseArea area)
        {
            switch (area)
            {
                case FastVsHouseArea.AriaStreet:
                case FastVsHouseArea.KaiaFarm:
                    return 1.18f;
                case FastVsHouseArea.Ruins:
                    return 1.42f;
                case FastVsHouseArea.CentralPlaza:
                    return 1.08f;
                case FastVsHouseArea.MiaHouse:
                    return 0.95f;
                case FastVsHouseArea.Exterior:
                default:
                    return 1.00f;
            }
        }

        private static float GetMidDistanceLandformClosureAreaPhase(FastVsHouseArea area)
        {
            switch (area)
            {
                case FastVsHouseArea.Exterior:
                    return 3.0f * Mathf.Deg2Rad;
                case FastVsHouseArea.CentralPlaza:
                    return -4.0f * Mathf.Deg2Rad;
                case FastVsHouseArea.MiaHouse:
                    return 5.0f * Mathf.Deg2Rad;
                case FastVsHouseArea.AriaStreet:
                    return -2.5f * Mathf.Deg2Rad;
                case FastVsHouseArea.KaiaFarm:
                    return 6.5f * Mathf.Deg2Rad;
                case FastVsHouseArea.Ruins:
                    return -6.0f * Mathf.Deg2Rad;
                default:
                    return 0f;
            }
        }

        private static float GetMidDistanceLandformClosurePathCenterAngle(FastVsHouseArea area)
        {
            switch (area)
            {
                case FastVsHouseArea.Exterior:
                    return 32.0f * Mathf.Deg2Rad;
                case FastVsHouseArea.CentralPlaza:
                    return -6.0f * Mathf.Deg2Rad;
                case FastVsHouseArea.MiaHouse:
                    return -14.0f * Mathf.Deg2Rad;
                case FastVsHouseArea.AriaStreet:
                    return 10.0f * Mathf.Deg2Rad;
                case FastVsHouseArea.KaiaFarm:
                    return 13.0f * Mathf.Deg2Rad;
                case FastVsHouseArea.Ruins:
                    return -5.0f * Mathf.Deg2Rad;
                default:
                    return 0f;
            }
        }

        private static void ApplyMidDistanceLandformClosureRendererPolicy(Transform parent)
        {
            var expectedLayer = parent.gameObject.layer;
            foreach (var transform in parent.GetComponentsInChildren<Transform>(true))
            {
                transform.gameObject.layer = expectedLayer;
            }

            foreach (var renderer in parent.GetComponentsInChildren<Renderer>(true))
            {
                renderer.shadowCastingMode = ShadowCastingMode.Off;
                renderer.receiveShadows = false;
            }
        }

        private static void CreateChapter1PhaseFForegroundShorelineClosureForOutdoorMaps(
            Transform exteriorRoot,
            Transform plazaRoot,
            Transform miaHouseRoot,
            Transform ariaStreetRoot,
            Transform kaiaFarmRoot,
            Transform ruinsRoot,
            string prefix,
            bool past,
            Materials materials)
        {
            _ = materials;

            CreateChapter1PhaseFForegroundShorelineClosure(exteriorRoot, prefix, past, FastVsHouseArea.Exterior);
            CreateChapter1PhaseFForegroundShorelineClosure(plazaRoot, prefix, past, FastVsHouseArea.CentralPlaza);
            CreateChapter1PhaseFForegroundShorelineClosure(miaHouseRoot, prefix, past, FastVsHouseArea.MiaHouse);
            CreateChapter1PhaseFForegroundShorelineClosure(ariaStreetRoot, prefix, past, FastVsHouseArea.AriaStreet);
            CreateChapter1PhaseFForegroundShorelineClosure(kaiaFarmRoot, prefix, past, FastVsHouseArea.KaiaFarm);
            CreateChapter1PhaseFForegroundShorelineClosure(ruinsRoot, prefix, past, FastVsHouseArea.Ruins);
        }

        private static void CreateChapter1PhaseFForegroundShorelineClosure(Transform mapRoot, string prefix, bool past, FastVsHouseArea area)
        {
            var areaToken = GetDistantPanoramaVistaAreaToken(area);
            var center = GetDistantPanoramaVistaCenter(area);
            var parent = new GameObject($"{prefix}_{areaToken}_ForegroundShorelineClosure").transform;
            parent.SetParent(mapRoot, false);
            parent.localPosition = Vector3.zero;
            parent.localRotation = Quaternion.identity;
            parent.localScale = Vector3.one;
            parent.gameObject.layer = past ? OtherTimeSpaceRenderLayer : CurrentSpaceRenderLayer;

            var scale = GetForegroundShorelineClosureScale(area);
            var terrainMaterial = EnsureForegroundShorelineClosureTerrainMaterial(past);
            var pathMaterial = EnsureForegroundShorelineClosurePathMaterial(past);
            var stoneMaterial = EnsureForegroundShorelineClosureStoneMaterial(past);
            var reedMaterial = EnsureForegroundShorelineClosureReedMaterial(past);
            var scope = $"{prefix}.{areaToken.ToLowerInvariant()}.foreground_shoreline_closure";

            for (var index = 0; index < ForegroundShorelineClosureFrontSkirtCount; index++)
            {
                var seed = 17891 + (int)area * 421 + (past ? 1693 : 0) + index * 89;
                var spread = (index - (ForegroundShorelineClosureFrontSkirtCount - 1) * 0.5f) * 3.45f * scale;
                var position = center + new Vector3(
                    spread + DistantPanoramaVistaSigned(seed + 5, 0.34f * scale),
                    0.238f + DistantPanoramaVistaHash01(seed + 11) * 0.034f,
                    -7.35f * scale + DistantPanoramaVistaSigned(seed + 17, 0.42f * scale));
                var width = Mathf.Lerp(4.2f, 5.8f, DistantPanoramaVistaHash01(seed + 23)) * scale;
                var depth = Mathf.Lerp(2.2f, 3.4f, DistantPanoramaVistaHash01(seed + 29)) * scale;
                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_ForegroundShorelineClosure_FrontSkirt_S{index + 1:00}",
                    parent,
                    position,
                    Quaternion.Euler(0f, DistantPanoramaVistaSigned(seed + 31, 5.5f), 0f),
                    CreateMidDistanceLandformClosureShelfMesh(
                        $"{prefix}_{areaToken}_ForegroundShorelineClosure_FrontSkirt_S{index + 1:00}_Mesh",
                        seed,
                        width,
                        depth,
                        Mathf.Lerp(0.12f, 0.24f, DistantPanoramaVistaHash01(seed + 37))),
                    terrainMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PathOrFloor,
                    $"{scope}.front_skirt.s{index + 1:00}");
            }

            for (var index = 0; index < ForegroundShorelineClosureSideReturnCount; index++)
            {
                var seed = 19319 + (int)area * 443 + (past ? 1747 : 0) + index * 97;
                var leftSide = index < ForegroundShorelineClosureSideReturnCount / 2;
                var sideIndex = leftSide ? index : index - ForegroundShorelineClosureSideReturnCount / 2;
                var sideSign = leftSide ? -1f : 1f;
                var position = center + new Vector3(
                    sideSign * (9.70f * scale + DistantPanoramaVistaSigned(seed + 5, 0.32f * scale)),
                    0.226f + DistantPanoramaVistaHash01(seed + 11) * 0.032f,
                    Mathf.Lerp(-5.4f, 2.8f, sideIndex / 1f) * scale + DistantPanoramaVistaSigned(seed + 17, 0.50f * scale));
                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_ForegroundShorelineClosure_SideReturn_S{index + 1:00}",
                    parent,
                    position,
                    Quaternion.Euler(0f, 90f + sideSign * DistantPanoramaVistaSigned(seed + 23, 5.0f), 0f),
                    CreateMidDistanceLandformClosureShelfMesh(
                        $"{prefix}_{areaToken}_ForegroundShorelineClosure_SideReturn_S{index + 1:00}_Mesh",
                        seed,
                        Mathf.Lerp(4.8f, 6.4f, DistantPanoramaVistaHash01(seed + 29)) * scale,
                        Mathf.Lerp(1.8f, 2.8f, DistantPanoramaVistaHash01(seed + 31)) * scale,
                        Mathf.Lerp(0.10f, 0.22f, DistantPanoramaVistaHash01(seed + 37))),
                    terrainMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PathOrFloor,
                    $"{scope}.side_return.s{index + 1:00}");
            }

            var pathX = GetForegroundShorelineClosurePathX(area) * scale;
            for (var index = 0; index < ForegroundShorelineClosurePathTongueCount; index++)
            {
                var seed = 20903 + (int)area * 467 + (past ? 1811 : 0) + index * 101;
                var position = center + new Vector3(
                    pathX + (index - 1) * 0.58f * scale + DistantPanoramaVistaSigned(seed + 5, 0.18f * scale),
                    0.268f + index * 0.010f,
                    (-5.45f - index * 0.84f) * scale + DistantPanoramaVistaSigned(seed + 11, 0.18f * scale));
                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_ForegroundShorelineClosure_PathTongue_S{index + 1:00}",
                    parent,
                    position,
                    Quaternion.Euler(0f, GetForegroundShorelineClosurePathYaw(area) + DistantPanoramaVistaSigned(seed + 17, 4.0f), 0f),
                    CreateMidDistanceLandformClosureShelfMesh(
                        $"{prefix}_{areaToken}_ForegroundShorelineClosure_PathTongue_S{index + 1:00}_Mesh",
                        seed,
                        Mathf.Lerp(2.80f, 4.10f, DistantPanoramaVistaHash01(seed + 23)) * scale,
                        Mathf.Lerp(3.80f, 5.80f, DistantPanoramaVistaHash01(seed + 29)) * scale,
                        Mathf.Lerp(0.055f, 0.120f, DistantPanoramaVistaHash01(seed + 31))),
                    pathMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PathOrFloor,
                    $"{scope}.path_tongue.s{index + 1:00}");
            }

            for (var index = 0; index < ForegroundShorelineClosureStoneBreakCount; index++)
            {
                var seed = 22511 + (int)area * 487 + (past ? 1873 : 0) + index * 103;
                var frontT = index / (float)(ForegroundShorelineClosureStoneBreakCount - 1);
                var sideBias = index % 3 == 0 ? -1f : (index % 3 == 1 ? 1f : 0f);
                var position = center + new Vector3(
                    Mathf.Lerp(-7.8f, 7.8f, frontT) * scale + sideBias * DistantPanoramaVistaHash01(seed + 5) * 0.64f * scale,
                    0.286f + DistantPanoramaVistaHash01(seed + 11) * 0.044f,
                    (-6.76f + DistantPanoramaVistaSigned(seed + 17, 0.54f)) * scale);
                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_ForegroundShorelineClosure_StoneBreak_S{index + 1:00}",
                    parent,
                    position,
                    Quaternion.Euler(0f, DistantPanoramaVistaSigned(seed + 23, 28f), 0f),
                    CreateMidDistanceLandformClosureLowBankMesh(
                        $"{prefix}_{areaToken}_ForegroundShorelineClosure_StoneBreak_S{index + 1:00}_Mesh",
                        seed,
                        Mathf.Lerp(1.20f, 2.35f, DistantPanoramaVistaHash01(seed + 29)) * scale,
                        Mathf.Lerp(0.28f, 0.62f, DistantPanoramaVistaHash01(seed + 31)),
                        Mathf.Lerp(0.32f, 0.74f, DistantPanoramaVistaHash01(seed + 37)) * scale),
                    stoneMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{scope}.stone_break.s{index + 1:00}");
            }

            for (var index = 0; index < ForegroundShorelineClosureReedFoldCount; index++)
            {
                var seed = 24169 + (int)area * 503 + (past ? 1931 : 0) + index * 107;
                var leftCluster = index < ForegroundShorelineClosureReedFoldCount / 2;
                var clusterIndex = leftCluster ? index : index - ForegroundShorelineClosureReedFoldCount / 2;
                var sideSign = leftCluster ? -1f : 1f;
                var position = center + new Vector3(
                    sideSign * (6.0f + clusterIndex * 1.15f) * scale + DistantPanoramaVistaSigned(seed + 5, 0.34f * scale),
                    0.292f + DistantPanoramaVistaHash01(seed + 11) * 0.050f,
                    (-6.12f - clusterIndex * 0.52f) * scale + DistantPanoramaVistaSigned(seed + 17, 0.24f * scale));
                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_ForegroundShorelineClosure_ReedFold_S{index + 1:00}",
                    parent,
                    position,
                    Quaternion.Euler(0f, sideSign * 7.0f + DistantPanoramaVistaSigned(seed + 23, 8.0f), 0f),
                    CreateDistantPanoramaVistaTreelineFoldMesh(
                        $"{prefix}_{areaToken}_ForegroundShorelineClosure_ReedFold_S{index + 1:00}_Mesh",
                        seed,
                        Mathf.Lerp(1.80f, 3.20f, DistantPanoramaVistaHash01(seed + 29)) * scale,
                        Mathf.Lerp(0.85f, 1.75f, DistantPanoramaVistaHash01(seed + 31)) * (past ? 1.06f : 1f),
                        0.42f),
                    reedMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{scope}.reed_fold.s{index + 1:00}");
            }

            ApplyForegroundShorelineClosureRendererPolicy(parent);
        }

        private static float GetForegroundShorelineClosureScale(FastVsHouseArea area)
        {
            switch (area)
            {
                case FastVsHouseArea.CentralPlaza:
                    return 1.12f;
                case FastVsHouseArea.MiaHouse:
                    return 0.96f;
                case FastVsHouseArea.AriaStreet:
                    return 1.34f;
                case FastVsHouseArea.KaiaFarm:
                    return 1.40f;
                case FastVsHouseArea.Ruins:
                    return 1.84f;
                case FastVsHouseArea.Exterior:
                default:
                    return 1.00f;
            }
        }

        private static float GetForegroundShorelineClosurePathX(FastVsHouseArea area)
        {
            switch (area)
            {
                case FastVsHouseArea.Exterior:
                    return 2.8f;
                case FastVsHouseArea.CentralPlaza:
                    return -0.8f;
                case FastVsHouseArea.MiaHouse:
                    return -1.6f;
                case FastVsHouseArea.AriaStreet:
                    return 1.8f;
                case FastVsHouseArea.KaiaFarm:
                    return -3.2f;
                case FastVsHouseArea.Ruins:
                    return 0.8f;
                default:
                    return 0f;
            }
        }

        private static float GetForegroundShorelineClosurePathYaw(FastVsHouseArea area)
        {
            switch (area)
            {
                case FastVsHouseArea.Exterior:
                    return -14f;
                case FastVsHouseArea.MiaHouse:
                    return 8f;
                case FastVsHouseArea.AriaStreet:
                    return -7f;
                case FastVsHouseArea.KaiaFarm:
                    return 12f;
                case FastVsHouseArea.Ruins:
                    return -4f;
                case FastVsHouseArea.CentralPlaza:
                default:
                    return 0f;
            }
        }

        private static void ApplyForegroundShorelineClosureRendererPolicy(Transform parent)
        {
            var expectedLayer = parent.gameObject.layer;
            foreach (var transform in parent.GetComponentsInChildren<Transform>(true))
            {
                transform.gameObject.layer = expectedLayer;
            }

            foreach (var renderer in parent.GetComponentsInChildren<Renderer>(true))
            {
                renderer.shadowCastingMode = ShadowCastingMode.Off;
                renderer.receiveShadows = false;
            }
        }

        private static void CreateChapter1PhaseGForegroundEdgeBreakupForOutdoorMaps(
            Transform exteriorRoot,
            Transform plazaRoot,
            Transform miaHouseRoot,
            Transform ariaStreetRoot,
            Transform kaiaFarmRoot,
            Transform ruinsRoot,
            string prefix,
            bool past,
            Materials materials)
        {
            CreateChapter1PhaseGForegroundEdgeBreakup(exteriorRoot, prefix, past, FastVsHouseArea.Exterior);
            CreateChapter1PhaseGForegroundEdgeBreakup(plazaRoot, prefix, past, FastVsHouseArea.CentralPlaza);
            CreateChapter1PhaseGForegroundEdgeBreakup(miaHouseRoot, prefix, past, FastVsHouseArea.MiaHouse);
            CreateChapter1PhaseGForegroundEdgeBreakup(ariaStreetRoot, prefix, past, FastVsHouseArea.AriaStreet);
            CreateChapter1PhaseGForegroundEdgeBreakup(kaiaFarmRoot, prefix, past, FastVsHouseArea.KaiaFarm);
            CreateChapter1PhaseGForegroundEdgeBreakup(ruinsRoot, prefix, past, FastVsHouseArea.Ruins);
        }

        private static void CreateChapter1PhaseGForegroundEdgeBreakup(Transform mapRoot, string prefix, bool past, FastVsHouseArea area)
        {
            var areaToken = GetDistantPanoramaVistaAreaToken(area);
            var center = GetDistantPanoramaVistaCenter(area);
            var parent = new GameObject($"{prefix}_{areaToken}_ForegroundEdgeBreakup").transform;
            parent.SetParent(mapRoot, false);
            parent.localPosition = Vector3.zero;
            parent.localRotation = Quaternion.identity;
            parent.localScale = Vector3.one;
            parent.gameObject.layer = past ? OtherTimeSpaceRenderLayer : CurrentSpaceRenderLayer;

            var scale = GetForegroundShorelineClosureScale(area);
            var terrainMaterial = EnsureForegroundEdgeBreakupTerrainMaterial(past);
            var pathMaterial = EnsureForegroundEdgeBreakupPathMaterial(past);
            var detailMaterial = EnsureForegroundEdgeBreakupDetailMaterial(past);
            var scope = $"{prefix}.{areaToken.ToLowerInvariant()}.foreground_edge_breakup";

            for (var index = 0; index < ForegroundEdgeBreakupGroundPatchCount; index++)
            {
                var seed = 25703 + (int)area * 557 + (past ? 2069 : 0) + index * 109;
                var t = index / (float)(ForegroundEdgeBreakupGroundPatchCount - 1);
                var x = Mathf.Lerp(-8.8f, 8.8f, t) * scale + DistantPanoramaVistaSigned(seed + 5, 0.44f * scale);
                var z = Mathf.Lerp(-7.10f, -5.50f, DistantPanoramaVistaHash01(seed + 11)) * scale;
                var width = Mathf.Lerp(3.1f, 5.2f, DistantPanoramaVistaHash01(seed + 17)) * scale;
                var depth = Mathf.Lerp(1.5f, 2.5f, DistantPanoramaVistaHash01(seed + 23)) * scale;
                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_ForegroundEdgeBreakup_GroundPatch_S{index + 1:00}",
                    parent,
                    center + new Vector3(x, 0.365f + DistantPanoramaVistaHash01(seed + 29) * 0.026f, z),
                    Quaternion.Euler(0f, DistantPanoramaVistaSigned(seed + 31, 10.5f), 0f),
                    CreateMidDistanceLandformClosureShelfMesh(
                        $"{prefix}_{areaToken}_ForegroundEdgeBreakup_GroundPatch_S{index + 1:00}_Mesh",
                        seed,
                        width,
                        depth,
                        Mathf.Lerp(0.035f, 0.075f, DistantPanoramaVistaHash01(seed + 37))),
                    terrainMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PathOrFloor,
                    $"{scope}.ground_patch.s{index + 1:00}");
            }

            var pathX = GetForegroundShorelineClosurePathX(area) * scale;
            for (var index = 0; index < ForegroundEdgeBreakupPathPatchCount; index++)
            {
                var seed = 27329 + (int)area * 577 + (past ? 2111 : 0) + index * 113;
                var x = pathX + (index - (ForegroundEdgeBreakupPathPatchCount - 1) * 0.5f) * 0.86f * scale +
                    DistantPanoramaVistaSigned(seed + 5, 0.24f * scale);
                var z = (-5.78f - index * 0.22f) * scale + DistantPanoramaVistaSigned(seed + 11, 0.22f * scale);
                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_ForegroundEdgeBreakup_PathPatch_S{index + 1:00}",
                    parent,
                    center + new Vector3(x, 0.388f + index * 0.004f, z),
                    Quaternion.Euler(0f, GetForegroundShorelineClosurePathYaw(area) + DistantPanoramaVistaSigned(seed + 17, 7.0f), 0f),
                    CreateMidDistanceLandformClosureShelfMesh(
                        $"{prefix}_{areaToken}_ForegroundEdgeBreakup_PathPatch_S{index + 1:00}_Mesh",
                        seed,
                        Mathf.Lerp(1.45f, 2.65f, DistantPanoramaVistaHash01(seed + 23)) * scale,
                        Mathf.Lerp(1.20f, 2.40f, DistantPanoramaVistaHash01(seed + 29)) * scale,
                        Mathf.Lerp(0.025f, 0.060f, DistantPanoramaVistaHash01(seed + 31))),
                    pathMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PathOrFloor,
                    $"{scope}.path_patch.s{index + 1:00}");
            }

            for (var index = 0; index < ForegroundEdgeBreakupDetailPatchCount; index++)
            {
                var seed = 29101 + (int)area * 593 + (past ? 2161 : 0) + index * 127;
                var side = index % 2 == 0 ? -1f : 1f;
                var band = index / (float)(ForegroundEdgeBreakupDetailPatchCount - 1);
                var x = side * Mathf.Lerp(3.2f, 7.0f, band) * scale + DistantPanoramaVistaSigned(seed + 5, 0.32f * scale);
                var z = Mathf.Lerp(-6.98f, -5.26f, DistantPanoramaVistaHash01(seed + 11)) * scale;
                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_ForegroundEdgeBreakup_DetailPatch_S{index + 1:00}",
                    parent,
                    center + new Vector3(x, 0.405f + DistantPanoramaVistaHash01(seed + 17) * 0.030f, z),
                    Quaternion.Euler(0f, side * 12f + DistantPanoramaVistaSigned(seed + 23, 18f), 0f),
                    CreateMidDistanceLandformClosureLowBankMesh(
                        $"{prefix}_{areaToken}_ForegroundEdgeBreakup_DetailPatch_S{index + 1:00}_Mesh",
                        seed,
                        Mathf.Lerp(1.35f, 2.75f, DistantPanoramaVistaHash01(seed + 29)) * scale,
                        Mathf.Lerp(0.22f, 0.44f, DistantPanoramaVistaHash01(seed + 31)),
                        Mathf.Lerp(0.28f, 0.58f, DistantPanoramaVistaHash01(seed + 37)) * scale),
                    detailMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{scope}.detail_patch.s{index + 1:00}");
            }

            ApplyForegroundEdgeBreakupRendererPolicy(parent);
        }

        private static void ApplyForegroundEdgeBreakupRendererPolicy(Transform parent)
        {
            var expectedLayer = parent.gameObject.layer;
            foreach (var transform in parent.GetComponentsInChildren<Transform>(true))
            {
                transform.gameObject.layer = expectedLayer;
            }

            foreach (var renderer in parent.GetComponentsInChildren<Renderer>(true))
            {
                renderer.shadowCastingMode = ShadowCastingMode.Off;
                renderer.receiveShadows = false;
            }
        }

        private static void CreateChapter1PhaseHFarShoreHoleClosureForOutdoorMaps(
            Transform exteriorRoot,
            Transform plazaRoot,
            Transform miaHouseRoot,
            Transform ariaStreetRoot,
            Transform kaiaFarmRoot,
            Transform ruinsRoot,
            string prefix,
            bool past,
            Materials materials)
        {
            _ = materials;

            CreateChapter1PhaseHFarShoreHoleClosure(exteriorRoot, prefix, past, FastVsHouseArea.Exterior);
            CreateChapter1PhaseHFarShoreHoleClosure(plazaRoot, prefix, past, FastVsHouseArea.CentralPlaza);
            CreateChapter1PhaseHFarShoreHoleClosure(miaHouseRoot, prefix, past, FastVsHouseArea.MiaHouse);
            CreateChapter1PhaseHFarShoreHoleClosure(ariaStreetRoot, prefix, past, FastVsHouseArea.AriaStreet);
            CreateChapter1PhaseHFarShoreHoleClosure(kaiaFarmRoot, prefix, past, FastVsHouseArea.KaiaFarm);
            CreateChapter1PhaseHFarShoreHoleClosure(ruinsRoot, prefix, past, FastVsHouseArea.Ruins);
        }

        private static void CreateChapter1PhaseHFarShoreHoleClosure(Transform mapRoot, string prefix, bool past, FastVsHouseArea area)
        {
            var areaToken = GetDistantPanoramaVistaAreaToken(area);
            var center = GetDistantPanoramaVistaCenter(area);
            var parent = new GameObject($"{prefix}_{areaToken}_FarShoreHoleClosure").transform;
            parent.SetParent(mapRoot, false);
            parent.localPosition = Vector3.zero;
            parent.localRotation = Quaternion.identity;
            parent.localScale = Vector3.one;
            parent.gameObject.layer = past ? OtherTimeSpaceRenderLayer : CurrentSpaceRenderLayer;

            var baseAngle = GetFarShoreHoleClosureBaseAngle(area);
            var radiusScale = GetFarShoreHoleClosureRadiusScale(area);
            var widthScale = GetFarShoreHoleClosureWidthScale(area);
            var terrainMaterial = EnsureFarShoreHoleClosureTerrainMaterial(past);
            var bankMaterial = EnsureFarShoreHoleClosureBankMaterial(past);
            var coppiceMaterial = EnsureFarShoreHoleClosureCoppiceMaterial(past);
            var scope = $"{prefix}.{areaToken.ToLowerInvariant()}.far_shore_hole_closure";

            for (var index = 0; index < FarShoreHoleClosureShelfCount; index++)
            {
                var seed = 31847 + (int)area * 631 + (past ? 2309 : 0) + index * 139;
                var t = index / (float)(FarShoreHoleClosureShelfCount - 1);
                var angle = baseAngle +
                    Mathf.Lerp(-16.0f, 18.0f, t) * Mathf.Deg2Rad +
                    DistantPanoramaVistaSigned(seed + 5, 1.9f) * Mathf.Deg2Rad;
                var radial = new Vector3(Mathf.Sin(angle), 0f, Mathf.Cos(angle));
                var tangent = new Vector3(radial.z, 0f, -radial.x);
                var radius = (20.6f + index * 1.12f + DistantPanoramaVistaSigned(seed + 11, 0.82f)) * radiusScale;
                var position = center +
                    radial * radius +
                    tangent * DistantPanoramaVistaSigned(seed + 17, 0.92f * widthScale) +
                    new Vector3(0f, 0.145f + DistantPanoramaVistaHash01(seed + 23) * 0.055f, 0f);

                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_FarShoreHoleClosure_TerrainShelf_S{index + 1:00}",
                    parent,
                    position,
                    MidDistanceLandformClosureFacingRotation(center, position, -radial),
                    CreateMidDistanceLandformClosureShelfMesh(
                        $"{prefix}_{areaToken}_FarShoreHoleClosure_TerrainShelf_S{index + 1:00}_Mesh",
                        seed,
                        Mathf.Lerp(5.6f, 9.2f, DistantPanoramaVistaHash01(seed + 29)) * widthScale,
                        Mathf.Lerp(3.8f, 6.4f, DistantPanoramaVistaHash01(seed + 31)) * radiusScale,
                        Mathf.Lerp(0.10f, 0.24f, DistantPanoramaVistaHash01(seed + 37))),
                    terrainMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PathOrFloor,
                    $"{scope}.terrain_shelf.s{index + 1:00}");
            }

            for (var index = 0; index < FarShoreHoleClosureBankCount; index++)
            {
                var seed = 33971 + (int)area * 653 + (past ? 2371 : 0) + index * 149;
                var t = index / (float)(FarShoreHoleClosureBankCount - 1);
                var angle = baseAngle +
                    Mathf.Lerp(-11.0f, 15.0f, t) * Mathf.Deg2Rad +
                    DistantPanoramaVistaSigned(seed + 5, 1.4f) * Mathf.Deg2Rad;
                var radial = new Vector3(Mathf.Sin(angle), 0f, Mathf.Cos(angle));
                var tangent = new Vector3(radial.z, 0f, -radial.x);
                var radius = (24.4f + index * 1.55f + DistantPanoramaVistaSigned(seed + 11, 0.74f)) * radiusScale;
                var position = center +
                    radial * radius +
                    tangent * DistantPanoramaVistaSigned(seed + 17, 0.72f * widthScale) +
                    new Vector3(0f, 0.215f + DistantPanoramaVistaHash01(seed + 23) * 0.075f, 0f);

                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_FarShoreHoleClosure_LowBank_S{index + 1:00}",
                    parent,
                    position,
                    MidDistanceLandformClosureFacingRotation(center, position, -radial),
                    CreateMidDistanceLandformClosureLowBankMesh(
                        $"{prefix}_{areaToken}_FarShoreHoleClosure_LowBank_S{index + 1:00}_Mesh",
                        seed,
                        Mathf.Lerp(4.2f, 7.4f, DistantPanoramaVistaHash01(seed + 29)) * widthScale,
                        Mathf.Lerp(0.62f, 1.22f, DistantPanoramaVistaHash01(seed + 31)) * (past ? 1.05f : 1f),
                        Mathf.Lerp(0.55f, 0.98f, DistantPanoramaVistaHash01(seed + 37)) * radiusScale),
                    bankMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                    $"{scope}.low_bank.s{index + 1:00}");
            }

            for (var index = 0; index < FarShoreHoleClosureCoppiceCount; index++)
            {
                var seed = 36109 + (int)area * 677 + (past ? 2441 : 0) + index * 157;
                var t = index / (float)(FarShoreHoleClosureCoppiceCount - 1);
                var angle = baseAngle +
                    Mathf.Lerp(-18.0f, 20.0f, t) * Mathf.Deg2Rad +
                    DistantPanoramaVistaSigned(seed + 5, 1.6f) * Mathf.Deg2Rad;
                var radial = new Vector3(Mathf.Sin(angle), 0f, Mathf.Cos(angle));
                var tangent = new Vector3(radial.z, 0f, -radial.x);
                var radius = (26.2f + DistantPanoramaVistaSigned(seed + 11, 1.20f)) * radiusScale;
                var position = center +
                    radial * radius +
                    tangent * DistantPanoramaVistaSigned(seed + 17, 1.05f * widthScale) +
                    new Vector3(0f, 0.295f + DistantPanoramaVistaHash01(seed + 23) * 0.110f, 0f);

                CreateMidDistanceLandformClosurePiece(
                    $"{prefix}_{areaToken}_FarShoreHoleClosure_CoppiceFold_S{index + 1:00}",
                    parent,
                    position,
                    MidDistanceLandformClosureFacingRotation(center, position, -radial),
                    CreateDistantPanoramaVistaTreelineFoldMesh(
                        $"{prefix}_{areaToken}_FarShoreHoleClosure_CoppiceFold_S{index + 1:00}_Mesh",
                        seed,
                        Mathf.Lerp(4.0f, 7.8f, DistantPanoramaVistaHash01(seed + 29)) * widthScale,
                        Mathf.Lerp(1.28f, 2.42f, DistantPanoramaVistaHash01(seed + 31)) * (past ? 1.04f : 1f),
                        Mathf.Lerp(0.42f, 0.72f, DistantPanoramaVistaHash01(seed + 37)) * radiusScale),
                    coppiceMaterial,
                    TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
