        private static GameObject CreateAuthoredVegetationFeatureMesh(string objectName, Transform root, Vector3 localPosition, Vector3 localScale, Quaternion localRotation, Material material, string landmarkId, Mesh mesh)
        {
            var sceneObject = CreateAuthoredVegetationMesh(
                objectName,
                root,
                localPosition,
                localScale,
                localRotation,
                material,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                landmarkId,
                mesh);
            var landmark = sceneObject.GetComponent<TimeWindowPairedSpaceLandmark>();
            SerializedSet(landmark, "countsForArrival", false);
            return sceneObject;
        }

        private static void CreateDistantPanoramaVista(Transform root, string prefix, bool past, FastVsHouseArea area, Materials materials)
        {
            _ = materials;

            var areaToken = GetDistantPanoramaVistaAreaToken(area);
            var center = GetDistantPanoramaVistaCenter(area);
            var parent = new GameObject($"{prefix}_{areaToken}_DistantVista").transform;
            parent.SetParent(root, false);
            parent.localPosition = Vector3.zero;
            parent.localRotation = Quaternion.identity;
            parent.localScale = Vector3.one;
            parent.gameObject.layer = past ? OtherTimeSpaceRenderLayer : CurrentSpaceRenderLayer;

            CreateDistantPanoramaVistaTerrainApron(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaValleyThreads(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaMidgroundValleyBreaks(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaForegroundCoppices(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaNaturalTreeStands(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaNaturalConiferSpires(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaFoothillForest(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaAreaLandmarks(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaAreaSignatures(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaLandformFacets(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaCompositionPrototype(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaRidgeFacets(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaRidgeStrata(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaTreelineFolds(parent, prefix, past, area, areaToken, center);
            CreateDistantPanoramaVistaProductionDepthPrototype(parent, prefix, past, area, areaToken, center);

            for (var band = 0; band < DistantPanoramaVistaBandCount; band++)
            {
                var radius = GetDistantPanoramaVistaBandRadius(band);
                var height = band == 0 ? 3.10f : (band == 1 ? 5.85f : 8.90f);
                var thickness = band == 0 ? 0.92f : (band == 1 ? 0.76f : 0.58f);
                var material = EnsureDistantPanoramaVistaMaterial(past, band, area);
                var chordWidth = 2f * radius * Mathf.Tan(Mathf.PI / DistantPanoramaVistaSegmentCount) * 1.08f;

                for (var segment = 0; segment < DistantPanoramaVistaSegmentCount; segment++)
                {
                    var seed = 1009 + (int)area * 131 + (past ? 509 : 0) + band * 67 + segment * 17;
                    var angle = ((segment + 0.5f) / DistantPanoramaVistaSegmentCount) * Mathf.PI * 2f;
                    var radial = new Vector3(Mathf.Sin(angle), 0f, Mathf.Cos(angle));
                    var tangent = new Vector3(radial.z, 0f, -radial.x);
                    var radialJitter = DistantPanoramaVistaSigned(seed + 3, 2.25f);
                    var tangentJitter = DistantPanoramaVistaSigned(seed + 7, 1.15f);
                    var localPosition = center +
                        radial * (radius + radialJitter) +
                        tangent * tangentJitter +
                        new Vector3(0f, 0.10f + band * 0.05f, 0f);
                    var faceDirection = center - localPosition;
                    faceDirection.y = 0f;
                    if (faceDirection.sqrMagnitude < 0.01f)
                    {
                        faceDirection = -radial;
                    }

                    var segmentObject = new GameObject($"{prefix}_{areaToken}_DistantVista_B{band + 1}_S{segment + 1:00}");
                    segmentObject.transform.SetParent(parent, false);
                    segmentObject.transform.localPosition = localPosition;
                    segmentObject.transform.localRotation = Quaternion.LookRotation(faceDirection.normalized, Vector3.up);
                    segmentObject.transform.localScale = Vector3.one;
                    segmentObject.layer = past ? OtherTimeSpaceRenderLayer : CurrentSpaceRenderLayer;

                    var filter = segmentObject.AddComponent<MeshFilter>();
                    filter.sharedMesh = CreateDistantPanoramaVistaReliefMesh(
                        $"{segmentObject.name}_Mesh",
                        seed,
                        chordWidth,
                        height,
                        thickness,
                        band == 0);

                    var renderer = segmentObject.AddComponent<MeshRenderer>();
                    renderer.sharedMaterial = material;
                    renderer.shadowCastingMode = ShadowCastingMode.Off;
                    renderer.receiveShadows = false;

                    var landmark = segmentObject.AddComponent<TimeWindowPairedSpaceLandmark>();
                    SerializedSet(landmark, "landmarkId", $"{prefix}.{areaToken.ToLowerInvariant()}.distant_vista.b{band + 1}.s{segment + 1:00}");
                    SerializedSet(landmark, "kind", TimeWindowPairedSpaceLandmarkKind.PropOrFeature);
                    SerializedSet(landmark, "countsForArrival", false);
                }
            }

            ApplyDistantPanoramaVistaRendererPolicy(parent);
        }

        private static float GetDistantPanoramaVistaBandRadius(int band)
        {
            return band == 0 ? DistantPanoramaVistaNearRadius : (band == 1 ? DistantPanoramaVistaMidRadius : DistantPanoramaVistaFarRadius);
        }

        private static void ApplyDistantPanoramaVistaRendererPolicy(Transform parent)
        {
            foreach (var renderer in parent.GetComponentsInChildren<Renderer>(true))
            {
                renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
                renderer.receiveShadows = false;
            }
        }

        private static void ApplyDistantPanoramaVistaRendererPolicyForOutdoorRoots(params Transform[] roots)
        {
            foreach (var root in roots)
            {
                if (root == null)
                {
                    continue;
                }

                foreach (var renderer in root.GetComponentsInChildren<Renderer>(true))
                {
                    if (renderer == null ||
                        !renderer.gameObject.name.Contains("DistantVista", StringComparison.Ordinal))
                    {
                        continue;
                    }

                    renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
                    renderer.receiveShadows = false;
                }
            }
        }

