        private static void CreateDistantPanoramaVistaTerrainApron(Transform parent, string prefix, bool past, FastVsHouseArea area, string areaToken, Vector3 center)
        {
            var outerRadius = DistantPanoramaVistaForestRadius;
            var innerRadius = Mathf.Max(outerRadius - 8f, GetDistantPanoramaVistaTerrainApronInnerRadius(area));
            var outerWidth = 2f * outerRadius * Mathf.Tan(Mathf.PI / DistantPanoramaVistaSegmentCount) * 1.10f;
            var innerWidth = 2f * innerRadius * Mathf.Tan(Mathf.PI / DistantPanoramaVistaSegmentCount) * 1.18f;
            var material = EnsureDistantPanoramaVistaApronMaterial(past);

            for (var segment = 0; segment < DistantPanoramaVistaSegmentCount; segment++)
            {
                var seed = 1723 + (int)area * 149 + (past ? 601 : 0) + segment * 23;
                var angle = ((segment + 0.5f) / DistantPanoramaVistaSegmentCount) * Mathf.PI * 2f;
                var radial = new Vector3(Mathf.Sin(angle), 0f, Mathf.Cos(angle));
                var tangent = new Vector3(radial.z, 0f, -radial.x);
                var radialJitter = DistantPanoramaVistaSigned(seed + 5, 1.15f);
                var tangentJitter = DistantPanoramaVistaSigned(seed + 11, 0.75f);
                var localPosition = center +
                    radial * (outerRadius + radialJitter) +
                    tangent * tangentJitter +
                    new Vector3(0f, -0.12f, 0f);
                var faceDirection = center - localPosition;
                faceDirection.y = 0f;
                if (faceDirection.sqrMagnitude < 0.01f)
                {
                    faceDirection = -radial;
                }

                var segmentObject = new GameObject($"{prefix}_{areaToken}_DistantVista_TerrainApron_S{segment + 1:00}");
                segmentObject.transform.SetParent(parent, false);
                segmentObject.transform.localPosition = localPosition;
                segmentObject.transform.localRotation = Quaternion.LookRotation(faceDirection.normalized, Vector3.up);
                segmentObject.transform.localScale = Vector3.one;
                segmentObject.layer = past ? OtherTimeSpaceRenderLayer : CurrentSpaceRenderLayer;

                var filter = segmentObject.AddComponent<MeshFilter>();
                filter.sharedMesh = CreateDistantPanoramaVistaTerrainApronMesh(
                    $"{segmentObject.name}_Mesh",
                    seed,
                    outerWidth,
                    innerWidth,
                    Mathf.Max(outerRadius - innerRadius, 1f));

                var renderer = segmentObject.AddComponent<MeshRenderer>();
                renderer.sharedMaterial = material;
                renderer.shadowCastingMode = ShadowCastingMode.Off;
                renderer.receiveShadows = false;

                var landmark = segmentObject.AddComponent<TimeWindowPairedSpaceLandmark>();
                SerializedSet(landmark, "landmarkId", $"{prefix}.{areaToken.ToLowerInvariant()}.distant_vista.terrain_apron.s{segment + 1:00}");
                SerializedSet(landmark, "kind", TimeWindowPairedSpaceLandmarkKind.PropOrFeature);
                SerializedSet(landmark, "countsForArrival", false);
            }
        }

        private static void CreateDistantPanoramaVistaValleyThreads(Transform parent, string prefix, bool past, FastVsHouseArea area, string areaToken, Vector3 center)
        {
            var radius = DistantPanoramaVistaValleyThreadRadius;
            var material = EnsureDistantPanoramaVistaValleyThreadMaterial(past);
            var chordWidth = 2f * radius * Mathf.Tan(Mathf.PI / DistantPanoramaVistaSegmentCount) * 1.02f;

            for (var segment = 0; segment < DistantPanoramaVistaSegmentCount; segment++)
            {
                var seed = 1987 + (int)area * 173 + (past ? 653 : 0) + segment * 31;
                var angle = ((segment + 0.5f) / DistantPanoramaVistaSegmentCount) * Mathf.PI * 2f;
                var radial = new Vector3(Mathf.Sin(angle), 0f, Mathf.Cos(angle));
                var tangent = new Vector3(radial.z, 0f, -radial.x);
                var localPosition = center +
                    radial * (radius + DistantPanoramaVistaSigned(seed + 5, 0.42f)) +
                    tangent * DistantPanoramaVistaSigned(seed + 13, 1.15f) +
                    new Vector3(0f, -0.04f + DistantPanoramaVistaHash01(seed + 19) * 0.08f, 0f);
                var faceDirection = center - localPosition;
                faceDirection.y = 0f;
                if (faceDirection.sqrMagnitude < 0.01f)
                {
                    faceDirection = -radial;
                }

                var segmentObject = new GameObject($"{prefix}_{areaToken}_DistantVista_ValleyThread_S{segment + 1:00}");
                segmentObject.transform.SetParent(parent, false);
                segmentObject.transform.localPosition = localPosition;
                segmentObject.transform.localRotation = Quaternion.LookRotation(faceDirection.normalized, Vector3.up);
                segmentObject.transform.localScale = Vector3.one;
                segmentObject.layer = past ? OtherTimeSpaceRenderLayer : CurrentSpaceRenderLayer;

                var filter = segmentObject.AddComponent<MeshFilter>();
                filter.sharedMesh = CreateDistantPanoramaVistaValleyThreadMesh(
                    $"{segmentObject.name}_Mesh",
                    seed,
                    chordWidth * Mathf.Lerp(1.08f, 1.42f, DistantPanoramaVistaHash01(seed + 23)),
                    Mathf.Lerp(3.2f, 6.4f, DistantPanoramaVistaHash01(seed + 29)),
                    Mathf.Lerp(2.8f, 5.4f, DistantPanoramaVistaHash01(seed + 37)));

                var renderer = segmentObject.AddComponent<MeshRenderer>();
                renderer.sharedMaterial = material;
                renderer.shadowCastingMode = ShadowCastingMode.Off;
                renderer.receiveShadows = false;

                var landmark = segmentObject.AddComponent<TimeWindowPairedSpaceLandmark>();
                SerializedSet(landmark, "landmarkId", $"{prefix}.{areaToken.ToLowerInvariant()}.distant_vista.valley_thread.s{segment + 1:00}");
                SerializedSet(landmark, "kind", TimeWindowPairedSpaceLandmarkKind.PropOrFeature);
                SerializedSet(landmark, "countsForArrival", false);
            }
        }

        private static Mesh CreateDistantPanoramaVistaTerrainApronMesh(string meshName, int seed, float outerWidth, float innerWidth, float depth)
        {
            const int columnCount = 11;
            const int rowCount = 5;
            var vertices = new Vector3[columnCount * rowCount];
            var uvs = new Vector2[columnCount * rowCount];

            for (var row = 0; row < rowCount; row++)
            {
                var v = row / (float)(rowCount - 1);
                var rowWidth = Mathf.Lerp(outerWidth, innerWidth, v);
                var z = v * depth;
                for (var column = 0; column < columnCount; column++)
                {
                    var u = column / (float)(columnCount - 1);
                    var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                    var lowRise = Mathf.Lerp(0.10f, -0.18f, v);
                    var surfaceBreak = DistantPanoramaVistaSigned(seed + row * 41 + column * 13, 0.085f) * edgeFalloff;
                    var index = row * columnCount + column;
                    vertices[index] = new Vector3(
                        Mathf.Lerp(-rowWidth * 0.5f, rowWidth * 0.5f, u),
                        lowRise + surfaceBreak,
                        z);
                    uvs[index] = new Vector2(u, v);
                }
            }

            var triangles = new List<int>((columnCount - 1) * (rowCount - 1) * 12);
            for (var row = 0; row < rowCount - 1; row++)
            {
                for (var column = 0; column < columnCount - 1; column++)
                {
                    var a = row * columnCount + column;
                    var b = a + 1;
                    var c = (row + 1) * columnCount + column;
                    var d = c + 1;

                    triangles.Add(a);
                    triangles.Add(c);
                    triangles.Add(b);
                    triangles.Add(b);
                    triangles.Add(c);
                    triangles.Add(d);

                    triangles.Add(b);
                    triangles.Add(c);
                    triangles.Add(a);
                    triangles.Add(d);
                    triangles.Add(c);
                    triangles.Add(b);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaValleyThreadMesh(string meshName, int seed, float width, float depth, float bankHeight)
        {
            const int columnCount = 12;
            const int rowCount = 4;
            var vertices = new Vector3[columnCount * rowCount];
            var uvs = new Vector2[columnCount * rowCount];
            var diagonalLean = DistantPanoramaVistaSigned(seed + 43, 0.18f);
            var centerDrift = DistantPanoramaVistaSigned(seed + 47, 0.10f);

            for (var row = 0; row < rowCount; row++)
            {
                var v = row / (float)(rowCount - 1);
                var z = Mathf.Lerp(-depth * 0.38f, depth * 0.62f, v);
                var rowDrift = (v - 0.5f) * diagonalLean + Mathf.Sin(v * Mathf.PI) * centerDrift;
                var rowWidth = width * Mathf.Lerp(0.78f, 1.08f, Mathf.Sin(v * Mathf.PI));

                for (var column = 0; column < columnCount; column++)
                {
                    var u = column / (float)(columnCount - 1);
                    var x = Mathf.Lerp(-rowWidth * 0.5f, rowWidth * 0.5f, u) + rowDrift * width;
                    var centerLine = 0.50f + rowDrift * 0.46f;
                    var centerDistance = Mathf.Abs(u - 0.5f) * 2f;
                    var driftingDistance = Mathf.Abs(u - centerLine) * 2f;
                    var trough = Mathf.Clamp01(1f - driftingDistance);
                    var bank = Mathf.Clamp01(1f - Mathf.Abs(centerDistance - 0.68f) * 2.8f);
                    var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                    var ridge = bankHeight * (0.42f + bank * 0.58f);
                    var notch = bankHeight * trough * Mathf.Lerp(0.30f, 0.58f, DistantPanoramaVistaHash01(seed + row * 71 + column * 19));
                    var rowLift = row == 0 ? -0.18f : (row == 1 ? 0.42f : (row == 2 ? 0.78f : 1.00f));
                    var ripple = DistantPanoramaVistaSigned(seed + row * 59 + column * 17, 0.12f) * edgeFalloff;
                    var y = rowLift * bankHeight + ridge * v - notch * v + ripple;

                    if (row == 0)
                    {
                        y = -0.22f + ripple * 0.25f;
                    }
                    else if (column == 0 || column == columnCount - 1)
                    {
                        y *= 0.58f;
                    }

                    var index = row * columnCount + column;
                    vertices[index] = new Vector3(x, y, z);
                    uvs[index] = new Vector2(u, v);
                }
            }

            var triangles = new List<int>((columnCount - 1) * (rowCount - 1) * 12);
            for (var row = 0; row < rowCount - 1; row++)
            {
                for (var column = 0; column < columnCount - 1; column++)
                {
                    var a = row * columnCount + column;
                    var b = row * columnCount + column + 1;
                    var c = (row + 1) * columnCount + column;
                    var d = (row + 1) * columnCount + column + 1;
                    AddDoubleSidedQuad(triangles, a, b, c, d);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaMidgroundValleyMesh(string meshName, int seed, float width, float depth, float brushHeight)
        {
            const int columnCount = 13;
            const int rowCount = 6;
            var vertices = new Vector3[columnCount * rowCount];
            var uvs = new Vector2[columnCount * rowCount];

            for (var column = 0; column < columnCount; column++)
            {
                var u = column / (float)(columnCount - 1);
                var x = Mathf.Lerp(-width * 0.5f, width * 0.5f, u);
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var terraceNoise = DistantPanoramaVistaSigned(seed + column * 47, 0.08f) * edgeFalloff;
                var crownNoise = DistantPanoramaVistaHash01(seed + column * 61 + 7);
                var crownHeight = brushHeight * Mathf.Lerp(0.55f, 1.32f, crownNoise) * (0.48f + edgeFalloff * 0.52f);

                for (var row = 0; row < rowCount; row++)
                {
                    var v = row / (float)(rowCount - 1);
                    var z = depth * Mathf.Lerp(0f, 1f, v);
                    var y = -0.08f + terraceNoise * 0.30f;
                    if (row == 1)
                    {
                        y = 0.02f + terraceNoise;
                    }
                    else if (row == 2)
                    {
                        y = 0.14f + terraceNoise * 0.80f;
                    }
                    else if (row == 3)
                    {
                        y = 0.34f + terraceNoise * 0.55f;
                    }
                    else if (row == 4)
                    {
                        y = 0.54f + crownHeight;
                    }
                    else if (row == 5)
                    {
                        y = 0.18f + terraceNoise * 0.35f;
                    }

                    if (column == 0 || column == columnCount - 1)
                    {
                        y *= 0.45f;
                    }

                    var index = row * columnCount + column;
                    vertices[index] = new Vector3(x, y, z);
                    uvs[index] = new Vector2(u, v);
                }
            }

            var triangles = new List<int>((columnCount - 1) * (rowCount - 1) * 12);
            for (var row = 0; row < rowCount - 1; row++)
            {
                for (var column = 0; column < columnCount - 1; column++)
                {
                    var a = row * columnCount + column;
                    var b = row * columnCount + column + 1;
                    var c = (row + 1) * columnCount + column;
                    var d = (row + 1) * columnCount + column + 1;
                    AddDoubleSidedQuad(triangles, a, b, c, d);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaAreaLandmarkMesh(string meshName, int seed, int profile, float width, float maxHeight, float depth)
        {
            const int columnCount = 14;
            const int rowCount = 4;
            const int sideCount = 2;
            var vertices = new Vector3[columnCount * rowCount * sideCount];
            var uvs = new Vector2[columnCount * rowCount * sideCount];
            var frontZ = -depth * 0.5f;
            var backZ = depth * 0.5f;

            for (var column = 0; column < columnCount; column++)
            {
                var u = column / (float)(columnCount - 1);
                var x = Mathf.Lerp(-width * 0.5f, width * 0.5f, u);
                var height = GetDistantPanoramaVistaAreaLandmarkColumnHeight(profile, seed, column, u, maxHeight);
                var shoulderHeight = height * Mathf.Lerp(0.42f, 0.66f, DistantPanoramaVistaHash01(seed + column * 29 + 7));
                var baseLift = DistantPanoramaVistaSigned(seed + column * 31 + 11, 0.08f);

                for (var side = 0; side < sideCount; side++)
                {
                    var z = side == 0 ? frontZ : backZ;
                    var sideHeightScale = side == 0 ? 1f : 0.92f;
                    for (var row = 0; row < rowCount; row++)
                    {
                        var v = row / (float)(rowCount - 1);
                        var y = 0f;
                        if (row == 1)
                        {
                            y = Mathf.Max(0.06f, height * 0.22f + baseLift);
                        }
                        else if (row == 2)
                        {
                            y = Mathf.Max(0.12f, shoulderHeight + baseLift * 0.5f);
                        }
                        else if (row == 3)
                        {
                            y = height * sideHeightScale;
                        }

                        var vertexIndex = ((side * rowCount) + row) * columnCount + column;
                        vertices[vertexIndex] = new Vector3(x, y, z);
                        uvs[vertexIndex] = new Vector2(u, v);
                    }
                }
            }

            var triangles = new List<int>((columnCount - 1) * (rowCount - 1) * 24);
            for (var column = 0; column < columnCount - 1; column++)
            {
                for (var row = 0; row < rowCount - 1; row++)
                {
                    var a = row * columnCount + column;
                    var b = row * columnCount + column + 1;
                    var c = (row + 1) * columnCount + column;
                    var d = (row + 1) * columnCount + column + 1;
                    AddDoubleSidedQuad(triangles, a, b, c, d);

                    var backOffset = rowCount * columnCount;
                    AddDoubleSidedQuad(triangles, backOffset + a, backOffset + c, backOffset + b, backOffset + d);
                }

                var frontTopA = (rowCount - 1) * columnCount + column;
                var frontTopB = (rowCount - 1) * columnCount + column + 1;
                var backTopA = rowCount * columnCount + frontTopA;
                var backTopB = rowCount * columnCount + frontTopB;
                AddDoubleSidedQuad(triangles, frontTopA, frontTopB, backTopA, backTopB);
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaAreaSignatureMesh(string meshName, int seed, int profile, float width, float maxHeight, float depth)
        {
            const int columnCount = 16;
            const int rowCount = 5;
            const int sideCount = 2;
            var vertices = new Vector3[columnCount * rowCount * sideCount];
            var uvs = new Vector2[vertices.Length];
            var frontZ = -depth * 0.5f;
            var backZ = depth * 0.5f;

            for (var column = 0; column < columnCount; column++)
            {
                var u = column / (float)(columnCount - 1);
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.5f, width * 0.5f, u) +
                    DistantPanoramaVistaSigned(seed + column * 19, 0.22f) * edgeFalloff;
                var topHeight = GetDistantPanoramaVistaAreaSignatureColumnHeight(profile, seed, column, u, maxHeight);
                var shelfHeight = GetDistantPanoramaVistaAreaSignatureShelfHeight(profile, seed, column, u, topHeight);
                var baseLift = DistantPanoramaVistaSigned(seed + column * 31 + 11, 0.06f) * edgeFalloff;

                for (var side = 0; side < sideCount; side++)
                {
                    var z = side == 0 ? frontZ : backZ;
                    var sideHeightScale = side == 0 ? 1f : Mathf.Lerp(0.86f, 0.96f, DistantPanoramaVistaHash01(seed + column * 37 + 17));
                    for (var row = 0; row < rowCount; row++)
                    {
                        var v = row / (float)(rowCount - 1);
                        var y = 0f;
                        if (row == 1)
                        {
                            y = Mathf.Max(0.04f, topHeight * 0.14f + baseLift);
                        }
                        else if (row == 2)
                        {
                            y = Mathf.Max(0.08f, shelfHeight + baseLift * 0.65f);
                        }
                        else if (row == 3)
                        {
                            y = Mathf.Max(0.12f, Mathf.Lerp(shelfHeight, topHeight, 0.58f) + baseLift * 0.35f);
                        }
                        else if (row == 4)
                        {
                            y = topHeight * sideHeightScale;
                        }

                        var vertexIndex = ((side * rowCount) + row) * columnCount + column;
                        vertices[vertexIndex] = new Vector3(x, y, z);
                        uvs[vertexIndex] = new Vector2(u, v);
                    }
                }
            }

            var triangles = new List<int>((columnCount - 1) * (rowCount - 1) * 24);
            for (var column = 0; column < columnCount - 1; column++)
            {
                for (var row = 0; row < rowCount - 1; row++)
                {
                    var a = row * columnCount + column;
                    var b = row * columnCount + column + 1;
                    var c = (row + 1) * columnCount + column;
                    var d = (row + 1) * columnCount + column + 1;
                    AddDoubleSidedQuad(triangles, a, b, c, d);

                    var backOffset = rowCount * columnCount;
                    AddDoubleSidedQuad(triangles, backOffset + a, backOffset + c, backOffset + b, backOffset + d);
                }

                var frontTopA = (rowCount - 1) * columnCount + column;
                var frontTopB = (rowCount - 1) * columnCount + column + 1;
                var backTopA = rowCount * columnCount + frontTopA;
                var backTopB = rowCount * columnCount + frontTopB;
                AddDoubleSidedQuad(triangles, frontTopA, frontTopB, backTopA, backTopB);

                var frontBaseA = column;
                var frontBaseB = column + 1;
                var backBaseA = rowCount * columnCount + frontBaseA;
                var backBaseB = rowCount * columnCount + frontBaseB;
                AddDoubleSidedQuad(triangles, frontBaseA, backBaseA, frontBaseB, backBaseB);
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaCompositionPrototypeMesh(string meshName, int seed, int profile, float width, float maxHeight, float depth, bool past)
        {
            const int columnCount = 17;
            const int rowCount = 6;
            var sideVertexCount = columnCount * rowCount;
            var vertices = new Vector3[sideVertexCount * 2];
            var uvs = new Vector2[vertices.Length];

            for (var side = 0; side < 2; side++)
            {
                var sideOffset = side * sideVertexCount;
                var sideZ = side == 0 ? -depth * 0.5f : depth * 0.5f;
                for (var row = 0; row < rowCount; row++)
                {
                    var v = row / (float)(rowCount - 1);
                    var rowCurve = Mathf.Pow(v, profile == 0 ? 0.72f : (profile == 3 ? 0.82f : 0.94f));
                    for (var column = 0; column < columnCount; column++)
                    {
                        var u = column / (float)(columnCount - 1);
                        var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                        var topHeight = GetDistantPanoramaVistaCompositionPrototypeColumnHeight(profile, seed, column, u, maxHeight);
                        var baseLift = -0.28f + DistantPanoramaVistaSigned(seed + column * 17 + 11, 0.07f);
                        var shelfBreak = GetDistantPanoramaVistaCompositionPrototypeShelfOffset(profile, seed, row, column, topHeight);
                        var y = Mathf.Lerp(baseLift, topHeight, rowCurve) + shelfBreak * edgeFalloff;
                        if (row == 0)
                        {
                            y = baseLift;
                        }
                        else if (row == rowCount - 1)
                        {
                            y = topHeight;
                        }

                        var rowWidth = width * Mathf.Lerp(1.08f, 0.82f, v) * (profile == 2 ? Mathf.Lerp(0.96f, 0.74f, v * v) : 1f);
                        var xDrift = DistantPanoramaVistaSigned(seed + row * 61 + column * 19, 0.34f) * edgeFalloff * (0.30f + v * 0.70f);
                        var zDrift = DistantPanoramaVistaSigned(seed + row * 73 + column * 23 + side * 7, 0.18f) * edgeFalloff;
                        var index = sideOffset + row * columnCount + column;
                        vertices[index] = new Vector3(
                            Mathf.Lerp(-rowWidth * 0.5f, rowWidth * 0.5f, u) + xDrift,
                            y + (past ? 0.10f * v : 0f),
                            sideZ + zDrift);
                        uvs[index] = new Vector2(u, v);
                    }
                }
            }

            var triangles = new List<int>((columnCount - 1) * (rowCount - 1) * 24);
            var backOffset = sideVertexCount;
            for (var row = 0; row < rowCount - 1; row++)
            {
                for (var column = 0; column < columnCount - 1; column++)
                {
                    var a = row * columnCount + column;
                    var b = row * columnCount + column + 1;
                    var c = (row + 1) * columnCount + column;
                    var d = (row + 1) * columnCount + column + 1;
                    AddDoubleSidedQuad(triangles, a, b, c, d);
                    AddDoubleSidedQuad(triangles, backOffset + a, backOffset + c, backOffset + b, backOffset + d);
                }
            }

            for (var column = 0; column < columnCount - 1; column++)
            {
                var frontTopA = (rowCount - 1) * columnCount + column;
                var frontTopB = frontTopA + 1;
                var backTopA = backOffset + frontTopA;
                var backTopB = backOffset + frontTopB;
                AddDoubleSidedQuad(triangles, frontTopA, frontTopB, backTopA, backTopB);

                var frontBaseA = column;
                var frontBaseB = column + 1;
                var backBaseA = backOffset + frontBaseA;
                var backBaseB = backOffset + frontBaseB;
                AddDoubleSidedQuad(triangles, frontBaseA, backBaseA, frontBaseB, backBaseB);
            }

            for (var row = 0; row < rowCount - 1; row++)
            {
                var frontLeftA = row * columnCount;
                var frontLeftB = (row + 1) * columnCount;
                AddDoubleSidedQuad(triangles, frontLeftA, backOffset + frontLeftA, frontLeftB, backOffset + frontLeftB);

                var frontRightA = row * columnCount + columnCount - 1;
                var frontRightB = (row + 1) * columnCount + columnCount - 1;
                AddDoubleSidedQuad(triangles, frontRightA, frontRightB, backOffset + frontRightA, backOffset + frontRightB);
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static float GetDistantPanoramaVistaCompositionPrototypeColumnHeight(int profile, int seed, int column, float u, float maxHeight)
        {
            var edgeFalloff = Mathf.Sin(u * Mathf.PI);
            var noise = DistantPanoramaVistaSigned(seed + column * 41 + 3, 0.10f) * edgeFalloff;
            switch (profile)
            {
                case 0:
                {
                    var shoulder = Mathf.Clamp01(1f - Mathf.Abs(u - 0.34f) * 2.7f);
                    var shelf = Mathf.Clamp01(1f - Mathf.Abs(u - 0.67f) * 3.2f);
                    var heightScale = 0.46f + edgeFalloff * 0.30f + shoulder * 0.16f + shelf * 0.12f + noise;
                    return Mathf.Clamp(heightScale, 0.34f, 0.96f) * maxHeight;
                }
                case 1:
                {
                    var clumpA = Mathf.Clamp01(1f - Mathf.Abs(u - 0.22f) * 4.4f);
                    var clumpB = Mathf.Clamp01(1f - Mathf.Abs(u - 0.51f) * 5.2f);
                    var clumpC = Mathf.Clamp01(1f - Mathf.Abs(u - 0.80f) * 4.0f);
                    var canopy = Mathf.Max(clumpA * 0.92f, Mathf.Max(clumpB, clumpC * 0.86f));
                    var heightScale = 0.40f + canopy * 0.42f + edgeFalloff * 0.16f + noise;
                    return Mathf.Clamp(heightScale, 0.32f, 1.03f) * maxHeight;
                }
                case 2:
                {
                    var peakA = Mathf.Clamp01(1f - Mathf.Abs(u - 0.24f) * 3.4f);
                    var peakB = Mathf.Clamp01(1f - Mathf.Abs(u - 0.56f) * 4.0f);
                    var peakC = Mathf.Clamp01(1f - Mathf.Abs(u - 0.77f) * 4.8f);
                    var peak = Mathf.Max(peakA * 0.86f, Mathf.Max(peakB, peakC * 0.70f));
                    var heightScale = 0.34f + peak * 0.56f + edgeFalloff * 0.18f + noise;
                    return Mathf.Clamp(heightScale, 0.30f, 1.06f) * maxHeight;
                }
                case 3:
                default:
                {
                    var trough = Mathf.Clamp01(1f - Mathf.Abs(u - 0.52f) * 3.2f);
                    var leftBank = Mathf.Clamp01(1f - Mathf.Abs(u - 0.25f) * 3.8f);
                    var rightBank = Mathf.Clamp01(1f - Mathf.Abs(u - 0.76f) * 3.8f);
                    var bank = Mathf.Max(leftBank, rightBank);
                    var heightScale = 0.46f + bank * 0.36f + edgeFalloff * 0.16f - trough * 0.24f + noise;
                    return Mathf.Clamp(heightScale, 0.24f, 0.98f) * maxHeight;
                }
            }
        }

        private static float GetDistantPanoramaVistaCompositionPrototypeShelfOffset(int profile, int seed, int row, int column, float topHeight)
        {
            if (row == 0)
            {
                return 0f;
            }

            var noise = DistantPanoramaVistaSigned(seed + row * 83 + column * 29, 0.045f) * topHeight;
            switch (profile)
            {
                case 0:
                    return row == 2 || row == 3 ? topHeight * 0.055f + noise : noise;
                case 1:
                    return row == 1 ? -topHeight * 0.035f + noise : noise;
                case 2:
                    return row == 3 ? topHeight * 0.070f + noise : noise;
                case 3:
                default:
                    return row == 2 ? -topHeight * 0.060f + noise : noise;
            }
        }

        private static float GetDistantPanoramaVistaAreaLandmarkColumnHeight(int profile, int seed, int column, float u, float maxHeight)
        {
            var edgeFalloff = Mathf.Sin(u * Mathf.PI);
            if (profile == 1)
            {
                var terrace = column % 3 == 1 ? 1.0f : 0.64f;
                return maxHeight * Mathf.Lerp(0.26f, 0.52f, edgeFalloff) * terrace;
            }

            if (profile == 2)
            {
                var ridgeA = Mathf.Clamp01(1f - Mathf.Abs(u - 0.22f) * 3.2f);
                var ridgeB = Mathf.Clamp01(1f - Mathf.Abs(u - 0.52f) * 3.8f);
                var ridgeC = Mathf.Clamp01(1f - Mathf.Abs(u - 0.78f) * 3.4f);
                var brokenRidge = Mathf.Max(ridgeA * 0.86f, Mathf.Max(ridgeB, ridgeC * 0.78f));
                var breakNoise = Mathf.Lerp(0.72f, 1.24f, DistantPanoramaVistaHash01(seed + column * 53));
                var notch = column % 5 == 0 ? 0.88f : 1f;
                var heightScale = 0.36f + edgeFalloff * 0.34f + brokenRidge * 0.30f;
                return maxHeight * Mathf.Clamp(heightScale * breakNoise * notch, 0.30f, 1.08f);
            }

            if (profile == 3)
            {
                var roofPulse = column % 5 == 2 ? 1.18f : 0.78f;
                return maxHeight * Mathf.Lerp(0.42f, 0.98f, edgeFalloff) * roofPulse;
            }

            var blockPulse = (column % 4 == 0 || column % 4 == 3) ? 0.62f : 1.0f;
            var roofPeak = column % 6 == 2 ? 1.20f : 0.86f;
            return maxHeight * Mathf.Lerp(0.48f, 1.04f, edgeFalloff) * blockPulse * roofPeak;
        }

        private static float GetDistantPanoramaVistaAreaSignatureColumnHeight(int profile, int seed, int column, float u, float maxHeight)
        {
            var edgeFalloff = Mathf.Sin(u * Mathf.PI);
            var centerDip = Mathf.Abs(u - 0.5f) * 2f;
            var pulse = Mathf.Lerp(0.86f, 1.18f, DistantPanoramaVistaHash01(seed + column * 41 + 3));
            if (profile == 0)
            {
                var sideWall = Mathf.Lerp(0.26f, 1.05f, centerDip);
                var lowNotch = column == 7 || column == 8 ? 0.46f : 1f;
                return maxHeight * Mathf.Lerp(0.30f, 0.94f, edgeFalloff) * sideWall * lowNotch * pulse;
            }

            if (profile == 1)
            {
                var roofPeak = column % 5 == 2 ? 1.20f : 0.72f;
                var block = column % 4 == 0 ? 0.52f : 0.92f;
                return maxHeight * Mathf.Lerp(0.36f, 0.98f, edgeFalloff) * roofPeak * block * pulse;
            }

            if (profile == 2)
            {
                var roofRhythm = column % 6 == 1 || column % 6 == 4 ? 1.06f : 0.70f;
                return maxHeight * Mathf.Lerp(0.32f, 0.88f, edgeFalloff) * roofRhythm * pulse;
            }

            if (profile == 3)
            {
                var terraceStep = 0.42f + (column % 4) * 0.13f;
                return maxHeight * Mathf.Lerp(0.20f, 0.62f, edgeFalloff) * terraceStep * pulse;
            }

            var ridgeA = Mathf.Clamp01(1f - Mathf.Abs(u - 0.20f) * 3.6f);
            var ridgeB = Mathf.Clamp01(1f - Mathf.Abs(u - 0.50f) * 3.1f);
            var ridgeC = Mathf.Clamp01(1f - Mathf.Abs(u - 0.78f) * 4.0f);
            var valleyNotch = Mathf.Clamp01(1f - Mathf.Abs(u - 0.62f) * 5.0f);
            var brokenSide = column == 0 || column == 15 ? 0.46f : 1f;
            var ridgeMass = Mathf.Max(ridgeA * 0.80f, Mathf.Max(ridgeB, ridgeC * 0.74f));
            var heightScale = 0.40f + edgeFalloff * 0.22f + ridgeMass * 0.36f - valleyNotch * 0.12f;
            return maxHeight * Mathf.Clamp(heightScale * brokenSide * pulse, 0.28f, 1.05f);
        }

        private static float GetDistantPanoramaVistaAreaSignatureShelfHeight(int profile, int seed, int column, float u, float topHeight)
        {
            if (profile == 3)
            {
                var step = column % 4;
                return topHeight * Mathf.Lerp(0.18f, 0.52f, step / 3f);
            }

            if (profile == 4)
            {
                return topHeight * Mathf.Lerp(0.24f, 0.46f, DistantPanoramaVistaHash01(seed + column * 43 + 19));
            }

            var centralShelf = 0.30f + Mathf.Sin(u * Mathf.PI) * 0.26f;
            return topHeight * centralShelf;
        }

        private static Mesh CreateDistantPanoramaVistaRidgeFacetMesh(string meshName, int seed, int detailBand, float width, float maxHeight, float depth)
        {
            const int columnCount = 23;
            const int rowCount = 5;
            var sideVertexCount = columnCount * rowCount;
            var vertices = new Vector3[sideVertexCount * 2];
            var uvs = new Vector2[vertices.Length];

            for (var side = 0; side < 2; side++)
            {
                var sideOffset = side * sideVertexCount;
                var sideZ = side == 0 ? -depth * 0.5f : depth * 0.5f;
                for (var row = 0; row < rowCount; row++)
                {
                    var v = row / (float)(rowCount - 1);
                    for (var column = 0; column < columnCount; column++)
                    {
                        var u = column / (float)(columnCount - 1);
                        var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                        var ridgeA = Mathf.Clamp01(1f - Mathf.Abs(u - 0.22f) * (detailBand == 0 ? 4.6f : 3.8f));
                        var ridgeB = Mathf.Clamp01(1f - Mathf.Abs(u - 0.50f) * (detailBand == 0 ? 3.7f : 4.4f));
                        var ridgeC = Mathf.Clamp01(1f - Mathf.Abs(u - 0.78f) * (detailBand == 0 ? 4.2f : 3.5f));
                        var saddle = Mathf.Clamp01(1f - Mathf.Abs(u - (detailBand == 0 ? 0.64f : 0.38f)) * 5.4f);
                        var erosionCutA = Mathf.Clamp01(1f - Mathf.Abs(u - Mathf.Lerp(0.26f, 0.34f, DistantPanoramaVistaHash01(seed + 101))) * 8.0f);
                        var erosionCutB = Mathf.Clamp01(1f - Mathf.Abs(u - Mathf.Lerp(0.58f, 0.72f, DistantPanoramaVistaHash01(seed + 107))) * 7.0f);
                        var spur = Mathf.Clamp01(1f - Mathf.Abs(u - Mathf.Lerp(0.38f, 0.82f, DistantPanoramaVistaHash01(seed + 113))) * 6.2f);
                        var ridgeMass = Mathf.Max(ridgeA * 0.84f, Mathf.Max(ridgeB, ridgeC * 0.76f));
                        var columnNoise = DistantPanoramaVistaSigned(seed + column * 47 + 5, 0.12f) * edgeFalloff;
                        var topHeight = maxHeight * Mathf.Clamp(
                            0.34f + edgeFalloff * 0.20f + ridgeMass * 0.44f + spur * 0.10f -
                            saddle * 0.15f - Mathf.Max(erosionCutA, erosionCutB) * (detailBand == 0 ? 0.10f : 0.16f) + columnNoise,
                            0.20f,
                            1.12f);
                        var lowerCut = topHeight * Mathf.Clamp(0.07f + DistantPanoramaVistaHash01(seed + column * 53 + 17) * 0.12f + saddle * 0.08f, 0.06f, 0.34f);
                        var shelf = row == 1 || row == 2
                            ? (DistantPanoramaVistaSigned(seed + row * 79 + column * 29, 0.045f) - Mathf.Max(erosionCutA, erosionCutB) * 0.030f) * maxHeight * edgeFalloff
                            : 0f;
                        var y = Mathf.Lerp(lowerCut, topHeight, Mathf.Pow(v, 0.76f)) + shelf;
                        if (row == 0)
                        {
                            y = lowerCut;
                        }
                        else if (row == rowCount - 1)
                        {
                            y = topHeight;
                        }

                        var rowWidth = width * Mathf.Lerp(1.08f, detailBand == 0 ? 0.76f : 0.66f, v);
                        var xDrift = (DistantPanoramaVistaSigned(seed + row * 61 + column * 31 + side * 7, 0.30f) + (spur - erosionCutA) * 0.10f) * edgeFalloff * (0.25f + v * 0.75f);
                        var zDrift = DistantPanoramaVistaSigned(seed + row * 67 + column * 37 + side * 11, depth * 0.16f) * edgeFalloff;
                        var index = sideOffset + row * columnCount + column;
                        vertices[index] = new Vector3(
                            Mathf.Lerp(-rowWidth * 0.5f, rowWidth * 0.5f, u) + xDrift,
                            y,
                            sideZ + zDrift);
                        uvs[index] = new Vector2(u, v);
                    }
                }
            }

            var triangles = new List<int>((columnCount - 1) * (rowCount - 1) * 24);
            var backOffset = sideVertexCount;
            for (var row = 0; row < rowCount - 1; row++)
            {
                for (var column = 0; column < columnCount - 1; column++)
                {
                    var a = row * columnCount + column;
                    var b = row * columnCount + column + 1;
                    var c = (row + 1) * columnCount + column;
                    var d = (row + 1) * columnCount + column + 1;
                    AddDoubleSidedQuad(triangles, a, b, c, d);
                    AddDoubleSidedQuad(triangles, backOffset + a, backOffset + c, backOffset + b, backOffset + d);
                }
            }

            for (var column = 0; column < columnCount - 1; column++)
            {
                var frontTopA = (rowCount - 1) * columnCount + column;
                var frontTopB = frontTopA + 1;
                var backTopA = backOffset + frontTopA;
                var backTopB = backOffset + frontTopB;
                AddDoubleSidedQuad(triangles, frontTopA, frontTopB, backTopA, backTopB);

                var frontBaseA = column;
                var frontBaseB = column + 1;
                var backBaseA = backOffset + frontBaseA;
                var backBaseB = backOffset + frontBaseB;
                AddDoubleSidedQuad(triangles, frontBaseA, backBaseA, frontBaseB, backBaseB);
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaTreelineFoldMesh(string meshName, int seed, float width, float maxHeight, float thickness)
        {
            const int columnCount = 19;
            var vertices = new Vector3[columnCount * 6];
            var uvs = new Vector2[columnCount * 6];
            var frontZ = -thickness * 0.5f;
            var backZ = thickness * 0.5f;

            for (var i = 0; i < columnCount; i++)
            {
                var u = i / (float)(columnCount - 1);
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.5f, width * 0.5f, u) +
                    DistantPanoramaVistaSigned(seed + i * 31 + 11, 0.12f) * edgeFalloff;
                var clumpA = Mathf.Clamp01(1f - Mathf.Abs(u - 0.18f) * 5.2f);
                var clumpB = Mathf.Clamp01(1f - Mathf.Abs(u - 0.42f) * 4.8f);
                var clumpC = Mathf.Clamp01(1f - Mathf.Abs(u - 0.68f) * 5.0f);
                var clumpD = Mathf.Clamp01(1f - Mathf.Abs(u - 0.86f) * 5.4f);
                var clump = Mathf.Max(Mathf.Max(clumpA * 0.78f, clumpB), Mathf.Max(clumpC * 0.92f, clumpD * 0.70f));
                var gap = i % 5 == 0 || i % 7 == 3 ? 0.72f : 1f;
                var crown = maxHeight * Mathf.Clamp(0.24f + edgeFalloff * 0.20f + clump * 0.58f, 0.18f, 1.02f) * gap;
                var shoulder = crown * Mathf.Lerp(0.36f, 0.62f, DistantPanoramaVistaHash01(seed + i * 43 + 17));
                var backCrown = crown * Mathf.Lerp(0.82f, 1.08f, DistantPanoramaVistaHash01(seed + i * 47 + 19));
                if (i == 0 || i == columnCount - 1)
                {
                    crown = Mathf.Min(crown, maxHeight * 0.30f);
                    shoulder = Mathf.Min(shoulder, maxHeight * 0.20f);
                    backCrown = Mathf.Min(backCrown, maxHeight * 0.26f);
                }

                var baseLift = DistantPanoramaVistaSigned(seed + i * 29 + 23, 0.055f);
                var baseIndex = i * 6;
                vertices[baseIndex] = new Vector3(x, baseLift, frontZ);
                vertices[baseIndex + 1] = new Vector3(x + DistantPanoramaVistaSigned(seed + i * 37 + 5, 0.10f), shoulder, Mathf.Lerp(frontZ, backZ, 0.22f));
                vertices[baseIndex + 2] = new Vector3(x + DistantPanoramaVistaSigned(seed + i * 41 + 7, 0.18f), crown, frontZ);
                vertices[baseIndex + 3] = new Vector3(x, baseLift * 0.75f, backZ);
                vertices[baseIndex + 4] = new Vector3(x + DistantPanoramaVistaSigned(seed + i * 53 + 13, 0.09f), shoulder * 0.90f, Mathf.Lerp(frontZ, backZ, 0.78f));
                vertices[baseIndex + 5] = new Vector3(x + DistantPanoramaVistaSigned(seed + i * 59 + 17, 0.16f), backCrown, backZ);
                uvs[baseIndex] = new Vector2(u, 0f);
                uvs[baseIndex + 1] = new Vector2(u, 0.45f);
                uvs[baseIndex + 2] = new Vector2(u, 1f);
                uvs[baseIndex + 3] = new Vector2(u, 0f);
                uvs[baseIndex + 4] = new Vector2(u, 0.45f);
                uvs[baseIndex + 5] = new Vector2(u, 1f);
            }

            var triangles = new List<int>((columnCount - 1) * 60);
            for (var i = 0; i < columnCount - 1; i++)
            {
                var a = i * 6;
                var b = (i + 1) * 6;

                AddDoubleSidedQuad(triangles, a, b, a + 1, b + 1);
                AddDoubleSidedQuad(triangles, a + 1, b + 1, a + 2, b + 2);
                AddDoubleSidedQuad(triangles, a + 3, a + 4, b + 3, b + 4);
                AddDoubleSidedQuad(triangles, a + 4, a + 5, b + 4, b + 5);
                AddDoubleSidedQuad(triangles, a + 2, b + 2, a + 5, b + 5);
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaRidgeStrataMesh(string meshName, int seed, float width, float maxHeight, float thickness)
        {
            const int columnCount = 17;
            const int rowCount = 6;
            var sideVertexCount = columnCount * rowCount;
            var vertices = new Vector3[sideVertexCount * 2];
            var uvs = new Vector2[vertices.Length];
            var frontZ = -thickness * 0.5f;
            var backZ = thickness * 0.5f;

            for (var side = 0; side < 2; side++)
            {
                var sideOffset = side * sideVertexCount;
                var sideZ = side == 0 ? frontZ : backZ;
                for (var row = 0; row < rowCount; row++)
                {
                    var v = row / (float)(rowCount - 1);
                    var rowWidth = width * Mathf.Lerp(1.04f, 0.62f, v);
                    var stratumLift = (row % 2 == 0 ? 0.00f : 0.075f) * maxHeight;
                    for (var column = 0; column < columnCount; column++)
                    {
                        var u = column / (float)(columnCount - 1);
                        var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                        var slope = (u - 0.5f) * DistantPanoramaVistaSigned(seed + row * 47 + side * 11, maxHeight * 0.20f);
                        var terraceCut = ((column + row + seed) % 5 == 0 ? -0.035f : 0.018f) * maxHeight * edgeFalloff;
                        var ridgeNoise = DistantPanoramaVistaSigned(seed + row * 61 + column * 29 + side * 13, maxHeight * 0.062f) * edgeFalloff;
                        var y = maxHeight * Mathf.Lerp(0.00f, 0.90f, Mathf.Pow(v, 0.92f)) + slope + stratumLift + terraceCut + ridgeNoise;
                        if (row == 0)
                        {
                            y = DistantPanoramaVistaSigned(seed + column * 31 + side * 17, maxHeight * 0.020f);
                        }
                        else if (row == rowCount - 1)
                        {
                            var skylineNotch = Mathf.Clamp01(1f - Mathf.Abs(u - Mathf.Lerp(0.24f, 0.76f, DistantPanoramaVistaHash01(seed + side * 31 + 211))) * 7.5f);
                            var skylineSpur = Mathf.Clamp01(1f - Mathf.Abs(u - Mathf.Lerp(0.18f, 0.88f, DistantPanoramaVistaHash01(seed + side * 37 + 223))) * 6.0f);
                            y = maxHeight * Mathf.Clamp(
                                Mathf.Lerp(0.66f, 1.06f, DistantPanoramaVistaHash01(seed + column * 37 + side * 19)) -
                                skylineNotch * 0.12f + skylineSpur * 0.07f,
                                0.52f,
                                1.10f);
                        }

                        var x = Mathf.Lerp(-rowWidth * 0.5f, rowWidth * 0.5f, u) +
                            DistantPanoramaVistaSigned(seed + row * 43 + column * 23 + side * 7, width * 0.024f) * edgeFalloff;
                        var z = sideZ + DistantPanoramaVistaSigned(seed + row * 53 + column * 31 + side * 5, thickness * 0.12f) * edgeFalloff;
                        var index = sideOffset + row * columnCount + column;
                        vertices[index] = new Vector3(x, y, z);
                        uvs[index] = new Vector2(u, v);
                    }
                }
            }

            var triangles = new List<int>((columnCount - 1) * (rowCount - 1) * 24);
            var backOffset = sideVertexCount;
            for (var row = 0; row < rowCount - 1; row++)
            {
                for (var column = 0; column < columnCount - 1; column++)
                {
                    var a = row * columnCount + column;
                    var b = row * columnCount + column + 1;
                    var c = (row + 1) * columnCount + column;
                    var d = (row + 1) * columnCount + column + 1;
                    AddDoubleSidedQuad(triangles, a, b, c, d);
                    AddDoubleSidedQuad(triangles, backOffset + a, backOffset + c, backOffset + b, backOffset + d);
                }
            }

            for (var column = 0; column < columnCount - 1; column++)
            {
                var frontTopA = (rowCount - 1) * columnCount + column;
                var frontTopB = frontTopA + 1;
                var backTopA = backOffset + frontTopA;
                var backTopB = backOffset + frontTopB;
                AddDoubleSidedQuad(triangles, frontTopA, frontTopB, backTopA, backTopB);

                var frontBaseA = column;
                var frontBaseB = column + 1;
                var backBaseA = backOffset + frontBaseA;
                var backBaseB = backOffset + frontBaseB;
                AddDoubleSidedQuad(triangles, frontBaseA, backBaseA, frontBaseB, backBaseB);
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaNaturalTreeStandCanopyMesh(string meshName, int seed, float width, float maxHeight, float depth, bool past)
        {
            const int treeCount = 19;
            var vertices = new List<Vector3>(treeCount * 12);
            var uvs = new List<Vector2>(treeCount * 12);
            var triangles = new List<int>(treeCount * 54);
            var spacing = width / treeCount;

            for (var tree = 0; tree < treeCount; tree++)
            {
                var treeSeed = seed + tree * 113;
                var u = (tree + 0.5f) / treeCount;
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.5f, width * 0.5f, u) +
                    DistantPanoramaVistaSigned(treeSeed + 5, spacing * 0.22f) * edgeFalloff;
                var z = DistantPanoramaVistaSigned(treeSeed + 11, depth * 0.45f);
                var heightPulse = Mathf.Lerp(0.50f, 1.15f, DistantPanoramaVistaHash01(treeSeed + 17));
                var height = maxHeight * heightPulse * (past ? 1.06f : 1f);
                if (tree == 0 || tree == treeCount - 1)
                {
                    height *= 0.50f;
                }

                var broadleaf = DistantPanoramaVistaHash01(treeSeed + 23) > 0.32f;
                var lobeWidth = spacing * Mathf.Lerp(broadleaf ? 0.84f : 0.52f, broadleaf ? 1.28f : 0.78f, DistantPanoramaVistaHash01(treeSeed + 29));
                var lobeDepth = depth * Mathf.Lerp(broadleaf ? 0.48f : 0.32f, broadleaf ? 0.78f : 0.54f, DistantPanoramaVistaHash01(treeSeed + 31));
                var lobeBase = new Vector3(x, Mathf.Lerp(0.26f, 0.56f, DistantPanoramaVistaHash01(treeSeed + 37)), z);
                AddDistantPanoramaVistaCanopyLobe(vertices, uvs, triangles, lobeBase, lobeWidth, lobeDepth, height, treeSeed, broadleaf);

                if (broadleaf && DistantPanoramaVistaHash01(treeSeed + 41) > 0.46f)
                {
                    var sideOffset = DistantPanoramaVistaSigned(treeSeed + 43, lobeWidth * 0.22f);
                    AddDistantPanoramaVistaCanopyLobe(
                        vertices,
                        uvs,
                        triangles,
                        lobeBase + new Vector3(sideOffset, height * 0.18f, DistantPanoramaVistaSigned(treeSeed + 47, lobeDepth * 0.18f)),
                        lobeWidth * 0.58f,
                        lobeDepth * 0.66f,
                        height * 0.58f,
                        treeSeed + 53,
                        true);
                }

                if (tree > 1 && tree < treeCount - 2 && DistantPanoramaVistaHash01(treeSeed + 57) > 0.70f)
                {
                    AddDistantPanoramaVistaCanopyLobe(
                        vertices,
                        uvs,
                        triangles,
                        lobeBase + new Vector3(
                            DistantPanoramaVistaSigned(treeSeed + 61, lobeWidth * 0.18f),
                            height * 0.08f,
                            DistantPanoramaVistaSigned(treeSeed + 67, lobeDepth * 0.22f)),
                        lobeWidth * 0.44f,
                        lobeDepth * 0.46f,
                        height * 0.46f,
                        treeSeed + 71,
                        true);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices.ToArray(),
                uv = uvs.ToArray(),
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaNaturalCanopyVolumeMesh(string meshName, int seed, float width, float maxHeight, float depth, bool past)
        {
            const int crownCount = 13;
            var vertices = new List<Vector3>(crownCount * 34);
            var uvs = new List<Vector2>(crownCount * 34);
            var triangles = new List<int>(crownCount * 180);
            var spacing = width / crownCount;

            for (var crown = 0; crown < crownCount; crown++)
            {
                var crownSeed = seed + crown * 149;
                var u = (crown + 0.5f) / crownCount;
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.49f, width * 0.49f, u) +
                    DistantPanoramaVistaSigned(crownSeed + 5, spacing * 0.28f) * edgeFalloff;
                var z = -depth * Mathf.Lerp(0.22f, 0.62f, DistantPanoramaVistaHash01(crownSeed + 11)) +
                    DistantPanoramaVistaSigned(crownSeed + 17, depth * 0.16f);
                var crownWidth = spacing * Mathf.Lerp(1.42f, 2.45f, DistantPanoramaVistaHash01(crownSeed + 23));
                var crownDepth = depth * Mathf.Lerp(0.40f, 0.84f, DistantPanoramaVistaHash01(crownSeed + 29));
                var crownHeight = maxHeight * Mathf.Lerp(0.34f, 0.58f, DistantPanoramaVistaHash01(crownSeed + 31)) * (past ? 1.04f : 1f);
                var baseHeight = maxHeight * Mathf.Lerp(0.18f, 0.36f, DistantPanoramaVistaHash01(crownSeed + 37));
                var baseCenter = new Vector3(x, baseHeight, z);

                AddDistantPanoramaVistaCanopyLobe(vertices, uvs, triangles, baseCenter, crownWidth, crownDepth, crownHeight, crownSeed, true);
                AddDistantPanoramaVistaCanopyLobe(
                    vertices,
                    uvs,
                    triangles,
                    baseCenter + new Vector3(
                        DistantPanoramaVistaSigned(crownSeed + 41, crownWidth * 0.22f),
                        crownHeight * Mathf.Lerp(0.16f, 0.30f, DistantPanoramaVistaHash01(crownSeed + 43)),
                        -crownDepth * Mathf.Lerp(0.16f, 0.32f, DistantPanoramaVistaHash01(crownSeed + 47))),
                    crownWidth * Mathf.Lerp(0.48f, 0.72f, DistantPanoramaVistaHash01(crownSeed + 53)),
                    crownDepth * Mathf.Lerp(0.52f, 0.76f, DistantPanoramaVistaHash01(crownSeed + 59)),
                    crownHeight * Mathf.Lerp(0.46f, 0.68f, DistantPanoramaVistaHash01(crownSeed + 61)),
                    crownSeed + 67,
                    true);

                if (crown > 1 && crown < crownCount - 2)
                {
                    AddDistantPanoramaVistaLeafFringe(
                        vertices,
                        uvs,
                        triangles,
                        baseCenter + new Vector3(
                            DistantPanoramaVistaSigned(crownSeed + 71, crownWidth * 0.16f),
                            crownHeight * Mathf.Lerp(0.38f, 0.58f, DistantPanoramaVistaHash01(crownSeed + 73)),
                            -crownDepth * Mathf.Lerp(0.20f, 0.42f, DistantPanoramaVistaHash01(crownSeed + 79))),
                        spacing * Mathf.Lerp(1.20f, 1.72f, DistantPanoramaVistaHash01(crownSeed + 83)),
                        crownHeight,
                        crownDepth,
                        crownSeed + 89,
                        past);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices.ToArray(),
                uv = uvs.ToArray(),
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaNaturalSpeciesClusterMesh(string meshName, int seed, float width, float maxHeight, float depth, bool past, bool coniferCluster)
        {
            const int groupCount = 11;
            var vertices = new List<Vector3>(groupCount * 52);
            var uvs = new List<Vector2>(groupCount * 52);
            var triangles = new List<int>(groupCount * 300);
            var spacing = width / groupCount;

            for (var group = 0; group < groupCount; group++)
            {
                var groupSeed = seed + group * 157;
                var u = (group + 0.5f) / groupCount;
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.48f, width * 0.48f, u) +
                    DistantPanoramaVistaSigned(groupSeed + 5, spacing * 0.24f) * edgeFalloff;
                var z = DistantPanoramaVistaSigned(groupSeed + 11, depth * 0.36f) -
                    depth * Mathf.Lerp(0.04f, 0.26f, DistantPanoramaVistaHash01(groupSeed + 17));
                var groupHeight = maxHeight * Mathf.Lerp(0.46f, 0.92f, DistantPanoramaVistaHash01(groupSeed + 23)) * (past ? 1.04f : 1f);

                if (coniferCluster)
                {
                    var tierCount = 4 + (DistantPanoramaVistaHash01(groupSeed + 29) > 0.58f ? 1 : 0);
                    var treeWidth = spacing * Mathf.Lerp(1.32f, 2.12f, DistantPanoramaVistaHash01(groupSeed + 31));
                    var treeDepth = depth * Mathf.Lerp(0.44f, 0.82f, DistantPanoramaVistaHash01(groupSeed + 37));
                    for (var tier = 0; tier < tierCount; tier++)
                    {
                        var tierT = tier / (float)Mathf.Max(1, tierCount - 1);
                        var tierBase = new Vector3(
                            x + DistantPanoramaVistaSigned(groupSeed + 41 + tier * 7, treeWidth * 0.10f),
                            groupHeight * Mathf.Lerp(0.04f, 0.60f, tierT),
                            z + DistantPanoramaVistaSigned(groupSeed + 47 + tier * 11, treeDepth * 0.12f));
                        AddDistantPanoramaVistaConiferTier(
                            vertices,
                            uvs,
                            triangles,
                            tierBase,
                            treeWidth * Mathf.Lerp(1.02f, 0.38f, tierT),
                            treeDepth * Mathf.Lerp(1.00f, 0.42f, tierT),
                            groupHeight * Mathf.Lerp(0.38f, 0.22f, tierT),
                            groupSeed + tier * 43);
                    }
                }
                else
                {
                    var crownWidth = spacing * Mathf.Lerp(1.70f, 2.85f, DistantPanoramaVistaHash01(groupSeed + 31));
                    var crownDepth = depth * Mathf.Lerp(0.48f, 0.96f, DistantPanoramaVistaHash01(groupSeed + 37));
                    var crownHeight = groupHeight * Mathf.Lerp(0.58f, 0.90f, DistantPanoramaVistaHash01(groupSeed + 41));
                    var baseHeight = groupHeight * Mathf.Lerp(0.14f, 0.28f, DistantPanoramaVistaHash01(groupSeed + 43));
                    var baseCenter = new Vector3(x, baseHeight, z);
                    AddDistantPanoramaVistaCanopyLobe(vertices, uvs, triangles, baseCenter, crownWidth, crownDepth, crownHeight, groupSeed, true);
                    AddDistantPanoramaVistaCanopyLobe(
                        vertices,
                        uvs,
                        triangles,
                        baseCenter + new Vector3(
                            DistantPanoramaVistaSigned(groupSeed + 47, crownWidth * 0.22f),
                            crownHeight * Mathf.Lerp(0.14f, 0.30f, DistantPanoramaVistaHash01(groupSeed + 53)),
                            DistantPanoramaVistaSigned(groupSeed + 59, crownDepth * 0.26f)),
                        crownWidth * Mathf.Lerp(0.42f, 0.66f, DistantPanoramaVistaHash01(groupSeed + 61)),
                        crownDepth * Mathf.Lerp(0.50f, 0.72f, DistantPanoramaVistaHash01(groupSeed + 67)),
                        crownHeight * Mathf.Lerp(0.44f, 0.62f, DistantPanoramaVistaHash01(groupSeed + 71)),
                        groupSeed + 73,
                        true);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices.ToArray(),
                uv = uvs.ToArray(),
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaNaturalCanopyAccentMesh(string meshName, int seed, float width, float maxHeight, float depth, bool past)
        {
            const int accentCount = 13;
            var vertices = new List<Vector3>(accentCount * 24);
            var uvs = new List<Vector2>(accentCount * 24);
            var triangles = new List<int>(accentCount * 84);
            var spacing = width / accentCount;

            for (var accent = 0; accent < accentCount; accent++)
            {
                var accentSeed = seed + accent * 127;
                var u = (accent + 0.5f) / accentCount;
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.48f, width * 0.48f, u) +
                    DistantPanoramaVistaSigned(accentSeed + 5, spacing * 0.20f) * edgeFalloff;
                var z = -depth * Mathf.Lerp(0.08f, 0.28f, DistantPanoramaVistaHash01(accentSeed + 11)) +
                    DistantPanoramaVistaSigned(accentSeed + 17, depth * 0.12f);
                var lobeWidth = spacing * Mathf.Lerp(0.42f, 0.82f, DistantPanoramaVistaHash01(accentSeed + 23));
                var lobeDepth = depth * Mathf.Lerp(0.18f, 0.34f, DistantPanoramaVistaHash01(accentSeed + 29));
                var lobeHeight = maxHeight * Mathf.Lerp(0.20f, 0.38f, DistantPanoramaVistaHash01(accentSeed + 31)) * (past ? 1.04f : 1f);
                var baseHeight = maxHeight * Mathf.Lerp(0.30f, 0.56f, DistantPanoramaVistaHash01(accentSeed + 37));
                AddDistantPanoramaVistaCanopyLobe(
                    vertices,
                    uvs,
                    triangles,
                    new Vector3(x, baseHeight, z),
                    lobeWidth,
                    lobeDepth,
                    lobeHeight,
                    accentSeed,
                    true);
                AddDistantPanoramaVistaLeafFringe(
                    vertices,
                    uvs,
                    triangles,
                    new Vector3(x, baseHeight + lobeHeight * 0.48f, z - lobeDepth * 0.12f),
                    spacing,
                    lobeHeight,
                    lobeDepth,
                    accentSeed + 101,
                    past);
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices.ToArray(),
                uv = uvs.ToArray(),
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaNaturalCanopyFleckMesh(string meshName, int seed, float width, float maxHeight, float depth, bool past)
        {
            const int fleckCount = 31;
            var vertices = new List<Vector3>(fleckCount * 4);
            var uvs = new List<Vector2>(fleckCount * 4);
            var triangles = new List<int>(fleckCount * 12);
            var spacing = width / fleckCount;

            for (var fleck = 0; fleck < fleckCount; fleck++)
            {
                var fleckSeed = seed + fleck * 103;
                var u = (fleck + 0.5f) / fleckCount;
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.50f, width * 0.50f, u) +
                    DistantPanoramaVistaSigned(fleckSeed + 5, spacing * 0.36f) * edgeFalloff;
                var y = maxHeight * Mathf.Lerp(0.34f, 0.84f, DistantPanoramaVistaHash01(fleckSeed + 11));
                var z = -depth * Mathf.Lerp(0.16f, 0.42f, DistantPanoramaVistaHash01(fleckSeed + 17)) +
                    DistantPanoramaVistaSigned(fleckSeed + 19, depth * 0.14f);
                var fleckWidth = spacing * Mathf.Lerp(0.38f, 0.96f, DistantPanoramaVistaHash01(fleckSeed + 23));
                var fleckHeight = maxHeight * Mathf.Lerp(0.075f, 0.190f, DistantPanoramaVistaHash01(fleckSeed + 29)) * (past ? 1.03f : 1f);
                var leanX = DistantPanoramaVistaSigned(fleckSeed + 31, fleckWidth * 0.30f);
                var leanZ = DistantPanoramaVistaSigned(fleckSeed + 37, depth * 0.08f);
                var start = vertices.Count;
                var center = new Vector3(x, y, z);

                vertices.Add(center + new Vector3(-fleckWidth * 0.52f, -fleckHeight * 0.30f, -leanZ * 0.28f));
                vertices.Add(center + new Vector3(fleckWidth * 0.48f, -fleckHeight * 0.24f, leanZ * 0.22f));
                vertices.Add(center + new Vector3(fleckWidth * 0.28f + leanX, fleckHeight * 0.72f, leanZ));
                vertices.Add(center + new Vector3(-fleckWidth * 0.34f + leanX * 0.36f, fleckHeight * 0.62f, -leanZ * 0.55f));
                uvs.Add(new Vector2(0.04f, 0.10f));
                uvs.Add(new Vector2(0.96f, 0.16f));
                uvs.Add(new Vector2(0.74f, 0.94f));
                uvs.Add(new Vector2(0.16f, 0.86f));
                AddDoubleSidedQuad(triangles, start, start + 1, start + 3, start + 2);
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices.ToArray(),
                uv = uvs.ToArray(),
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaNaturalCanopyShadowMesh(string meshName, int seed, float width, float maxHeight, float depth, bool past)
        {
            const int pocketCount = 25;
            var vertices = new List<Vector3>(pocketCount * 4);
            var uvs = new List<Vector2>(pocketCount * 4);
            var triangles = new List<int>(pocketCount * 12);
            var spacing = width / pocketCount;

            for (var pocket = 0; pocket < pocketCount; pocket++)
            {
                var pocketSeed = seed + pocket * 109;
                var u = (pocket + 0.5f) / pocketCount;
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.48f, width * 0.48f, u) +
                    DistantPanoramaVistaSigned(pocketSeed + 5, spacing * 0.34f) * edgeFalloff;
                var y = maxHeight * Mathf.Lerp(0.26f, 0.72f, DistantPanoramaVistaHash01(pocketSeed + 11));
                var z = -depth * Mathf.Lerp(0.04f, 0.24f, DistantPanoramaVistaHash01(pocketSeed + 17)) +
                    DistantPanoramaVistaSigned(pocketSeed + 19, depth * 0.18f);
                var pocketWidth = spacing * Mathf.Lerp(0.36f, 0.90f, DistantPanoramaVistaHash01(pocketSeed + 23));
                var pocketHeight = maxHeight * Mathf.Lerp(0.080f, 0.205f, DistantPanoramaVistaHash01(pocketSeed + 29)) * (past ? 1.04f : 1f);
                var leanX = DistantPanoramaVistaSigned(pocketSeed + 31, pocketWidth * 0.28f);
                var leanZ = DistantPanoramaVistaSigned(pocketSeed + 37, depth * 0.10f);
                var waist = Mathf.Lerp(0.48f, 0.76f, DistantPanoramaVistaHash01(pocketSeed + 41));
                var start = vertices.Count;
                var center = new Vector3(x, y, z);

                vertices.Add(center + new Vector3(-pocketWidth * 0.52f, -pocketHeight * 0.42f, -leanZ * 0.32f));
                vertices.Add(center + new Vector3(pocketWidth * 0.48f, -pocketHeight * 0.36f, leanZ * 0.28f));
                vertices.Add(center + new Vector3(pocketWidth * waist * 0.26f + leanX, pocketHeight * 0.68f, leanZ));
                vertices.Add(center + new Vector3(-pocketWidth * waist * 0.34f + leanX * 0.38f, pocketHeight * 0.76f, -leanZ * 0.74f));
                uvs.Add(new Vector2(0.02f, 0.08f));
                uvs.Add(new Vector2(0.98f, 0.14f));
                uvs.Add(new Vector2(0.76f, 0.90f));
                uvs.Add(new Vector2(0.18f, 0.96f));
                AddDoubleSidedQuad(triangles, start, start + 1, start + 3, start + 2);
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices.ToArray(),
                uv = uvs.ToArray(),
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static void AddDistantPanoramaVistaLeafFringe(List<Vector3> vertices, List<Vector2> uvs, List<int> triangles, Vector3 center, float spacing, float height, float depth, int seed, bool past)
        {
            const int shardCount = 6;
            for (var shard = 0; shard < shardCount; shard++)
            {
                var shardSeed = seed + shard * 37;
                var lane = (shard - (shardCount - 1) * 0.5f) / shardCount;
                var x = center.x + lane * spacing * 1.05f + DistantPanoramaVistaSigned(shardSeed + 5, spacing * 0.16f);
                var y = center.y + DistantPanoramaVistaSigned(shardSeed + 11, height * 0.26f);
                var z = center.z + DistantPanoramaVistaSigned(shardSeed + 17, depth * 0.40f);
                var shardWidth = spacing * Mathf.Lerp(0.18f, 0.38f, DistantPanoramaVistaHash01(shardSeed + 23));
                var shardHeight = height * Mathf.Lerp(0.16f, 0.34f, DistantPanoramaVistaHash01(shardSeed + 29)) * (past ? 1.04f : 1f);
                var leanX = DistantPanoramaVistaSigned(shardSeed + 31, shardWidth * 0.38f);
                var leanZ = DistantPanoramaVistaSigned(shardSeed + 37, depth * 0.16f);
                var depthSkew = DistantPanoramaVistaSigned(shardSeed + 41, depth * 0.12f);
                var start = vertices.Count;
                var shardCenter = new Vector3(x, y, z);

                vertices.Add(shardCenter + new Vector3(-shardWidth * 0.55f, -shardHeight * 0.28f, -depthSkew));
                vertices.Add(shardCenter + new Vector3(shardWidth * 0.52f, -shardHeight * 0.20f, depthSkew));
                vertices.Add(shardCenter + new Vector3(-shardWidth * 0.28f + leanX, shardHeight * 0.80f, -depthSkew * 0.42f + leanZ));
                vertices.Add(shardCenter + new Vector3(shardWidth * 0.34f + leanX, shardHeight * 0.72f, depthSkew * 0.58f + leanZ));
                uvs.Add(new Vector2(0.05f, 0.10f));
                uvs.Add(new Vector2(0.95f, 0.18f));
                uvs.Add(new Vector2(0.18f, 0.92f));
                uvs.Add(new Vector2(0.88f, 0.86f));
                AddDoubleSidedQuad(triangles, start, start + 1, start + 2, start + 3);
            }
        }

        private static void AddDistantPanoramaVistaCanopyLobe(List<Vector3> vertices, List<Vector2> uvs, List<int> triangles, Vector3 baseCenter, float width, float depth, float height, int seed, bool broadleaf)
        {
            const int sideCount = 8;
            var start = vertices.Count;
            var lean = new Vector3(
                DistantPanoramaVistaSigned(seed + 59, width * 0.08f),
                0f,
                DistantPanoramaVistaSigned(seed + 61, depth * 0.08f));
            var bottom = baseCenter + new Vector3(0f, broadleaf ? -0.10f : 0f, 0f);
            var top = baseCenter + lean + new Vector3(0f, height * (broadleaf ? 0.86f : 1.04f), 0f);
            vertices.Add(bottom);
            vertices.Add(top);
            uvs.Add(new Vector2(0.50f, 0.05f));
            uvs.Add(new Vector2(0.50f, 1.00f));

            for (var i = 0; i < sideCount; i++)
            {
                var angle = (i / (float)sideCount) * Mathf.PI * 2f + DistantPanoramaVistaSigned(seed + 67, 0.10f);
                var sidePulse = Mathf.Lerp(0.82f, 1.18f, DistantPanoramaVistaHash01(seed + i * 17 + 71));
                var y = baseCenter.y + height * Mathf.Lerp(broadleaf ? 0.34f : 0.22f, broadleaf ? 0.58f : 0.38f, DistantPanoramaVistaHash01(seed + i * 19 + 73));
                vertices.Add(new Vector3(
                    baseCenter.x + Mathf.Cos(angle) * width * 0.50f * sidePulse,
                    y,
                    baseCenter.z + Mathf.Sin(angle) * depth * 0.50f * sidePulse));
                uvs.Add(new Vector2(0.50f + Mathf.Cos(angle) * 0.46f, 0.48f + Mathf.Sin(angle) * 0.28f));
            }

            var bottomIndex = start;
            var topIndex = start + 1;
            var ringStart = start + 2;
            for (var i = 0; i < sideCount; i++)
            {
                var current = ringStart + i;
                var next = ringStart + ((i + 1) % sideCount);
                triangles.Add(topIndex);
                triangles.Add(current);
                triangles.Add(next);
                triangles.Add(bottomIndex);
                triangles.Add(next);
                triangles.Add(current);
            }
        }

        private static Mesh CreateDistantPanoramaVistaNaturalConiferSpireMesh(string meshName, int seed, float width, float maxHeight, float depth, bool past)
        {
            const int treeCount = 17;
            const int tierCount = 6;
            var vertices = new List<Vector3>(treeCount * tierCount * 8);
            var uvs = new List<Vector2>(treeCount * tierCount * 8);
            var triangles = new List<int>(treeCount * tierCount * 72);
            var spacing = width / treeCount;

            for (var tree = 0; tree < treeCount; tree++)
            {
                var treeSeed = seed + tree * 131;
                var u = (tree + 0.5f) / treeCount;
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.50f, width * 0.50f, u) +
                    DistantPanoramaVistaSigned(treeSeed + 5, spacing * 0.28f) * edgeFalloff;
                var z = DistantPanoramaVistaSigned(treeSeed + 11, depth * 0.48f);
                var heightPulse = Mathf.Lerp(0.62f, 1.14f, DistantPanoramaVistaHash01(treeSeed + 17));
                var treeHeight = maxHeight * heightPulse * (past ? 1.04f : 1f);
                if (tree == 0 || tree == treeCount - 1)
                {
                    treeHeight *= 0.56f;
                }

                var treeWidth = spacing * Mathf.Lerp(0.72f, 1.18f, DistantPanoramaVistaHash01(treeSeed + 23));
                var treeDepth = depth * Mathf.Lerp(0.34f, 0.66f, DistantPanoramaVistaHash01(treeSeed + 29));
                for (var tier = 0; tier < tierCount; tier++)
                {
                    var tierT = tier / (float)(tierCount - 1);
                    var tierBase = new Vector3(
                        x + DistantPanoramaVistaSigned(treeSeed + 31 + tier * 7, treeWidth * 0.10f),
                        treeHeight * Mathf.Lerp(0.06f, 0.66f, tierT),
                        z + DistantPanoramaVistaSigned(treeSeed + 37 + tier * 11, treeDepth * 0.12f));
                    AddDistantPanoramaVistaConiferTier(
                        vertices,
                        uvs,
                        triangles,
                        tierBase,
                        treeWidth * Mathf.Lerp(1.04f, 0.40f, tierT),
                        treeDepth * Mathf.Lerp(1.00f, 0.42f, tierT),
                        treeHeight * Mathf.Lerp(0.34f, 0.20f, tierT),
                        treeSeed + tier * 43);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices.ToArray(),
                uv = uvs.ToArray(),
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static void AddDistantPanoramaVistaConiferTier(List<Vector3> vertices, List<Vector2> uvs, List<int> triangles, Vector3 baseCenter, float width, float depth, float height, int seed)
        {
            const int sideCount = 6;
            var start = vertices.Count;
            var lean = new Vector3(
                DistantPanoramaVistaSigned(seed + 41, width * 0.08f),
                0f,
                DistantPanoramaVistaSigned(seed + 43, depth * 0.08f));
            vertices.Add(baseCenter);
            uvs.Add(new Vector2(0.50f, 0.05f));
            vertices.Add(baseCenter + lean + new Vector3(0f, height, 0f));
            uvs.Add(new Vector2(0.50f, 1.00f));

            for (var side = 0; side < sideCount; side++)
            {
                var angle = (side / (float)sideCount) * Mathf.PI * 2f + DistantPanoramaVistaSigned(seed + 47, 0.10f);
                var pulse = Mathf.Lerp(0.82f, 1.18f, DistantPanoramaVistaHash01(seed + side * 19 + 53));
                vertices.Add(baseCenter + new Vector3(
                    Mathf.Cos(angle) * width * 0.50f * pulse,
                    height * Mathf.Lerp(0.04f, 0.14f, DistantPanoramaVistaHash01(seed + side * 23 + 59)),
                    Mathf.Sin(angle) * depth * 0.50f * pulse));
                uvs.Add(new Vector2(0.50f + Mathf.Cos(angle) * 0.44f, 0.42f + Mathf.Sin(angle) * 0.30f));
            }

            var bottomIndex = start;
            var tipIndex = start + 1;
            var ringStart = start + 2;
            for (var side = 0; side < sideCount; side++)
            {
                var current = ringStart + side;
                var next = ringStart + ((side + 1) % sideCount);
                triangles.Add(tipIndex);
                triangles.Add(current);
                triangles.Add(next);
                triangles.Add(tipIndex);
                triangles.Add(next);
                triangles.Add(current);
                triangles.Add(bottomIndex);
                triangles.Add(next);
                triangles.Add(current);
                triangles.Add(bottomIndex);
                triangles.Add(current);
                triangles.Add(next);
            }
        }

        private static Mesh CreateDistantPanoramaVistaNaturalTreeStandTrunkMesh(string meshName, int seed, float width, float maxHeight, float depth)
        {
            const int treeCount = 21;
            var vertices = new List<Vector3>(treeCount * 12);
            var uvs = new List<Vector2>(treeCount * 12);
            var triangles = new List<int>(treeCount * 108);
            var spacing = width / treeCount;

            for (var tree = 0; tree < treeCount; tree++)
            {
                var treeSeed = seed + tree * 113;
                var u = (tree + 0.5f) / treeCount;
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.5f, width * 0.5f, u) +
                    DistantPanoramaVistaSigned(treeSeed + 5, spacing * 0.22f) * edgeFalloff;
                var z = DistantPanoramaVistaSigned(treeSeed + 11, depth * 0.45f);
                var heightPulse = Mathf.Lerp(0.52f, 1.08f, DistantPanoramaVistaHash01(treeSeed + 17));
                var treeHeight = maxHeight * heightPulse;
                if (tree == 0 || tree == treeCount - 1)
                {
                    treeHeight *= 0.56f;
                }

                var trunkHeight = treeHeight * Mathf.Lerp(0.36f, 0.52f, DistantPanoramaVistaHash01(treeSeed + 79));
                var trunkWidth = spacing * Mathf.Lerp(0.060f, 0.105f, DistantPanoramaVistaHash01(treeSeed + 83));
                var trunkDepth = Mathf.Max(trunkWidth * 0.80f, depth * 0.045f);
                var top = new Vector3(
                    x + DistantPanoramaVistaSigned(treeSeed + 89, trunkWidth * 0.80f),
                    trunkHeight,
                    z + DistantPanoramaVistaSigned(treeSeed + 97, trunkDepth * 0.70f));
                AddDistantPanoramaVistaTrunkPrism(vertices, uvs, triangles, new Vector3(x, 0f, z), top, trunkWidth, trunkDepth);

                if (tree > 0 && tree < treeCount - 1 && DistantPanoramaVistaHash01(treeSeed + 101) > 0.48f)
                {
                    var splitBase = new Vector3(
                        x + DistantPanoramaVistaSigned(treeSeed + 103, trunkWidth * 0.56f),
                        trunkHeight * Mathf.Lerp(0.30f, 0.48f, DistantPanoramaVistaHash01(treeSeed + 107)),
                        z + DistantPanoramaVistaSigned(treeSeed + 109, trunkDepth * 0.45f));
                    var splitTop = splitBase + new Vector3(
                        DistantPanoramaVistaSigned(treeSeed + 113, spacing * 0.18f),
                        trunkHeight * Mathf.Lerp(0.42f, 0.66f, DistantPanoramaVistaHash01(treeSeed + 127)),
                        DistantPanoramaVistaSigned(treeSeed + 131, depth * 0.055f));
                    AddDistantPanoramaVistaTrunkPrism(
                        vertices,
                        uvs,
                        triangles,
                        splitBase,
                        splitTop,
                        trunkWidth * 0.58f,
                        trunkDepth * 0.62f);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices.ToArray(),
                uv = uvs.ToArray(),
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaNaturalBranchTraceMesh(string meshName, int seed, float width, float maxHeight, float depth)
        {
            const int treeCount = 21;
            var vertices = new List<Vector3>(treeCount * 32);
            var uvs = new List<Vector2>(treeCount * 32);
            var triangles = new List<int>(treeCount * 240);
            var spacing = width / treeCount;

            for (var tree = 0; tree < treeCount; tree++)
            {
                var treeSeed = seed + tree * 113;
                var u = (tree + 0.5f) / treeCount;
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.5f, width * 0.5f, u) +
                    DistantPanoramaVistaSigned(treeSeed + 5, spacing * 0.22f) * edgeFalloff;
                var z = depth * Mathf.Lerp(0.30f, 0.62f, DistantPanoramaVistaHash01(treeSeed + 11)) +
                    DistantPanoramaVistaSigned(treeSeed + 13, depth * 0.10f);
                var heightPulse = Mathf.Lerp(0.52f, 1.08f, DistantPanoramaVistaHash01(treeSeed + 17));
                var treeHeight = maxHeight * heightPulse;
                if (tree == 0 || tree == treeCount - 1)
                {
                    treeHeight *= 0.56f;
                }

                var trunkHeight = treeHeight * Mathf.Lerp(0.46f, 0.64f, DistantPanoramaVistaHash01(treeSeed + 79));
                var branchBase = new Vector3(x, trunkHeight * Mathf.Lerp(0.78f, 1.04f, DistantPanoramaVistaHash01(treeSeed + 83)), z);
                var branchWidth = Mathf.Max(spacing * Mathf.Lerp(0.075f, 0.130f, DistantPanoramaVistaHash01(treeSeed + 89)), 0.060f);
                var branchDepth = Mathf.Max(branchWidth * 0.62f, depth * 0.045f);
                var sweep = spacing * Mathf.Lerp(0.42f, 0.82f, DistantPanoramaVistaHash01(treeSeed + 97));
                var lift = treeHeight * Mathf.Lerp(0.18f, 0.34f, DistantPanoramaVistaHash01(treeSeed + 101));
                var frontLean = depth * Mathf.Lerp(0.10f, 0.28f, DistantPanoramaVistaHash01(treeSeed + 103));
                AddDistantPanoramaVistaTrunkPrism(
                    vertices,
                    uvs,
                    triangles,
                    branchBase,
                    branchBase + new Vector3(-sweep, lift, -frontLean),
                    branchWidth,
                    branchDepth);
                AddDistantPanoramaVistaTrunkPrism(
                    vertices,
                    uvs,
                    triangles,
                    branchBase + new Vector3(0f, treeHeight * 0.04f, 0f),
                    branchBase + new Vector3(sweep * 0.86f, lift * 0.82f, frontLean * 0.72f),
                    branchWidth * 0.86f,
                    branchDepth * 0.88f);
                if (DistantPanoramaVistaHash01(treeSeed + 105) > 0.38f)
                {
                    var twigBase = branchBase + new Vector3(
                        DistantPanoramaVistaSigned(treeSeed + 115, spacing * 0.10f),
                        treeHeight * Mathf.Lerp(0.06f, 0.14f, DistantPanoramaVistaHash01(treeSeed + 119)),
                        DistantPanoramaVistaSigned(treeSeed + 121, depth * 0.045f));
                    var twigSign = DistantPanoramaVistaHash01(treeSeed + 123) > 0.5f ? 1f : -1f;
                    AddDistantPanoramaVistaTrunkPrism(
                        vertices,
                        uvs,
                        triangles,
                        twigBase,
                        twigBase + new Vector3(
                            twigSign * sweep * Mathf.Lerp(0.34f, 0.58f, DistantPanoramaVistaHash01(treeSeed + 125)),
                            lift * Mathf.Lerp(0.34f, 0.52f, DistantPanoramaVistaHash01(treeSeed + 129)),
                            -frontLean * Mathf.Lerp(0.25f, 0.46f, DistantPanoramaVistaHash01(treeSeed + 133))),
                        branchWidth * 0.48f,
                        branchDepth * 0.54f);
                }

                if (tree % 3 == 1)
                {
                    var leaderBase = new Vector3(
                        x + DistantPanoramaVistaSigned(treeSeed + 107, spacing * 0.12f),
                        treeHeight * Mathf.Lerp(0.40f, 0.56f, DistantPanoramaVistaHash01(treeSeed + 109)),
                        z + depth * Mathf.Lerp(0.04f, 0.14f, DistantPanoramaVistaHash01(treeSeed + 113)));
                    var leaderTop = leaderBase + new Vector3(
                        DistantPanoramaVistaSigned(treeSeed + 127, spacing * 0.12f),
                        treeHeight * Mathf.Lerp(0.32f, 0.50f, DistantPanoramaVistaHash01(treeSeed + 131)),
                        DistantPanoramaVistaSigned(treeSeed + 137, depth * 0.06f));
                    AddDistantPanoramaVistaTrunkPrism(
                        vertices,
                        uvs,
                        triangles,
                        leaderBase,
                        leaderTop,
                        branchWidth * 0.74f,
                        branchDepth * 0.72f);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices.ToArray(),
                uv = uvs.ToArray(),
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaNaturalUnderstoryMesh(string meshName, int seed, float width, float maxHeight, float depth, bool past)
        {
            const int shrubCount = 27;
            var vertices = new List<Vector3>(shrubCount * 14);
            var uvs = new List<Vector2>(shrubCount * 14);
            var triangles = new List<int>(shrubCount * 84);
            var spacing = width / shrubCount;

            for (var shrub = 0; shrub < shrubCount; shrub++)
            {
                var shrubSeed = seed + shrub * 97;
                var u = (shrub + 0.5f) / shrubCount;
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.50f, width * 0.50f, u) +
                    DistantPanoramaVistaSigned(shrubSeed + 5, spacing * 0.30f) * edgeFalloff;
                var z = depth * Mathf.Lerp(0.30f, 0.66f, DistantPanoramaVistaHash01(shrubSeed + 11)) +
                    DistantPanoramaVistaSigned(shrubSeed + 13, depth * 0.08f);
                var lobeWidth = spacing * Mathf.Lerp(0.76f, 1.34f, DistantPanoramaVistaHash01(shrubSeed + 17));
                var lobeDepth = depth * Mathf.Lerp(0.26f, 0.52f, DistantPanoramaVistaHash01(shrubSeed + 23));
                var lobeHeight = maxHeight * Mathf.Lerp(0.14f, 0.28f, DistantPanoramaVistaHash01(shrubSeed + 29)) * (past ? 1.05f : 1f);
                var baseHeight = Mathf.Lerp(0.12f, 0.38f, DistantPanoramaVistaHash01(shrubSeed + 31));
                AddDistantPanoramaVistaCanopyLobe(
                    vertices,
                    uvs,
                    triangles,
                    new Vector3(x, baseHeight, z),
                    lobeWidth,
                    lobeDepth,
                    lobeHeight,
                    shrubSeed,
                    true);

                if (shrub > 1 && shrub < shrubCount - 2 && DistantPanoramaVistaHash01(shrubSeed + 37) > 0.42f)
                {
                    AddDistantPanoramaVistaCanopyLobe(
                        vertices,
                        uvs,
                        triangles,
                        new Vector3(
                            x + DistantPanoramaVistaSigned(shrubSeed + 41, spacing * 0.18f),
                            baseHeight + lobeHeight * 0.18f,
                            z + DistantPanoramaVistaSigned(shrubSeed + 43, lobeDepth * 0.40f)),
                        lobeWidth * 0.54f,
                        lobeDepth * 0.64f,
                        lobeHeight * 0.68f,
                        shrubSeed + 47,
                        true);
                }

                if (shrub > 2 && shrub < shrubCount - 3 && DistantPanoramaVistaHash01(shrubSeed + 53) > 0.64f)
                {
                    AddDistantPanoramaVistaCanopyLobe(
                        vertices,
                        uvs,
                        triangles,
                        new Vector3(
                            x + DistantPanoramaVistaSigned(shrubSeed + 59, spacing * 0.24f),
                            baseHeight + lobeHeight * 0.04f,
                            z + DistantPanoramaVistaSigned(shrubSeed + 61, lobeDepth * 0.50f)),
                        lobeWidth * 0.42f,
                        lobeDepth * 0.52f,
                        lobeHeight * 0.46f,
                        shrubSeed + 67,
                        true);
                }
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices.ToArray(),
                uv = uvs.ToArray(),
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static void AddDistantPanoramaVistaTrunkPrism(List<Vector3> vertices, List<Vector2> uvs, List<int> triangles, Vector3 bottomCenter, Vector3 topCenter, float width, float depth)
        {
            var start = vertices.Count;
            var halfWidth = width * 0.5f;
            var halfDepth = depth * 0.5f;
            vertices.Add(bottomCenter + new Vector3(-halfWidth, 0f, -halfDepth));
            vertices.Add(bottomCenter + new Vector3(halfWidth, 0f, -halfDepth));
            vertices.Add(bottomCenter + new Vector3(-halfWidth, 0f, halfDepth));
            vertices.Add(bottomCenter + new Vector3(halfWidth, 0f, halfDepth));
            vertices.Add(topCenter + new Vector3(-halfWidth * 0.55f, 0f, -halfDepth * 0.55f));
            vertices.Add(topCenter + new Vector3(halfWidth * 0.55f, 0f, -halfDepth * 0.55f));
            vertices.Add(topCenter + new Vector3(-halfWidth * 0.55f, 0f, halfDepth * 0.55f));
            vertices.Add(topCenter + new Vector3(halfWidth * 0.55f, 0f, halfDepth * 0.55f));

            for (var i = 0; i < 8; i++)
            {
                uvs.Add(new Vector2((i & 1) == 0 ? 0f : 1f, i < 4 ? 0f : 1f));
            }

            AddDoubleSidedQuad(triangles, start, start + 1, start + 4, start + 5);
            AddDoubleSidedQuad(triangles, start + 2, start + 6, start + 3, start + 7);
            AddDoubleSidedQuad(triangles, start, start + 4, start + 2, start + 6);
            AddDoubleSidedQuad(triangles, start + 1, start + 3, start + 5, start + 7);
            AddDoubleSidedQuad(triangles, start + 4, start + 5, start + 6, start + 7);
        }

        private static Mesh CreateDistantPanoramaVistaForestMesh(string meshName, int seed, float width, float maxHeight, float thickness)
        {
            const int columnCount = 17;
            var vertices = new Vector3[columnCount * 4];
            var uvs = new Vector2[columnCount * 4];
            var frontZ = -thickness * 0.5f;
            var backZ = thickness * 0.5f;

            for (var i = 0; i < columnCount; i++)
            {
                var u = i / (float)(columnCount - 1);
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.5f, width * 0.5f, u) +
                    DistantPanoramaVistaSigned(seed + i * 23 + 5, 0.10f) * edgeFalloff;
                var clumpA = Mathf.Clamp01(1f - Mathf.Abs(u - 0.24f) * 4.4f);
                var clumpB = Mathf.Clamp01(1f - Mathf.Abs(u - 0.52f) * 5.0f);
                var clumpC = Mathf.Clamp01(1f - Mathf.Abs(u - 0.80f) * 4.6f);
                var crownPulse = 0.34f + edgeFalloff * 0.22f + Mathf.Max(clumpA * 0.72f, Mathf.Max(clumpB, clumpC * 0.82f)) * 0.42f;
                var spire = DistantPanoramaVistaHash01(seed + i * 43);
                var height = maxHeight * crownPulse * Mathf.Lerp(0.70f, 1.22f, spire);
                if (i == 0 || i == columnCount - 1)
                {
                    height = Mathf.Min(height, maxHeight * 0.38f);
                }

                var baseIndex = i * 4;
                vertices[baseIndex] = new Vector3(x, 0f, frontZ);
                vertices[baseIndex + 1] = new Vector3(x, height, frontZ);
                vertices[baseIndex + 2] = new Vector3(x, 0f, backZ);
                vertices[baseIndex + 3] = new Vector3(x, height * 0.92f, backZ);
                uvs[baseIndex] = new Vector2(u, 0f);
                uvs[baseIndex + 1] = new Vector2(u, 1f);
                uvs[baseIndex + 2] = new Vector2(u, 0f);
                uvs[baseIndex + 3] = new Vector2(u, 1f);
            }

            var triangles = new List<int>((columnCount - 1) * 24);
            for (var i = 0; i < columnCount - 1; i++)
            {
                var a = i * 4;
                var b = (i + 1) * 4;

                AddDoubleSidedQuad(triangles, a, b, a + 1, b + 1);
                AddDoubleSidedQuad(triangles, a + 2, a + 3, b + 2, b + 3);
                AddDoubleSidedQuad(triangles, a + 1, b + 1, a + 3, b + 3);
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static Mesh CreateDistantPanoramaVistaReliefMesh(string meshName, int seed, float width, float maxHeight, float thickness, bool lowTreeLine)
        {
            const int columnCount = 23;
            var vertices = new Vector3[columnCount * 6];
            var uvs = new Vector2[columnCount * 6];
            var frontZ = -thickness * 0.5f;
            var backZ = thickness * 0.5f;

            for (var i = 0; i < columnCount; i++)
            {
                var u = i / (float)(columnCount - 1);
                var edgeFalloff = Mathf.Sin(u * Mathf.PI);
                var x = Mathf.Lerp(-width * 0.5f, width * 0.5f, u) +
                    DistantPanoramaVistaSigned(seed + i * 29 + 11, 0.10f) * edgeFalloff;
                var edgeTaper = 0.52f + Mathf.Sin(u * Mathf.PI) * 0.48f;
                var step = DistantPanoramaVistaHash01(seed + i * 37);
                var peakA = Mathf.Clamp01(1f - Mathf.Abs(u - 0.20f) * (lowTreeLine ? 4.8f : 3.8f));
                var peakB = Mathf.Clamp01(1f - Mathf.Abs(u - 0.48f) * (lowTreeLine ? 5.2f : 4.5f));
                var peakC = Mathf.Clamp01(1f - Mathf.Abs(u - 0.76f) * (lowTreeLine ? 4.4f : 4.0f));
                var saddle = Mathf.Clamp01(1f - Mathf.Abs(u - 0.62f) * 5.6f);
                var erodedGapA = Mathf.Clamp01(1f - Mathf.Abs(u - Mathf.Lerp(0.28f, 0.38f, DistantPanoramaVistaHash01(seed + 103))) * 7.2f);
                var erodedGapB = Mathf.Clamp01(1f - Mathf.Abs(u - Mathf.Lerp(0.58f, 0.86f, DistantPanoramaVistaHash01(seed + 109))) * 6.8f);
                var rockShoulder = Mathf.Clamp01(1f - Mathf.Abs(u - Mathf.Lerp(0.20f, 0.82f, DistantPanoramaVistaHash01(seed + 127))) * 5.8f);
                var authoredRhythm = Mathf.Max(peakA * 0.78f, Mathf.Max(peakB, peakC * 0.86f)) - saddle * 0.16f;
                var peakHeight = maxHeight * edgeTaper * Mathf.Lerp(lowTreeLine ? 0.40f : 0.50f, lowTreeLine ? 0.86f : 1.15f, step);
                peakHeight *= Mathf.Clamp(
                    0.86f + authoredRhythm * 0.31f + rockShoulder * 0.16f -
                    Mathf.Max(erodedGapA, erodedGapB) * (lowTreeLine ? 0.12f : 0.22f),
                    lowTreeLine ? 0.64f : 0.56f,
                    lowTreeLine ? 1.16f : 1.28f);
                if (i == 0 || i == columnCount - 1)
                {
                    peakHeight = Mathf.Min(peakHeight, maxHeight * 0.34f);
                }

                var shoulderHeight = peakHeight * Mathf.Lerp(0.26f, lowTreeLine ? 0.52f : 0.66f, DistantPanoramaVistaHash01(seed + i * 53 + 11));
                shoulderHeight += maxHeight * (rockShoulder * 0.06f - Mathf.Max(erodedGapA, erodedGapB) * 0.045f);
                var baseLift = DistantPanoramaVistaSigned(seed + i * 19 + 7, 0.06f);
                var baseIndex = i * 6;
                var skylineLean = (rockShoulder - erodedGapA) * 0.16f * edgeFalloff;
                vertices[baseIndex] = new Vector3(x, baseLift * 0.22f, frontZ);
                vertices[baseIndex + 1] = new Vector3(x + DistantPanoramaVistaSigned(seed + i * 31 + 13, 0.10f) * edgeFalloff - skylineLean, shoulderHeight + baseLift, Mathf.Lerp(frontZ, backZ, 0.24f));
                vertices[baseIndex + 2] = new Vector3(x + skylineLean, peakHeight, frontZ);
                vertices[baseIndex + 3] = new Vector3(x, baseLift * 0.16f, backZ);
                vertices[baseIndex + 4] = new Vector3(x + DistantPanoramaVistaSigned(seed + i * 41 + 17, 0.09f) * edgeFalloff + skylineLean * 0.5f, shoulderHeight * 0.92f + baseLift, Mathf.Lerp(frontZ, backZ, 0.76f));
                vertices[baseIndex + 5] = new Vector3(x + DistantPanoramaVistaSigned(seed + i * 47 + 19, 0.12f) * edgeFalloff + skylineLean, peakHeight * Mathf.Lerp(0.88f, 1.01f, DistantPanoramaVistaHash01(seed + i * 59 + 23)), backZ);
                uvs[baseIndex] = new Vector2(u, 0f);
                uvs[baseIndex + 1] = new Vector2(u, 0.42f);
                uvs[baseIndex + 2] = new Vector2(u, 1f);
                uvs[baseIndex + 3] = new Vector2(u, 0f);
                uvs[baseIndex + 4] = new Vector2(u, 0.42f);
                uvs[baseIndex + 5] = new Vector2(u, 1f);
            }

            var triangles = new List<int>((columnCount - 1) * 48);
            for (var i = 0; i < columnCount - 1; i++)
            {
                var a = i * 6;
                var b = (i + 1) * 6;

                AddDoubleSidedQuad(triangles, a, b, a + 1, b + 1);
                AddDoubleSidedQuad(triangles, a + 1, b + 1, a + 2, b + 2);
                AddDoubleSidedQuad(triangles, a + 3, a + 4, b + 3, b + 4);
                AddDoubleSidedQuad(triangles, a + 4, a + 5, b + 4, b + 5);
                AddDoubleSidedQuad(triangles, a + 2, b + 2, a + 5, b + 5);
            }

            var mesh = new Mesh
            {
                name = meshName,
                vertices = vertices,
                uv = uvs,
                triangles = triangles.ToArray()
            };
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static void AddDoubleSidedQuad(List<int> triangles, int a, int b, int c, int d)
        {
            triangles.Add(a);
            triangles.Add(c);
            triangles.Add(b);
            triangles.Add(b);
            triangles.Add(c);
            triangles.Add(d);

            triangles.Add(a);
            triangles.Add(b);
            triangles.Add(c);
            triangles.Add(b);
            triangles.Add(d);
            triangles.Add(c);
        }

        private static Material EnsureDistantPanoramaVistaMaterial(bool past, int band, FastVsHouseArea area)
        {
            return EnsureDistantPanoramaVistaTexturedBandMaterial(past, band, area);
        }

        private static Material EnsureDistantPanoramaVistaTexturedBandMaterial(bool past, int band, FastVsHouseArea area)
        {
            var areaToken = GetDistantPanoramaVistaAreaToken(area);
            var bandToken = band == 0 ? "NearHillsTextured" : (band == 1 ? "MidTreelineTextured" : "FarPeaksTextured");
            var id = past
                ? $"Ch1Distant_Past{areaToken}{bandToken}"
                : $"Ch1Distant_Current{areaToken}{bandToken}";
            var tiling = band == 0
                ? new Vector2(1.80f, 1.10f)
                : (band == 1 ? new Vector2(1.50f, 0.95f) : new Vector2(1.20f, 0.82f));
            Material material;
            if (past)
            {
                material = band == 0
                    ? PixelMaterial(
                        id,
                        new Color32(72, 76, 50, 255),
                        new Color32(88, 86, 56, 255),
                        new Color32(50, 56, 40, 255),
                        PixelPattern.DistantLandform,
                        true,
                        tiling,
                        FastVsHd2dMaterialRole.SurfaceLit)
                    : (band == 1
                        ? PixelMaterial(
                            id,
                            new Color32(44, 56, 38, 255),
                            new Color32(66, 72, 46, 255),
                            new Color32(28, 36, 30, 255),
                            PixelPattern.DistantNeedleCanopy,
                            true,
                            new Vector2(2.9f, 3.7f),
                            FastVsHd2dMaterialRole.SurfaceLit)
                        : PixelMaterial(
                            id,
                            new Color32(82, 70, 50, 255),
                            new Color32(112, 92, 58, 255),
                            new Color32(50, 44, 36, 255),
                            PixelPattern.DistantRockStrata,
                            true,
                            new Vector2(1.45f, 1.05f),
                            FastVsHd2dMaterialRole.SurfaceLit));
            }
            else
            {
                material = band == 0
                    ? PixelMaterial(
                        id,
                        new Color32(34, 68, 44, 255),
                        new Color32(62, 82, 46, 255),
                        new Color32(22, 42, 34, 255),
                        PixelPattern.DistantLandform,
                        true,
                        tiling,
                        FastVsHd2dMaterialRole.SurfaceLit)
                    : (band == 1
                        ? PixelMaterial(
                            id,
                            new Color32(18, 52, 42, 255),
                            new Color32(36, 70, 54, 255),
                            new Color32(8, 30, 28, 255),
                            PixelPattern.DistantNeedleCanopy,
                            true,
                            new Vector2(2.9f, 3.7f),
                            FastVsHd2dMaterialRole.SurfaceLit)
                        : PixelMaterial(
                            id,
                            new Color32(52, 62, 66, 255),
                            new Color32(78, 84, 78, 255),
                            new Color32(34, 42, 50, 255),
