        private static void CreateLibrary(Transform root, string prefix, bool past, Materials materials)
        {
            var c = LibraryVsCenter;
            var floor = past ? materials.PastWoodFloor : materials.CurrentInteriorFloor;
            var wall = past ? materials.PastInteriorWall : materials.CurrentInteriorWall;
            var wood = past ? materials.PastFurniture : materials.CurrentFurniture;
            var trim = past ? materials.PastFence : materials.CurrentFence;
            var backWallShelfMaterial = past
                ? BookshelfFrontMaterial($"{prefix}_Library_BackWallShelfWide", new Vector2(8.73f, 2.18f))
                : CurrentEmptyBookshelfFrontMaterial($"{prefix}_Library_BackWallShelfWide", new Vector2(8.73f, 2.18f));

            CreateLandmarkCube($"{prefix}_Library_PixelFloor", root, c, new Vector3(11.6f, 0.10f, 15.4f), Quaternion.identity, floor, true, TimeWindowPairedSpaceLandmarkKind.PathOrFloor, $"{prefix}.library.floor");
            CreateLandmarkCube($"{prefix}_Library_BackWall", root, c + new Vector3(0f, 1.40f, 7.55f), new Vector3(11.8f, 2.80f, 0.24f), Quaternion.identity, wall, true, TimeWindowPairedSpaceLandmarkKind.WallOrLandmark, $"{prefix}.library.back_wall");
            CreateLandmarkCube($"{prefix}_Library_BackWallShelfWide", root, c + new Vector3(0f, 1.24f, 7.28f), new Vector3(9.95f, 1.92f, 0.18f), Quaternion.identity, backWallShelfMaterial, false, TimeWindowPairedSpaceLandmarkKind.PropOrFeature, $"{prefix}.library.back_wall_shelf");
            AddHd2dSurfaceProfile(
                FindSceneObjectIncludingInactive($"{prefix}_Library_PixelFloor"),
                $"{(past ? "Past" : "Current")}.Library.Floor.Main",
                FastVsHouseArea.Library,
                FastVsHd2dSurfaceKind.Floor,
                !past,
                new Vector2(past ? 0.17f : 0.16f, past ? 0.28f : 0.27f),
                new Vector2(0.06f, 0.18f),
                past ? new Vector2(4f, 3f) : CurrentInteriorSurfaceReadabilityFloorTextureScale,
                true,
                past ? "past_wood_floor" : "current_interior_floor");
            AddHd2dSurfaceProfile(
                FindSceneObjectIncludingInactive($"{prefix}_Library_BackWall"),
                $"{(past ? "Past" : "Current")}.Library.Wall.Back",
                FastVsHouseArea.Library,
                FastVsHd2dSurfaceKind.Wall,
                !past,
                new Vector2(past ? 0.20f : 0.18f, past ? 0.31f : 0.29f),
                new Vector2(0.07f, 0.22f),
                new Vector2(6f, 4f),
                true,
                past ? "past_interior_wall" : "current_interior_wall");
            AddHd2dSurfaceProfile(
                FindSceneObjectIncludingInactive($"{prefix}_Library_BackWallShelfWide"),
                $"{(past ? "Past" : "Current")}.Library.Bookshelf.Back",
                FastVsHouseArea.Library,
                FastVsHd2dSurfaceKind.Bookshelf,
                !past,
                new Vector2(past ? 0.18f : 0.17f, past ? 0.28f : 0.27f),
                new Vector2(0.08f, 0.26f),
                new Vector2(4f, 3f),
                true,
                past ? "bookshelf_front_painted_hd2d" : "current_empty_bookshelf_front_hd2d");
            if (past)
            {
                CreateLandmarkCube("Past_Library_BackWallShelfBoardUpper", root, c + new Vector3(0f, 1.72f, 7.06f), new Vector3(9.45f, 0.08f, 0.22f), Quaternion.identity, wood, false, TimeWindowPairedSpaceLandmarkKind.PropOrFeature, "Past.library.back_wall_shelf.board.upper");
                CreateLandmarkCube("Past_Library_BackWallShelfBoardMiddle", root, c + new Vector3(0f, 1.20f, 7.06f), new Vector3(9.45f, 0.08f, 0.22f), Quaternion.identity, wood, false, TimeWindowPairedSpaceLandmarkKind.PropOrFeature, "Past.library.back_wall_shelf.board.middle");
                CreateLandmarkCube("Past_Library_BackWallShelfBoardLower", root, c + new Vector3(0f, 0.68f, 7.06f), new Vector3(9.45f, 0.08f, 0.22f), Quaternion.identity, wood, false, TimeWindowPairedSpaceLandmarkKind.PropOrFeature, "Past.library.back_wall_shelf.board.lower");
                // Rejected in built-player review: the single book-spine texture plate reads as a stray striped object.
