        private static void CreateLibraryWindowLightAccents(Transform root, string prefix, bool past, Materials materials)
        {
            _ = materials.WindowLight;
            var windowLight = EnsureHd2dLibraryWindowLightMaterial();
            var shaftScale = past ? new Vector3(1.96f, 1.50f, 1f) : new Vector3(1.80f, 1.38f, 1f);
            var poolScale = past ? new Vector3(1.18f, 1.84f, 1f) : new Vector3(1.10f, 1.72f, 1f);
            var shaftY = 1.12f;
            var poolY = 0.035f;
            var shaftDepth = past ? -1.95f : -1.88f;
            var poolDepth = past ? -1.58f : -1.52f;

            CreateHd2dLibraryWindowLightQuad(
                $"{prefix}_Library_WindowLightShaft_Left",
                root,
                LibraryVsCenter + new Vector3(-5.30f, shaftY, shaftDepth),
                Quaternion.Euler(0f, 90f, -7f),
                shaftScale,
                windowLight,
                $"{prefix}.library.window_light.shaft.left");

            CreateHd2dLibraryWindowLightQuad(
                $"{prefix}_Library_WindowLightShaft_Right",
                root,
                LibraryVsCenter + new Vector3(5.30f, shaftY, shaftDepth),
                Quaternion.Euler(0f, -90f, 7f),
                shaftScale,
                windowLight,
                $"{prefix}.library.window_light.shaft.right");

            CreateHd2dLibraryWindowLightQuad(
                $"{prefix}_Library_WindowLightPool_LeftFloor",
                root,
                LibraryVsCenter + new Vector3(-4.52f, poolY, poolDepth),
                Quaternion.Euler(90f, 0f, 0f),
                poolScale,
                windowLight,
                $"{prefix}.library.window_light.pool.left_floor");

            CreateHd2dLibraryWindowLightQuad(
                $"{prefix}_Library_WindowLightPool_RightFloor",
                root,
                LibraryVsCenter + new Vector3(4.52f, poolY, poolDepth),
                Quaternion.Euler(90f, 0f, 0f),
                poolScale,
                windowLight,
                $"{prefix}.library.window_light.pool.right_floor");
        }

        private static void CreateLibraryWallPlaneDressing(Transform root, string prefix, bool past, Materials materials, Vector3 c, Material wood, Material trim)
        {
            var shelfContactShadow = past ? materials.Shadow : materials.Dust;
            var wallBaseShadow = past ? materials.Shadow : materials.Dust;
            var backUpperDepthBandMaterial = past ? materials.Shadow : materials.Dust;
            var backPilasterMaterial = past ? trim : materials.Dust;
            var backPilasterScale = past ? new Vector3(0.10f, 1.44f, 0.06f) : new Vector3(0.08f, 1.30f, 0.05f);
            var windowRecessMaterial = past ? trim : materials.Dust;
            var windowRecessScale = past ? new Vector3(0.14f, 0.74f, 0.05f) : new Vector3(0.08f, 0.66f, 0.04f);

            CreateLandmarkCube(
                $"{prefix}_Library_WallPlane_BackUpperDepthBandA",
                root,
                c + new Vector3(0f, 2.18f, 6.99f),
                new Vector3(9.36f, 0.05f, 0.05f),
                Quaternion.identity,
                backUpperDepthBandMaterial,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.wall_plane.back_upper_depth_band_a");

            CreateLandmarkCube(
                $"{prefix}_Library_WallPlane_BackShelfContactShadowA",
                root,
                c + new Vector3(0f, 1.82f, 6.94f),
                new Vector3(9.08f, 0.04f, 0.05f),
                Quaternion.identity,
                shelfContactShadow,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.wall_plane.back_shelf_contact_shadow_a");

            CreateLandmarkCube(
                $"{prefix}_Library_WallPlane_BackPilasterLeftA",
                root,
                c + new Vector3(-3.44f, 1.58f, 7.02f),
                backPilasterScale,
                Quaternion.identity,
                backPilasterMaterial,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.wall_plane.back_pilaster_left_a");

            CreateLandmarkCube(
                $"{prefix}_Library_WallPlane_BackPilasterRightA",
                root,
                c + new Vector3(3.44f, 1.58f, 7.02f),
                backPilasterScale,
                Quaternion.identity,
                backPilasterMaterial,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.wall_plane.back_pilaster_right_a");

            CreateLandmarkCube(
                $"{prefix}_Library_WallPlane_LeftWallBaseShadowA",
                root,
                c + new Vector3(-5.50f, 0.032f, 0.40f),
                new Vector3(0.05f, 0.028f, 9.78f),
                Quaternion.identity,
                wallBaseShadow,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.wall_plane.left_wall_base_shadow_a");

            CreateLandmarkCube(
                $"{prefix}_Library_WallPlane_RightWallBaseShadowA",
                root,
                c + new Vector3(5.50f, 0.032f, 0.40f),
                new Vector3(0.05f, 0.028f, 9.78f),
                Quaternion.identity,
                wallBaseShadow,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.wall_plane.right_wall_base_shadow_a");

            CreateLandmarkCube(
                $"{prefix}_Library_WallPlane_LeftWindowRecessA",
                root,
                c + new Vector3(-5.50f, 1.48f, -2.01f),
                windowRecessScale,
                Quaternion.identity,
                windowRecessMaterial,
                false,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                $"{prefix}.library.wall_plane.left_window_recess_a");

            CreateLandmarkCube(
                $"{prefix}_Library_WallPlane_RightWindowRecessA",
