        private static TMP_FontAsset EnsureFastVsDialogueTmpFontAsset()
        {
            var existing = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(FastVsDialogueFontAssetPath);
            if (existing != null)
            {
                return existing;
            }

            throw new InvalidOperationException($"Fast VS dialogue TMP font asset is missing: {FastVsDialogueFontAssetPath}");
        }

        private static Camera CreateCamera(Transform currentRoot)
        {
            var cameraObject = new GameObject("Main Camera", typeof(Camera), typeof(AudioListener));
            cameraObject.tag = "MainCamera";
            var additionalData = cameraObject.GetComponent<UniversalAdditionalCameraData>();
            if (additionalData == null)
            {
                additionalData = cameraObject.AddComponent<UniversalAdditionalCameraData>();
            }

            additionalData.renderPostProcessing = true;
            additionalData.requiresDepthTexture = true;
            additionalData.volumeLayerMask |= (1 << CurrentSpaceRenderLayer) | (1 << OtherTimeSpaceRenderLayer);
            var camera = cameraObject.GetComponent<Camera>();
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color(0.064f, 0.060f, 0.060f, 1f);
            camera.fieldOfView = 38f;
            camera.nearClipPlane = 0.03f;
            camera.farClipPlane = 240f;
            var position = currentRoot.TransformPoint(HouseInteriorCenter + new Vector3(-0.90f, 2.78f, -5.15f));
            var lookAt = currentRoot.TransformPoint(HouseInteriorCenter + new Vector3(-0.20f, 0.72f, 0.20f));
            camera.transform.SetPositionAndRotation(position, Quaternion.LookRotation(lookAt - position, Vector3.up));
            return camera;
        }

        private static void ApplyInitialReviewLayers(Transform currentRoot, Transform pastRoot, Transform player, Camera camera)
        {
            SetLayerRecursive(currentRoot, CurrentSpaceRenderLayer);
            SetLayerRecursive(pastRoot, OtherTimeSpaceRenderLayer);
            SetLayerRecursive(player, PlayerVisibleRenderLayer);

            var currentBit = 1 << CurrentSpaceRenderLayer;
            var pastBit = 1 << OtherTimeSpaceRenderLayer;
            var portalBit = 1 << PortalFrameRenderLayer;
            var playerBit = 1 << PlayerVisibleRenderLayer;
            camera.cullingMask = (camera.cullingMask | currentBit | portalBit | playerBit) & ~pastBit;
        }

        private static void SetLayerRecursive(Transform root, int layer)
        {
            if (root == null)
            {
                return;
            }

            var clamped = Mathf.Clamp(layer, 0, 31);
            foreach (var target in root.GetComponentsInChildren<Transform>(true))
            {
                target.gameObject.layer = clamped;
            }
        }

        private static void CreateLighting(Camera camera, FastVsHouseAreaVisibility areaVisibility)
        {
            var lightObject = new GameObject("Directional Light", typeof(Light));
            var light = lightObject.GetComponent<Light>();
            light.type = LightType.Directional;
            light.intensity = 1.10f;
            light.shadows = LightShadows.Soft;
            light.shadowStrength = 0.80f;
            light.color = new Color(1.00f, 0.88f, 0.68f, 1f);
            lightObject.transform.rotation = Quaternion.Euler(GetUnifiedSunKeyLightEulerDegrees(FastVsHouseArea.Interior));
            ApplyHd2dPhaseBLensFlareToDirectionalLight(light);
#if BUTO
            var butoLight = lightObject.GetComponent<OccaSoftware.Buto.Runtime.ButoLight>() ??
                lightObject.AddComponent<OccaSoftware.Buto.Runtime.ButoLight>();
            butoLight.SetInheritance(true);
            butoLight.SetDirty();
            EditorUtility.SetDirty(butoLight);
#endif
            var warmFillObject = new GameObject("FastVS_HD2D_WarmFillLight", typeof(Light));
            var warmFill = warmFillObject.GetComponent<Light>();
            warmFill.type = LightType.Point;
            warmFill.intensity = 0.24f;
            warmFill.range = 5.8f;
            warmFill.color = new Color(1.00f, 0.72f, 0.46f, 1f);
            warmFill.shadows = LightShadows.None;
            warmFillObject.transform.position = new Vector3(-7.25f, 1.65f, -9.10f);

            var coolRimObject = new GameObject("FastVS_HD2D_CoolRimLight", typeof(Light));
            var coolRim = coolRimObject.GetComponent<Light>();
            coolRim.type = LightType.Directional;
            coolRim.intensity = 0.032f;
            coolRim.color = new Color(0.60f, 0.72f, 1.00f, 1f);
            coolRim.shadows = LightShadows.None;
            coolRimObject.transform.rotation = Quaternion.Euler(25f, 132f, 0f);

            ApplyReferenceSunShadowGradeCycle99(light, warmFill, coolRim);

            var libraryWindowObject = new GameObject("FastVS_HD2D_LibraryWindowLight", typeof(Light));
            var libraryWindow = libraryWindowObject.GetComponent<Light>();
            libraryWindow.type = LightType.Spot;
            libraryWindow.enabled = false;
            libraryWindow.intensity = 0f;
            libraryWindow.range = 8.5f;
            libraryWindow.spotAngle = 48f;
            libraryWindow.color = new Color(1.00f, 0.76f, 0.48f, 1f);
            libraryWindow.shadows = LightShadows.None;
            libraryWindow.cookie = EnsureHd2dLibraryWindowLightCookieTexture();
            libraryWindow.cullingMask = Hd2dFeedbackLibraryWindowLightCullingMask;
            libraryWindowObject.transform.SetPositionAndRotation(new Vector3(28.55f, 3.05f, 23.15f), Quaternion.Euler(58f, 36f, 0f));

            var directorObject = new GameObject("FastVS_HD2D_LightingDirector");
            var director = directorObject.AddComponent<FastVsHouseLightingDirector>();
            SerializedSet(director, "areaVisibility", areaVisibility);
            SerializedSet(director, "sceneCamera", camera);
            SerializedSet(director, "mainLight", light);
            SerializedSet(director, "warmFillLight", warmFill);
            SerializedSet(director, "coolRimLight", coolRim);
            SerializedSet(director, "libraryWindowLight", libraryWindow);
            director.ApplyAreaForReview(FastVsHouseArea.Interior);

            var realtimeRigObject = new GameObject("FastVS_HD2D_RealtimeLightShadowRig");
            var realtimeRig = realtimeRigObject.AddComponent<FastVsRealtimeLightShadowRig>();
            SerializedSet(realtimeRig, "areaVisibility", areaVisibility);
            SerializedSet(realtimeRig, "sceneCamera", camera);
            SerializedSet(realtimeRig, "mainLight", light);

            RenderSettings.ambientMode = AmbientMode.Flat;
            RenderSettings.ambientLight = new Color(0.155f, 0.145f, 0.138f, 1f);
            RenderSettings.fog = false;
            RenderSettings.fogMode = FogMode.Linear;
            RenderSettings.fogColor = new Color(0.080f, 0.074f, 0.070f);
            RenderSettings.fogStartDistance = 10f;
            RenderSettings.fogEndDistance = 42f;
        }

        private static void ApplyReferenceSunShadowGradeCycle99(Light mainLight, Light warmFill, Light coolRim)
        {
            if (mainLight != null)
            {
                mainLight.type = LightType.Directional;
                mainLight.intensity = 1.10f;
                mainLight.shadows = LightShadows.Soft;
                mainLight.shadowStrength = 0.80f;
                mainLight.color = new Color(1.00f, 0.88f, 0.68f, 1f);
            }

            if (warmFill != null)
            {
                warmFill.type = LightType.Point;
                warmFill.intensity = 0.24f;
                warmFill.shadows = LightShadows.None;
                warmFill.color = new Color(1.00f, 0.72f, 0.46f, 1f);
            }

            if (coolRim != null)
            {
                coolRim.type = LightType.Directional;
                coolRim.intensity = 0.032f;
                coolRim.shadows = LightShadows.None;
                coolRim.color = new Color(0.60f, 0.72f, 1.00f, 1f);
            }

            RenderSettings.ambientMode = AmbientMode.Flat;
            RenderSettings.ambientLight = new Color(0.145f, 0.136f, 0.128f, 1f);
            RenderSettings.fog = true;
            RenderSettings.fogMode = FogMode.Linear;
            RenderSettings.fogColor = new Color(0.186f, 0.154f, 0.124f);
            RenderSettings.fogStartDistance = 12f;
            RenderSettings.fogEndDistance = 48f;
        }

        private static Vector3 GetUnifiedSunKeyLightEulerDegrees(FastVsHouseArea area)
        {
            switch (area)
            {
                case FastVsHouseArea.Interior:
                case FastVsHouseArea.MiaInterior:
                case FastVsHouseArea.AriaInterior:
                    return new Vector3(UnifiedInteriorSunElevationDegrees, UnifiedSunAzimuthDegrees, 0f);
                case FastVsHouseArea.Library:
                    return new Vector3(UnifiedLibrarySunElevationDegrees, UnifiedSunAzimuthDegrees, 0f);
                case FastVsHouseArea.CentralPlaza:
                    return new Vector3(UnifiedCentralPlazaSunElevationDegrees, UnifiedSunAzimuthDegrees, 0f);
                case FastVsHouseArea.Exterior:
                default:
                    return new Vector3(UnifiedExteriorSunElevationDegrees, UnifiedSunAzimuthDegrees, 0f);
            }
        }

