        private static void ValidateHd2dCycle180RuntimeStorySunPolicySource()
        {
            var doorTransitionSourcePath = Path.Combine("Assets", "Scripts", "FastVS", "FastVsAreaDoorTransition.cs");
            var sunCycleSourcePath = Path.Combine("Assets", "Scripts", "FastVS", "SunCycle", "AnemoraSunCycleDriver.cs");
            var dynamicShaftSourcePath = Path.Combine("Assets", "Scripts", "FastVS", "FastVsDynamicSunShaftField.cs");
            var doorTransitionSource = File.ReadAllText(doorTransitionSourcePath);
            var sunCycleSource = File.ReadAllText(sunCycleSourcePath);
            var dynamicShaftSource = File.ReadAllText(dynamicShaftSourcePath);

            ValidateSourceToken(doorTransitionSource, "sourceArea == FastVsHouseArea.Library && targetArea == FastVsHouseArea.CentralPlaza", doorTransitionSourcePath);
            ValidateSourceToken(doorTransitionSource, "storyReachedPostLibraryNoon = true;", doorTransitionSourcePath);
            ValidateSourceToken(doorTransitionSource, "driver.ApplyPreset(storyReachedPostLibraryNoon ? SunPreset.Noon : SunPreset.Morning, true);", doorTransitionSourcePath);
            ValidateSourceToken(sunCycleSource, "IndoorSunSuppressionActiveForReview", sunCycleSourcePath);
            ValidateSourceToken(sunCycleSource, "areaVisibility.ActiveAreaForReview == FastVsHouseArea.Interior", sunCycleSourcePath);
            ValidateSourceToken(sunCycleSource, "areaVisibility.ActiveAreaForReview == FastVsHouseArea.Library", sunCycleSourcePath);
            ValidateSourceToken(dynamicShaftSource, "public sealed class FastVsDynamicSunShaftField", dynamicShaftSourcePath);
            ValidateSourceToken(dynamicShaftSource, "renderer.SetPropertyBlock(propertyBlock);", dynamicShaftSourcePath);
        }

        private static void ValidateLibraryArtifactTriageObject(string objectName, string expectedParentName, string expectedMaterialToken)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing library artifact triage object {objectName}.");
            }

            var parentName = sceneObject.transform.parent != null ? sceneObject.transform.parent.name : string.Empty;
            if (!string.Equals(parentName, expectedParentName, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must be parented under {expectedParentName}, found {parentName}.");
            }

            var renderer = sceneObject.GetComponent<Renderer>();
            var materialPath = renderer != null && renderer.sharedMaterial != null ? AssetDatabase.GetAssetPath(renderer.sharedMaterial) : string.Empty;
            if (string.IsNullOrEmpty(materialPath) || !materialPath.Contains(expectedMaterialToken, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep material token {expectedMaterialToken}, found {materialPath}.");
            }
        }

        private static void ValidateHd2dPhaseASunCyclePlazaBroadSunshaftReceiver(
            string objectName,
            string expectedParentName,
            Vector3 expectedLocalPosition,
            Vector3 expectedLocalScale,
            string expectedLandmarkId)
        {
            var receiverObject = FindSceneObjectIncludingInactive(objectName);
            if (receiverObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing Phase A plaza broad sunshaft receiver {objectName}.");
            }

            var parentName = receiverObject.transform.parent != null ? receiverObject.transform.parent.name : string.Empty;
            if (!string.Equals(parentName, expectedParentName, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must be parented under {expectedParentName}, found {parentName}.");
            }

            ValidateVectorNear($"{objectName} local position", receiverObject.transform.localPosition, expectedLocalPosition);
            ValidateVectorNear($"{objectName} local scale", receiverObject.transform.localScale, expectedLocalScale);

            if (receiverObject.GetComponent<Renderer>() != null || receiverObject.GetComponentsInChildren<Collider>(true).Length > 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must stay as a pure diagnostic receiver marker.");
            }

            var landmark = receiverObject.GetComponent<TimeWindowPairedSpaceLandmark>();
            if (landmark == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep a TimeWindowPairedSpaceLandmark.");
            }

            var landmarkSerialized = new SerializedObject(landmark);
            var landmarkIdProperty = landmarkSerialized.FindProperty("landmarkId");
            if (landmarkIdProperty == null ||
                landmarkIdProperty.propertyType != SerializedPropertyType.String ||
                !string.Equals(landmarkIdProperty.stringValue, expectedLandmarkId, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep landmark id {expectedLandmarkId}.");
            }

            var kindProperty = landmarkSerialized.FindProperty("kind");
            if (kindProperty == null ||
                kindProperty.propertyType != SerializedPropertyType.Enum ||
                kindProperty.enumValueIndex != Convert.ToInt32(TimeWindowPairedSpaceLandmarkKind.PropOrFeature))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must use TimeWindowPairedSpaceLandmarkKind.PropOrFeature.");
            }

            var countsForArrivalProperty = landmarkSerialized.FindProperty("countsForArrival");
            if (countsForArrivalProperty == null ||
                countsForArrivalProperty.propertyType != SerializedPropertyType.Boolean ||
                countsForArrivalProperty.boolValue)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must not count for arrival.");
            }
        }

        private static void ValidateHd2dPhaseBAlphaSceneLensFlareSetup()
        {
            var directionalSunObject = FindSceneObjectIncludingInactive("Directional Light");
            var directionalSun = directionalSunObject != null ? directionalSunObject.GetComponent<Light>() : null;
            if (directionalSun == null)
            {
                throw new InvalidOperationException("House slice validation failed: phase B-alpha directional lens flare setup is missing the Directional Light.");
            }

            var lensFlare = directionalSunObject.GetComponent<LensFlareComponentSRP>();
            if (lensFlare == null)
            {
                throw new InvalidOperationException("House slice validation failed: phase B-alpha directional lens flare setup is missing LensFlareComponentSRP.");
            }

            var lensFlareDataPath = AssetDatabase.GetAssetPath(lensFlare.lensFlareData);
            if (!string.Equals(lensFlareDataPath, Hd2dPhaseBLensFlareDataAssetPath, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: phase B-alpha directional lens flare must reference {Hd2dPhaseBLensFlareDataAssetPath}, found {lensFlareDataPath}.");
            }

            if (lensFlare.intensity < 0.25f || lensFlare.intensity > 0.80f)
            {
                throw new InvalidOperationException($"House slice validation failed: phase B-alpha directional lens flare intensity must remain in the SunPreset-driven range, found {lensFlare.intensity:0.000}.");
            }

            if (lensFlare.lensFlareData == null || lensFlare.lensFlareData.elements == null || lensFlare.lensFlareData.elements.Length < 6)
            {
                throw new InvalidOperationException("House slice validation failed: phase B-alpha directional lens flare data asset must contain at least 6 procedural elements.");
            }

            var volumeObject = FindSceneObjectIncludingInactive("FastVS_HD2D_GlobalVolume");
            var volume = volumeObject != null ? volumeObject.GetComponent<Volume>() : null;
            const string profilePath = "Assets/Settings/DefaultVolumeProfile.asset";
            if (volume == null || volume.sharedProfile == null || AssetDatabase.GetAssetPath(volume.sharedProfile) != profilePath)
            {
                throw new InvalidOperationException("House slice validation failed: phase B-alpha global volume must keep Assets/Settings/DefaultVolumeProfile.asset.");
            }

            var profile = volume.sharedProfile;
            if (!profile.TryGet<ScreenSpaceLensFlare>(out var screenSpaceLensFlare))
            {
                throw new InvalidOperationException("House slice validation failed: phase B-alpha default volume profile is missing ScreenSpaceLensFlare.");
            }

            if (!screenSpaceLensFlare.active ||
                Mathf.Abs(screenSpaceLensFlare.intensity.value - 0.4f) > 0.001f ||
                screenSpaceLensFlare.samples.value > 1 ||
                screenSpaceLensFlare.resolution.value != ScreenSpaceLensFlareResolution.Quarter)
            {
                throw new InvalidOperationException($"House slice validation failed: phase B-alpha ScreenSpaceLensFlare must stay active with intensity 0.4 and low samples, found active={screenSpaceLensFlare.active}, intensity={screenSpaceLensFlare.intensity.value:0.000}, samples={screenSpaceLensFlare.samples.value}, resolution={screenSpaceLensFlare.resolution.value}.");
            }

            ValidateHd2dPhaseBAlphaRenderPipelineLensFlareSupport();
        }

        private static void ValidateHd2dPhaseBAlphaRenderPipelineLensFlareSupport()
        {
            var pipelineAsset = AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(UniversalRenderPipelineAssetPath);
            if (pipelineAsset == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing URP asset at {UniversalRenderPipelineAssetPath}.");
            }

            var serialized = new SerializedObject(pipelineAsset);
            var supportDataDrivenLensFlare = serialized.FindProperty("m_SupportDataDrivenLensFlare");
            var supportScreenSpaceLensFlare = serialized.FindProperty("m_SupportScreenSpaceLensFlare");
            if (supportDataDrivenLensFlare == null || supportScreenSpaceLensFlare == null)
            {
                throw new InvalidOperationException("House slice validation failed: URP asset must expose data-driven and screen-space lens flare support serialized properties.");
            }

            if (!supportDataDrivenLensFlare.boolValue || !supportScreenSpaceLensFlare.boolValue)
            {
                throw new InvalidOperationException("House slice validation failed: URP lens flare support flags must remain enabled.");
            }
        }

        private static void ValidateHd2dPhaseASunCycleDriverDefaults(AnemoraSunCycleDriver driver)
        {
            var defaultPresetIndex = GetSerializedEnumIndex(driver, "defaultPreset");
            if (defaultPresetIndex != (int)SunPreset.Morning)
            {
                throw new InvalidOperationException($"House slice validation failed: Phase A SunCycle default preset must be Morning for the pre-library-exit story beat, found {(SunPreset)defaultPresetIndex}.");
            }

            var transitionDuration = GetSerializedFloat(driver, "transitionDuration");
            if (Mathf.Abs(transitionDuration - 1.8f) > 0.001f)
            {
                throw new InvalidOperationException($"House slice validation failed: Phase A SunCycle transition duration must be 1.8, found {transitionDuration:0.###}.");
            }
        }

        private static void ValidateHd2dPhaseASunCycleDriverPresets(AnemoraSunCycleDriver driver)
        {
            var expectedAssets = LoadHd2dPhaseASunPresetAssets();
            var serialized = new SerializedObject(driver);
            var presetsProperty = serialized.FindProperty("presets");
            if (presetsProperty == null || !presetsProperty.isArray)
            {
                throw new InvalidOperationException("House slice validation failed: Phase A SunCycle driver presets array is missing.");
            }

            if (presetsProperty.arraySize != expectedAssets.Length)
            {
                throw new InvalidOperationException($"House slice validation failed: Phase A SunCycle driver needs {expectedAssets.Length} presets, found {presetsProperty.arraySize}.");
            }

            for (var index = 0; index < expectedAssets.Length; index++)
            {
                var expectedAsset = expectedAssets[index];
                var referencedAsset = presetsProperty.GetArrayElementAtIndex(index).objectReferenceValue as SunPresetData;
                if (referencedAsset != expectedAsset)
                {
                    throw new InvalidOperationException($"House slice validation failed: Phase A SunCycle preset index {index} must reference {AssetDatabase.GetAssetPath(expectedAsset)}.");
                }

                if (driver.GetPresetData(expectedAsset.preset) != expectedAsset)
                {
                    throw new InvalidOperationException($"House slice validation failed: Phase A SunCycle driver lookup did not resolve {expectedAsset.preset}.");
                }
            }
        }

        private static void ValidateHd2dPhaseASunCycleAnchors()
        {
            ValidateHd2dPhaseASunCycleAnchor(
                "FastVS_HD2D_MapSunAnchor_Interior_Morning",
                "Current_HouseInteriorMap_SeparateSpace",
                SunPreset.Morning,
                false,
                0);
            ValidateHd2dPhaseASunCycleAnchor(
                "FastVS_HD2D_MapSunAnchor_Exterior_Morning",
                "Current_HouseExteriorMap_SeparateSpace",
                SunPreset.Morning,
                true,
                0);
            ValidateHd2dPhaseASunCycleAnchor(
                "FastVS_HD2D_MapSunAnchor_CentralPlaza_Morning",
                "Current_CentralPlazaMap_SeparateSpace",
                SunPreset.Morning,
                true,
                0);
            ValidateHd2dPhaseASunCycleAnchor(
                "FastVS_HD2D_MapSunAnchor_Library_Morning",
                "Current_LibraryMap_SeparateSpace",
                SunPreset.Morning,
                true,
                0);

            var anchors = UnityEngine.Object.FindObjectsByType<MapSunAnchor>(FindObjectsInactive.Include, FindObjectsSortMode.InstanceID);
            if (anchors.Length != 4)
            {
                throw new InvalidOperationException($"House slice validation failed: Phase A SunCycle expected exactly 4 map sun anchors, found {anchors.Length}.");
            }
        }

        private static void ValidateHd2dPhaseASunCycleAnchor(
            string objectName,
            string expectedParentName,
            SunPreset expectedPreset,
            bool expectedTransitionFromPrevious,
            int expectedPriority)
        {
            var anchorObject = FindSceneObjectIncludingInactive(objectName);
            if (anchorObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing Phase A SunCycle anchor object {objectName}.");
            }

            var anchor = anchorObject.GetComponent<MapSunAnchor>();
            if (anchor == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} is missing the MapSunAnchor component.");
            }

            var parentName = anchorObject.transform.parent != null ? anchorObject.transform.parent.name : string.Empty;
            if (!string.Equals(parentName, expectedParentName, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must be parented under {expectedParentName}, found {parentName}.");
            }

            if (anchor.SunPreset != expectedPreset ||
                anchor.TransitionFromPrevious != expectedTransitionFromPrevious ||
                anchor.Priority != expectedPriority)
            {
                throw new InvalidOperationException(
                    $"House slice validation failed: {objectName} has preset={anchor.SunPreset}, transition={anchor.TransitionFromPrevious}, priority={anchor.Priority}; " +
                    $"expected preset={expectedPreset}, transition={expectedTransitionFromPrevious}, priority={expectedPriority}.");
            }

            if (GetSerializedEnumIndex(anchor, "sunPreset") != (int)expectedPreset ||
                GetSerializedInt(anchor, "priority") != expectedPriority ||
                GetSerializedBool(anchor, "transitionFromPrevious") != expectedTransitionFromPrevious)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} serialized anchor fields do not match the public runtime contract.");
            }
        }

        private static void ValidateHd2dPhaseASunCycleTransition(AnemoraSunCycleDriver driver)
        {
            driver.ApplyPreset(SunPreset.Morning, true);
            if (driver.CurrentPreset != SunPreset.Morning || driver.TargetPreset != SunPreset.Morning || driver.IsTransitioning)
            {
                throw new InvalidOperationException("House slice validation failed: Phase A SunCycle instant morning application did not settle immediately.");
            }

            driver.ApplyPreset(SunPreset.Evening, false);
            if (!driver.IsTransitioning || driver.CurrentPreset != SunPreset.Morning || driver.TargetPreset != SunPreset.Evening)
            {
                throw new InvalidOperationException(
                    $"House slice validation failed: Phase A SunCycle non-instant transition did not start from Morning to Evening. " +
                    $"current={driver.CurrentPreset}, target={driver.TargetPreset}, transitioning={driver.IsTransitioning}.");
            }

            driver.ApplyPreset(SunPreset.Noon, true);
            if (driver.IsTransitioning || driver.CurrentPreset != SunPreset.Noon || driver.TargetPreset != SunPreset.Noon)
            {
                throw new InvalidOperationException("House slice validation failed: Phase A SunCycle instant noon cleanup did not settle immediately.");
            }
        }

        private static void ValidateHd2dPhaseASunCycleSceneYaml()
        {
            var sceneText = File.ReadAllText(ScenePath);
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, Hd2dPhaseASunCycleRootName);
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "FastVS_HD2D_MapSunAnchor_Interior_Morning");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "FastVS_HD2D_MapSunAnchor_Exterior_Morning");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "FastVS_HD2D_MapSunAnchor_CentralPlaza_Morning");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "FastVS_HD2D_MapSunAnchor_Library_Morning");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "FastVS_HD2D_Cycle180_CentralPlaza_BroadSunshaftReceiver_WestSpan");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "FastVS_HD2D_Cycle180_CentralPlaza_BroadSunshaftReceiver_CenterSpan");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "FastVS_HD2D_Cycle180_CentralPlaza_BroadSunshaftReceiver_EastSpan");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, Hd2dCycle180DynamicSunShaftFieldName);
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "FastVS_HD2D_Cycle180_CentralPlaza_DynamicSunShaft_WestWide");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "FastVS_HD2D_Cycle180_CentralPlaza_DynamicSunShaft_WestCenter");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "FastVS_HD2D_Cycle180_CentralPlaza_DynamicSunShaft_Center");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "FastVS_HD2D_Cycle180_CentralPlaza_DynamicSunShaft_EastCenter");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "FastVS_HD2D_Cycle180_CentralPlaza_DynamicSunShaft_EastWide");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "directionalSunLight:");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "globalVolume:");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "presets:");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "defaultPreset: 0");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "transitionDuration: 1.8");
            ValidateHd2dPhaseASunCycleYamlToken(sceneText, "transitionFromPrevious: 1");

            for (var presetIndex = 0; presetIndex < 4; presetIndex++)
            {
                var preset = (SunPreset)presetIndex;
                var guid = AssetDatabase.AssetPathToGUID(GetHd2dPhaseASunPresetAssetPath(preset));
                if (string.IsNullOrEmpty(guid))
                {
                    throw new InvalidOperationException($"House slice validation failed: missing GUID for Phase A SunCycle preset {preset}.");
                }

                ValidateHd2dPhaseASunCycleYamlToken(sceneText, guid);
            }
        }

