        private static void AddHd2dCycle181LibraryArtifactReportLine(List<string> lines, string objectName)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null)
            {
                lines.Add($"| `{objectName}` | missing | missing | missing | missing |");
                return;
            }

            var parentName = sceneObject.transform.parent != null ? sceneObject.transform.parent.name : string.Empty;
            var renderer = sceneObject.GetComponent<Renderer>();
            var materialPath = renderer != null && renderer.sharedMaterial != null ? AssetDatabase.GetAssetPath(renderer.sharedMaterial) : string.Empty;
            lines.Add($"| `{objectName}` | `{parentName}` | `{materialPath}` | `{sceneObject.transform.localPosition}` | `{sceneObject.transform.localScale}` |");
        }

        private static void AddHd2dPhaseASunCycleAnchorReportLine(List<string> lines, string objectName)
        {
            var anchorObject = FindSceneObjectIncludingInactive(objectName);
            var anchor = anchorObject != null ? anchorObject.GetComponent<MapSunAnchor>() : null;
            if (anchorObject == null || anchor == null)
            {
                lines.Add($"| `{objectName}` | missing | missing | missing | missing |");
                return;
            }

            var parentName = anchorObject.transform.parent != null ? anchorObject.transform.parent.name : string.Empty;
            lines.Add($"| `{objectName}` | `{parentName}` | {anchor.SunPreset} | {anchor.TransitionFromPrevious} | {anchor.Priority} |");
        }

        private static void AddHd2dCycle180BroadSunshaftReceiverReportLine(List<string> lines, string objectName)
        {
            var receiverObject = FindSceneObjectIncludingInactive(objectName);
            var landmark = receiverObject != null ? receiverObject.GetComponent<TimeWindowPairedSpaceLandmark>() : null;
            if (receiverObject == null || landmark == null)
            {
                lines.Add($"| `{objectName}` | missing | missing | missing | missing |");
                return;
            }

            var parentName = receiverObject.transform.parent != null ? receiverObject.transform.parent.name : string.Empty;
            var landmarkSerialized = new SerializedObject(landmark);
            var landmarkIdProperty = landmarkSerialized.FindProperty("landmarkId");
            var landmarkId = landmarkIdProperty != null && landmarkIdProperty.propertyType == SerializedPropertyType.String
                ? landmarkIdProperty.stringValue
                : string.Empty;
            lines.Add($"| `{objectName}` | `{parentName}` | `{landmarkId}` | `{receiverObject.transform.localPosition}` | `{receiverObject.transform.localScale}` |");
        }

        private static void AddHd2dCycle180DynamicSunShaftFieldReportLine(List<string> lines)
        {
            var fieldObject = FindSceneObjectIncludingInactive(Hd2dCycle180DynamicSunShaftFieldName);
            var field = fieldObject != null ? fieldObject.GetComponent<FastVsDynamicSunShaftField>() : null;
            if (fieldObject == null || field == null)
            {
                lines.Add($"| `{Hd2dCycle180DynamicSunShaftFieldName}` | missing | 0 | missing |");
                return;
            }

            var parentName = fieldObject.transform.parent != null ? fieldObject.transform.parent.name : string.Empty;
            var serialized = new SerializedObject(field);
            var baseAlpha = serialized.FindProperty("baseAlpha")?.floatValue ?? 0f;
            var viewReactiveAlpha = serialized.FindProperty("viewReactiveAlpha")?.floatValue ?? 0f;
            var pulseSpeed = serialized.FindProperty("pulseSpeed")?.floatValue ?? 0f;
            var cameraParallax = serialized.FindProperty("cameraParallax")?.floatValue ?? 0f;
            lines.Add($"| `{Hd2dCycle180DynamicSunShaftFieldName}` | `{parentName}` | {field.ShaftRendererCountForReview} | base {baseAlpha:0.###}, view {viewReactiveAlpha:0.###}, pulse {pulseSpeed:0.###}, parallax {cameraParallax:0.###} |");
        }

        private static void AddHd2dCycle180DynamicSunShaftRendererReportLines(List<string> lines)
        {
            var fieldObject = FindSceneObjectIncludingInactive(Hd2dCycle180DynamicSunShaftFieldName);
            if (fieldObject == null)
            {
                lines.Add("| missing | missing | missing | missing | missing |");
                return;
            }

            var renderers = fieldObject.GetComponentsInChildren<Renderer>(true);
            for (var i = 0; i < renderers.Length; i++)
            {
                var renderer = renderers[i];
                if (renderer == null)
                {
                    continue;
                }

                var parentName = renderer.transform.parent != null ? renderer.transform.parent.name : string.Empty;
                var materialPath = renderer.sharedMaterial != null ? AssetDatabase.GetAssetPath(renderer.sharedMaterial) : string.Empty;
                lines.Add($"| `{renderer.name}` | `{parentName}` | `{materialPath}` | `{renderer.transform.localPosition}` | `{renderer.transform.localScale}` |");
            }
        }

        private static void ValidateSerializedObjectReference(UnityEngine.Object target, string fieldName, UnityEngine.Object expected, string label)
        {
            var actual = GetSerializedObjectReference(target, fieldName);
            if (actual != expected)
            {
                throw new InvalidOperationException($"House slice validation failed: {label} must reference {expected.name}.");
            }
        }

        private static UnityEngine.Object GetSerializedObjectReference(UnityEngine.Object target, string fieldName)
        {
            var serialized = new SerializedObject(target);
            var property = serialized.FindProperty(fieldName);
            if (property == null || property.propertyType != SerializedPropertyType.ObjectReference)
            {
                throw new InvalidOperationException($"Serialized object reference field not found: {target.GetType().Name}.{fieldName}");
            }

            return property.objectReferenceValue;
        }

        private static int GetSerializedEnumIndex(UnityEngine.Object target, string fieldName)
        {
            var serialized = new SerializedObject(target);
            var property = serialized.FindProperty(fieldName);
            if (property == null || property.propertyType != SerializedPropertyType.Enum)
            {
                throw new InvalidOperationException($"Serialized enum field not found: {target.GetType().Name}.{fieldName}");
            }

            return property.enumValueIndex;
        }

        private static float GetSerializedFloat(UnityEngine.Object target, string fieldName)
        {
            var serialized = new SerializedObject(target);
            var property = serialized.FindProperty(fieldName);
            if (property == null || property.propertyType != SerializedPropertyType.Float)
            {
                throw new InvalidOperationException($"Serialized float field not found: {target.GetType().Name}.{fieldName}");
            }

            return property.floatValue;
        }

        private static int GetSerializedInt(UnityEngine.Object target, string fieldName)
        {
            var serialized = new SerializedObject(target);
            var property = serialized.FindProperty(fieldName);
            if (property == null || property.propertyType != SerializedPropertyType.Integer)
            {
                throw new InvalidOperationException($"Serialized integer field not found: {target.GetType().Name}.{fieldName}");
            }

            return property.intValue;
        }

        private static bool GetSerializedBool(UnityEngine.Object target, string fieldName)
        {
            var serialized = new SerializedObject(target);
            var property = serialized.FindProperty(fieldName);
            if (property == null || property.propertyType != SerializedPropertyType.Boolean)
            {
                throw new InvalidOperationException($"Serialized bool field not found: {target.GetType().Name}.{fieldName}");
            }

            return property.boolValue;
        }

        private static void SerializedSetObjectReferenceArray(UnityEngine.Object target, string fieldName, UnityEngine.Object[] values)
        {
            var serialized = new SerializedObject(target);
            var property = serialized.FindProperty(fieldName);
            if (property == null || !property.isArray)
            {
                throw new InvalidOperationException($"Serialized object reference array field not found: {target.GetType().Name}.{fieldName}");
            }

            property.arraySize = values.Length;
            for (var index = 0; index < values.Length; index++)
            {
                property.GetArrayElementAtIndex(index).objectReferenceValue = values[index];
            }

            serialized.ApplyModifiedPropertiesWithoutUndo();
        }

        private static void ApplyCycle92FadedDuskCameraGrade(VolumeProfile profile)
        {
            if (profile == null)
            {
                throw new InvalidOperationException("Fast VS HD-2D faded dusk camera grade failed: volume profile is missing.");
            }

            if (!profile.TryGet<ColorAdjustments>(out var colorAdjustments))
            {
                colorAdjustments = profile.Add<ColorAdjustments>(true);
            }

            if (!profile.TryGet<Bloom>(out var bloom))
            {
                bloom = profile.Add<Bloom>(true);
            }

            if (!profile.TryGet<Vignette>(out var vignette))
            {
                vignette = profile.Add<Vignette>(true);
            }

            if (!profile.TryGet<Tonemapping>(out var tonemapping))
            {
                tonemapping = profile.Add<Tonemapping>(true);
            }

            if (!profile.TryGet<WhiteBalance>(out var whiteBalance))
            {
                whiteBalance = profile.Add<WhiteBalance>(true);
            }

            if (!profile.TryGet<ColorLookup>(out var colorLookup))
            {
                colorLookup = profile.Add<ColorLookup>(true);
            }

            if (!profile.TryGet<FilmGrain>(out var filmGrain))
            {
                filmGrain = profile.Add<FilmGrain>(true);
            }

            if (!profile.TryGet<DepthOfField>(out var depthOfField))
            {
                depthOfField = profile.Add<DepthOfField>(true);
            }

            colorAdjustments.active = true;
            colorAdjustments.postExposure.overrideState = true;
            colorAdjustments.postExposure.value = 0f;
            colorAdjustments.contrast.overrideState = true;
            colorAdjustments.contrast.value = 14f;
            colorAdjustments.colorFilter.overrideState = true;
            colorAdjustments.colorFilter.value = new Color(1.08f, 1.04f, 0.92f, 1f);
            colorAdjustments.hueShift.overrideState = true;
            colorAdjustments.hueShift.value = 0f;
            colorAdjustments.saturation.overrideState = true;
            colorAdjustments.saturation.value = 0f;

            bloom.active = true;
            bloom.threshold.overrideState = true;
            bloom.threshold.value = 0.85f;
            bloom.intensity.overrideState = true;
            bloom.intensity.value = 0.80f;
            bloom.scatter.overrideState = true;
            bloom.scatter.value = 0.72f;
            bloom.clamp.overrideState = true;
            bloom.clamp.value = 65472f;
            bloom.tint.overrideState = true;
            bloom.tint.value = new Color(1.00f, 0.94f, 0.86f, 1f);
            bloom.highQualityFiltering.overrideState = true;
            bloom.highQualityFiltering.value = true;
            bloom.downscale.overrideState = true;
            bloom.downscale.value = BloomDownscaleMode.Half;
            bloom.maxIterations.overrideState = true;
            bloom.maxIterations.value = 6;
            bloom.dirtTexture.overrideState = true;
            bloom.dirtTexture.value = null;
            bloom.dirtIntensity.overrideState = true;
            bloom.dirtIntensity.value = 0f;

            vignette.active = true;
            vignette.color.overrideState = true;
            vignette.color.value = Color.black;
            vignette.center.overrideState = true;
            vignette.center.value = new Vector2(0.5f, 0.5f);
            vignette.intensity.overrideState = true;
            vignette.intensity.value = 0.30f;
            vignette.smoothness.overrideState = true;
            vignette.smoothness.value = 0.40f;
            vignette.rounded.overrideState = true;
            vignette.rounded.value = false;

            tonemapping.active = true;
            tonemapping.mode.overrideState = true;
            tonemapping.mode.value = TonemappingMode.ACES;

            whiteBalance.active = true;
            whiteBalance.temperature.overrideState = true;
            whiteBalance.temperature.value = 8f;
            whiteBalance.tint.overrideState = true;
            whiteBalance.tint.value = 0f;

            ApplyStage5LutColorLookup(colorLookup);

            filmGrain.active = false;
            filmGrain.intensity.overrideState = true;
            filmGrain.intensity.value = 0f;
            filmGrain.response.overrideState = true;
            filmGrain.response.value = 0.8f;
            filmGrain.texture.overrideState = true;
            filmGrain.texture.value = null;

            depthOfField.active = true;
            depthOfField.mode.overrideState = true;
            depthOfField.mode.value = DepthOfFieldMode.Bokeh;
            depthOfField.gaussianStart.overrideState = false;
            depthOfField.gaussianEnd.overrideState = false;
            depthOfField.gaussianMaxRadius.overrideState = false;
            depthOfField.highQualitySampling.overrideState = true;
            depthOfField.highQualitySampling.value = true;
            depthOfField.focusDistance.overrideState = true;
            depthOfField.focusDistance.value = 5.4f;
            depthOfField.aperture.overrideState = true;
            depthOfField.aperture.value = 2.4f;
            depthOfField.focalLength.overrideState = true;
            depthOfField.focalLength.value = 85f;
            depthOfField.bladeCount.overrideState = true;
            depthOfField.bladeCount.value = 6;
            depthOfField.bladeCurvature.overrideState = true;
            depthOfField.bladeCurvature.value = 0.85f;
            depthOfField.bladeRotation.overrideState = true;
            depthOfField.bladeRotation.value = 0f;

            ApplyHd2dPhaseBAlphaScreenSpaceLensFlare(profile);
            EnsureHd2dPhaseBAlphaRenderPipelineLensFlareSupport();
            EditorUtility.SetDirty(profile);
        }

        private static void ApplyStage5LutColorLookup(ColorLookup colorLookup)
        {
            var daylightLut = AssetDatabase.LoadAssetAtPath<Texture2D>(Stage5LutDaylightPlazaTexturePath);
            if (daylightLut == null)
            {
                throw new InvalidOperationException($"Fast VS HD-2D Stage 5 LUT is missing: {Stage5LutDaylightPlazaTexturePath}");
            }

            colorLookup.active = true;
            colorLookup.texture.overrideState = true;
            colorLookup.texture.value = daylightLut;
            colorLookup.contribution.overrideState = true;
            colorLookup.contribution.value = Stage5LutContribution;
            EditorUtility.SetDirty(colorLookup);
        }

