                visibility,
                FastVsHouseArea.Ruins,
                "F lower gorge right bank bypass",
                Chapter1RuinsMapCenter + new Vector3(2.35f, 0.02f, -5.10f));
            ValidateBlockedContinuationPoint(
                controller,
                visibility,
                FastVsHouseArea.Ruins,
                "F lower bridge-mouth side bypass",
                Chapter1RuinsMapCenter + new Vector3(-2.35f, 0.02f, -2.60f));
        }

        private static void ValidateBlockedContinuationPoint(
            TimeWindowPairedSpacePortalController controller,
            FastVsHouseAreaVisibility visibility,
            FastVsHouseArea area,
            string label,
            Vector3 localPoint)
        {
            visibility.SetActiveAreaForReview(area);
            controller.ForcePlayerCurrentLocalForReview(Chapter1F1FromE3Target);
            UnityEngine.Object.FindFirstObjectByType<FastVsVisualDirectionGuide>(FindObjectsInactive.Include)?.ApplyActiveTimeIsolationForReview();
            Physics.SyncTransforms();

            var root = controller.CurrentSpaceRootForReview;
            if (root == null)
            {
                throw new InvalidOperationException("House slice validation failed: current space root missing during blocked point validation.");
            }

            var world = root.TransformPoint(localPoint);
            var bottom = world + Vector3.up * 0.26f;
            var top = world + Vector3.up * 1.10f;
            var hits = Physics.OverlapCapsule(bottom, top, 0.24f, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            foreach (var hit in hits)
            {
                if (IsBlockingContinuationRouteCollider(hit))
                {
                    return;
                }
            }

            throw new InvalidOperationException($"House slice validation failed: {label} must be blocked so the bridge remains the intended crossing.");
        }

        private static void ValidateChapter1BridgeCharacterControllerTraversal(
            TimeWindowPairedSpacePortalController controller,
            FastVsHouseAreaVisibility visibility,
            bool otherTime)
        {
            var player = UnityEngine.Object.FindFirstObjectByType<CharacterController>();
            if (player == null)
            {
                throw new InvalidOperationException("House slice validation failed: player controller missing for bridge traversal validation.");
            }

            var route = new[]
            {
                BridgeTraversalProbePoint(Chapter1F1FromE3Target),
                Chapter1RuinsMapCenter + new Vector3(-10.80f, 0.18f, 0.02f),
                Chapter1RuinsMapCenter + new Vector3(-6.72f, 0.18f, 0.04f),
                Chapter1RuinsMapCenter + new Vector3(-2.20f, 0.18f, -0.01f),
                Chapter1RuinsMapCenter + new Vector3(0.00f, 0.18f, -0.02f),
                Chapter1RuinsMapCenter + new Vector3(2.20f, 0.18f, 0.01f),
                Chapter1RuinsMapCenter + new Vector3(6.72f, 0.18f, 0.04f),
                Chapter1RuinsMapCenter + new Vector3(10.80f, 0.18f, 0.02f),
                BridgeTraversalProbePoint(Chapter1F6RouteTriggerCenter)
            };

            visibility.SetActiveAreaForReview(FastVsHouseArea.Ruins);
            if (otherTime)
            {
                controller.ForcePlayerOtherTimeLocalForReview(route[0]);
            }
            else
            {
                controller.ForcePlayerCurrentLocalForReview(route[0]);
            }

            UnityEngine.Object.FindFirstObjectByType<FastVsVisualDirectionGuide>(FindObjectsInactive.Include)?.ApplyActiveTimeIsolationForReview();
            Physics.SyncTransforms();

            var sideLabel = otherTime ? "past" : "current";
            for (var i = 0; i < route.Length; i++)
            {
                ValidateBridgeTraversalSupportPoint(controller, route[i], $"{sideLabel} bridge route support {i + 1}");
            }

            for (var i = 1; i < route.Length; i++)
            {
                MoveCharacterControllerAlongBridgeSegment(controller, player, route[i], otherTime, $"{sideLabel} bridge traversal segment {i}");
            }

            var finalLocal = controller.GetPlayerLocalCoordinateForReview();
            var finalDelta = new Vector2(finalLocal.x - route[route.Length - 1].x, finalLocal.z - route[route.Length - 1].z).magnitude;
            if (finalDelta > 0.38f)
            {
                throw new InvalidOperationException($"House slice validation failed: {sideLabel} bridge traversal did not reach F6. final={finalLocal}, target={route[route.Length - 1]}, delta={finalDelta:0.000}.");
            }
        }

        private static Vector3 BridgeTraversalProbePoint(Vector3 localPoint)
        {
            return new Vector3(localPoint.x, 0.18f, localPoint.z);
        }

        private static void ValidateBridgeTraversalSupportPoint(TimeWindowPairedSpacePortalController controller, Vector3 localPoint, string label)
        {
            var root = controller.PlayerInOtherTime ? controller.OtherTimeSpaceRootForReview : controller.CurrentSpaceRootForReview;
            if (root == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing active root for {label}.");
            }

            var origin = root.TransformPoint(localPoint + Vector3.up * 1.25f);
            var hits = Physics.RaycastAll(origin, Vector3.down, 1.70f, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            Array.Sort(hits, (a, b) => a.distance.CompareTo(b.distance));
            foreach (var hit in hits)
            {
                if (hit.collider == null ||
                    hit.collider.GetComponentInParent<CharacterController>() != null)
                {
                    continue;
                }

                if (IsBlockingContinuationRouteCollider(hit.collider))
                {
                    throw new InvalidOperationException($"House slice validation failed: {label} is covered by blocking collider {hit.collider.name}.");
                }

                var landmark = hit.collider.GetComponentInParent<TimeWindowPairedSpaceLandmark>();
                if (landmark != null && landmark.Kind == TimeWindowPairedSpaceLandmarkKind.PathOrFloor)
                {
                    return;
                }
            }

            throw new InvalidOperationException($"House slice validation failed: {label} has no PathOrFloor support below the player capsule.");
        }

        private static void MoveCharacterControllerAlongBridgeSegment(
            TimeWindowPairedSpacePortalController controller,
            CharacterController player,
            Vector3 targetLocal,
            bool otherTime,
            string label)
        {
            const float StepDistance = 0.18f;
            const float GroundingDrop = 0.035f;
            const int MaxSteps = 180;

            for (var stepIndex = 0; stepIndex < MaxSteps; stepIndex++)
            {
                if (controller.PlayerInOtherTime != otherTime)
                {
                    throw new InvalidOperationException($"House slice validation failed: {label} changed the active time side during movement.");
                }

                var beforeLocal = controller.GetPlayerLocalCoordinateForReview();
                var horizontal = new Vector2(targetLocal.x - beforeLocal.x, targetLocal.z - beforeLocal.z);
                if (horizontal.magnitude <= 0.22f)
                {
                    return;
                }

                var beforeXZ = new Vector2(beforeLocal.x, beforeLocal.z);
                var step = new Vector3(horizontal.x, 0f, horizontal.y).normalized * Mathf.Min(StepDistance, horizontal.magnitude);
                step.y = -GroundingDrop;
                controller.MovePlayerLocalForReview(step, true);
                Physics.SyncTransforms();

                var afterLocal = controller.GetPlayerLocalCoordinateForReview();
                var afterXZ = new Vector2(afterLocal.x, afterLocal.z);
                var moved = Vector2.Distance(beforeXZ, afterXZ);
                if (moved < 0.035f)
                {
                    throw new InvalidOperationException($"House slice validation failed: {label} was blocked before reaching the next bridge waypoint. before={beforeLocal}, after={afterLocal}, target={targetLocal}, player={player.name}.");
                }

                if (afterLocal.y < -0.12f || afterLocal.y > 0.82f)
                {
                    throw new InvalidOperationException($"House slice validation failed: {label} left the playable bridge height band. local={afterLocal}, target={targetLocal}.");
                }
            }

            throw new InvalidOperationException($"House slice validation failed: {label} exceeded the step budget before reaching {targetLocal}.");
        }

        private static void ValidateWalkableRoute(
            TimeWindowPairedSpacePortalController controller,
            FastVsHouseAreaVisibility visibility,
            FastVsHouseArea area,
            string label,
            params Vector3[] localPoints)
        {
            if (localPoints == null || localPoints.Length < 2)
            {
                throw new InvalidOperationException($"House slice validation failed: {label} walkable route needs at least two points.");
            }

            visibility.SetActiveAreaForReview(area);
            controller.ForcePlayerCurrentLocalForReview(localPoints[0]);
            UnityEngine.Object.FindFirstObjectByType<FastVsVisualDirectionGuide>(FindObjectsInactive.Include)?.ApplyActiveTimeIsolationForReview();
            Physics.SyncTransforms();

            for (var i = 0; i < localPoints.Length; i++)
            {
                ValidateWalkablePoint(controller, localPoints[i], $"{label} point {i + 1}");
            }

            for (var i = 0; i < localPoints.Length - 1; i++)
            {
                ValidateWalkableSegment(controller, localPoints[i], localPoints[i + 1], $"{label} segment {i + 1}");
            }
        }

        private static void ValidateWalkablePoint(TimeWindowPairedSpacePortalController controller, Vector3 localPoint, string label)
        {
            var root = controller.CurrentSpaceRootForReview;
            if (root == null)
            {
                throw new InvalidOperationException("House slice validation failed: current space root missing during continuation route clearance validation.");
            }

            var world = root.TransformPoint(localPoint);
            var bottom = world + Vector3.up * 0.26f;
            var top = world + Vector3.up * 1.10f;
            var hits = Physics.OverlapCapsule(bottom, top, 0.24f, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            foreach (var hit in hits)
            {
                if (IsBlockingContinuationRouteCollider(hit))
                {
                    throw new InvalidOperationException($"House slice validation failed: {label} overlaps blocking collider {hit.name}.");
                }
            }
        }

        private static void ValidateWalkableSegment(TimeWindowPairedSpacePortalController controller, Vector3 startLocal, Vector3 endLocal, string label)
        {
            var root = controller.CurrentSpaceRootForReview;
            if (root == null)
            {
                throw new InvalidOperationException("House slice validation failed: current space root missing during continuation route clearance validation.");
            }

            var start = root.TransformPoint(startLocal);
            var end = root.TransformPoint(endLocal);
            var direction = end - start;
            direction.y = 0f;
            var distance = direction.magnitude;
            if (distance <= 0.001f)
            {
                return;
            }

            direction /= distance;
            var bottom = start + Vector3.up * 0.26f;
            var top = start + Vector3.up * 1.10f;
            var hits = Physics.CapsuleCastAll(bottom, top, 0.24f, direction, distance, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore);
            foreach (var hit in hits)
            {
                if (IsBlockingContinuationRouteCollider(hit.collider))
                {
                    throw new InvalidOperationException($"House slice validation failed: {label} is blocked by collider {hit.collider.name}.");
                }
            }
        }

        private static bool IsBlockingContinuationRouteCollider(Collider collider)
        {
            if (collider == null ||
                collider.GetComponentInParent<CharacterController>() != null)
            {
                return false;
            }

            var landmark = collider.GetComponentInParent<TimeWindowPairedSpaceLandmark>();
            return landmark == null || landmark.Kind != TimeWindowPairedSpaceLandmarkKind.PathOrFloor;
        }

        private static void ValidateCameraStaysOnSameCoordinateRoot(TimeWindowPairedSpacePortalController controller)
        {
            var guide = UnityEngine.Object.FindFirstObjectByType<FastVsVisualDirectionGuide>();
            if (guide == null)
            {
                throw new InvalidOperationException("House slice validation failed: missing visual direction guide.");
            }

            controller.ForcePlayerOtherTimeLocalForReview(HouseInteriorPlayerStart);
            guide.ApplyActiveTimeIsolationForReview();
            var expectedSameCoordinateAnchor = controller.CurrentSpaceRootForReview.TransformPoint(HouseInteriorPlayerStart);
            ValidateWorldVectorNear("same-coordinate past camera anchor", guide.ResolveActiveCameraAnchorForReview(), expectedSameCoordinateAnchor, 0.05f);
            var camera = Camera.main;
            if (camera == null)
            {
                throw new InvalidOperationException("House slice validation failed: missing main camera for active-time culling validation.");
            }

            var currentBit = 1 << controller.CurrentSpaceRenderLayerForReview;
            var otherBit = 1 << controller.OtherTimeSpaceRenderLayerForReview;
            var portalBit = 1 << controller.PortalFrameRenderLayerForReview;
            var playerBit = 1 << controller.PlayerVisibleRenderLayerForReview;
            if (controller.CurrentSpaceRootForReview == null ||
                controller.OtherTimeSpaceRootForReview == null ||
                controller.CurrentSpaceRootForReview.gameObject.layer != controller.CurrentSpaceRenderLayerForReview ||
                controller.OtherTimeSpaceRootForReview.gameObject.layer != controller.OtherTimeSpaceRenderLayerForReview ||
                controller.PlayerRenderLayerForReview != controller.PlayerVisibleRenderLayerForReview)
            {
                throw new InvalidOperationException("House slice validation failed: startup render layers should isolate current, past, and player before any Time Window is created.");
            }

            if ((camera.cullingMask & currentBit) == 0 ||
                (camera.cullingMask & portalBit) == 0 ||
                (camera.cullingMask & playerBit) != 0 ||
                (camera.cullingMask & otherBit) != 0)
            {
                throw new InvalidOperationException("House slice validation failed: other-time player must be hidden from the main camera and restricted to the Time Window aperture.");
            }

            if (controller.PlayerRenderLayerForReview != controller.PlayerVisibleRenderLayerForReview)
            {
                throw new InvalidOperationException("House slice validation failed: player becomes hidden by Time Window culling after entering the Time Window.");
            }

            controller.ForcePlayerCurrentLocalForReview(HouseInteriorPlayerStart);
            guide.ApplyActiveTimeIsolationForReview();
            var expectedCurrentAnchor = controller.CurrentSpaceRootForReview.TransformPoint(HouseInteriorPlayerStart);
            ValidateWorldVectorNear("current camera anchor", guide.ResolveActiveCameraAnchorForReview(), expectedCurrentAnchor, 0.05f);
            if ((camera.cullingMask & currentBit) == 0 ||
                (camera.cullingMask & portalBit) == 0 ||
                (camera.cullingMask & playerBit) == 0 ||
                (camera.cullingMask & otherBit) != 0)
            {
                throw new InvalidOperationException("House slice validation failed: current camera culling no longer keeps past outside the window hidden.");
            }
        }

        private static void ValidateChapter1ContinuationTimeWindowRightSidePlacement(TimeWindowPairedSpacePortalController controller)
        {
            var camera = Camera.main;
            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            if (camera == null || visibility == null)
            {
                throw new InvalidOperationException("House slice validation failed: missing camera or visibility controller for continuation Time Window placement.");
            }

            var rightSideDragStart = new Vector2(850f, 230f);
            var rightSideDragEnd = new Vector2(1180f, 610f);
            var samples = new[]
            {
                (Label: "Aria D1 entry right-side Time Window", Area: FastVsHouseArea.AriaStreet, Local: Chapter1D1FromC3Target),
                (Label: "Aria D3 exit right-side Time Window", Area: FastVsHouseArea.AriaStreet, Local: GroundedRouteLocal(Chapter1D3RouteTriggerCenter)),
                (Label: "Kaia E1 entry right-side Time Window", Area: FastVsHouseArea.KaiaFarm, Local: Chapter1E1FromD3Target),
                (Label: "Kaia E3 exit right-side Time Window", Area: FastVsHouseArea.KaiaFarm, Local: GroundedRouteLocal(Chapter1E3RouteTriggerCenter)),
                (Label: "Ruins F1 entry right-side Time Window", Area: FastVsHouseArea.Ruins, Local: Chapter1F1FromE3Target),
                (Label: "Ruins F5 mid-route right-side Time Window", Area: FastVsHouseArea.Ruins, Local: GroundedRouteLocal(Chapter1F5RouteTriggerCenter)),
                (Label: "Ruins F6 exit right-side Time Window", Area: FastVsHouseArea.Ruins, Local: GroundedRouteLocal(Chapter1F6RouteTriggerCenter))
            };

            foreach (var sample in samples)
            {
                controller.ClosePortal();
                visibility.SetActiveAreaForReview(sample.Area);
                controller.ForcePlayerCurrentLocalForReview(sample.Local);
                PositionReviewCamera(camera, controller.CurrentSpaceRootForReview.TransformPoint(sample.Local));

                if (!controller.TryOpenPortalForTests(rightSideDragStart, rightSideDragEnd) || !controller.HasPortalPair)
                {
                    throw new InvalidOperationException($"House slice validation failed: {sample.Label} drag-open was rejected. regionSize={controller.RegionSizeForReview} playerX={sample.Local.x:0.00}.");
                }

                var portalLocal = controller.PortalLocalCenterForReview;
                if (portalLocal.x < sample.Local.x + 0.75f)
                {
                    throw new InvalidOperationException($"House slice validation failed: {sample.Label} was clamped left of the intended right-side placement. regionSize={controller.RegionSizeForReview} playerX={sample.Local.x:0.00}, portalX={portalLocal.x:0.00}.");
                }
            }

            controller.ClosePortal();
            visibility.SetActiveAreaForReview(FastVsHouseArea.Interior);
            controller.ForcePlayerCurrentLocalForReview(HouseInteriorPlayerStart);
        }

        private static Vector3 GroundedRouteLocal(Vector3 routeTriggerCenter)
        {
            return new Vector3(routeTriggerCenter.x, 0.02f, routeTriggerCenter.z);
        }

        private static void ValidateInitialCurrentOnlyCulling(TimeWindowPairedSpacePortalController controller)
        {
            var camera = Camera.main;
            if (camera == null)
            {
                throw new InvalidOperationException("House slice validation failed: missing main camera for initial culling validation.");
            }

            var currentBit = 1 << controller.CurrentSpaceRenderLayerForReview;
            var otherBit = 1 << controller.OtherTimeSpaceRenderLayerForReview;
            var portalBit = 1 << controller.PortalFrameRenderLayerForReview;
            var playerBit = 1 << controller.PlayerVisibleRenderLayerForReview;
            if ((camera.cullingMask & currentBit) == 0 ||
                (camera.cullingMask & portalBit) == 0 ||
                (camera.cullingMask & playerBit) == 0 ||
                (camera.cullingMask & otherBit) != 0)
            {
                throw new InvalidOperationException("House slice validation failed: startup camera culling should show current/player/portal layers while hiding past.");
            }
        }

