        private static void ValidateAuthoredVegetationMeshObject(string objectName, string expectedParentName, string requiredMeshToken, int minVertexCount, int minTriangleIndexCount, bool requireActive = true)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing authored vegetation object {objectName}.");
            }

            if (sceneObject.transform.parent == null || sceneObject.transform.parent.name != expectedParentName)
            {
                throw new InvalidOperationException($"House slice validation failed: authored vegetation {objectName} must be parented under {expectedParentName}.");
            }

            if (requireActive && !sceneObject.activeSelf)
            {
                throw new InvalidOperationException($"House slice validation failed: authored vegetation {objectName} must remain active.");
            }

            var filter = sceneObject.GetComponent<MeshFilter>();
            if (filter == null || filter.sharedMesh == null)
            {
                throw new InvalidOperationException($"House slice validation failed: authored vegetation {objectName} must use a MeshFilter.");
            }

            var meshName = filter.sharedMesh.name ?? string.Empty;
            if (meshName.IndexOf(AuthoredVegetationMeshNamePrefix, StringComparison.Ordinal) < 0 ||
                meshName.IndexOf(requiredMeshToken, StringComparison.Ordinal) < 0 ||
                meshName.IndexOf("Cube", StringComparison.OrdinalIgnoreCase) >= 0 ||
                meshName.IndexOf("Sphere", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                throw new InvalidOperationException($"House slice validation failed: authored vegetation {objectName} must use an authored low-poly mesh, found {meshName}.");
            }

            if (filter.sharedMesh.vertexCount < minVertexCount || filter.sharedMesh.triangles.Length < minTriangleIndexCount)
            {
                throw new InvalidOperationException($"House slice validation failed: authored vegetation {objectName} mesh is too primitive: vertices={filter.sharedMesh.vertexCount}, triangleIndices={filter.sharedMesh.triangles.Length}.");
            }

            var renderer = sceneObject.GetComponent<MeshRenderer>();
            if (renderer == null || !renderer.enabled || renderer.sharedMaterial == null)
            {
                throw new InvalidOperationException($"House slice validation failed: authored vegetation {objectName} must keep an enabled MeshRenderer and material.");
            }

            if (sceneObject.GetComponent<Collider>() != null || sceneObject.GetComponentsInChildren<Collider>(true).Length > 0)
            {
                throw new InvalidOperationException($"House slice validation failed: authored vegetation {objectName} must not add primitive collision.");
            }

            if (sceneObject.GetComponent<TimeWindowPairedSpaceLandmark>() == null)
            {
                throw new InvalidOperationException($"House slice validation failed: authored vegetation {objectName} must keep its landmark marker.");
            }
        }

        private static void ValidateFastVsHd2dDistantPanoramaVista()
        {
            ValidateDistantPanoramaVistaLandformFacetTexture("Ch1Distant_CurrentLandformFacetBackRidge", 0.036f);
            ValidateDistantPanoramaVistaLandformFacetTexture("Ch1Distant_PastLandformFacetBackRidge", 0.036f);
            ValidateDistantPanoramaVistaLandformFacetTexture("Ch1Distant_CurrentLandformFacetFrontTree", 0.034f);
            ValidateDistantPanoramaVistaLandformFacetTexture("Ch1Distant_PastLandformFacetFrontTree", 0.034f);

            for (var i = 0; i < DistantPanoramaVistaAreas.Length; i++)
            {
                var area = DistantPanoramaVistaAreas[i];
                ValidateDistantPanoramaVistaRoot("Current", area);
                ValidateDistantPanoramaVistaRoot("Past", area);
            }

            var camera = Camera.main;
            if (camera == null)
            {
                throw new InvalidOperationException("House slice validation failed: distant panorama vista requires a main camera for far clip validation.");
            }

            if (camera.farClipPlane < 220f)
            {
                throw new InvalidOperationException($"House slice validation failed: distant panorama vista needs the far clip to stay at least 220, but was {camera.farClipPlane:0.000}.");
            }

            for (var i = 0; i < DistantPanoramaVistaAreas.Length; i++)
            {
                var area = DistantPanoramaVistaAreas[i];
                ApplyDistantPanoramaVistaAtmosphereForReview(camera, area, false);
                if (!RenderSettings.fog || RenderSettings.fogMode != FogMode.Linear)
                {
                    throw new InvalidOperationException($"House slice validation failed: distant panorama vista fog must be enabled and Linear for {area}.");
                }

                if (RenderSettings.fogStartDistance < 30f || RenderSettings.fogStartDistance > 48f || RenderSettings.fogEndDistance < 196f || RenderSettings.fogEndDistance > 226f)
                {
                    throw new InvalidOperationException($"House slice validation failed: distant panorama vista fog range must cover the map edge before the ring for {area}, found start={RenderSettings.fogStartDistance:0.000}, end={RenderSettings.fogEndDistance:0.000}.");
                }

                if (camera.backgroundColor.maxColorComponent < 0.220f)
                {
                    throw new InvalidOperationException($"House slice validation failed: distant panorama vista camera background must replace the black void for {area}, found {camera.backgroundColor}.");
                }

                ValidateDistantPanoramaVistaCameraCoverage(camera, "Current", area);
                ValidateDistantPanoramaVistaCameraCoverage(camera, "Past", area);
            }
        }

        private static void ValidateDistantPanoramaVistaLandformFacetTexture(string textureId, float minLuminanceRange)
        {
            ValidateGeneratedRepeatTextureAsset(textureId, 32, 32, 3);
            ValidateTextureLuminanceRange(textureId, minLuminanceRange, $"{textureId} landform facet texture");
        }

        private static void ValidateFastVsHd2dMidgroundEdgeClosurePrototype()
        {
            ValidateMidgroundEdgeClosurePrototypeRoot("Current");
            ValidateMidgroundEdgeClosurePrototypeRoot("Past");

            var camera = Camera.main;
            if (camera == null)
            {
                throw new InvalidOperationException("House slice validation failed: midground edge closure prototype requires a main camera for visibility validation.");
            }

            ValidateMidgroundEdgeClosurePrototypeCameraCoverage(camera, "Current");
            ValidateMidgroundEdgeClosurePrototypeCameraCoverage(camera, "Past");
        }

        private static void ValidateMidgroundEdgeClosurePrototypeRoot(string prefix)
        {
            const FastVsHouseArea area = FastVsHouseArea.Exterior;
            var areaToken = GetDistantPanoramaVistaAreaToken(area);
            var rootName = $"{prefix}_{areaToken}_MidgroundEdgeClosure";
            var root = FindSceneObjectIncludingInactive(rootName);
            if (root == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing midground edge closure root {rootName}.");
            }

            var expectedParentName = $"{prefix}_{areaToken}Map_SeparateSpace";
            if (root.transform.parent == null || root.transform.parent.name != expectedParentName)
            {
                throw new InvalidOperationException($"House slice validation failed: midground edge closure root {rootName} must stay parented under {expectedParentName}.");
            }

            var expectedLayer = string.Equals(prefix, "Past", StringComparison.Ordinal) ? OtherTimeSpaceRenderLayer : CurrentSpaceRenderLayer;
            if (root.layer != expectedLayer)
            {
                throw new InvalidOperationException($"House slice validation failed: midground edge closure root {rootName} must stay on render layer {expectedLayer}, found {root.layer}.");
            }

            ApplyMidgroundEdgeClosureRendererPolicy(root.transform);
            var filters = root.GetComponentsInChildren<MeshFilter>(true);
            if (filters.Length < MidgroundEdgeClosurePrototypeMeshCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs {MidgroundEdgeClosurePrototypeMeshCount} authored midground edge closure meshes, found {filters.Length}.");
            }

            var center = HouseExteriorCenter;
            var pathOrFloorCount = 0;
            var propCount = 0;
            foreach (var filter in filters)
            {
                if (filter == null || filter.sharedMesh == null || filter.sharedMesh.vertexCount < 16 || filter.sharedMesh.triangles.Length < 36)
                {
                    throw new InvalidOperationException($"House slice validation failed: midground edge closure mesh {filter?.gameObject.name ?? "<null>"} must keep authored mesh density.");
                }

                if (filter.gameObject.layer != expectedLayer)
                {
                    throw new InvalidOperationException($"House slice validation failed: midground edge closure mesh {filter.gameObject.name} must stay on render layer {expectedLayer}, found {filter.gameObject.layer}.");
                }

                if (filter.GetComponent<Collider>() != null || filter.GetComponentsInChildren<Collider>(true).Length > 0)
                {
                    throw new InvalidOperationException($"House slice validation failed: midground edge closure mesh {filter.gameObject.name} must not add collision.");
                }

                if (filter.gameObject.name.Contains("DistantVista", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException($"House slice validation failed: midground edge closure mesh must not be folded into distant vista validation: {filter.gameObject.name}.");
                }

                var renderer = filter.GetComponent<Renderer>();
                if (renderer == null || renderer.sharedMaterial == null || renderer.shadowCastingMode != ShadowCastingMode.Off || renderer.receiveShadows)
                {
                    throw new InvalidOperationException($"House slice validation failed: midground edge closure mesh {filter.gameObject.name} must use a non-shadow renderer with material.");
                }

                var localOffset = filter.transform.localPosition - center;
                if (localOffset.z < -6.4f || localOffset.z > 8.2f || Mathf.Abs(localOffset.x) > 10.2f)
                {
                    throw new InvalidOperationException($"House slice validation failed: midground edge closure mesh {filter.gameObject.name} left the intended House Exterior edge skirt band at offset {localOffset}.");
                }

                var landmark = filter.GetComponent<TimeWindowPairedSpaceLandmark>();
                if (landmark == null)
                {
                    throw new InvalidOperationException($"House slice validation failed: midground edge closure mesh {filter.gameObject.name} must keep a landmark marker.");
                }

                if (filter.gameObject.name.Contains("Shelf", StringComparison.Ordinal) ||
                    filter.gameObject.name.Contains("RoadContinuation", StringComparison.Ordinal))
                {
                    pathOrFloorCount++;
                }
                else
                {
                    propCount++;
                }
            }

            if (pathOrFloorCount < 6 || propCount < 4)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} must combine terrain/path closure and prop silhouette closure, pathOrFloor={pathOrFloorCount}, prop={propCount}.");
            }
        }

