        private static void ValidateArchitecturalSurfaceAccentRoot(string prefix, FastVsHouseArea area)
        {
            var areaToken = GetDistantPanoramaVistaAreaToken(area);
            var rootName = $"{prefix}_{areaToken}_ArchitecturalSurfaceAccents";
            var root = FindSceneObjectIncludingInactive(rootName);
            if (root == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing architectural surface accent root {rootName}.");
            }

            var expectedParentName = $"{prefix}_{areaToken}Map_SeparateSpace";
            if (root.transform.parent == null || root.transform.parent.name != expectedParentName)
            {
                throw new InvalidOperationException($"House slice validation failed: architectural surface accent root {rootName} must stay parented under {expectedParentName}.");
            }

            var expectedLayer = string.Equals(prefix, "Past", StringComparison.Ordinal) ? OtherTimeSpaceRenderLayer : CurrentSpaceRenderLayer;
            if (root.layer != expectedLayer)
            {
                throw new InvalidOperationException($"House slice validation failed: architectural surface accent root {rootName} must stay on render layer {expectedLayer}, found {root.layer}.");
            }

            ApplyArchitecturalSurfaceAccentRendererPolicy(root.transform);
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_FacadeVerticalWearA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_FacadePatchBreakA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_WindowSillShadowA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_WindowSillShadowB");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_BaseContactShadowA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_RoofRidgeWearA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_RoofEaveShadowA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_UpperTrimRailA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_FacadeLeftPilasterA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_FacadeRightPilasterA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_LowerMasonryBandA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_MidLintelBandA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_FacadePlasterCapA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_RoofTileStripeB");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_RoofFrontFasciaA");
            ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_RoofRearShadowBandA");
            if (area == FastVsHouseArea.Ruins)
            {
                ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_BridgeDeckWearThreadA");
                ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_BridgeSideShadowThreadA");
                ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_BridgeDeckPlankA");
                ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_BridgeDeckPlankB");
                ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_BridgeDeckPlankC");
                ValidateArchitecturalSurfaceAccentChild(rootName, $"{rootName}_BridgeDeckPlankD");
            }

            var renderers = root.GetComponentsInChildren<Renderer>(true);
            var expectedCount = ArchitecturalSurfaceAccentPerMapCount +
                (area == FastVsHouseArea.Ruins ? ArchitecturalSurfaceAccentRuinsExtraCount : 0);
            if (renderers.Length < expectedCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs {expectedCount} architectural surface accents, found {renderers.Length}.");
            }

            var center = GetDistantPanoramaVistaCenter(area);
            var facadeMaterialCount = 0;
            var roofMaterialCount = 0;
            var shadowAccentCount = 0;
            var trimAccentCount = 0;
            var bridgeAccentCount = 0;
            foreach (var renderer in renderers)
            {
                if (renderer == null)
                {
                    continue;
                }

                var obj = renderer.gameObject;
                if (obj.layer != expectedLayer)
                {
                    throw new InvalidOperationException($"House slice validation failed: architectural surface accent {obj.name} must stay on render layer {expectedLayer}, found {obj.layer}.");
                }

                if (obj.GetComponent<Collider>() != null || obj.GetComponentsInChildren<Collider>(true).Length > 0)
                {
                    throw new InvalidOperationException($"House slice validation failed: architectural surface accent {obj.name} must remain visual-only and add no collision.");
                }

                if (renderer.shadowCastingMode != ShadowCastingMode.Off || renderer.receiveShadows)
                {
                    throw new InvalidOperationException($"House slice validation failed: architectural surface accent {obj.name} must use a non-shadow renderer.");
                }

                var landmark = obj.GetComponent<TimeWindowPairedSpaceLandmark>();
                if (landmark == null)
                {
                    throw new InvalidOperationException($"House slice validation failed: architectural surface accent {obj.name} must keep a landmark marker.");
                }

                var localScale = obj.transform.localScale;
                if (localScale.x <= 0.01f || localScale.y <= 0.01f || localScale.z <= 0.005f ||
                    localScale.y > 1.45f &&
                    !obj.name.Contains("FacadeVerticalWear", StringComparison.Ordinal) &&
                    !obj.name.Contains("Pilaster", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException($"House slice validation failed: architectural surface accent {obj.name} has invalid thin-surface scale {localScale}.");
                }

                var localOffset = obj.transform.localPosition - center;
                if (Mathf.Abs(localOffset.x) > 29.5f ||
                    Mathf.Abs(localOffset.z) > 9.8f ||
                    localOffset.y < 0.20f ||
                    localOffset.y > 3.45f)
                {
                    throw new InvalidOperationException($"House slice validation failed: architectural surface accent {obj.name} left the intended authored architecture band at offset {localOffset}.");
                }

                var material = renderer.sharedMaterial;
                ValidateArchitecturalSurfaceAccentMaterial(obj.name, material);
                var materialName = material != null ? material.name ?? string.Empty : string.Empty;
                var lowerMaterialName = materialName.ToLowerInvariant();
                if (materialName.IndexOf("AgedPlaster2K", StringComparison.Ordinal) >= 0)
                {
                    facadeMaterialCount++;
                }

                if (materialName.IndexOf("WeatheredRoof2K", StringComparison.Ordinal) >= 0)
                {
                    roofMaterialCount++;
                }

                if (lowerMaterialName.Contains("shadow", StringComparison.Ordinal))
                {
                    shadowAccentCount++;
                }

                if (lowerMaterialName.Contains("frame", StringComparison.Ordinal) ||
                    obj.name.Contains("Trim", StringComparison.Ordinal) ||
                    obj.name.Contains("Fascia", StringComparison.Ordinal) ||
                    obj.name.Contains("Pilaster", StringComparison.Ordinal))
                {
                    trimAccentCount++;
                }

                if (obj.name.Contains("Bridge", StringComparison.Ordinal))
                {
                    bridgeAccentCount++;
                }
            }

            if (facadeMaterialCount < 2 ||
                roofMaterialCount < 1 ||
                shadowAccentCount < 3 ||
                trimAccentCount < 1)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} must combine facade, roof, trim, and shadow accents; facade={facadeMaterialCount}, roof={roofMaterialCount}, shadow={shadowAccentCount}, trim={trimAccentCount}.");
            }

            if (area == FastVsHouseArea.Ruins && bridgeAccentCount < ArchitecturalSurfaceAccentRuinsExtraCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} must include bridge deck accent threads, found {bridgeAccentCount}.");
            }
        }

        private static void ValidateArchitecturalSurfaceAccentChild(string rootName, string objectName)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing architectural surface accent {objectName}.");
            }

            if (sceneObject.transform.parent == null || sceneObject.transform.parent.name != rootName)
            {
                throw new InvalidOperationException($"House slice validation failed: architectural surface accent {objectName} must stay parented under {rootName}.");
            }
        }

        private static void ValidateArchitecturalSurfaceAccentMaterial(string objectName, Material material)
        {
            if (material == null)
            {
                throw new InvalidOperationException($"House slice validation failed: architectural surface accent {objectName} must use a material.");
            }

            var materialName = material.name ?? string.Empty;
            if (materialName.IndexOf("Ch1Surface_", StringComparison.Ordinal) >= 0)
            {
                if (materialName.IndexOf("ArchitecturalAccent", StringComparison.Ordinal) < 0)
                {
                    throw new InvalidOperationException($"House slice validation failed: architectural surface accent {objectName} must use the dedicated Ch1Surface architectural accent material, got {materialName}.");
                }

                var materialPath = AssetDatabase.GetAssetPath(material);
                if (string.IsNullOrEmpty(materialPath) ||
                    materialPath.IndexOf("/FastVS_House_Ch1Surface_", StringComparison.Ordinal) < 0 ||
                    !materialPath.EndsWith(".mat", StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException($"House slice validation failed: architectural surface accent {objectName} material must be a generated Ch1Surface_ asset, got {materialPath}.");
                }

                var texture = GetMaterialPrimaryTexture(material);
                if (texture == null ||
                    texture.width != Chapter1ProductionSurfaceTextureSize ||
                    texture.height != Chapter1ProductionSurfaceTextureSize)
                {
                    throw new InvalidOperationException($"House slice validation failed: architectural surface accent {objectName} must use a {Chapter1ProductionSurfaceTextureSize}x{Chapter1ProductionSurfaceTextureSize} texture.");
                }

                var tint = material.HasProperty("_BaseColor") ? material.GetColor("_BaseColor") : material.GetColor("_Color");
                if (Mathf.Max(tint.r, tint.g, tint.b) > 0.86f)
                {
                    throw new InvalidOperationException($"House slice validation failed: architectural surface accent {objectName} tint is too bright for built-player bloom, found {tint}.");
                }

                return;
            }

            var lowerMaterialName = materialName.ToLowerInvariant();
            if (lowerMaterialName.Contains("shadow", StringComparison.Ordinal) ||
                lowerMaterialName.Contains("frame", StringComparison.Ordinal) ||
                lowerMaterialName.Contains("furniture", StringComparison.Ordinal) ||
                lowerMaterialName.Contains("path", StringComparison.Ordinal))
            {
                return;
            }

            throw new InvalidOperationException($"House slice validation failed: architectural surface accent {objectName} uses an unsupported accent material {materialName}.");
        }

        private static void ValidateDistantPanoramaVistaRoot(string prefix, FastVsHouseArea area)
        {
            var areaToken = GetDistantPanoramaVistaAreaToken(area);
            var rootName = $"{prefix}_{areaToken}_DistantVista";
            var root = FindSceneObjectIncludingInactive(rootName);
            if (root == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing distant panorama vista root {rootName}.");
            }

            var expectedParentName = $"{prefix}_{areaToken}Map_SeparateSpace";
            if (root.transform.parent == null || root.transform.parent.name != expectedParentName)
            {
                throw new InvalidOperationException($"House slice validation failed: distant panorama vista root {rootName} must stay parented under {expectedParentName}.");
            }

            var expectedLayer = string.Equals(prefix, "Past", StringComparison.Ordinal) ? OtherTimeSpaceRenderLayer : CurrentSpaceRenderLayer;
            if (root.layer != expectedLayer)
            {
                throw new InvalidOperationException($"House slice validation failed: distant panorama vista root {rootName} must stay on render layer {expectedLayer}, found {root.layer}.");
            }

            ApplyDistantPanoramaVistaRendererPolicy(root.transform);
            var filters = root.GetComponentsInChildren<MeshFilter>(true);
            if (DistantPanoramaVistaSegmentCount < 24)
            {
                throw new InvalidOperationException($"House slice validation failed: distant panorama vista needs at least 24 radial segments for authored silhouette continuity, found {DistantPanoramaVistaSegmentCount}.");
            }

            if (DistantPanoramaVistaFarRadius < 112f)
            {
                throw new InvalidOperationException($"House slice validation failed: distant panorama vista far radius must stay beyond 112m for parallax depth, found {DistantPanoramaVistaFarRadius:0.000}.");
            }

            var expectedSegments = DistantPanoramaVistaSegmentCount * (DistantPanoramaVistaBandCount + 5) +
                DistantPanoramaVistaNaturalTreeStandCount * 2 +
                DistantPanoramaVistaNaturalCanopyVolumeCount +
                DistantPanoramaVistaNaturalSpeciesClusterCount +
                DistantPanoramaVistaNaturalCanopyAccentCount +
                DistantPanoramaVistaNaturalCanopyFleckCount +
                DistantPanoramaVistaNaturalCanopyShadowCount +
                DistantPanoramaVistaNaturalBranchTraceCount +
                DistantPanoramaVistaNaturalUnderstoryCount +
                DistantPanoramaVistaNaturalConiferSpireCount +
                DistantPanoramaVistaRidgeFacetMeshCount +
                DistantPanoramaVistaRidgeStrataMeshCount +
                DistantPanoramaVistaTreelineFoldMeshCount +
                DistantPanoramaVistaAreaLandmarkCount +
                DistantPanoramaVistaAreaSignatureCount +
                DistantPanoramaVistaLandformFacetCount;
            if (HasDistantPanoramaVistaProductionDepthPrototype(area))
            {
                expectedSegments += DistantPanoramaVistaProductionDepthPrototypeMeshCount;
            }

            if (filters.Length < expectedSegments)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} has {filters.Length} distant vista segments, expected at least {expectedSegments}.");
            }

            var valleyThreadCount = 0;
            foreach (var filter in filters)
            {
                if (filter != null && filter.gameObject.name.Contains("DistantVista_ValleyThread", StringComparison.Ordinal))
                {
                    valleyThreadCount++;
                }
            }

            if (valleyThreadCount < DistantPanoramaVistaSegmentCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs one authored valley thread per distant vista segment, found {valleyThreadCount}.");
            }

            var midgroundValleyBreakCount = 0;
            foreach (var filter in filters)
            {
                if (filter != null && filter.gameObject.name.Contains("DistantVista_MidgroundValleyBreak", StringComparison.Ordinal))
                {
                    midgroundValleyBreakCount++;
                }
            }

            if (midgroundValleyBreakCount < DistantPanoramaVistaSegmentCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs one authored midground valley break per distant vista segment, found {midgroundValleyBreakCount}.");
            }

            var foregroundCoppiceCount = 0;
            foreach (var filter in filters)
            {
                if (filter != null && filter.gameObject.name.Contains("DistantVista_ForegroundCoppice", StringComparison.Ordinal))
                {
                    foregroundCoppiceCount++;
                }
            }

            if (foregroundCoppiceCount < DistantPanoramaVistaSegmentCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs one authored foreground coppice per distant vista segment, found {foregroundCoppiceCount}.");
            }

            var naturalTreeStandCount = 0;
            var naturalCanopyVolumeCount = 0;
            var naturalSpeciesClusterCount = 0;
            var naturalCanopyAccentCount = 0;
            var naturalCanopyFleckCount = 0;
            var naturalCanopyShadowCount = 0;
            var naturalTreeTrunkCount = 0;
            var naturalBranchTraceCount = 0;
            var naturalUnderstoryCount = 0;
            var naturalConiferSpireCount = 0;
            foreach (var filter in filters)
            {
                if (filter == null)
                {
                    continue;
                }

                if (filter.gameObject.name.Contains("DistantVista_NaturalTreeStand", StringComparison.Ordinal))
                {
                    naturalTreeStandCount++;
                }
                else if (filter.gameObject.name.Contains("DistantVista_NaturalCanopyVolume", StringComparison.Ordinal))
                {
                    naturalCanopyVolumeCount++;
                }
                else if (filter.gameObject.name.Contains("DistantVista_NaturalSpeciesCluster", StringComparison.Ordinal))
                {
                    naturalSpeciesClusterCount++;
                }
                else if (filter.gameObject.name.Contains("DistantVista_NaturalCanopyAccent", StringComparison.Ordinal))
                {
                    naturalCanopyAccentCount++;
                }
                else if (filter.gameObject.name.Contains("DistantVista_NaturalCanopyFleck", StringComparison.Ordinal))
                {
                    naturalCanopyFleckCount++;
                }
                else if (filter.gameObject.name.Contains("DistantVista_NaturalCanopyShadow", StringComparison.Ordinal))
                {
                    naturalCanopyShadowCount++;
                }
                else if (filter.gameObject.name.Contains("DistantVista_NaturalTreeTrunks", StringComparison.Ordinal))
                {
                    naturalTreeTrunkCount++;
                }
                else if (filter.gameObject.name.Contains("DistantVista_NaturalBranchTrace", StringComparison.Ordinal))
                {
                    naturalBranchTraceCount++;
                }
                else if (filter.gameObject.name.Contains("DistantVista_NaturalUnderstory", StringComparison.Ordinal))
                {
                    naturalUnderstoryCount++;
                }
                else if (filter.gameObject.name.Contains("DistantVista_NaturalConiferSpire", StringComparison.Ordinal))
                {
                    naturalConiferSpireCount++;
                }
            }

            if (naturalTreeStandCount < DistantPanoramaVistaNaturalTreeStandCount ||
                naturalCanopyVolumeCount < DistantPanoramaVistaNaturalCanopyVolumeCount ||
                naturalSpeciesClusterCount < DistantPanoramaVistaNaturalSpeciesClusterCount ||
                naturalCanopyAccentCount < DistantPanoramaVistaNaturalCanopyAccentCount ||
                naturalCanopyFleckCount < DistantPanoramaVistaNaturalCanopyFleckCount ||
                naturalCanopyShadowCount < DistantPanoramaVistaNaturalCanopyShadowCount ||
                naturalTreeTrunkCount < DistantPanoramaVistaNaturalTreeStandCount ||
                naturalBranchTraceCount < DistantPanoramaVistaNaturalBranchTraceCount ||
                naturalUnderstoryCount < DistantPanoramaVistaNaturalUnderstoryCount ||
                naturalConiferSpireCount < DistantPanoramaVistaNaturalConiferSpireCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs natural tree stand canopy/volume/species/accent/fleck/shadow/trunk/branch/understory/conifer layers, found canopy={naturalTreeStandCount}, volumes={naturalCanopyVolumeCount}, species={naturalSpeciesClusterCount}, accents={naturalCanopyAccentCount}, flecks={naturalCanopyFleckCount}, shadows={naturalCanopyShadowCount}, trunks={naturalTreeTrunkCount}, branches={naturalBranchTraceCount}, understory={naturalUnderstoryCount}, conifers={naturalConiferSpireCount}.");
            }

            var areaLandmarkCount = 0;
            foreach (var filter in filters)
            {
                if (filter != null && filter.gameObject.name.Contains("DistantVista_AreaLandmark", StringComparison.Ordinal))
                {
                    areaLandmarkCount++;
                }
            }

            if (areaLandmarkCount < DistantPanoramaVistaAreaLandmarkCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs {DistantPanoramaVistaAreaLandmarkCount} authored area landmarks, found {areaLandmarkCount}.");
            }

            var areaSignatureCount = 0;
            foreach (var filter in filters)
            {
                if (filter != null && filter.gameObject.name.Contains("DistantVista_AreaSignature", StringComparison.Ordinal))
                {
                    areaSignatureCount++;
                }
            }

            if (areaSignatureCount < DistantPanoramaVistaAreaSignatureCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs {DistantPanoramaVistaAreaSignatureCount} authored area signatures, found {areaSignatureCount}.");
            }

            var landformFacetCount = 0;
            foreach (var filter in filters)
            {
                if (filter != null && filter.gameObject.name.Contains("DistantVista_LandformFacet", StringComparison.Ordinal))
                {
                    landformFacetCount++;
                }
            }

            if (landformFacetCount < DistantPanoramaVistaLandformFacetCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs {DistantPanoramaVistaLandformFacetCount} authored landform facet meshes, found {landformFacetCount}.");
            }

            var compositionPrototypeCount = 0;
            foreach (var filter in filters)
            {
                if (filter != null && filter.gameObject.name.Contains("DistantVista_CompositionPrototype", StringComparison.Ordinal))
                {
                    compositionPrototypeCount++;
                }
            }

            if (HasDistantPanoramaVistaCompositionPrototype(area) && compositionPrototypeCount < DistantPanoramaVistaCompositionPrototypeCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs {DistantPanoramaVistaCompositionPrototypeCount} authored composition prototype meshes, found {compositionPrototypeCount}.");
            }

            var ridgeFacetCount = 0;
            var ridgeStrataCount = 0;
            foreach (var filter in filters)
            {
                if (filter != null && filter.gameObject.name.Contains("DistantVista_RidgeFacet", StringComparison.Ordinal))
                {
                    ridgeFacetCount++;
                }
                else if (filter != null && filter.gameObject.name.Contains("DistantVista_RidgeStrata", StringComparison.Ordinal))
                {
                    ridgeStrataCount++;
                }
            }

            if (ridgeFacetCount < DistantPanoramaVistaRidgeFacetMeshCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs {DistantPanoramaVistaRidgeFacetMeshCount} authored ridge facet detail meshes, found {ridgeFacetCount}.");
            }

            if (ridgeStrataCount < DistantPanoramaVistaRidgeStrataMeshCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs {DistantPanoramaVistaRidgeStrataMeshCount} authored ridge strata meshes, found {ridgeStrataCount}.");
            }

            var treelineFoldCount = 0;
            foreach (var filter in filters)
            {
                if (filter != null && filter.gameObject.name.Contains("DistantVista_TreelineFold", StringComparison.Ordinal))
                {
                    treelineFoldCount++;
                }
            }

            if (treelineFoldCount < DistantPanoramaVistaTreelineFoldMeshCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs {DistantPanoramaVistaTreelineFoldMeshCount} authored treeline fold detail meshes, found {treelineFoldCount}.");
            }

            var productionDepthCount = 0;
            foreach (var filter in filters)
            {
                if (filter != null && filter.gameObject.name.Contains("DistantVista_ProductionDepth", StringComparison.Ordinal))
                {
                    productionDepthCount++;
                }
            }

            if (HasDistantPanoramaVistaProductionDepthPrototype(area) &&
                productionDepthCount < DistantPanoramaVistaProductionDepthPrototypeMeshCount)
            {
                throw new InvalidOperationException($"House slice validation failed: {rootName} needs {DistantPanoramaVistaProductionDepthPrototypeMeshCount} authored production-depth vista meshes, found {productionDepthCount}.");
            }

            var center = GetDistantPanoramaVistaCenter(area);
            foreach (var filter in filters)
            {
                if (filter.sharedMesh == null || filter.sharedMesh.vertexCount < 36 || filter.sharedMesh.triangles.Length < 108)
                {
                    throw new InvalidOperationException($"House slice validation failed: distant vista segment {filter.gameObject.name} must keep authored relief density.");
                }

                var localPosition = filter.transform.localPosition;
                var horizontalDistance = Vector2.Distance(new Vector2(localPosition.x, localPosition.z), new Vector2(center.x, center.z));
                if (horizontalDistance < 62f || horizontalDistance > 124f)
                {
                    throw new InvalidOperationException($"House slice validation failed: distant vista segment {filter.gameObject.name} radius {horizontalDistance:0.000} is outside the intended ring.");
                }

                if (filter.gameObject.layer != expectedLayer)
                {
                    throw new InvalidOperationException($"House slice validation failed: distant vista segment {filter.gameObject.name} must stay on render layer {expectedLayer}, found {filter.gameObject.layer}.");
                }

                if (filter.GetComponent<Collider>() != null || filter.GetComponentsInChildren<Collider>(true).Length > 0)
                {
                    throw new InvalidOperationException($"House slice validation failed: distant vista segment {filter.gameObject.name} must not add collision.");
                }

                var renderer = filter.GetComponent<Renderer>();
                if (renderer == null || renderer.sharedMaterial == null || !renderer.sharedMaterial.name.Contains("Ch1Distant", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException($"House slice validation failed: distant vista segment {filter.gameObject.name} must use a Ch1Distant material.");
                }

                if (filter.gameObject.name.Contains("DistantVista_LandformFacet", StringComparison.Ordinal) &&
                    ResolveMaterialTexture(renderer.sharedMaterial) == null)
                {
                    throw new InvalidOperationException($"House slice validation failed: distant vista landform facet {filter.gameObject.name} must use a textured material.");
                }

                if (filter.gameObject.name.Contains("DistantVista_ProductionDepth", StringComparison.Ordinal) &&
                    ResolveMaterialTexture(renderer.sharedMaterial) == null)
                {
                    throw new InvalidOperationException($"House slice validation failed: distant vista production-depth mesh {filter.gameObject.name} must use a textured material.");
                }

                if (HasDistantPanoramaVistaProductionDepthPrototype(area) &&
                    (filter.gameObject.name.Contains("_DistantVista_B", StringComparison.Ordinal) ||
                        filter.gameObject.name.Contains("DistantVista_FoothillForest", StringComparison.Ordinal)) &&
                    ResolveMaterialTexture(renderer.sharedMaterial) == null)
                {
                    throw new InvalidOperationException($"House slice validation failed: distant vista production-depth base band {filter.gameObject.name} must use a textured material.");
                }

                if (renderer.shadowCastingMode != ShadowCastingMode.Off)
                {
                    throw new InvalidOperationException($"House slice validation failed: distant vista segment {filter.gameObject.name} must not cast shadows.");
                }

                var landmark = filter.GetComponent<TimeWindowPairedSpaceLandmark>();
                if (landmark == null)
                {
                    throw new InvalidOperationException($"House slice validation failed: distant vista segment {filter.gameObject.name} must keep a landmark marker.");
                }
            }

            foreach (var child in root.GetComponentsInChildren<Transform>(true))
            {
                if (child != root.transform && child.name.Contains("OutdoorVoidBackground", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException($"House slice validation failed: flat void background slab remained inside distant vista root: {child.name}.");
                }
            }

            ValidateDistantPanoramaVistaLegacyFlatSurfacesSuppressed(prefix, area);
        }

        private static void ValidateDistantPanoramaVistaLegacyFlatSurfacesSuppressed(string prefix, FastVsHouseArea area)
        {
            var areaToken = GetDistantPanoramaVistaAreaToken(area);
            var mapRootName = $"{prefix}_{areaToken}Map_SeparateSpace";
            var mapRoot = FindSceneObjectIncludingInactive(mapRootName);
            if (mapRoot == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing map root for distant vista flat-surface suppression: {mapRootName}.");
            }

            foreach (var child in mapRoot.GetComponentsInChildren<Transform>(true))
            {
                if (child == mapRoot.transform || !child.gameObject.activeSelf)
                {
                    continue;
                }

                if (IsDistantPanoramaVistaLegacyFlatSurfaceName(child.name))
                {
                    throw new InvalidOperationException($"House slice validation failed: legacy flat backdrop surface must be inactive while distant panorama vista is authored: {child.name}.");
                }
            }
        }

        private static void ValidateDistantPanoramaVistaCameraCoverage(Camera camera, string prefix, FastVsHouseArea area)
        {
            var root = FindSceneObjectIncludingInactive($"{prefix}_{GetDistantPanoramaVistaAreaToken(area)}_DistantVista");
            if (root == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing distant vista root for camera coverage: {prefix} {area}.");
            }

            var center = GetDistantPanoramaVistaCenter(area);
            PositionChapter1AllMapsCamera(
                camera,
                center,
                GetDistantPanoramaVistaReviewPositionOffset(area),
                GetDistantPanoramaVistaReviewLookAtOffset(area));

            var visibleCount = 0;
            var horizonCount = 0;
            var compositionPrototypeVisibleCount = 0;
            var qualityDetailVisibleCount = 0;
            var naturalTreeStandVisibleCount = 0;
            var naturalCanopyVolumeVisibleCount = 0;
            var naturalSpeciesClusterVisibleCount = 0;
            var naturalCanopyAccentVisibleCount = 0;
            var naturalCanopyFleckVisibleCount = 0;
            var naturalCanopyShadowVisibleCount = 0;
            var naturalBranchTraceVisibleCount = 0;
            var naturalUnderstoryVisibleCount = 0;
            var naturalConiferSpireVisibleCount = 0;
            var landformFacetVisibleCount = 0;
            var ridgeStrataVisibleCount = 0;
            var productionDepthVisibleCount = 0;
            foreach (var renderer in root.GetComponentsInChildren<Renderer>(true))
            {
                if (renderer == null || !renderer.enabled)
                {
                    continue;
                }

                if (DistantPanoramaVistaBoundsTouchesCamera(camera, renderer.bounds, out var minY, out var maxY))
                {
                    visibleCount++;
                    if (maxY > 0.70f && minY < 1.02f && maxY - minY > 0.05f)
                    {
                        horizonCount++;
                    }

                    if (HasDistantPanoramaVistaCompositionPrototype(area) &&
                        renderer.gameObject.name.Contains("DistantVista_CompositionPrototype", StringComparison.Ordinal))
                    {
                        compositionPrototypeVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_RidgeFacet", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_LandformFacet", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_TreelineFold", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_NaturalTreeStand", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_NaturalCanopyVolume", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_NaturalSpeciesCluster", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_NaturalCanopyAccent", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_NaturalCanopyFleck", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_NaturalCanopyShadow", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_NaturalBranchTrace", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_NaturalUnderstory", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_NaturalConiferSpire", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_RidgeStrata", StringComparison.Ordinal) ||
                        renderer.gameObject.name.Contains("DistantVista_ProductionDepth", StringComparison.Ordinal))
                    {
                        qualityDetailVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_NaturalTreeStand", StringComparison.Ordinal))
                    {
                        naturalTreeStandVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_NaturalCanopyVolume", StringComparison.Ordinal))
                    {
                        naturalCanopyVolumeVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_NaturalSpeciesCluster", StringComparison.Ordinal))
                    {
                        naturalSpeciesClusterVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_NaturalCanopyAccent", StringComparison.Ordinal))
                    {
                        naturalCanopyAccentVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_NaturalCanopyFleck", StringComparison.Ordinal))
                    {
                        naturalCanopyFleckVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_NaturalCanopyShadow", StringComparison.Ordinal))
                    {
                        naturalCanopyShadowVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_NaturalBranchTrace", StringComparison.Ordinal))
                    {
                        naturalBranchTraceVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_NaturalUnderstory", StringComparison.Ordinal))
                    {
                        naturalUnderstoryVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_NaturalConiferSpire", StringComparison.Ordinal))
                    {
                        naturalConiferSpireVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_LandformFacet", StringComparison.Ordinal))
                    {
                        landformFacetVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_RidgeStrata", StringComparison.Ordinal))
                    {
                        ridgeStrataVisibleCount++;
                    }

                    if (renderer.gameObject.name.Contains("DistantVista_ProductionDepth", StringComparison.Ordinal))
                    {
                        productionDepthVisibleCount++;
                    }
                }
            }

            if (visibleCount < 2 || horizonCount < 2)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} must project into the wide camera view, visible={visibleCount}, horizon={horizonCount}.");
            }

            if (HasDistantPanoramaVistaCompositionPrototype(area) && compositionPrototypeVisibleCount < 3)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} composition prototype must be visible in the wide camera, visible={compositionPrototypeVisibleCount}.");
            }

            if (qualityDetailVisibleCount < DistantPanoramaVistaQualityDetailVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} ridge/treeline quality details must be visible in the wide camera, visible={qualityDetailVisibleCount}.");
            }

            if (naturalTreeStandVisibleCount < DistantPanoramaVistaNaturalTreeStandVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} natural tree stands must visibly replace flat forest silhouettes, visible={naturalTreeStandVisibleCount}.");
            }

            if (naturalCanopyVolumeVisibleCount < DistantPanoramaVistaNaturalCanopyVolumeVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} natural canopy volumes must visibly read as layered tree crowns, visible={naturalCanopyVolumeVisibleCount}.");
            }

            if (naturalSpeciesClusterVisibleCount < DistantPanoramaVistaNaturalSpeciesClusterVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} natural species clusters must visibly group broadleaf and conifer profiles, visible={naturalSpeciesClusterVisibleCount}.");
            }

            if (naturalCanopyAccentVisibleCount < DistantPanoramaVistaNaturalCanopyAccentVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} natural canopy accents must be visible enough to break the dark forest band, visible={naturalCanopyAccentVisibleCount}.");
            }

            if (naturalCanopyFleckVisibleCount < DistantPanoramaVistaNaturalCanopyFleckVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} natural canopy flecks must be visible enough to add varied leaf-face highlights, visible={naturalCanopyFleckVisibleCount}.");
            }

            if (naturalCanopyShadowVisibleCount < DistantPanoramaVistaNaturalCanopyShadowVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} natural canopy shadow pockets must be visible enough to carve interior foliage depth, visible={naturalCanopyShadowVisibleCount}.");
            }

            if (naturalBranchTraceVisibleCount < DistantPanoramaVistaNaturalBranchTraceVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} branch traces must be visible enough to make the forest read as individual trees, visible={naturalBranchTraceVisibleCount}.");
            }

            if (naturalUnderstoryVisibleCount < DistantPanoramaVistaNaturalUnderstoryVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} understory layers must be visible enough to break the flat tree-line base, visible={naturalUnderstoryVisibleCount}.");
            }

            if (naturalConiferSpireVisibleCount < DistantPanoramaVistaNaturalConiferSpireVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} conifer spires must be visible enough to add natural species variety, visible={naturalConiferSpireVisibleCount}.");
            }

            if (landformFacetVisibleCount < DistantPanoramaVistaLandformFacetVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} landform facets must visibly break the upper panorama silhouette, visible={landformFacetVisibleCount}.");
            }

            if (ridgeStrataVisibleCount < DistantPanoramaVistaRidgeStrataVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} ridge strata must visibly read as authored terrain surfaces, visible={ridgeStrataVisibleCount}.");
            }

            if (HasDistantPanoramaVistaProductionDepthPrototype(area) &&
                productionDepthVisibleCount < DistantPanoramaVistaProductionDepthPrototypeVisibleMinimum)
            {
                throw new InvalidOperationException($"House slice validation failed: distant vista {prefix} {area} production-depth prototype must visibly add foreground/mid/far depth, visible={productionDepthVisibleCount}.");
            }
        }

        private static bool DistantPanoramaVistaBoundsTouchesCamera(Camera camera, Bounds bounds, out float minY, out float maxY)
        {
            minY = float.PositiveInfinity;
            maxY = float.NegativeInfinity;
            var minX = float.PositiveInfinity;
            var maxX = float.NegativeInfinity;
            var anyInDepth = false;
            var center = bounds.center;
            var extents = bounds.extents;

            for (var xi = -1; xi <= 1; xi += 2)
            {
                for (var yi = -1; yi <= 1; yi += 2)
                {
                    for (var zi = -1; zi <= 1; zi += 2)
                    {
                        var corner = center + Vector3.Scale(extents, new Vector3(xi, yi, zi));
                        var viewport = camera.WorldToViewportPoint(corner);
                        if (viewport.z <= camera.nearClipPlane || viewport.z >= camera.farClipPlane)
                        {
                            continue;
                        }

                        anyInDepth = true;
                        minX = Mathf.Min(minX, viewport.x);
                        maxX = Mathf.Max(maxX, viewport.x);
                        minY = Mathf.Min(minY, viewport.y);
                        maxY = Mathf.Max(maxY, viewport.y);
                    }
                }
            }

            return anyInDepth && maxX >= -0.08f && minX <= 1.08f && maxY >= -0.04f && minY <= 1.08f;
        }

        private static void ValidateLibraryMapLayout(string floorName, string backWallName, string leftBalconyName, string rightBalconyName, string backGalleryName, string railingName)
        {
            var floor = FindSceneObjectIncludingInactive(floorName);
            if (floor == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing library floor: {floorName}");
            }

            if (floor.transform.localScale.x < 11.2f || floor.transform.localScale.x > 12.4f)
            {
                throw new InvalidOperationException($"House slice validation failed: library floor width is outside the intended narrow range: {floorName}");
            }

            if (floor.transform.localScale.z < 14.5f)
            {
                throw new InvalidOperationException($"House slice validation failed: library floor is not deep enough: {floorName}");
            }

            if (FindSceneObjectIncludingInactive(backWallName) == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing library back wall: {backWallName}");
            }

            if (FindSceneObjectIncludingInactive(leftBalconyName) == null ||
                FindSceneObjectIncludingInactive(rightBalconyName) == null ||
                FindSceneObjectIncludingInactive(backGalleryName) == null ||
                FindSceneObjectIncludingInactive(railingName) == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing library second-floor blockout pieces for {floorName}");
            }
        }

