        private static LensFlareDataElementSRP CreateHd2dPhaseBLensFlareElement(
            float position,
            float localIntensity,
            float uniformScale,
            Color tint,
            SRPLensFlareBlendMode blendMode,
            SRPLensFlareType flareType,
            bool allowMultipleElement,
            int count,
            bool preserveAspectRatio,
            float ringThickness,
            int sideCount,
            float sdfRoundness)
        {
            var element = new LensFlareDataElementSRP
            {
                visible = true,
                position = position,
                positionOffset = Vector2.zero,
                angularOffset = 0f,
                translationScale = Vector2.one,
                localIntensity = localIntensity,
                lensFlareTexture = null,
                uniformScale = uniformScale,
                sizeXY = Vector2.one,
                allowMultipleElement = allowMultipleElement,
                count = count,
                preserveAspectRatio = preserveAspectRatio,
                rotation = 0f,
                tintColorType = SRPLensFlareColorType.Constant,
                tint = tint,
                tintGradient = new TextureGradient(
                    new GradientColorKey[] { new GradientColorKey(Color.black, 0f), new GradientColorKey(Color.white, 1f) },
                    new GradientAlphaKey[] { new GradientAlphaKey(0f, 0f), new GradientAlphaKey(1f, 1f) }),
                blendMode = blendMode,
                autoRotate = false,
                flareType = flareType,
                modulateByLightColor = true,
                distribution = SRPLensFlareDistribution.Uniform,
                lengthSpread = 1f,
                positionCurve = new AnimationCurve(new Keyframe(0f, 0f, 1f, 1f), new Keyframe(1f, 1f, 1f, -1f)),
                scaleCurve = new AnimationCurve(new Keyframe(0f, 1f), new Keyframe(1f, 1f)),
                seed = 0,
                intensityVariation = 0f,
                positionVariation = Vector2.zero,
                scaleVariation = 0f,
                rotationVariation = 0f,
                enableRadialDistortion = false,
                targetSizeDistortion = Vector2.one,
                distortionCurve = new AnimationCurve(new Keyframe(0f, 0f, 1f, 1f), new Keyframe(1f, 1f, 1f, -1f)),
                distortionRelativeToCenter = false,
                fallOff = 0.5f,
                edgeOffset = 1f,
                sideCount = sideCount,
                sdfRoundness = sdfRoundness,
                inverseSDF = false,
                uniformAngle = 0f,
                uniformAngleCurve = new AnimationCurve(new Keyframe(0f, 0f), new Keyframe(1f, 0f)),
                ringThickness = ringThickness,
                hoopFactor = 1f,
                noiseAmplitude = 1f,
                noiseFrequency = 1,
                noiseSpeed = 0f,
                shapeCutOffSpeed = 0f,
                shapeCutOffRadius = 10f
            };

            element.colorGradient = new Gradient();
            element.colorGradient.SetKeys(
                new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(Color.white, 1f) },
                new[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(1f, 1f) });
            return element;
        }

        private static void ApplyHd2dPhaseBAlphaScreenSpaceLensFlare(VolumeProfile profile)
        {
            if (profile == null)
            {
                throw new InvalidOperationException("Fast VS HD-2D phase B-alpha screen-space lens flare setup failed: volume profile is missing.");
            }

            if (!profile.TryGet<ScreenSpaceLensFlare>(out var screenSpaceLensFlare))
            {
                screenSpaceLensFlare = profile.Add<ScreenSpaceLensFlare>(true);
            }

            screenSpaceLensFlare.active = true;
            screenSpaceLensFlare.intensity.overrideState = true;
            screenSpaceLensFlare.intensity.value = 0.4f;
            screenSpaceLensFlare.tintColor.overrideState = true;
            screenSpaceLensFlare.tintColor.value = new Color(1.00f, 0.95f, 0.88f, 1f);
            screenSpaceLensFlare.bloomMip.overrideState = true;
            screenSpaceLensFlare.bloomMip.value = 1;
            screenSpaceLensFlare.firstFlareIntensity.overrideState = true;
            screenSpaceLensFlare.firstFlareIntensity.value = 0.75f;
            screenSpaceLensFlare.secondaryFlareIntensity.overrideState = true;
            screenSpaceLensFlare.secondaryFlareIntensity.value = 0.32f;
            screenSpaceLensFlare.warpedFlareIntensity.overrideState = true;
            screenSpaceLensFlare.warpedFlareIntensity.value = 0.18f;
            screenSpaceLensFlare.warpedFlareScale.overrideState = true;
            screenSpaceLensFlare.warpedFlareScale.value = new Vector2(1f, 1f);
            screenSpaceLensFlare.samples.overrideState = true;
            screenSpaceLensFlare.samples.value = 1;
            screenSpaceLensFlare.sampleDimmer.overrideState = true;
            screenSpaceLensFlare.sampleDimmer.value = 0.65f;
            screenSpaceLensFlare.vignetteEffect.overrideState = true;
            screenSpaceLensFlare.vignetteEffect.value = 0.90f;
            screenSpaceLensFlare.startingPosition.overrideState = true;
            screenSpaceLensFlare.startingPosition.value = 1.20f;
            screenSpaceLensFlare.scale.overrideState = true;
            screenSpaceLensFlare.scale.value = 1.15f;
            screenSpaceLensFlare.streaksIntensity.overrideState = true;
            screenSpaceLensFlare.streaksIntensity.value = 0f;
            screenSpaceLensFlare.streaksLength.overrideState = true;
            screenSpaceLensFlare.streaksLength.value = 0.25f;
            screenSpaceLensFlare.streaksOrientation.overrideState = true;
            screenSpaceLensFlare.streaksOrientation.value = 0f;
            screenSpaceLensFlare.streaksThreshold.overrideState = true;
            screenSpaceLensFlare.streaksThreshold.value = 0.40f;
            screenSpaceLensFlare.resolution.overrideState = true;
            screenSpaceLensFlare.resolution.value = ScreenSpaceLensFlareResolution.Quarter;
            screenSpaceLensFlare.chromaticAbberationIntensity.overrideState = true;
            screenSpaceLensFlare.chromaticAbberationIntensity.value = 0.12f;
            EditorUtility.SetDirty(profile);
            EditorUtility.SetDirty(screenSpaceLensFlare);
        }

        private static bool EnsureHd2dPhaseBAlphaRenderPipelineLensFlareSupport()
        {
            var pipelineAsset = AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>(UniversalRenderPipelineAssetPath);
            if (pipelineAsset == null)
            {
                throw new InvalidOperationException($"Fast VS HD-2D phase B-alpha lens flare setup failed: missing URP asset at {UniversalRenderPipelineAssetPath}.");
            }

            var serialized = new SerializedObject(pipelineAsset);
            var supportDataDrivenLensFlare = serialized.FindProperty("m_SupportDataDrivenLensFlare");
            var supportScreenSpaceLensFlare = serialized.FindProperty("m_SupportScreenSpaceLensFlare");
            if (supportDataDrivenLensFlare == null || supportScreenSpaceLensFlare == null)
            {
                throw new InvalidOperationException("Fast VS HD-2D phase B-alpha lens flare setup failed: URP asset is missing lens flare support serialized properties.");
            }

            supportDataDrivenLensFlare.boolValue = true;
            supportScreenSpaceLensFlare.boolValue = true;

            var volumetricFogEnabled = serialized.FindProperty("m_VolumetricFogEnabled");
            var hasVolumetricFogEnabled = volumetricFogEnabled != null;
            if (hasVolumetricFogEnabled)
            {
#if BUTO
                volumetricFogEnabled.boolValue = false;
#else
                volumetricFogEnabled.boolValue = true;
#endif
            }

            serialized.ApplyModifiedPropertiesWithoutUndo();
            EditorUtility.SetDirty(pipelineAsset);
            return hasVolumetricFogEnabled;
        }

        private static void WriteHd2dPhaseBLensFlareDiagnosticsReport(string outputDirectory)
        {
            Directory.CreateDirectory(outputDirectory);

            var directionalSunObject = FindSceneObjectIncludingInactive("Directional Light");
            var directionalSun = directionalSunObject != null ? directionalSunObject.GetComponent<Light>() : null;
            var lensFlare = directionalSunObject != null ? directionalSunObject.GetComponent<LensFlareComponentSRP>() : null;
            var volumeObject = FindSceneObjectIncludingInactive("FastVS_HD2D_GlobalVolume");
            var volume = volumeObject != null ? volumeObject.GetComponent<Volume>() : null;
            var profile = volume != null ? volume.sharedProfile : null;
            ScreenSpaceLensFlare screenSpaceLensFlare = null;
            if (profile != null)
            {
                profile.TryGet<ScreenSpaceLensFlare>(out screenSpaceLensFlare);
            }
            var volumetricFogPropertyPresent = EnsureHd2dPhaseBAlphaRenderPipelineLensFlareSupport();
            var dataDrivenSupport = GetSerializedBoolAssetValue(UniversalRenderPipelineAssetPath, "m_SupportDataDrivenLensFlare");
            var screenSpaceSupport = GetSerializedBoolAssetValue(UniversalRenderPipelineAssetPath, "m_SupportScreenSpaceLensFlare");
            var reportPath = Path.Combine(outputDirectory, Hd2dPhaseBLensFlareDiagnosticsReportFileName);
            var lines = new List<string>
            {
                "# HD2D Phase B Alpha Scene Lens Flare Diagnostics",
                string.Empty,
                $"- Validate entry: `{nameof(ValidateHd2dPhaseBAlphaSceneLensFlareBatch)}`",
                $"- Capture entry: `{nameof(CaptureHd2dPhaseBAlphaSceneLensFlareCycle175ScreenshotsBatch)}`",
                $"- Directional light: `{(directionalSun != null ? directionalSun.name : "<missing>")}`",
                $"- Lens flare asset: `{Hd2dPhaseBLensFlareDataAssetPath}`",
                $"- Lens flare intensity: `{(lensFlare != null ? lensFlare.intensity : 0f):0.000}`",
                $"- Screen-space lens flare active: `{(screenSpaceLensFlare != null && screenSpaceLensFlare.active)}`",
                $"- Screen-space lens flare intensity: `{(screenSpaceLensFlare != null ? screenSpaceLensFlare.intensity.value : 0f):0.000}`",
                $"- Screen-space lens flare samples: `{(screenSpaceLensFlare != null ? screenSpaceLensFlare.samples.value : 0)}`",
                $"- URP support flags: data-driven=`{dataDrivenSupport}`, screen-space=`{screenSpaceSupport}`",
                $"- URP serialized volumetric fog property exposed locally: `{volumetricFogPropertyPresent}`",
                string.Empty,
                "- Visual state is recorded for Tom's PNG review; this report does not claim visual sign-off."
            };

            File.WriteAllText(reportPath, string.Join(Environment.NewLine, lines) + Environment.NewLine);
            if (!File.Exists(reportPath))
            {
                throw new InvalidOperationException($"Fast VS phase B-alpha lens flare diagnostics report failed: missing output file {reportPath}");
            }

            AssetDatabase.Refresh();
        }

        private static void ValidateHd2dPhaseCAlphaEmissiveVfxSetup()
        {
            ValidateHd2dStage2EmissiveShaderProfile();
            BuildHd2dPhaseCAlphaEmissiveVfxDiagnosticsLines(out _, out _);
        }

        private static void WriteHd2dPhaseCAlphaEmissiveVfxDiagnosticsReport(string outputDirectory)
        {
            Directory.CreateDirectory(outputDirectory);

            var lines = BuildHd2dPhaseCAlphaEmissiveVfxDiagnosticsLines(out _, out _);
            var reportPath = Path.Combine(outputDirectory, Hd2dPhaseCAlphaEmissiveVfxDiagnosticsReportFileName);
            File.WriteAllText(reportPath, string.Join(Environment.NewLine, lines) + Environment.NewLine);
            if (!File.Exists(reportPath))
            {
                throw new InvalidOperationException($"Fast VS phase C-alpha emissive VFX diagnostics report failed: missing output file {reportPath}");
            }

            AssetDatabase.Refresh();
        }

        private static List<string> BuildHd2dPhaseCAlphaEmissiveVfxDiagnosticsLines(out bool vfxGraphPackageAvailable, out bool particleSystemFallbackUsed)
        {
            vfxGraphPackageAvailable = IsHd2dVisualEffectGraphPackageAvailable();
            particleSystemFallbackUsed = true;

            ValidateHd2dPhaseCAlphaEmissiveVfxObjects();

            var fireSpark = FindSceneObjectIncludingInactive("FastVS_HD2D_PhaseCAlpha_Fire_Spark");
            var firefly = FindSceneObjectIncludingInactive("FastVS_HD2D_PhaseCAlpha_Firefly");
            var smoke = FindSceneObjectIncludingInactive("FastVS_HD2D_PhaseCAlpha_Smoke");
            var waterSplash = FindSceneObjectIncludingInactive("FastVS_HD2D_PhaseCAlpha_WaterSplash");
            var libraryWarmLight = FindSceneObjectIncludingInactive("FastVS_HD2D_PhaseCAlpha_LibraryWarmEmissiveLight")?.GetComponent<Light>();
            var plazaWaterLight = FindSceneObjectIncludingInactive("FastVS_HD2D_PhaseCAlpha_PlazaWaterSparkleLight")?.GetComponent<Light>();

            var fireSparkSystem = fireSpark != null ? fireSpark.GetComponent<ParticleSystem>() : null;
            var fireflySystem = firefly != null ? firefly.GetComponent<ParticleSystem>() : null;
            var smokeSystem = smoke != null ? smoke.GetComponent<ParticleSystem>() : null;
            var waterSplashSystem = waterSplash != null ? waterSplash.GetComponent<ParticleSystem>() : null;

            return new List<string>
            {
                "# HD2D Phase C Alpha Emissive VFX Diagnostics",
                string.Empty,
                $"- Validate entry: `{nameof(ValidateHd2dPhaseCAlphaEmissiveVfxBatch)}`",
                $"- Capture entry: `{nameof(CaptureHd2dPhaseCAlphaEmissiveVfxCycle177ScreenshotsBatch)}`",
                $"- VFX Graph package available: `{vfxGraphPackageAvailable}`",
                $"- ParticleSystem fallback used: `{particleSystemFallbackUsed}`",
                $"- Fallback state recorded without failing when VFX Graph is absent: `{!vfxGraphPackageAvailable && particleSystemFallbackUsed}`",
                $"- Stage 2 window light emission: color=`{Stage2WindowLightEmissionColor}`, intensity=`{Stage2WindowLightEmissionIntensity:0.000}`",
                $"- Stage 2 library window light emission: color=`{Stage2LibraryWindowLightEmissionColor}`, intensity=`{Stage2LibraryWindowLightEmissionIntensity:0.000}`",
                $"- Phase C-alpha fire spark particles: max=`{(fireSparkSystem != null ? fireSparkSystem.main.maxParticles : 0)}`, lifetime=`{(fireSparkSystem != null ? fireSparkSystem.main.startLifetime.constant : 0f):0.000}`, color=`{(fireSparkSystem != null ? fireSparkSystem.main.startColor.color : Color.clear)}`",
                $"- Phase C-alpha firefly particles: max=`{(fireflySystem != null ? fireflySystem.main.maxParticles : 0)}`, lifetime=`{(fireflySystem != null ? fireflySystem.main.startLifetime.constant : 0f):0.000}`, color=`{(fireflySystem != null ? fireflySystem.main.startColor.color : Color.clear)}`",
                $"- Phase C-alpha smoke particles: max=`{(smokeSystem != null ? smokeSystem.main.maxParticles : 0)}`, lifetime=`{(smokeSystem != null ? smokeSystem.main.startLifetime.constant : 0f):0.000}`, color=`{(smokeSystem != null ? smokeSystem.main.startColor.color : Color.clear)}`",
                $"- Phase C-alpha water splash particles: max=`{(waterSplashSystem != null ? waterSplashSystem.main.maxParticles : 0)}`, lifetime=`{(waterSplashSystem != null ? waterSplashSystem.main.startLifetime.constant : 0f):0.000}`, color=`{(waterSplashSystem != null ? waterSplashSystem.main.startColor.color : Color.clear)}`",
                $"- Phase C-alpha library warm emissive light intensity: `{(libraryWarmLight != null ? libraryWarmLight.intensity : 0f):0.000}`",
                $"- Phase C-alpha plaza water sparkle light intensity: `{(plazaWaterLight != null ? plazaWaterLight.intensity : 0f):0.000}`",
                string.Empty,
                "- Tom review evidence only; this report does not claim visual sign-off."
            };
        }

        private static void ValidateHd2dFeedbackLightingPolishSceneState()
        {
            var exteriorAnchor = FindSceneObjectIncludingInactive("FastVS_HD2D_MapSunAnchor_Exterior_Morning")?.GetComponent<MapSunAnchor>();
            if (exteriorAnchor == null || !exteriorAnchor.TransitionFromPrevious)
            {
                throw new InvalidOperationException("Fast VS feedback lighting polish validation failed: the exterior sun anchor must use runtime transition smoothing.");
            }

            var atmosphereMaterial = EnsureHd2dAtmosphereParticleMaterial();
            ValidateHd2dFeedbackMaterialAlpha(atmosphereMaterial, "_BaseColor", 0.60f);
            ValidateHd2dFeedbackMaterialAlpha(atmosphereMaterial, "_Color", 0.60f);
            ValidateHd2dFeedbackParticleStartAlpha("FastVS_HD2D_CurrentLibrary_DustMotes", 0.06f);
            ValidateHd2dFeedbackParticleStartAlpha("FastVS_HD2D_Stage7_CurrentLibrary_Fireflies", 0.08f);
            ValidateHd2dFeedbackParticleStartAlpha("FastVS_HD2D_CurrentPlaza_DustDrift", 0.06f);
            ValidateHd2dFeedbackParticleStartAlpha("FastVS_HD2D_Stage7_CurrentPlaza_SunMotes", 0.06f);
            ValidateHd2dFeedbackParticleStartAlpha("FastVS_HD2D_PhaseCAlpha_Fire_Spark", 0.56f);
            ValidateHd2dFeedbackParticleStartAlpha("FastVS_HD2D_PhaseCAlpha_Firefly", 0.25f);
            ValidateHd2dFeedbackParticleStartAlpha("FastVS_HD2D_PhaseCAlpha_Smoke", 0.23f);
            ValidateHd2dFeedbackParticleStartAlpha("FastVS_HD2D_PhaseCAlpha_WaterSplash", 0.31f);

            ValidateHd2dFeedbackObjectScale("Current_Library_Stage8n_FloorLoosePageA", new Vector3(0.34f, 0.012f, 0.13f));
            ValidateHd2dFeedbackObjectScale("Current_Library_Stage8n_FloorLoosePageShadowA", new Vector3(0.40f, 0.008f, 0.16f));
            ValidateHd2dFeedbackObjectScale("Current_Library_Stage8n_FloorClosedBookShadowA", new Vector3(0.34f, 0.008f, 0.16f));
            ValidateSceneObjectRemoved("Current_Library_Stage8n_FloorClosedBookA");
            ValidateHd2dFeedbackMaterialNameContains("Current_Library_Stage8n_FloorLoosePageShadowA", "depth_shadow");
            ValidateHd2dFeedbackMaterialNameContains("Current_Library_Stage8n_FloorClosedBookShadowA", "depth_shadow");
            ValidateHd2dFeedbackInactive("Current_Library_Stage8c_WarmFloorPool_LongTableA");
            ValidateHd2dFeedbackInactive("Current_Library_Stage8l_MidFloorShadowBreakA");
            ValidateHd2dFeedbackInactive("Current_Library_RuinFloorDetail_DustMatCenterA");
            ValidateHd2dFeedbackInactive("Current_Library_FloorDecay_ScuffBandCenter");

            var libraryWarmLight = FindSceneObjectIncludingInactive("FastVS_HD2D_PhaseCAlpha_LibraryWarmEmissiveLight")?.GetComponent<Light>();
            var plazaWaterLight = FindSceneObjectIncludingInactive("FastVS_HD2D_PhaseCAlpha_PlazaWaterSparkleLight")?.GetComponent<Light>();
            if (libraryWarmLight == null || libraryWarmLight.intensity > 3.05f || libraryWarmLight.range > 3.25f ||
                plazaWaterLight == null || plazaWaterLight.intensity > 1.25f || plazaWaterLight.range > 2.25f)
            {
                throw new InvalidOperationException("Fast VS feedback lighting polish validation failed: local emissive point lights are above the tuned feedback limits.");
            }

            var warmPoolMaxAlpha = GetHd2dTextureMaxAlpha(EnsureHd2dWarmLightPoolTexture());
            var atmosphereMaxAlpha = GetHd2dTextureMaxAlpha(EnsureHd2dAtmosphereParticleTexture());
            if (warmPoolMaxAlpha > 0.145f || atmosphereMaxAlpha > 0.505f)
            {
                throw new InvalidOperationException(
                    $"Fast VS feedback lighting polish validation failed: generated overlay textures are too opaque. warmPool={warmPoolMaxAlpha:0.000}, atmosphere={atmosphereMaxAlpha:0.000}.");
            }
        }

        private static void WriteHd2dFeedbackLightingPolishDiagnosticsReport(string outputDirectory)
        {
            Directory.CreateDirectory(outputDirectory);

            var lines = BuildHd2dFeedbackLightingPolishDiagnosticsLines();
            var reportPath = Path.Combine(outputDirectory, Hd2dFeedbackLightingPolishDiagnosticsReportFileName);
            File.WriteAllText(reportPath, string.Join(Environment.NewLine, lines) + Environment.NewLine);
            if (!File.Exists(reportPath))
            {
                throw new InvalidOperationException($"Fast VS feedback lighting polish diagnostics report failed: missing output file {reportPath}");
            }

            AssetDatabase.Refresh();
        }

        private static List<string> BuildHd2dFeedbackLightingPolishDiagnosticsLines()
        {
            ValidateHd2dFeedbackLightingPolishSceneState();

            var exteriorAnchor = FindSceneObjectIncludingInactive("FastVS_HD2D_MapSunAnchor_Exterior_Morning")?.GetComponent<MapSunAnchor>();
            var atmosphereMaterial = EnsureHd2dAtmosphereParticleMaterial();
            var libraryWarmLight = FindSceneObjectIncludingInactive("FastVS_HD2D_PhaseCAlpha_LibraryWarmEmissiveLight")?.GetComponent<Light>();
            var plazaWaterLight = FindSceneObjectIncludingInactive("FastVS_HD2D_PhaseCAlpha_PlazaWaterSparkleLight")?.GetComponent<Light>();
            var floorPage = FindSceneObjectIncludingInactive("Current_Library_Stage8n_FloorLoosePageA");
            var floorBook = FindSceneObjectIncludingInactive("Current_Library_Stage8n_FloorClosedBookShadowA");
            var floorPool = FindSceneObjectIncludingInactive("Current_Library_Stage8c_WarmFloorPool_LongTableA");
            var shadowBreak = FindSceneObjectIncludingInactive("Current_Library_Stage8l_MidFloorShadowBreakA");
            var packageManifest = File.Exists("Packages/manifest.json") &&
                File.ReadAllText("Packages/manifest.json").Contains("com.gamelovers.mcp-unity");
            var mcpSettings = File.Exists("ProjectSettings/McpUnitySettings.json");

            return new List<string>
            {
                "# HD2D Feedback Lighting Polish Diagnostics",
                string.Empty,
                $"- Validate entry: `{nameof(ValidateHd2dFeedbackLightingPolishBatch)}`",
                $"- Capture entry: `{nameof(CaptureHd2dFeedbackLightingPolishCycle179ScreenshotsBatch)}`",
                $"- Build exe path: `{BuildExePath}`",
                $"- Launch note: start the whole `Builds/FastVS_HouseSlice` folder, not only a copied exe.",
                $"- Exterior anchor transition smoothing: `{(exteriorAnchor != null && exteriorAnchor.TransitionFromPrevious)}`",
                $"- Atmosphere material _BaseColor alpha: `{(atmosphereMaterial != null && atmosphereMaterial.HasProperty("_BaseColor") ? atmosphereMaterial.GetColor("_BaseColor").a : 0f):0.000}`",
                $"- Atmosphere material texture max alpha: `{GetHd2dTextureMaxAlpha(EnsureHd2dAtmosphereParticleTexture()):0.000}`",
                $"- Warm light pool texture max alpha: `{GetHd2dTextureMaxAlpha(EnsureHd2dWarmLightPoolTexture()):0.000}`",
                $"- Library warm emissive light intensity/range: `{(libraryWarmLight != null ? libraryWarmLight.intensity : 0f):0.000}` / `{(libraryWarmLight != null ? libraryWarmLight.range : 0f):0.000}`",
                $"- Plaza water sparkle light intensity/range: `{(plazaWaterLight != null ? plazaWaterLight.intensity : 0f):0.000}` / `{(plazaWaterLight != null ? plazaWaterLight.range : 0f):0.000}`",
                $"- Library floor loose page scale: `{(floorPage != null ? floorPage.transform.localScale : Vector3.zero)}`",
                $"- Library floor closed book scale: `{(floorBook != null ? floorBook.transform.localScale : Vector3.zero)}`",
                $"- Library broad warm floor pool active: `{(floorPool != null && floorPool.activeSelf)}`",
                $"- Library mid-floor shadow break active: `{(shadowBreak != null && shadowBreak.activeSelf)}`",
                $"- Unity MCP package in manifest: `{packageManifest}`",
                $"- Unity MCP settings file present: `{mcpSettings}`",
                string.Empty,
                "- Tom review evidence only; this report does not claim visual sign-off."
            };
        }

        private static void ValidateHd2dFeedbackMaterialAlpha(Material material, string propertyName, float maxAlpha)
        {
            if (material == null || !material.HasProperty(propertyName) || material.GetColor(propertyName).a > maxAlpha + 0.0001f)
            {
                var alpha = material != null && material.HasProperty(propertyName) ? material.GetColor(propertyName).a : -1f;
                throw new InvalidOperationException($"Fast VS feedback lighting polish validation failed: material {propertyName} alpha is {alpha:0.000}, expected <= {maxAlpha:0.000}.");
            }
        }

        private static void ValidateHd2dFeedbackParticleStartAlpha(string objectName, float maxAlpha)
        {
            var particleObject = FindSceneObjectIncludingInactive(objectName);
            var system = particleObject != null ? particleObject.GetComponent<ParticleSystem>() : null;
            var alpha = system != null ? system.main.startColor.color.a : -1f;
            if (system == null || alpha > maxAlpha + 0.0001f)
            {
                throw new InvalidOperationException($"Fast VS feedback lighting polish validation failed: particle {objectName} alpha is {alpha:0.000}, expected <= {maxAlpha:0.000}.");
            }
        }

        private static void ValidateHd2dFeedbackObjectScale(string objectName, Vector3 maxScale)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            var scale = sceneObject != null ? sceneObject.transform.localScale : Vector3.positiveInfinity;
            if (sceneObject == null ||
                scale.x > maxScale.x + 0.0001f ||
                scale.y > maxScale.y + 0.0001f ||
                scale.z > maxScale.z + 0.0001f)
            {
                throw new InvalidOperationException($"Fast VS feedback lighting polish validation failed: object {objectName} scale is {scale}, expected <= {maxScale}.");
            }
        }

        private static void ValidateHd2dFeedbackMaterialNameContains(string objectName, string requiredToken)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            var renderer = sceneObject != null ? sceneObject.GetComponent<MeshRenderer>() : null;
            var materialName = renderer != null && renderer.sharedMaterial != null ? renderer.sharedMaterial.name : string.Empty;
            if (string.IsNullOrEmpty(materialName) || materialName.IndexOf(requiredToken, StringComparison.OrdinalIgnoreCase) < 0)
            {
                throw new InvalidOperationException($"Fast VS feedback lighting polish validation failed: object {objectName} material {materialName} does not contain token {requiredToken}.");
            }
        }

        private static void ValidateHd2dFeedbackInactive(string objectName)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null || sceneObject.activeSelf)
            {
                throw new InvalidOperationException($"Fast VS feedback lighting polish validation failed: object {objectName} must be kept inactive in review captures.");
            }
        }

        private static float GetHd2dTextureMaxAlpha(Texture2D texture)
        {
            if (texture == null)
            {
                return 0f;
            }

            var pixels = texture.GetPixels32();
            var maxAlpha = 0f;
            for (var i = 0; i < pixels.Length; i++)
            {
                maxAlpha = Mathf.Max(maxAlpha, pixels[i].a / 255f);
            }

            return maxAlpha;
        }

        private static void ValidateHd2dPhaseCBetaArtisticTiltShiftAdoptionReportState()
        {
#if FRONKON_TILTSHIFT
            ValidateHd2dPhaseCBetaArtisticTiltShiftIntegratedState();
#else
            ValidateStage7TiltShiftRendererFeature();
#endif

            var rendererAssetTextInspected = false;
            var rendererFallbackFeatureFound = false;
            var rendererFallbackBlockActive = false;
            BuildHd2dPhaseCBetaArtisticTiltShiftAdoptionDiagnosticsLines(
                out _,
                out _,
                out _,
                out _,
                out rendererAssetTextInspected,
                out rendererFallbackFeatureFound,
                out rendererFallbackBlockActive);

            if (!rendererAssetTextInspected)
            {
                throw new InvalidOperationException("Fast VS HD-2D phase C-beta Artistic tilt-shift adoption validation failed: the URP renderer asset text could not be inspected.");
            }

#if FRONKON_TILTSHIFT
            if (rendererFallbackBlockActive)
            {
                throw new InvalidOperationException("Fast VS HD-2D phase C-beta Artistic tilt-shift adoption validation failed: the self-made Stage 7 tilt-shift fallback is still active while Fronkon is enabled.");
            }
#else
            if (!rendererFallbackFeatureFound || !rendererFallbackBlockActive)
            {
                throw new InvalidOperationException("Fast VS HD-2D phase C-beta Artistic tilt-shift adoption validation failed: the self-made Stage 7 tilt-shift fallback block is not active.");
            }
#endif
        }

#if FRONKON_TILTSHIFT
        private static void ValidateHd2dPhaseCBetaArtisticTiltShiftIntegratedState()
        {
            const string rendererDataPath = "Assets/Settings/UniversalRenderPipeline_Renderer.asset";
            const string profilePath = "Assets/Settings/DefaultVolumeProfile.asset";
            var rendererData = AssetDatabase.LoadAssetAtPath<UniversalRendererData>(rendererDataPath);
            if (rendererData == null)
            {
                throw new InvalidOperationException($"Fast VS HD-2D phase C-beta Artistic tilt-shift validation failed: missing renderer data at {rendererDataPath}.");
            }

            FronkonGames.Artistic.TiltShift.TiltShift artisticFeature = null;
            FullScreenPassRendererFeature fallbackFeature = null;
            for (var i = 0; i < rendererData.rendererFeatures.Count; i++)
            {
                if (rendererData.rendererFeatures[i] is FronkonGames.Artistic.TiltShift.TiltShift tiltShift)
                {
                    artisticFeature = tiltShift;
                }
                else if (rendererData.rendererFeatures[i] is FullScreenPassRendererFeature fullScreenFeature &&
                         string.Equals(fullScreenFeature.name, Stage7TiltShiftFeatureName, StringComparison.Ordinal))
                {
                    fallbackFeature = fullScreenFeature;
                }
            }

            if (artisticFeature == null || !IsScriptableRendererFeatureActive(artisticFeature))
            {
                throw new InvalidOperationException("Fast VS HD-2D phase C-beta Artistic tilt-shift validation failed: Fronkon TiltShift renderer feature is missing or inactive.");
            }

            if (fallbackFeature == null || IsScriptableRendererFeatureActive(fallbackFeature))
            {
                throw new InvalidOperationException("Fast VS HD-2D phase C-beta Artistic tilt-shift validation failed: self-made Stage 7 tilt-shift renderer feature must exist but be inactive.");
            }

            var profile = AssetDatabase.LoadAssetAtPath<VolumeProfile>(profilePath);
            if (profile == null ||
                !profile.TryGet<FronkonGames.Artistic.TiltShift.TiltShiftVolume>(out var tiltShiftVolume) ||
                !tiltShiftVolume.active ||
                !tiltShiftVolume.intensity.overrideState ||
                Mathf.Abs(tiltShiftVolume.intensity.value - 1f) > 0.001f ||
                !tiltShiftVolume.angle.overrideState ||
                Mathf.Abs(tiltShiftVolume.angle.value) > 0.001f ||
                !tiltShiftVolume.aperture.overrideState ||
                Mathf.Abs(tiltShiftVolume.aperture.value - 0.7f) > 0.001f ||
                !tiltShiftVolume.blur.overrideState ||
                Mathf.Abs(tiltShiftVolume.blur.value - 1.2f) > 0.001f ||
                !tiltShiftVolume.blurCurve.overrideState ||
                Mathf.Abs(tiltShiftVolume.blurCurve.value - 3f) > 0.001f ||
                !tiltShiftVolume.quality.overrideState ||
                tiltShiftVolume.quality.value != FronkonGames.Artistic.TiltShift.Quality.High)
            {
                throw new InvalidOperationException("Fast VS HD-2D phase C-beta Artistic tilt-shift validation failed: TiltShiftVolume must be active with horizontal high-quality HD-2D defaults.");
            }
        }
#endif

