                out _);
            var reportPath = Path.Combine(outputDirectory, Hd2dPhaseCBetaArtisticTiltShiftAdoptionDiagnosticsReportFileName);
            File.WriteAllText(reportPath, string.Join(Environment.NewLine, lines) + Environment.NewLine);
            if (!File.Exists(reportPath))
            {
                throw new InvalidOperationException($"Fast VS phase C-beta Artistic tilt-shift adoption diagnostics report failed: missing output file {reportPath}");
            }
        }

        private static List<string> BuildHd2dPhaseCBetaArtisticTiltShiftAdoptionDiagnosticsLines(
            out bool artisticImported,
            out bool volumeCandidateFound,
            out bool manifestInspected,
            out bool packageLockInspected,
            out bool rendererAssetTextInspected,
            out bool rendererFallbackFeatureFound,
            out bool rendererFallbackBlockActive)
        {
            var artisticTokens = new[]
            {
                "Fronkon Games",
                "FronkonGames",
                "Fronkon",
                "Artistic Tilt Shift",
                "Artistic: Tilt Shift",
                "ArtisticTiltShift"
            };
            var rendererArtisticHintTokens = new[]
            {
                "Fronkon Games",
                "FronkonGames",
                "Fronkon",
                "Artistic Tilt Shift",
                "Artistic: Tilt Shift",
                "ArtisticTiltShift"
            };
            var volumeTokens = new[]
            {
                "Volume",
                "VolumeComponent",
                "VolumeParameter",
                "VolumeOverride"
            };

            var assetPathMatches = CollectHd2dPhaseCBetaArtisticTiltShiftAssetPathMatches(artisticTokens);
            var assemblyMatches = CollectHd2dPhaseCBetaArtisticTiltShiftAssemblyMatches(artisticTokens);
            manifestInspected = TryReadHd2dTextFile(Path.Combine("Packages", "manifest.json"), out var manifestText);
            var manifestMatches = manifestInspected
                ? CollectHd2dPhaseCBetaArtisticTiltShiftTextMatches(manifestText, artisticTokens)
                : new List<string>();
            packageLockInspected = TryReadHd2dTextFile(Path.Combine("Packages", "packages-lock.json"), out var packageLockText);
            var packageLockMatches = packageLockInspected
                ? CollectHd2dPhaseCBetaArtisticTiltShiftTextMatches(packageLockText, artisticTokens)
                : new List<string>();
            rendererAssetTextInspected = TryReadHd2dTextFile("Assets/Settings/UniversalRenderPipeline_Renderer.asset", out var rendererAssetText);
            var rendererArtisticHintMatches = rendererAssetTextInspected
                ? CollectHd2dPhaseCBetaArtisticTiltShiftTextMatches(rendererAssetText, rendererArtisticHintTokens)
                : new List<string>();
            var rendererVolumeMatches = rendererAssetTextInspected
                ? CollectHd2dPhaseCBetaArtisticTiltShiftTextMatches(rendererAssetText, volumeTokens)
                : new List<string>();

            artisticImported =
                assetPathMatches.Count > 0 ||
                assemblyMatches.Count > 0 ||
                manifestMatches.Count > 0 ||
                packageLockMatches.Count > 0;

            volumeCandidateFound =
                artisticImported &&
                (ContainsAnyTokenInMatches(assemblyMatches, volumeTokens) ||
                 rendererArtisticHintMatches.Count > 0 && rendererVolumeMatches.Count > 0);

            rendererFallbackFeatureFound = rendererAssetTextInspected && ContainsAnyToken(rendererAssetText, Stage7TiltShiftFeatureName);
            rendererFallbackBlockActive = rendererFallbackFeatureFound && IsHd2dPhaseCBetaArtisticTiltShiftRendererFallbackBlockActive(rendererAssetText);
#if FRONKON_TILTSHIFT
            var artisticRendererFeatureActive = IsHd2dPhaseCBetaArtisticRendererFeatureActive();
            var artisticVolumeOverrideActive = IsHd2dPhaseCBetaArtisticVolumeOverrideConfigured();
#else
            var artisticRendererFeatureActive = false;
            var artisticVolumeOverrideActive = false;
#endif

            return new List<string>
            {
                "# HD2D Phase C Beta Artistic Tilt Shift Adoption Diagnostics",
                string.Empty,
                $"- Validate entry: `{nameof(ValidateHd2dPhaseCBetaArtisticTiltShiftAdoptionBatch)}`",
                $"- Capture entry: `{nameof(CaptureHd2dPhaseCBetaArtisticTiltShiftAdoptionCycle178ScreenshotsBatch)}`",
                $"- Artistic imported: `{artisticImported}`",
                $"- Packages/manifest.json inspected: `{manifestInspected}`",
                $"- Packages/manifest.json matches: `{FormatHd2dPhaseCBetaArtisticTiltShiftMatchSummary(manifestMatches)}`",
                $"- Packages/packages-lock.json inspected: `{packageLockInspected}`",
                $"- Packages/packages-lock.json matches: `{FormatHd2dPhaseCBetaArtisticTiltShiftMatchSummary(packageLockMatches)}`",
                $"- Asset path matches: `{FormatHd2dPhaseCBetaArtisticTiltShiftMatchSummary(assetPathMatches)}`",
                $"- Loaded assembly/type matches: `{FormatHd2dPhaseCBetaArtisticTiltShiftMatchSummary(assemblyMatches)}`",
                $"- Renderer asset text artistic hint matches: `{FormatHd2dPhaseCBetaArtisticTiltShiftMatchSummary(rendererArtisticHintMatches)}`",
                $"- Volume override/type candidates found: `{volumeCandidateFound}`",
                $"- Fronkon renderer feature active: `{artisticRendererFeatureActive}`",
                $"- Fronkon TiltShiftVolume override configured: `{artisticVolumeOverrideActive}`",
                $"- Renderer asset text inspected: `{rendererAssetTextInspected}`",
                $"- Renderer asset contains FastVS HD2D Stage7 TiltShift: `{rendererFallbackFeatureFound}`",
                $"- Renderer asset serialized block active: `{rendererFallbackBlockActive}`",
                $"- Self-made tilt shift fallback active: `{rendererFallbackBlockActive}`",
                $"- When Artistic is absent, the self-made tilt shift fallback stays active: `{!artisticImported && rendererFallbackBlockActive}`",
                $"- When Artistic is enabled, the self-made fallback is inactive: `{artisticRendererFeatureActive && !rendererFallbackBlockActive}`",
                string.Empty,
                "- Tom must decide adoption after import/comparison; this report does not claim visual acceptance."
            };
        }

#if FRONKON_TILTSHIFT
        private static bool IsHd2dPhaseCBetaArtisticRendererFeatureActive()
        {
            var rendererData = AssetDatabase.LoadAssetAtPath<UniversalRendererData>("Assets/Settings/UniversalRenderPipeline_Renderer.asset");
            if (rendererData == null)
            {
                return false;
            }

            for (var i = 0; i < rendererData.rendererFeatures.Count; i++)
            {
                if (rendererData.rendererFeatures[i] is FronkonGames.Artistic.TiltShift.TiltShift feature)
                {
                    return IsScriptableRendererFeatureActive(feature);
                }
            }

            return false;
        }

        private static bool IsHd2dPhaseCBetaArtisticVolumeOverrideConfigured()
        {
            var profile = AssetDatabase.LoadAssetAtPath<VolumeProfile>("Assets/Settings/DefaultVolumeProfile.asset");
            return profile != null &&
                   profile.TryGet<FronkonGames.Artistic.TiltShift.TiltShiftVolume>(out var tiltShiftVolume) &&
                   tiltShiftVolume.active &&
                   tiltShiftVolume.intensity.overrideState &&
                   tiltShiftVolume.intensity.value > 0f;
        }
#endif

        private static List<string> CollectHd2dPhaseCBetaArtisticTiltShiftAssetPathMatches(params string[] tokens)
        {
            var matches = new List<string>();
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var assetPaths = AssetDatabase.GetAllAssetPaths();
            for (var i = 0; i < assetPaths.Length; i++)
            {
                var assetPath = assetPaths[i];
                if (!ContainsAnyToken(assetPath, tokens))
                {
                    continue;
                }

                if (seen.Add(assetPath))
                {
                    matches.Add(assetPath);
                }
            }

            return matches;
        }

        private static List<string> CollectHd2dPhaseCBetaArtisticTiltShiftAssemblyMatches(params string[] tokens)
        {
            var matches = new List<string>();
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var assemblies = AppDomain.CurrentDomain.GetAssemblies();
            for (var i = 0; i < assemblies.Length; i++)
            {
                var assembly = assemblies[i];
                if (assembly == null)
                {
                    continue;
                }

                var assemblyName = assembly.GetName().Name;
                if (!string.IsNullOrEmpty(assemblyName) && ContainsAnyToken(assemblyName, tokens) && seen.Add(assemblyName))
                {
                    matches.Add(assemblyName);
                }

                Type[] types = null;
                try
                {
                    types = assembly.GetTypes();
                }
                catch (ReflectionTypeLoadException reflectionTypeLoadException)
                {
                    types = reflectionTypeLoadException.Types;
                }
                catch
                {
                    continue;
                }

                if (types == null)
                {
                    continue;
                }

                for (var j = 0; j < types.Length; j++)
                {
                    var type = types[j];
                    if (type == null)
                    {
                        continue;
                    }

                    var typeName = type.FullName ?? type.Name ?? string.Empty;
                    if (!ContainsAnyToken(typeName, tokens))
                    {
                        continue;
                    }

                    if (seen.Add(typeName))
                    {
                        matches.Add(typeName);
                    }
                }
            }

            return matches;
        }

        private static List<string> CollectHd2dPhaseCBetaArtisticTiltShiftTextMatches(string sourceText, params string[] tokens)
        {
            var matches = new List<string>();
            if (string.IsNullOrEmpty(sourceText))
            {
                return matches;
            }

            for (var i = 0; i < tokens.Length; i++)
            {
                var token = tokens[i];
                if (!string.IsNullOrEmpty(token) && ContainsAnyToken(sourceText, token) && !ContainsAnyTokenInMatches(matches, token))
                {
                    matches.Add(token);
                }
            }

            return matches;
        }

        private static bool TryReadHd2dTextFile(string relativePath, out string text)
        {
            text = string.Empty;
            var fullPath = Path.GetFullPath(relativePath);
            if (!File.Exists(fullPath))
            {
                return false;
            }

            try
            {
                text = File.ReadAllText(fullPath);
                return true;
            }
            catch
            {
                text = string.Empty;
                return false;
            }
        }

        private static bool IsHd2dPhaseCBetaArtisticTiltShiftRendererFallbackBlockActive(string rendererAssetText)
        {
            if (string.IsNullOrEmpty(rendererAssetText))
            {
                return false;
            }

            var featureMarker = "m_Name: " + Stage7TiltShiftFeatureName;
            var featureIndex = rendererAssetText.IndexOf(featureMarker, StringComparison.Ordinal);
            if (featureIndex < 0)
            {
                return false;
            }

            var blockEndIndex = rendererAssetText.IndexOf("\n--- !u!", featureIndex, StringComparison.Ordinal);
            if (blockEndIndex < 0)
            {
                blockEndIndex = rendererAssetText.Length;
            }

            var blockText = rendererAssetText.Substring(featureIndex, blockEndIndex - featureIndex);
            return ContainsAnyToken(blockText, Stage7TiltShiftFeatureName) &&
                   ContainsAnyToken(blockText, "FullScreenPassRendererFeature") &&
                   ContainsAnyToken(blockText, "m_Active: 1");
        }

        private static string FormatHd2dPhaseCBetaArtisticTiltShiftMatchSummary(IReadOnlyList<string> matches)
        {
            if (matches == null || matches.Count == 0)
            {
                return "<none>";
            }

            var summaryCount = Math.Min(matches.Count, 4);
            var summary = string.Empty;
            for (var i = 0; i < summaryCount; i++)
            {
                if (i > 0)
                {
                    summary += ", ";
                }

                summary += matches[i];
            }

            if (matches.Count > summaryCount)
            {
                summary += $" (+{matches.Count - summaryCount} more)";
            }

            return summary;
        }

        private static bool IsHd2dVisualEffectGraphPackageAvailable()
        {
            var manifestPath = Path.Combine("Packages", "manifest.json");
            if (File.Exists(manifestPath))
            {
                var manifestText = File.ReadAllText(manifestPath);
                if (ContainsAnyToken(manifestText, "com.unity.visualeffectgraph", "visualeffectgraph"))
                {
                    return true;
                }
            }

            var packageLockPath = Path.Combine("Packages", "packages-lock.json");
            if (File.Exists(packageLockPath))
            {
                var packageLockText = File.ReadAllText(packageLockPath);
                if (ContainsAnyToken(packageLockText, "com.unity.visualeffectgraph", "visualeffectgraph"))
                {
                    return true;
                }
            }

            var packageCacheDirectory = Path.Combine("Library", "PackageCache");
            if (Directory.Exists(packageCacheDirectory))
            {
                foreach (var packageDirectory in Directory.GetDirectories(packageCacheDirectory, "com.unity.visualeffectgraph@*"))
                {
                    if (!string.IsNullOrEmpty(packageDirectory))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private static void ValidateHd2dPhaseBBetaButoAdoptionReportState()
        {
#if BUTO
            ValidateHd2dPhaseBBetaButoIntegratedState();
#else
            var fallbackWiringActive = false;
            BuildHd2dPhaseBBetaButoAdoptionDiagnosticsLines(out _, out _, out _, out fallbackWiringActive);

            if (!fallbackWiringActive)
            {
                throw new InvalidOperationException("Fast VS HD-2D phase B-beta Buto adoption validation failed: the B-alpha fallback wiring is broken.");
            }
#endif
        }

#if BUTO
        private static void ValidateHd2dPhaseBBetaButoIntegratedState()
        {
            const string rendererDataPath = "Assets/Settings/UniversalRenderPipeline_Renderer.asset";
            const string profilePath = "Assets/Settings/DefaultVolumeProfile.asset";
            var rendererData = AssetDatabase.LoadAssetAtPath<UniversalRendererData>(rendererDataPath);
            if (rendererData == null)
            {
                throw new InvalidOperationException($"Fast VS HD-2D phase B-beta Buto validation failed: missing renderer data at {rendererDataPath}.");
            }

            OccaSoftware.Buto.Runtime.ButoRenderFeature butoFeature = null;
            for (var i = 0; i < rendererData.rendererFeatures.Count; i++)
            {
                if (rendererData.rendererFeatures[i] is OccaSoftware.Buto.Runtime.ButoRenderFeature feature)
                {
                    butoFeature = feature;
                    break;
                }
            }

            if (butoFeature == null || !IsScriptableRendererFeatureActive(butoFeature))
            {
                throw new InvalidOperationException("Fast VS HD-2D phase B-beta Buto validation failed: ButoRenderFeature is missing or inactive.");
            }

            var profile = AssetDatabase.LoadAssetAtPath<VolumeProfile>(profilePath);
            if (profile == null ||
                !profile.TryGet<OccaSoftware.Buto.Runtime.ButoVolumetricFog>(out var butoFog) ||
                !butoFog.active ||
                !butoFog.mode.overrideState ||
                butoFog.mode.value != OccaSoftware.Buto.Runtime.VolumetricFogMode.On ||
                !butoFog.fogDensity.overrideState ||
                butoFog.fogDensity.value <= 0f ||
                !butoFog.anisotropy.overrideState)
            {
                throw new InvalidOperationException("Fast VS HD-2D phase B-beta Buto validation failed: ButoVolumetricFog override must be active and configured.");
            }

            var directionalSunObject = FindSceneObjectIncludingInactive("Directional Light");
            if (directionalSunObject == null || directionalSunObject.GetComponent<OccaSoftware.Buto.Runtime.ButoLight>() == null)
            {
                throw new InvalidOperationException("Fast VS HD-2D phase B-beta Buto validation failed: Directional Light must have ButoLight for god rays.");
            }

            if (TryGetSerializedBoolAssetValue(UniversalRenderPipelineAssetPath, "m_VolumetricFogEnabled", out var standardVolumetricEnabled) &&
                standardVolumetricEnabled)
            {
                throw new InvalidOperationException("Fast VS HD-2D phase B-beta Buto validation failed: URP standard volumetric fog must be disabled when Buto is enabled.");
            }
        }
#endif

        private static void WriteHd2dPhaseBBetaButoAdoptionDiagnosticsReport(string outputDirectory)
        {
            Directory.CreateDirectory(outputDirectory);

            var fallbackWiringActive = false;
            var lines = BuildHd2dPhaseBBetaButoAdoptionDiagnosticsLines(out _, out _, out _, out fallbackWiringActive);
            var reportPath = Path.Combine(outputDirectory, Hd2dPhaseBBetaButoAdoptionDiagnosticsReportFileName);
            File.WriteAllText(reportPath, string.Join(Environment.NewLine, lines) + Environment.NewLine);
            if (!File.Exists(reportPath))
            {
                throw new InvalidOperationException($"Fast VS phase B-beta Buto adoption diagnostics report failed: missing output file {reportPath}");
            }
        }

        private static List<string> BuildHd2dPhaseBBetaButoAdoptionDiagnosticsLines(
            out bool butoImported,
            out bool rendererCandidateFound,
            out bool volumeCandidateFound,
            out bool fallbackWiringActive)
        {
            var assetPathMatches = CollectHd2dPhaseBBetaButoAssetPathMatches();
            var assemblyMatches = CollectHd2dPhaseBBetaButoAssemblyMatches();
            var rendererAssetTextInspected = TryReadHd2dPhaseBBetaButoRendererAssetText(out var rendererAssetText);
            var rendererAssetTextMatches = CollectHd2dPhaseBBetaButoRendererAssetTextMatches(rendererAssetText);
            var rendererAssetTextHasButoHint = rendererAssetTextInspected && ContainsAnyToken(rendererAssetText, "Buto", "OccaSoftware");

            butoImported = assetPathMatches.Count > 0 || assemblyMatches.Count > 0 || rendererAssetTextHasButoHint;
            rendererCandidateFound =
                ContainsAnyTokenInMatches(assemblyMatches, "RendererFeature", "ScriptableRendererFeature", "FullScreenPassRendererFeature") ||
                (rendererAssetTextHasButoHint && ContainsAnyToken(rendererAssetText, "RendererFeature", "ScriptableRendererFeature", "FullScreenPassRendererFeature"));
            volumeCandidateFound =
                ContainsAnyTokenInMatches(assemblyMatches, "Volume", "VolumeComponent") ||
                (rendererAssetTextHasButoHint && ContainsAnyToken(rendererAssetText, "Volume", "VolumeComponent"));
#if BUTO
            var butoRendererFeatureActive = IsHd2dPhaseBBetaButoRendererFeatureActive();
            var butoVolumeOverrideActive = IsHd2dPhaseBBetaButoVolumeOverrideConfigured();
            var butoLightOnSun = IsHd2dPhaseBBetaButoLightOnDirectionalSun();
            var urpStandardVolumetricDisabled = !TryGetSerializedBoolAssetValue(UniversalRenderPipelineAssetPath, "m_VolumetricFogEnabled", out var standardVolumetricEnabled) ||
                !standardVolumetricEnabled;
            fallbackWiringActive = butoRendererFeatureActive && butoVolumeOverrideActive && butoLightOnSun && urpStandardVolumetricDisabled;
#else
            fallbackWiringActive = true;
#endif

            return new List<string>
            {
                "# HD2D Phase B Beta Buto Adoption Diagnostics",
                string.Empty,
                $"- Validate entry: `{nameof(ValidateHd2dPhaseBBetaButoAdoptionBatch)}`",
                $"- Capture entry: `{nameof(CaptureHd2dPhaseBBetaButoAdoptionCycle176ScreenshotsBatch)}`",
                $"- Buto imported: `{butoImported}`",
                $"- Buto absent in current scan: `{!butoImported}`",
                $"- Asset path matches: `{FormatHd2dPhaseBBetaButoMatchSummary(assetPathMatches)}`",
                $"- Loaded assembly/type matches: `{FormatHd2dPhaseBBetaButoMatchSummary(assemblyMatches)}`",
                $"- URP renderer asset text inspected: `{rendererAssetTextInspected}`",
                $"- Renderer asset text matches: `{FormatHd2dPhaseBBetaButoMatchSummary(rendererAssetTextMatches)}`",
                $"- Renderer feature candidates found: `{rendererCandidateFound}`",
                $"- Volume candidates found: `{volumeCandidateFound}`",
#if BUTO
                $"- Buto renderer feature active: `{butoRendererFeatureActive}`",
                $"- ButoVolumetricFog override configured: `{butoVolumeOverrideActive}`",
                $"- Directional Light has ButoLight: `{butoLightOnSun}`",
                $"- URP standard volumetric disabled: `{urpStandardVolumetricDisabled}`",
#endif
                $"- URP standard/B-alpha fallback remains active: `{fallbackWiringActive}`",
                $"- When Buto is absent, the current URP standard/B-alpha fallback stays active: `{!butoImported && fallbackWiringActive}`",
                string.Empty,
                "- Tom must decide adoption after import/comparison; this report does not claim visual acceptance."
            };
        }

#if BUTO
        private static bool IsHd2dPhaseBBetaButoRendererFeatureActive()
        {
            var rendererData = AssetDatabase.LoadAssetAtPath<UniversalRendererData>("Assets/Settings/UniversalRenderPipeline_Renderer.asset");
            if (rendererData == null)
            {
                return false;
            }

            for (var i = 0; i < rendererData.rendererFeatures.Count; i++)
            {
                if (rendererData.rendererFeatures[i] is OccaSoftware.Buto.Runtime.ButoRenderFeature feature)
                {
                    return IsScriptableRendererFeatureActive(feature);
                }
            }

            return false;
        }

        private static bool IsHd2dPhaseBBetaButoVolumeOverrideConfigured()
        {
            var profile = AssetDatabase.LoadAssetAtPath<VolumeProfile>("Assets/Settings/DefaultVolumeProfile.asset");
            return profile != null &&
                   profile.TryGet<OccaSoftware.Buto.Runtime.ButoVolumetricFog>(out var butoFog) &&
                   butoFog.active &&
                   butoFog.mode.overrideState &&
                   butoFog.mode.value == OccaSoftware.Buto.Runtime.VolumetricFogMode.On &&
                   butoFog.fogDensity.overrideState &&
                   butoFog.fogDensity.value > 0f;
        }

        private static bool IsHd2dPhaseBBetaButoLightOnDirectionalSun()
        {
            var directionalSunObject = FindSceneObjectIncludingInactive("Directional Light");
            return directionalSunObject != null && directionalSunObject.GetComponent<OccaSoftware.Buto.Runtime.ButoLight>() != null;
        }
#endif

        private static List<string> CollectHd2dPhaseBBetaButoAssetPathMatches()
        {
            var matches = new List<string>();
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var assetPaths = AssetDatabase.GetAllAssetPaths();
            for (var i = 0; i < assetPaths.Length; i++)
            {
                var assetPath = assetPaths[i];
                if (!ContainsAnyToken(assetPath, "Buto", "OccaSoftware"))
                {
                    continue;
                }

                if (seen.Add(assetPath))
                {
                    matches.Add(assetPath);
                }
            }

            return matches;
        }

        private static List<string> CollectHd2dPhaseBBetaButoAssemblyMatches()
        {
            var matches = new List<string>();
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var assemblies = AppDomain.CurrentDomain.GetAssemblies();
            for (var i = 0; i < assemblies.Length; i++)
            {
                var assembly = assemblies[i];
                if (assembly == null)
                {
                    continue;
                }

                var assemblyName = assembly.GetName().Name;
                if (!string.IsNullOrEmpty(assemblyName) && ContainsAnyToken(assemblyName, "Buto", "OccaSoftware") && seen.Add(assemblyName))
                {
                    matches.Add(assemblyName);
                }

                Type[] types = null;
                try
                {
                    types = assembly.GetTypes();
                }
                catch (ReflectionTypeLoadException reflectionTypeLoadException)
                {
                    types = reflectionTypeLoadException.Types;
                }
                catch
                {
                    continue;
                }

                if (types == null)
                {
                    continue;
                }

                for (var j = 0; j < types.Length; j++)
                {
                    var type = types[j];
                    if (type == null)
                    {
                        continue;
                    }

                    var typeName = type.FullName ?? type.Name ?? string.Empty;
                    if (!ContainsAnyToken(typeName, "Buto", "OccaSoftware"))
                    {
                        continue;
                    }

                    if (seen.Add(typeName))
                    {
                        matches.Add(typeName);
                    }
                }
            }

            return matches;
        }

        private static bool TryReadHd2dPhaseBBetaButoRendererAssetText(out string rendererAssetText)
        {
            rendererAssetText = string.Empty;
            var rendererAssetPath = "Assets/Settings/UniversalRenderPipeline_Renderer.asset";
            var rendererAssetFullPath = Path.GetFullPath(rendererAssetPath);
            if (!File.Exists(rendererAssetFullPath))
            {
                return false;
            }

            try
            {
                rendererAssetText = File.ReadAllText(rendererAssetFullPath);
                return true;
            }
            catch
            {
                rendererAssetText = string.Empty;
                return false;
            }
        }

        private static List<string> CollectHd2dPhaseBBetaButoRendererAssetTextMatches(string rendererAssetText)
        {
            var matches = new List<string>();
            if (string.IsNullOrEmpty(rendererAssetText))
            {
                return matches;
            }

            var inspectedTokens = new[]
            {
                "Buto",
                "OccaSoftware",
                "RendererFeature",
                "ScriptableRendererFeature",
                "FullScreenPassRendererFeature",
                "Volume",
                "VolumeComponent"
            };

            for (var i = 0; i < inspectedTokens.Length; i++)
            {
                var token = inspectedTokens[i];
                if (ContainsAnyToken(rendererAssetText, token) && !ContainsAnyTokenInMatches(matches, token))
                {
                    matches.Add(token);
                }
            }

            return matches;
        }

        private static bool ContainsAnyToken(string value, params string[] tokens)
        {
            if (string.IsNullOrEmpty(value) || tokens == null)
            {
                return false;
            }

            for (var i = 0; i < tokens.Length; i++)
            {
                var token = tokens[i];
                if (string.IsNullOrEmpty(token))
                {
                    continue;
                }

                if (string.Equals(token, "Buto", StringComparison.OrdinalIgnoreCase))
                {
                    if (ContainsButoPackageToken(value))
                    {
                        return true;
                    }

                    continue;
                }

                if (value.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    return true;
                }
            }

            return false;
        }

        private static bool ContainsButoPackageToken(string value)
        {
            var index = 0;
            while (index < value.Length)
            {
                var matchIndex = value.IndexOf("Buto", index, StringComparison.OrdinalIgnoreCase);
                if (matchIndex < 0)
                {
                    return false;
                }

                var beforeIsIdentifier = matchIndex > 0 && (char.IsLetterOrDigit(value[matchIndex - 1]) || value[matchIndex - 1] == '_');
                var afterIndex = matchIndex + 4;
                var afterIsLowerIdentifier = afterIndex < value.Length && (char.IsLower(value[afterIndex]) || char.IsDigit(value[afterIndex]) || value[afterIndex] == '_');
                if (!beforeIsIdentifier && !afterIsLowerIdentifier)
                {
                    return true;
                }

                index = matchIndex + 4;
            }

            return false;
        }

        private static bool ContainsAnyTokenInMatches(IReadOnlyList<string> values, params string[] tokens)
        {
            if (values == null || tokens == null)
            {
                return false;
            }

            for (var i = 0; i < values.Count; i++)
            {
                if (ContainsAnyToken(values[i], tokens))
                {
                    return true;
                }
            }

            return false;
        }

        private static string FormatHd2dPhaseBBetaButoMatchSummary(IReadOnlyList<string> matches)
        {
            if (matches == null || matches.Count == 0)
            {
                return "<none>";
            }

            var summaryCount = Math.Min(matches.Count, 4);
            var summary = string.Empty;
            for (var i = 0; i < summaryCount; i++)
            {
                if (i > 0)
                {
                    summary += ", ";
                }

                summary += matches[i];
            }

            if (matches.Count > summaryCount)
            {
                summary += $" (+{matches.Count - summaryCount} more)";
            }

            return summary;
        }

        private static bool IsScriptableRendererFeatureActive(ScriptableRendererFeature feature)
        {
            if (feature == null)
            {
                return false;
            }

            var serialized = new SerializedObject(feature);
            var active = serialized.FindProperty("m_Active");
            return active == null || active.propertyType != SerializedPropertyType.Boolean || active.boolValue;
        }

        private static bool TryGetSerializedBoolAssetValue(string assetPath, string propertyName, out bool value)
        {
            value = false;
            var asset = AssetDatabase.LoadAssetAtPath<UnityEngine.Object>(assetPath);
            if (asset == null)
            {
                return false;
            }

            var serialized = new SerializedObject(asset);
            var property = serialized.FindProperty(propertyName);
            if (property == null || property.propertyType != SerializedPropertyType.Boolean)
            {
                return false;
            }

            value = property.boolValue;
            return true;
        }

        private static bool GetSerializedBoolAssetValue(string assetPath, string propertyName)
        {
            var asset = AssetDatabase.LoadAssetAtPath<UnityEngine.Object>(assetPath);
            if (asset == null)
            {
                throw new InvalidOperationException($"Fast VS HD-2D phase B-alpha diagnostics failed: missing asset at {assetPath}.");
            }

            var serialized = new SerializedObject(asset);
            var property = serialized.FindProperty(propertyName);
            if (property == null || property.propertyType != SerializedPropertyType.Boolean)
            {
                throw new InvalidOperationException($"Fast VS HD-2D phase B-alpha diagnostics failed: asset at {assetPath} is missing serialized bool property {propertyName}.");
            }

            return property.boolValue;
        }

        private static void ValidateStage5LutColorLookup(ColorLookup colorLookup, string context)
        {
            ValidateStage5LutTexture(Stage5LutDaylightPlazaTexturePath, $"{context} daylight plaza LUT");
            ValidateStage5LutTexture(Stage5LutIndoorWarmTexturePath, $"{context} indoor warm LUT");
            ValidateStage5LutTexture(Stage5LutTimeWindowPastTexturePath, $"{context} TimeWindow past LUT");

            if (colorLookup == null ||
                !colorLookup.active ||
                !colorLookup.texture.overrideState ||
                !colorLookup.contribution.overrideState)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} ColorLookup must be active with texture and contribution overrides.");
            }

            var texture = colorLookup.texture.value as Texture2D;
            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} ColorLookup must reference a Texture2D LUT.");
            }

            var texturePath = AssetDatabase.GetAssetPath(texture);
            if (!string.Equals(texturePath, Stage5LutDaylightPlazaTexturePath, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {context} ColorLookup must use {Stage5LutDaylightPlazaTexturePath}, but used {texturePath}.");
            }

            if (Mathf.Abs(colorLookup.contribution.value - Stage5LutContribution) > 0.001f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} ColorLookup contribution must stay at {Stage5LutContribution:0.00}, but was {colorLookup.contribution.value:0.000}.");
            }
        }

        private static void ValidateStage5LutTexture(string path, string context)
        {
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing {context} asset at {path}.");
            }

            if (texture.width != 1024 || texture.height != 32)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} must be a 1024x32 32^3 LUT, but was {texture.width}x{texture.height}.");
            }

            if (texture.filterMode != FilterMode.Bilinear || texture.wrapMode != TextureWrapMode.Clamp)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} must use bilinear filtering and clamp wrapping.");
            }

            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} must have TextureImporter settings.");
            }

            if (importer.mipmapEnabled || importer.sRGBTexture || importer.textureCompression != TextureImporterCompression.Uncompressed)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} import settings must disable mipmaps, disable sRGB, and use uncompressed texture data.");
            }
        }

        private static void ValidateHd2dStage2EmissiveShaderProfile()
        {
            ValidateStage2ShaderEmissionProperties(Shader.Find(SurfaceRampLitShaderName), SurfaceRampLitShaderName);
            ValidateStage2ShaderEmissionProperties(Shader.Find(SpriteCardRampShaderName), SpriteCardRampShaderName);
            ValidateStage2EmissionMaterial(
                Stage2WindowLightMaterialId,
                Stage2WindowLightEmissionColor,
                Stage2WindowLightEmissionIntensity);
            ValidateStage2EmissionMaterial(
                Stage2LibraryWindowLightMaterialId,
                Stage2LibraryWindowLightEmissionColor,
                Stage2LibraryWindowLightEmissionIntensity);
        }

        private static void ValidateHd2dStage3LightingCookie()
        {
            var controller = UnityEngine.Object.FindFirstObjectByType<TimeWindowPairedSpacePortalController>();
            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            var guide = UnityEngine.Object.FindFirstObjectByType<FastVsVisualDirectionGuide>();
            var director = UnityEngine.Object.FindFirstObjectByType<FastVsHouseLightingDirector>();
            var realtimeRig = UnityEngine.Object.FindFirstObjectByType<FastVsRealtimeLightShadowRig>();
            var mainLight = FindSceneObjectIncludingInactive("Directional Light")?.GetComponent<Light>();
            var warmFill = FindSceneObjectIncludingInactive("FastVS_HD2D_WarmFillLight")?.GetComponent<Light>();
            var coolRim = FindSceneObjectIncludingInactive("FastVS_HD2D_CoolRimLight")?.GetComponent<Light>();
            var libraryWindow = FindSceneObjectIncludingInactive("FastVS_HD2D_LibraryWindowLight")?.GetComponent<Light>();
            if (controller == null || visibility == null || guide == null || director == null || realtimeRig == null ||
                mainLight == null || warmFill == null || coolRim == null || libraryWindow == null)
            {
                throw new InvalidOperationException("House slice validation failed: Stage 3 lighting/cookie validation needs controller, visibility, guide, director, realtime rig, and all four lights.");
            }

            ValidateStage3AreaLightingProfile("FastVS_HD2D_HouseInteriorLightingProfile", FastVsHouseArea.Interior, 1.20f, 0.60f);
            ValidateStage3AreaLightingProfile("FastVS_HD2D_HouseExteriorLightingProfile", FastVsHouseArea.Exterior, 1.80f, 0.40f);
            ValidateStage3AreaLightingProfile("FastVS_HD2D_CentralPlazaLightingProfile", FastVsHouseArea.CentralPlaza, 1.72f, 0.30f);
            ValidateStage3AreaLightingProfile("FastVS_HD2D_LibraryLightingProfile", FastVsHouseArea.Library, 1.70f, 0.50f);

            var mainLightManagedBySunCycle = IsMainDirectionalLightManagedBySunCycleForReview();

            void Apply(FastVsHouseArea area, Vector3 playerLocal)
            {
                visibility.SetActiveAreaForReview(area);
                controller.ForcePlayerCurrentLocalForReview(playerLocal);
                guide.ApplyActiveTimeIsolationForReview();
                director.ApplyAreaForReview(area);
                realtimeRig.ApplyNowForReview();
            }

            Apply(FastVsHouseArea.Interior, HouseInteriorCenter);
            if (!mainLightManagedBySunCycle)
            {
                ValidateStage3LightValue(mainLight.intensity, 1.20f, 0.03f, "Stage 3 interior main light");
            }
            ValidateStage3LightValue(warmFill.intensity, 0.60f, 0.01f, "Stage 3 interior warm fill");
            ValidateStage3LightValue(coolRim.intensity, 0.15f, 0.01f, "Stage 3 interior cool rim");
            if (libraryWindow.enabled || libraryWindow.cookie != null)
            {
                throw new InvalidOperationException("House slice validation failed: Stage 3 interior must keep library window light and cookie disabled.");
            }

            Apply(FastVsHouseArea.Exterior, HouseExteriorCenter);
            if (!mainLightManagedBySunCycle)
            {
                ValidateStage3LightValue(mainLight.intensity, 2.05f, 0.03f, "Stage 3 exterior public-legibility realtime main light");
            }
            ValidateStage3LightValue(warmFill.intensity, 0.40f, 0.01f, "Stage 3 exterior warm fill");
            ValidateStage3LightValue(coolRim.intensity, 0.16f, 0.01f, "Stage 3 exterior cool rim");
            if (!mainLightManagedBySunCycle &&
                (mainLight.cookie == null ||
                mainLight.cookie.name != Stage3ExteriorSunCookieName ||
                mainLight.cookie.width != 128 ||
                mainLight.cookie.height != 128 ||
                mainLight.cookie.filterMode != FilterMode.Bilinear ||
                mainLight.cookie.wrapMode != TextureWrapMode.Clamp ||
                mainLight.cookieSize < 11.8f ||
                mainLight.cookieSize > 12.2f))
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 3 exterior must use procedural sun cookie {Stage3ExteriorSunCookieName}, found cookie={mainLight.cookie}, size={mainLight.cookieSize:0.00}.");
            }

            Apply(FastVsHouseArea.CentralPlaza, CentralPlazaVsCenter);
            if (!mainLightManagedBySunCycle)
            {
                ValidateStage3LightValue(mainLight.intensity, 2.32f, 0.03f, "Stage 3 central plaza realtime main light");
            }
            ValidateStage3LightValue(warmFill.intensity, 0.30f, 0.01f, "Stage 3 central plaza warm fill");
            ValidateStage3LightValue(coolRim.intensity, 0.16f, 0.01f, "Stage 3 central plaza cool rim");
            if (!mainLightManagedBySunCycle &&
                (mainLight.cookie == null || mainLight.cookie.name != "FastVS_CentralPlazaRealtimeSunCookieCycle147"))
            {
                throw new InvalidOperationException("House slice validation failed: Stage 3 central plaza must preserve the existing realtime sun cookie.");
            }

            Apply(FastVsHouseArea.Library, LibraryVsCenter);
            if (!mainLightManagedBySunCycle)
            {
                ValidateStage3LightValue(mainLight.intensity, 1.95f, 0.03f, "Stage 3 library public-legibility realtime main light");
            }
            ValidateStage3LightValue(warmFill.intensity, 0.50f, 0.01f, "Stage 3 library warm fill");
            ValidateStage3LightValue(coolRim.intensity, 0.16f, 0.01f, "Stage 3 library cool rim");
            ValidateStage3LightValue(libraryWindow.intensity, 1.50f, 0.01f, "Stage 3 library window light");
            if (!libraryWindow.enabled ||
                libraryWindow.cookie == null ||
                libraryWindow.cookie.name != Stage3LibraryWindowCookieName ||
                libraryWindow.cookie.width != 128 ||
                libraryWindow.cookie.height != 128 ||
                libraryWindow.cookie.filterMode != FilterMode.Bilinear ||
                libraryWindow.cookie.wrapMode != TextureWrapMode.Clamp)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 3 library window must use procedural cookie {Stage3LibraryWindowCookieName}, found enabled={libraryWindow.enabled}, cookie={libraryWindow.cookie}.");
            }

            if (!mainLightManagedBySunCycle &&
                mainLight.cookie != null &&
                mainLight.cookie.name == Stage3ExteriorSunCookieName)
            {
                throw new InvalidOperationException("House slice validation failed: Stage 3 library main light must not reuse the exterior sun cookie.");
            }

            ValidateStage3SurfaceRampShaderText();
        }

        private static void ValidateHd2dStage4PaintedOverlay()
        {
            if (TryValidateHd2dPhaseAPaintedOverlayRemovalSource())
            {
                return;
            }

            var controller = UnityEngine.Object.FindFirstObjectByType<TimeWindowPairedSpacePortalController>();
            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            var guide = UnityEngine.Object.FindFirstObjectByType<FastVsVisualDirectionGuide>();
            var realtimeRig = UnityEngine.Object.FindFirstObjectByType<FastVsRealtimeLightShadowRig>();
            var camera = Camera.main;
            if (controller == null || visibility == null || guide == null || realtimeRig == null || camera == null)
            {
                throw new InvalidOperationException("House slice validation failed: Stage 4 painted overlay validation needs controller, visibility, guide, realtime rig, and main camera.");
            }

            void Apply(FastVsHouseArea area, Vector3 playerLocal)
            {
                visibility.SetActiveAreaForReview(area);
                controller.ForcePlayerCurrentLocalForReview(playerLocal);
                guide.ApplyActiveTimeIsolationForReview();
                realtimeRig.ApplyNowForReview();
            }

            Apply(FastVsHouseArea.Exterior, HouseExteriorCenter);
            ValidateStage4OverlayActive(camera, FastVsHouseArea.Exterior);

            Apply(FastVsHouseArea.CentralPlaza, CentralPlazaVsCenter);
            ValidateStage4OverlayActive(camera, FastVsHouseArea.CentralPlaza);

            Apply(FastVsHouseArea.Library, LibraryVsCenter);
            ValidateStage4OverlayActive(camera, FastVsHouseArea.Library);

            Apply(FastVsHouseArea.Interior, HouseInteriorCenter);
            ValidateStage4OverlayInactive();
            ValidateStage4RuntimeSourceText();
        }

        private static void ValidateHd2dStage6PaintedGodRays()
        {
            if (TryValidateHd2dPhaseAPaintedOverlayRemovalSource())
            {
                return;
            }

            ValidateHd2dStage4PaintedOverlay();
            ValidateStage6PaintedGodRaysRuntimeSourceText();
        }

        private static void ValidateStage4OverlayActive(Camera camera, FastVsHouseArea area)
        {
            var root = FindSceneObjectIncludingInactive(Stage4OverlayRootName);
            if (root == null)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 4 {area} painted overlay root is missing.");
            }

            if (!root.activeSelf || !root.activeInHierarchy)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 4 {area} painted overlay root must be active for outdoor/runtime areas.");
            }

            if (root.transform.parent != camera.transform)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 4 {area} painted overlay root must be parented to the main camera.");
            }

            ValidateStage4OverlayRenderer(Stage4GradePlateName, 5000, "FastVS_Cycle128GradeTexture", 512, 288, 0.46f, area);
            ValidateStage4OverlayRenderer(Stage4RayPlateName, 5010, "FastVS_Cycle128RayTexture", 256, 144, 0.455f, area);
            ValidateStage4OverlayRenderer(Stage4ShadowPaintPlateName, 5020, "FastVS_Cycle131ShadowPaintTexture", 320, 180, 0.450f, area);
            ValidateStage4OverlayRenderer(Stage4SunPaintPlateName, 5030, "FastVS_Cycle131SunPaintTexture", 320, 180, 0.445f, area);
        }

        private static void ValidateStage4OverlayInactive()
        {
            var root = FindSceneObjectIncludingInactive(Stage4OverlayRootName);
            if (root != null && root.activeSelf)
            {
                throw new InvalidOperationException("House slice validation failed: Stage 4 painted overlay must remain inactive in Interior.");
            }
        }

        private static void ValidateStage4OverlayRenderer(
            string objectName,
            int expectedRenderQueue,
            string expectedTextureName,
            int expectedTextureWidth,
            int expectedTextureHeight,
            float expectedLocalZ,
            FastVsHouseArea area)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            var renderer = sceneObject != null ? sceneObject.GetComponent<MeshRenderer>() : null;
            if (renderer == null)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 4 {area} painted overlay renderer {objectName} is missing.");
            }

            if (!renderer.enabled || !renderer.gameObject.activeInHierarchy)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 4 {area} painted overlay renderer {objectName} must be enabled and visible.");
            }

            if (renderer.transform.parent == null || renderer.transform.parent.name != Stage4OverlayRootName)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 4 {area} painted overlay renderer {objectName} must be parented to {Stage4OverlayRootName}.");
            }

            if (renderer.shadowCastingMode != ShadowCastingMode.Off || renderer.receiveShadows)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 4 {area} painted overlay renderer {objectName} must not cast or receive shadows.");
            }

            if (Mathf.Abs(renderer.transform.localPosition.z - expectedLocalZ) > 0.01f ||
                renderer.transform.localScale.x < 0.10f ||
                renderer.transform.localScale.y < 0.10f)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 4 {area} painted overlay renderer {objectName} has invalid camera-plane placement or scale.");
            }

            var material = renderer.sharedMaterial;
            if (material == null || material.renderQueue != expectedRenderQueue)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 4 {area} painted overlay renderer {objectName} must use render queue {expectedRenderQueue}.");
            }

            var texture = ResolveMaterialTexture(material);
            if (texture == null ||
                texture.name != expectedTextureName ||
                texture.width != expectedTextureWidth ||
                texture.height != expectedTextureHeight ||
                texture.filterMode != FilterMode.Bilinear ||
                texture.wrapMode != TextureWrapMode.Clamp)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 4 {area} painted overlay renderer {objectName} must use {expectedTextureName} ({expectedTextureWidth}x{expectedTextureHeight}) with bilinear/clamp sampling.");
            }
        }

        private static void ValidateStage4RuntimeSourceText()
        {
            const string sourcePath = "Assets/Scripts/FastVS/FastVsRealtimeLightShadowRig.cs";
            var sourceText = File.ReadAllText(sourcePath);
            if (!sourceText.Contains("ApplyCycle131CameraPaintOverlay(isRealtimeOutdoor)", StringComparison.Ordinal) ||
                !sourceText.Contains("SetCycle128CameraGradeActive(active)", StringComparison.Ordinal) ||
                !sourceText.Contains("Mathf.Min(alpha, 0.10f)", StringComparison.Ordinal) ||
                !sourceText.Contains("Mathf.Min(alpha, 0.11f)", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("House slice validation failed: Stage 4 runtime rig must keep outdoor-only painted overlay activation and public-review legibility alpha clamps.");
            }
        }

        private static void ValidateStage6PaintedGodRaysRuntimeSourceText()
        {
            const string sourcePath = "Assets/Scripts/FastVS/FastVsRealtimeLightShadowRig.cs";
            var sourceText = File.ReadAllText(sourcePath);
            if (!sourceText.Contains("ShapeCycle128BeamAlpha(beam, u, v)", StringComparison.Ordinal) ||
                !sourceText.Contains("ShapeCycle131SunPaintAlpha(alpha, u, v)", StringComparison.Ordinal) ||
                !sourceText.Contains("Mathf.Min(alpha, 0.24f)", StringComparison.Ordinal) ||
                !sourceText.Contains("ApplyCycle131CameraPaintOverlay(isRealtimeOutdoor)", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("House slice validation failed: Stage 6 painted god rays must strengthen the existing outdoor-only painted overlay without changing the runtime camera gate.");
            }
        }

        private static void ValidateHd2dStage7BokehFocus()
        {
            var controller = UnityEngine.Object.FindFirstObjectByType<TimeWindowPairedSpacePortalController>();
            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            var guide = UnityEngine.Object.FindFirstObjectByType<FastVsVisualDirectionGuide>();
            var realtimeRig = UnityEngine.Object.FindFirstObjectByType<FastVsRealtimeLightShadowRig>();
            var camera = Camera.main;
            var focusController = camera != null ? camera.GetComponent<FastVsHd2dDepthOfFieldFocusController>() : null;
            var volumeObject = FindSceneObjectIncludingInactive("FastVS_HD2D_GlobalVolume");
            var volume = volumeObject != null ? volumeObject.GetComponent<Volume>() : null;
            if (controller == null || visibility == null || guide == null || realtimeRig == null ||
                camera == null || focusController == null || volume == null || volume.sharedProfile == null)
            {
                throw new InvalidOperationException("House slice validation failed: Stage 7 Bokeh focus validation needs controller, visibility, guide, realtime rig, camera focus controller, and global volume.");
            }

            if (!volume.sharedProfile.TryGet<DepthOfField>(out var sharedDepthOfField))
            {
                throw new InvalidOperationException("House slice validation failed: Stage 7 global volume must include DepthOfField.");
            }

            ValidateStage7BokehDofProfile(sharedDepthOfField, "Stage 7 shared profile");
            ValidateStage7TiltShiftRendererFeature();

            visibility.SetActiveAreaForReview(FastVsHouseArea.CentralPlaza);
            var playerLocal = CentralPlazaVsCenter + new Vector3(-0.35f, 0.02f, 3.20f);
            controller.ForcePlayerCurrentLocalForReview(playerLocal);
            guide.ApplyActiveTimeIsolationForReview();
            realtimeRig.ApplyNowForReview();
            PositionReviewCamera(camera, controller.CurrentSpaceRootForReview.TransformPoint(playerLocal));
            focusController.ApplyNowForReview();

            if (focusController.FocusTargetForReview == null ||
                focusController.VolumeForReview == null ||
                Mathf.Abs(focusController.ApertureForReview - 2.4f) > 0.05f ||
                Mathf.Abs(focusController.FocalLengthForReview - 85f) > 1.0f)
            {
                throw new InvalidOperationException("House slice validation failed: Stage 7 Bokeh focus controller must target Niro and apply the expected aperture/focal length.");
            }

            var targetWorld = focusController.FocusTargetForReview.position + new Vector3(0f, 0.72f, 0f);
            var expectedFocusDistance = Mathf.Clamp(
                Vector3.Distance(camera.transform.position, targetWorld),
                2.5f,
                12.0f);
            if (Mathf.Abs(focusController.FocusDistanceForReview - expectedFocusDistance) > 0.20f)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 7 focus distance must track the player, expected {expectedFocusDistance:0.000}, found {focusController.FocusDistanceForReview:0.000}.");
            }
        }

        private static void ValidateStage7BokehDofProfile(DepthOfField depthOfField, string context)
        {
            if (depthOfField == null ||
                !depthOfField.active ||
                !depthOfField.mode.overrideState ||
                depthOfField.mode.value != DepthOfFieldMode.Bokeh ||
                !depthOfField.focusDistance.overrideState ||
                depthOfField.focusDistance.value < 4.8f ||
                depthOfField.focusDistance.value > 6.0f ||
                !depthOfField.aperture.overrideState ||
                Mathf.Abs(depthOfField.aperture.value - 2.4f) > 0.12f ||
                !depthOfField.focalLength.overrideState ||
                Mathf.Abs(depthOfField.focalLength.value - 85f) > 2.0f ||
                !depthOfField.bladeCount.overrideState ||
                depthOfField.bladeCount.value != 6 ||
                !depthOfField.bladeCurvature.overrideState ||
                Mathf.Abs(depthOfField.bladeCurvature.value - 0.85f) > 0.05f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} must use Stage 7 Bokeh DoF focusDistance 5.4, aperture 2.4, focalLength 85, bladeCount 6, bladeCurvature 0.85.");
            }
        }

        private static void ValidateStage7TiltShiftRendererFeature()
        {
            const string rendererDataPath = "Assets/Settings/UniversalRenderPipeline_Renderer.asset";
            var rendererData = AssetDatabase.LoadAssetAtPath<UniversalRendererData>(rendererDataPath);
            if (rendererData == null)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 7 renderer data is missing: {rendererDataPath}");
            }

            FullScreenPassRendererFeature tiltShiftFeature = null;
            for (var i = 0; i < rendererData.rendererFeatures.Count; i++)
            {
                if (rendererData.rendererFeatures[i] is FullScreenPassRendererFeature fullScreenFeature &&
                    string.Equals(fullScreenFeature.name, Stage7TiltShiftFeatureName, StringComparison.Ordinal))
                {
                    tiltShiftFeature = fullScreenFeature;
                    break;
                }
            }

            var material = AssetDatabase.LoadAssetAtPath<Material>(Stage7TiltShiftMaterialPath);
            var shader = Shader.Find(Stage7TiltShiftShaderName);
            if (tiltShiftFeature == null ||
                material == null ||
                shader == null ||
                tiltShiftFeature.passMaterial != material ||
                material.shader != shader ||
                tiltShiftFeature.injectionPoint != FullScreenPassRendererFeature.InjectionPoint.AfterRenderingPostProcessing ||
                !tiltShiftFeature.fetchColorBuffer ||
                tiltShiftFeature.passIndex != 0 ||
                Mathf.Abs(material.GetFloat("_Intensity") - 0.68f) > 0.02f ||
                Mathf.Abs(material.GetFloat("_Radius") - 2.25f) > 0.05f ||
                Mathf.Abs(material.GetFloat("_SharpWidth") - 0.18f) > 0.02f)
            {
                throw new InvalidOperationException("House slice validation failed: Stage 7 tilt-shift FullScreenPassRendererFeature/material must be active after post processing with the expected screen-space blur settings.");
            }
        }

