        private static void ValidateHd2dStage7PublicReviewCameraClarity()
        {
            var controller = UnityEngine.Object.FindFirstObjectByType<TimeWindowPairedSpacePortalController>();
            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            var guide = UnityEngine.Object.FindFirstObjectByType<FastVsVisualDirectionGuide>();
            var director = UnityEngine.Object.FindFirstObjectByType<FastVsHouseLightingDirector>();
            var realtimeRig = UnityEngine.Object.FindFirstObjectByType<FastVsRealtimeLightShadowRig>();
            var camera = Camera.main;
            if (controller == null || visibility == null || guide == null || director == null || realtimeRig == null || camera == null)
            {
                throw new InvalidOperationException("House slice validation failed: Stage 7 public review camera clarity needs controller, visibility, guide, director, realtime rig, and main camera.");
            }

            visibility.SetActiveAreaForReview(FastVsHouseArea.Exterior);
            controller.ForcePlayerCurrentLocalForReview(HouseExteriorCenter);
            guide.ApplyActiveTimeIsolationForReview();
            director.ApplyAreaForReview(FastVsHouseArea.Exterior);
            realtimeRig.ApplyNowForReview();
            camera.fieldOfView = 30f;
            PositionCloseReviewCamera(
                camera,
                controller.CurrentSpaceRootForReview.TransformPoint(HouseExteriorCenter),
                new Vector3(1.25f, 1.85f, -8.05f),
                new Vector3(0.10f, 0.72f, 0.38f));

            var localPosition = controller.CurrentSpaceRootForReview.InverseTransformPoint(camera.transform.position) - HouseExteriorCenter;
            if (Mathf.Abs(localPosition.z + 8.05f) > 0.05f ||
                Mathf.Abs(localPosition.y - 1.85f) > 0.05f ||
                Mathf.Abs(camera.fieldOfView - 30f) > 0.01f)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 7 public review exterior camera was not set to the low pulled-back clarity frame. offset={localPosition}, fov={camera.fieldOfView:0.00}");
            }

            ValidateStage7PublicReviewCameraClaritySourceText();
        }

        private static void ValidateStage7PublicReviewAreaLight(string label, Light mainLight, float shadowMin, float shadowMax, float ambientMin, float ambientMax)
        {
            var mainLightManagedBySunCycle = IsMainDirectionalLightManagedBySunCycleForReview();
            if (mainLight.type != LightType.Directional ||
                mainLight.shadows != LightShadows.Soft ||
                (!mainLightManagedBySunCycle &&
                 (mainLight.shadowStrength < shadowMin || mainLight.shadowStrength > shadowMax)))
            {
                throw new InvalidOperationException($"House slice validation failed: {label} needs readable soft-shadow strength {shadowMin:0.00}..{shadowMax:0.00}, found type={mainLight.type}, shadows={mainLight.shadows}, strength={mainLight.shadowStrength:0.000}.");
            }

            if (mainLightManagedBySunCycle)
            {
                return;
            }

            if (RenderSettings.ambientMode != AmbientMode.Flat)
            {
                throw new InvalidOperationException($"House slice validation failed: {label} must use flat review ambient lighting.");
            }

            var ambient = RenderSettings.ambientLight;
            var ambientAverage = (ambient.r + ambient.g + ambient.b) / 3f;
            if (ambientAverage < ambientMin || ambientAverage > ambientMax)
            {
                throw new InvalidOperationException($"House slice validation failed: {label} needs review ambient average {ambientMin:0.000}..{ambientMax:0.000}, found {ambient}.");
            }
        }

        private static void ValidateStage7PublicReviewCentralReceivers()
        {
            var receiverCount = 0;
            var block = new MaterialPropertyBlock();
            foreach (var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None))
            {
                if (renderer == null ||
                    !renderer.gameObject.scene.IsValid() ||
                    !renderer.enabled ||
                    !renderer.receiveShadows ||
                    !renderer.gameObject.name.Contains("Current_CentralPlaza", StringComparison.Ordinal))
                {
                    continue;
                }

                if (IsStage7PlazaSoftBalanceReceiver(renderer, block))
                {
                    receiverCount++;
                }
            }

            if (receiverCount < 12)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 7 public review shadow legibility expected at least 12 lifted central-plaza receiver property blocks, found {receiverCount}.");
            }
        }

        private static void ValidateStage7PublicReviewAreaReceivers(FastVsHouseArea area, int minReceiverCount)
        {
            var receiverCount = 0;
            var block = new MaterialPropertyBlock();
            foreach (var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None))
            {
                if (renderer == null ||
                    !renderer.gameObject.scene.IsValid() ||
                    !renderer.enabled ||
                    !renderer.receiveShadows ||
                    !IsCycle161RendererInArea(renderer, area))
                {
                    continue;
                }

                var material = renderer.sharedMaterial;
                if (material == null ||
                    !material.HasProperty("_DirectionalLightStrength") ||
                    !material.HasProperty("_ShadowReceiveStrength") ||
                    !material.HasProperty("_ShadowTextureStrength"))
                {
                    continue;
                }

                renderer.GetPropertyBlock(block);
                if (block.GetFloat("_DirectionalLightStrength") >= 0.90f &&
                    block.GetFloat("_ShadowReceiveStrength") > 0f &&
                    block.GetFloat("_ShadowReceiveStrength") <= 0.32f &&
                    block.GetFloat("_ShadowTextureStrength") <= 0.13f)
                {
                    receiverCount++;
                }
            }

            if (receiverCount < minReceiverCount)
            {
                throw new InvalidOperationException($"House slice validation failed: Stage 7 public legibility expected lifted realtime receiver property blocks in {area}, found {receiverCount}.");
            }
        }

        private static void ValidateStage7PublicReviewShadowLegibilitySourceText()
        {
            var sourcePath = Path.Combine(Application.dataPath, "Scripts", "FastVS", "FastVsRealtimeLightShadowRig.cs");
            var source = File.ReadAllText(sourcePath);
            if (IsMainDirectionalLightManagedBySunCycleForReview())
            {
                ValidateHd2dPhaseAPaintedOverlayRemovalSource();
                if (!source.Contains("private const float CentralPlazaStage7jShadowReceiveStrength = 0.44f;", StringComparison.Ordinal) ||
                    !source.Contains("private const float RealtimeOutdoorShadowReceiveStrength = 0.30f;", StringComparison.Ordinal) ||
                    !source.Contains("ApplyRealtimeSurfaceGrade(renderer, activeArea);", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException("House slice validation failed: Stage 7 public review shadow legibility Phase A source guards are missing.");
                }
            }
            else if (!source.Contains("ResolveReviewShadowStrength(area)", StringComparison.Ordinal) ||
                     !source.Contains("private const float ExteriorReviewShadowStrength = 0.42f;", StringComparison.Ordinal) ||
                     !source.Contains("private const float LibraryReviewShadowStrength = 0.30f;", StringComparison.Ordinal) ||
                     !source.Contains("private const float CentralPlazaStage7jShadowStrength = 0.52f;", StringComparison.Ordinal) ||
                     !source.Contains("private const float CentralPlazaStage7jShadowReceiveStrength = 0.44f;", StringComparison.Ordinal) ||
                     !source.Contains("private const float RealtimeOutdoorShadowReceiveStrength = 0.30f;", StringComparison.Ordinal) ||
                     !source.Contains("Mathf.Min(alpha, 0.10f)", StringComparison.Ordinal) ||
                     !source.Contains("Mathf.Min(alpha, 0.11f)", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("House slice validation failed: Stage 7 public review shadow legibility source guards are missing.");
            }

            if (source.Contains("isRealtimeOutdoor ? 0.94f", StringComparison.Ordinal) ||
                source.Contains("new Color(0.010f, 0.012f, 0.010f", StringComparison.Ordinal) ||
                source.Contains("new Color(0.012f, 0.014f, 0.012f", StringComparison.Ordinal))
            {
                throw new InvalidOperationException("House slice validation failed: Stage 7 public review shadow legibility must not restore the previous black review overlay or 0.94 outdoor shadow strength.");
            }
        }

