        private static void ValidateFastVsHd2dThirtyFirstCycleCentralPlazaFloorFountainDetails()
        {
            var currentFloorDetails = new[]
            {
                "Current_CentralPlaza_FloorJointNorthBand",
                "Current_CentralPlaza_FloorJointSouthBand",
                "Current_CentralPlaza_FloorJointWestBand",
                "Current_CentralPlaza_FloorJointEastBand",
                "Current_CentralPlaza_FloorJointCenterSeam",
                "Current_CentralPlaza_FloorJointFountainApproachSeam"
            };

            var pastFloorDetails = new[]
            {
                "Past_CentralPlaza_FloorJointNorthBand",
                "Past_CentralPlaza_FloorJointSouthBand",
                "Past_CentralPlaza_FloorJointWestBand",
                "Past_CentralPlaza_FloorJointEastBand",
                "Past_CentralPlaza_FloorJointCenterSeam",
                "Past_CentralPlaza_FloorJointFountainApproachSeam"
            };

            var currentFountainDetails = new[]
            {
                "Current_CentralPlaza_FountainDryBasinInnerFloor",
                "Current_CentralPlaza_FountainDryBasinRimChipA",
                "Current_CentralPlaza_FountainDryBasinCrackA",
                "Current_CentralPlaza_FountainDryBasinWoodShardA"
            };

            var pastFountainDetails = new[]
            {
                "Past_CentralPlaza_FountainWaterInnerRimA",
                "Past_CentralPlaza_FountainWaterInnerRimB",
                "Past_CentralPlaza_FountainWaterHighlightA",
                "Past_CentralPlaza_FountainWaterHighlightB"
            };

            foreach (var objectName in currentFloorDetails)
            {
                ValidateCentralPlazaDetailObject(objectName, "Current_CentralPlazaMap_SeparateSpace", 0.08f);
            }

            foreach (var objectName in pastFloorDetails)
            {
                ValidateCentralPlazaDetailObject(objectName, "Past_CentralPlazaMap_SeparateSpace", 0.08f);
            }

            foreach (var objectName in currentFountainDetails)
            {
                ValidateCentralPlazaDetailObject(objectName, "Current_CentralPlazaMap_SeparateSpace", 0.12f);
            }

            foreach (var objectName in pastFountainDetails)
            {
                ValidateCentralPlazaDetailObject(objectName, "Past_CentralPlazaMap_SeparateSpace", 0.12f);
            }

            ValidateLandmarkExists("Current_CentralPlaza_FountainBase", "Current_CentralPlazaMap_SeparateSpace");
            ValidateLandmarkExists("Past_CentralPlaza_FountainBase", "Past_CentralPlazaMap_SeparateSpace");
            ValidateLandmarkExists("Current_CentralPlaza_FountainWater", "Current_CentralPlazaMap_SeparateSpace");
            ValidateLandmarkExists("Past_CentralPlaza_FountainWater", "Past_CentralPlazaMap_SeparateSpace");
            ValidateLandmarkExists("Current_CentralPlaza_FountainNoStepCollider", "Current_CentralPlazaMap_SeparateSpace");
            ValidateLandmarkExists("Past_CentralPlaza_FountainNoStepCollider", "Past_CentralPlazaMap_SeparateSpace");
            ValidateLandmarkExists("Current_CentralPlaza_ToHouseExterior_MapMoveGlowPad", "Current_CentralPlazaMap_SeparateSpace");
            ValidateLandmarkExists("Past_CentralPlaza_ToHouseExterior_MapMoveGlowPad", "Past_CentralPlazaMap_SeparateSpace");
            ValidateLandmarkExists("Current_CentralPlaza_ToLibrary_MapMoveGlowPad", "Current_CentralPlazaMap_SeparateSpace");
            ValidateLandmarkExists("Past_CentralPlaza_ToLibrary_MapMoveGlowPad", "Past_CentralPlazaMap_SeparateSpace");
            ValidateLandmarkExists("Current_CentralPlaza_LibraryNorthFacade", "Current_CentralPlazaMap_SeparateSpace");
            ValidateLandmarkExists("Past_CentralPlaza_LibraryNorthFacade", "Past_CentralPlazaMap_SeparateSpace");
        }

        private static void ValidateCurrentCentralPlazaDryFountainDetails()
        {
            var requiredWood = new[]
            {
                "Current_CentralPlaza_DryFountainWoodPlankA",
                "Current_CentralPlaza_DryFountainWoodPlankB"
            };

            foreach (var objectName in requiredWood)
            {
                var plank = FindSceneObjectIncludingInactive(objectName);
                var renderer = plank != null ? plank.GetComponent<Renderer>() : null;
                if (renderer == null ||
                    renderer.sharedMaterial == null ||
                    (renderer.sharedMaterial.name.IndexOf("current_furniture", StringComparison.OrdinalIgnoreCase) < 0 &&
                     renderer.sharedMaterial.name.IndexOf("current_fence", StringComparison.OrdinalIgnoreCase) < 0))
                {
                    throw new InvalidOperationException($"House slice validation failed: dry fountain top should use visible wood debris, not a black bar: {objectName}");
                }
            }

            var crack = FindSceneObjectIncludingInactive("Current_CentralPlaza_DryFountainCrack");
            if (crack == null || crack.transform.localScale.x > 0.82f || crack.transform.localScale.y > 0.05f)
            {
                throw new InvalidOperationException("House slice validation failed: dry fountain crack must remain a small detail, not a large black bar.");
            }

            ValidateSceneObjectMaterialNameContains("Current_CentralPlaza_DryFountainCrack", "dust");
            ValidateSceneObjectMaterialNameContains("Current_CentralPlaza_FountainDryBasinCrackA", "dust");
        }

        private static void ValidateSceneObjectMaterialNameContains(string objectName, string expectedMaterialToken)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            var renderer = sceneObject != null ? sceneObject.GetComponent<Renderer>() : null;
            var materialName = renderer != null && renderer.sharedMaterial != null ? renderer.sharedMaterial.name : string.Empty;
            if (materialName.IndexOf(expectedMaterialToken, StringComparison.OrdinalIgnoreCase) < 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must use a material containing {expectedMaterialToken} in its name.");
            }
        }

        private static void ValidateLibrarySideBookshelves()
        {
            ValidateLibrarySideBookshelfPair("Left");
            ValidateLibrarySideBookshelfPair("Right");
        }

        private static void ValidateLibrarySideBookshelfPair(string side)
        {
            var currentRoot = FindSceneObjectIncludingInactive($"Current_Library_{side}SideBookshelf");
            var pastRoot = FindSceneObjectIncludingInactive($"Past_Library_{side}SideBookshelf");
            if (currentRoot == null || pastRoot == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing current/past library side bookshelf roots: {side}");
            }

            ValidateLibrarySideBookshelfParent(currentRoot, "Current");
            ValidateLibrarySideBookshelfParent(pastRoot, "Past");
            ValidateVectorNear($"{side} library side bookshelf root position", currentRoot.transform.localPosition, pastRoot.transform.localPosition);
            if (Quaternion.Angle(currentRoot.transform.localRotation, pastRoot.transform.localRotation) > 0.02f)
            {
                throw new InvalidOperationException($"House slice validation failed: current/past {side.ToLowerInvariant()} library side bookshelf roots no longer share the same rotation.");
            }

            ValidateLibrarySideBookshelfFrame(currentRoot.transform, "Current", side, false);
            ValidateLibrarySideBookshelfFrame(pastRoot.transform, "Past", side, true);
            ValidateLibrarySideBookshelfFrameParity(currentRoot.transform, pastRoot.transform, side);

            if (pastRoot.transform.childCount < 9)
            {
                throw new InvalidOperationException($"House slice validation failed: past {side.ToLowerInvariant()} library side bookshelf should keep the frame and front lips.");
            }

            if (currentRoot.transform.Find($"{currentRoot.name}_BookshelfFrontTexturePanel") != null)
            {
                throw new InvalidOperationException($"House slice validation failed: current {side.ToLowerInvariant()} library side bookshelf must not use a front texture panel.");
            }

            ValidateSceneObjectRemoved($"{pastRoot.name}_BookshelfFrontTexturePanel");
        }

