        private static void ValidateHd2dPhaseCAlphaParticleSystem(
            string objectName,
            string expectedParentName,
            int expectedLayer,
            Material expectedMaterial,
            Vector3 expectedLocalPosition,
            Vector3 expectedShapeScale,
            int expectedMaxParticles,
            float expectedDuration,
            float expectedLifetime,
            float expectedEmissionRate,
            float expectedStartSpeed,
            float expectedStartSize,
            float expectedGravityModifier,
            float expectedRandomDirectionAmount,
            Color expectedStartColor,
            bool expectColorOverLifetime)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing Phase C-alpha particle system {objectName}.");
            }

            if (sceneObject.layer != expectedLayer)
            {
                throw new InvalidOperationException($"House slice validation failed: Phase C-alpha particle system {objectName} must stay on layer {expectedLayer}, but was {sceneObject.layer}.");
            }

            if (sceneObject.transform.parent == null || sceneObject.transform.parent.name != expectedParentName)
            {
                throw new InvalidOperationException($"House slice validation failed: Phase C-alpha particle system {objectName} must stay under {expectedParentName}.");
            }

            ValidateVectorNear($"{objectName} local position", sceneObject.transform.localPosition, expectedLocalPosition);
            ValidateVectorNear($"{objectName} local scale", sceneObject.transform.localScale, Vector3.one);

            var system = sceneObject.GetComponent<ParticleSystem>();
            var renderer = sceneObject.GetComponent<ParticleSystemRenderer>();
            if (system == null || renderer == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must have ParticleSystem and ParticleSystemRenderer components.");
            }

            var main = system.main;
            var emission = system.emission;
            var shape = system.shape;
            var colorOverLifetime = system.colorOverLifetime;
            if (renderer.sharedMaterial != expectedMaterial ||
                renderer.shadowCastingMode != ShadowCastingMode.Off ||
                renderer.receiveShadows ||
                renderer.renderMode != ParticleSystemRenderMode.Billboard ||
                renderer.alignment != ParticleSystemRenderSpace.View ||
                main.maxParticles != expectedMaxParticles ||
                Mathf.Abs(main.duration - expectedDuration) > 0.01f ||
                Mathf.Abs(main.startLifetime.constant - expectedLifetime) > 0.01f ||
                Mathf.Abs(main.startSpeed.constant - expectedStartSpeed) > 0.01f ||
                Mathf.Abs(main.startSize.constant - expectedStartSize) > 0.01f ||
                Mathf.Abs(main.gravityModifier.constant - expectedGravityModifier) > 0.02f ||
                Mathf.Abs(emission.rateOverTime.constant - expectedEmissionRate) > 0.05f ||
                main.simulationSpace != ParticleSystemSimulationSpace.World ||
                shape.shapeType != ParticleSystemShapeType.Box ||
                shape.scale != expectedShapeScale ||
                Mathf.Abs(shape.randomDirectionAmount - expectedRandomDirectionAmount) > 0.02f ||
                main.loop != true ||
                main.prewarm != true ||
                main.playOnAwake != true ||
                main.stopAction != ParticleSystemStopAction.None ||
                colorOverLifetime.enabled != expectColorOverLifetime)
            {
                throw new InvalidOperationException(
                    $"House slice validation failed: {objectName} must stay a low-count world-space atmosphere fallback emitter. " +
                    $"material={(renderer.sharedMaterial != null ? renderer.sharedMaterial.name : "<none>")}, maxParticles={main.maxParticles}, duration={main.duration:0.000}, lifetime={main.startLifetime.constant:0.000}, emission={emission.rateOverTime.constant:0.000}, speed={main.startSpeed.constant:0.000}, size={main.startSize.constant:0.000}, gravity={main.gravityModifier.constant:0.000}, randomDirection={shape.randomDirectionAmount:0.000}, colorOverLifetime={colorOverLifetime.enabled}.");
            }

            ValidateColorNear($"{objectName} start color", main.startColor.color, expectedStartColor, 0.03f);
        }

        private static void ValidateHd2dPhaseCAlphaPointLight(
            string objectName,
            string expectedParentName,
            int expectedLayer,
            Vector3 expectedLocalPosition,
            Color expectedColor,
            float expectedIntensity,
            float expectedRange)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing Phase C-alpha point light {objectName}.");
            }

            if (sceneObject.layer != expectedLayer)
            {
                throw new InvalidOperationException($"House slice validation failed: Phase C-alpha point light {objectName} must stay on layer {expectedLayer}, but was {sceneObject.layer}.");
            }

            if (sceneObject.transform.parent == null || sceneObject.transform.parent.name != expectedParentName)
            {
                throw new InvalidOperationException($"House slice validation failed: Phase C-alpha point light {objectName} must stay under {expectedParentName}.");
            }

            ValidateVectorNear($"{objectName} local position", sceneObject.transform.localPosition, expectedLocalPosition);

            if (sceneObject.transform.localRotation != Quaternion.identity || sceneObject.transform.localScale != Vector3.one)
            {
                throw new InvalidOperationException($"House slice validation failed: Phase C-alpha point light {objectName} must keep identity rotation and unit scale.");
            }

            var light = sceneObject.GetComponent<Light>();
            if (light == null ||
                light.type != LightType.Point ||
                light.shadows != LightShadows.None ||
                light.cullingMask != (1 << expectedLayer) ||
                Mathf.Abs(light.intensity - expectedIntensity) > 0.02f ||
                Mathf.Abs(light.range - expectedRange) > 0.05f)
            {
                throw new InvalidOperationException(
                    $"House slice validation failed: Phase C-alpha point light {objectName} must stay a restrained point light with the expected mask and intensity. " +
                    $"type={(light != null ? light.type.ToString() : "<none>")}, shadows={(light != null ? light.shadows.ToString() : "<none>")}, cullingMask={(light != null ? light.cullingMask : 0)}, intensity={(light != null ? light.intensity : 0f):0.000}, range={(light != null ? light.range : 0f):0.000}.");
            }

            ValidateColorNear($"{objectName} color", light.color, expectedColor, 0.03f);
        }

        private static void ValidateGeneratedRepeatTextureAsset(string textureId, int minWidth, int minHeight, int minimumDistinctColors)
        {
            var path = $"{TextureDirectory}/FastVS_House_{textureId}.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing generated texture asset {path}.");
            }

            if (texture.width < minWidth || texture.height < minHeight)
            {
                throw new InvalidOperationException($"House slice validation failed: {textureId} must be at least {minWidth}x{minHeight}, but was {texture.width}x{texture.height}.");
            }

            if (texture.filterMode != FilterMode.Point || texture.wrapMode != TextureWrapMode.Repeat)
            {
                throw new InvalidOperationException($"House slice validation failed: {textureId} must use point filtering and repeat wrap.");
            }

            if (CountDistinctOpaqueColors(texture) < minimumDistinctColors)
            {
                throw new InvalidOperationException($"House slice validation failed: {textureId} must contain enough opaque color variation.");
            }
        }

        private static void ValidateGeneratedSurfaceMaterialTexture(string materialId, string textureId)
        {
            var materialPath = $"{MaterialDirectory}/FastVS_House_{materialId}.mat";
            var texturePath = $"{TextureDirectory}/FastVS_House_{textureId}.asset";
            var material = AssetDatabase.LoadAssetAtPath<Material>(materialPath);
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(texturePath);
            if (material == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing material asset {materialPath}.");
            }

            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing texture asset {texturePath}.");
            }

            if (!MaterialUsesTexture(material, texture))
            {
                throw new InvalidOperationException($"House slice validation failed: {materialId} must reference {textureId}.");
            }
        }

        private static void ValidateCharacterContactShadowTextureMetrics(string context)
        {
            var path = $"{TextureDirectory}/FastVS_House_character_contact_shadow.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing character contact shadow texture asset {path} for {context}.");
            }

            ValidateCharacterContactShadowTextureMetrics(texture, context);
        }

        private static void ValidateCharacterContactShadowTextureMetrics(Texture2D texture, string context)
        {
            if (texture.width != 96 || texture.height != 48)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} must keep the character contact shadow texture at exactly 96x48, but was {texture.width}x{texture.height}.");
            }

            if (texture.filterMode != FilterMode.Bilinear)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} must keep the character contact shadow texture bilinear.");
            }

            if (texture.wrapMode != TextureWrapMode.Clamp)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} must keep the character contact shadow texture clamp-wrapped.");
            }

            var centerX = texture.width / 2;
            var centerY = texture.height / 2;
            var leftFootX = Mathf.Clamp(Mathf.RoundToInt(texture.width * 0.37f), 0, texture.width - 1);
            var rightFootX = Mathf.Clamp(Mathf.RoundToInt(texture.width * 0.63f), 0, texture.width - 1);
            var footY = Mathf.Clamp(Mathf.RoundToInt(texture.height * 0.60f), 0, texture.height - 1);

            var centerAlpha = texture.GetPixel(centerX, centerY).a;
            var leftEdgeAlpha = texture.GetPixel(0, centerY).a;
            var rightEdgeAlpha = texture.GetPixel(texture.width - 1, centerY).a;
            var topEdgeAlpha = texture.GetPixel(centerX, texture.height - 1).a;
            var bottomEdgeAlpha = texture.GetPixel(centerX, 0).a;
            var leftFootAlpha = texture.GetPixel(leftFootX, footY).a;
            var rightFootAlpha = texture.GetPixel(rightFootX, footY).a;
            var topLeftCornerAlpha = texture.GetPixel(0, texture.height - 1).a;
            var topRightCornerAlpha = texture.GetPixel(texture.width - 1, texture.height - 1).a;
            var bottomLeftCornerAlpha = texture.GetPixel(0, 0).a;
            var bottomRightCornerAlpha = texture.GetPixel(texture.width - 1, 0).a;

            var maxAlpha = 0f;
            foreach (var pixel in texture.GetPixels32())
            {
                maxAlpha = Mathf.Max(maxAlpha, pixel.a / 255f);
            }

            if (centerAlpha < 0.22f || centerAlpha > 0.38f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} center alpha {centerAlpha:0.000} is outside the 0.22-0.38 range.");
            }

            if (leftEdgeAlpha > 0.02f || rightEdgeAlpha > 0.02f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} edge alpha must stay at or below 0.020. left={leftEdgeAlpha:0.000}, right={rightEdgeAlpha:0.000}.");
            }

            if (topEdgeAlpha > 0.03f || bottomEdgeAlpha > 0.03f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} top/bottom edge alpha must stay soft. top={topEdgeAlpha:0.000}, bottom={bottomEdgeAlpha:0.000}.");
            }

            if (leftFootAlpha < 0.34f || leftFootAlpha > 0.52f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} left foot alpha {leftFootAlpha:0.000} is outside the 0.34-0.52 range.");
            }

            if (rightFootAlpha < 0.34f || rightFootAlpha > 0.52f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} right foot alpha {rightFootAlpha:0.000} is outside the 0.34-0.52 range.");
            }

            if (maxAlpha < 0.48f || maxAlpha > 0.54f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} max alpha {maxAlpha:0.000} is outside the 0.48-0.54 range.");
            }

            if (topLeftCornerAlpha > 0.01f || topRightCornerAlpha > 0.01f || bottomLeftCornerAlpha > 0.01f || bottomRightCornerAlpha > 0.01f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} corner alpha must stay near transparent. tl={topLeftCornerAlpha:0.000}, tr={topRightCornerAlpha:0.000}, bl={bottomLeftCornerAlpha:0.000}, br={bottomRightCornerAlpha:0.000}.");
            }
        }

        private static void ValidateHd2dCharacterGroundBounceTexture()
        {
            var path = $"{TextureDirectory}/FastVS_House_hd2d_character_ground_bounce_soft.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing ground bounce texture asset {path}.");
            }

            if (texture.width != 96 || texture.height != 48)
            {
                throw new InvalidOperationException($"House slice validation failed: hd2d_character_ground_bounce_soft must be 96x48, but was {texture.width}x{texture.height}.");
            }

            if (texture.filterMode != FilterMode.Bilinear || texture.wrapMode != TextureWrapMode.Clamp)
            {
                throw new InvalidOperationException("House slice validation failed: hd2d_character_ground_bounce_soft must use bilinear clamp sampling.");
            }

            var center = texture.GetPixel(texture.width / 2, texture.height / 2).a;
            var edge = texture.GetPixel(0, texture.height / 2).a;
            var corner = texture.GetPixel(0, 0).a;
            var maxAlpha = 0f;
            foreach (var pixel in texture.GetPixels32())
            {
                maxAlpha = Mathf.Max(maxAlpha, pixel.a / 255f);
            }

            if (center < 0.16f || center > 0.24f)
            {
                throw new InvalidOperationException($"House slice validation failed: hd2d_character_ground_bounce_soft center alpha must stay in the 0.16-0.24 range, but was {center:0.000}.");
            }

            if (edge > center * 0.55f || corner > 0.025f)
            {
                throw new InvalidOperationException($"House slice validation failed: hd2d_character_ground_bounce_soft alpha falloff looks broken. edge={edge:0.000}, corner={corner:0.000}.");
            }

            if (maxAlpha < 0.18f || maxAlpha > 0.24f)
            {
                throw new InvalidOperationException($"House slice validation failed: hd2d_character_ground_bounce_soft max alpha must stay in the 0.18-0.24 range, but was {maxAlpha:0.000}.");
            }
        }

        private static void ValidateCharacterDirectionalCastShadowTexture()
        {
            var texture = LoadDirectionalCastShadowTextureForValidation();
            if (texture == null)
            {
                throw new InvalidOperationException("House slice validation failed: missing directional cast shadow texture asset.");
            }

            if (texture.width != 96 || texture.height != 64)
            {
                throw new InvalidOperationException($"House slice validation failed: character_directional_cast_shadow_soft must be 96x64, but was {texture.width}x{texture.height}.");
            }

            var importer = AssetImporter.GetAtPath($"{TextureDirectory}/FastVS_House_character_directional_cast_shadow_soft.png") as TextureImporter;
            if (importer == null ||
                !importer.alphaIsTransparency ||
                importer.mipmapEnabled ||
                importer.filterMode != FilterMode.Bilinear ||
                importer.wrapMode != TextureWrapMode.Clamp)
            {
                throw new InvalidOperationException("House slice validation failed: character_directional_cast_shadow_soft must use bilinear clamp sampling.");
            }

            if (TextureAlphaChannelIsEmpty(texture))
            {
                throw new InvalidOperationException("House slice validation failed: character_directional_cast_shadow_soft alpha must not be empty.");
            }

            var center = texture.GetPixel(texture.width / 2, texture.height / 2).a;
            var edge = texture.GetPixel(0, texture.height / 2).a;
            var tail = texture.GetPixel(texture.width - 1, texture.height / 2).a;
            var corner = texture.GetPixel(0, 0).a;
            var maxAlpha = 0f;
            foreach (var pixel in texture.GetPixels32())
            {
                maxAlpha = Mathf.Max(maxAlpha, pixel.a / 255f);
            }

            if (center < 0.20f || center > 0.34f)
            {
                throw new InvalidOperationException($"House slice validation failed: character_directional_cast_shadow_soft center alpha must stay in the 0.20-0.34 range, but was {center:0.000}.");
            }

            if (edge > center * 0.65f || tail > center * 0.82f || corner > 0.02f)
            {
                throw new InvalidOperationException($"House slice validation failed: character_directional_cast_shadow_soft alpha falloff looks broken. edge={edge:0.000}, tail={tail:0.000}, corner={corner:0.000}.");
            }

            if (maxAlpha < 0.36f || maxAlpha > 0.44f)
            {
                throw new InvalidOperationException($"House slice validation failed: character_directional_cast_shadow_soft max alpha must stay in the 0.36-0.44 range, but was {maxAlpha:0.000}.");
            }

            UnityEngine.Object.DestroyImmediate(texture);
        }

        private static Texture2D LoadDirectionalCastShadowTextureForValidation()
        {
            var path = $"{TextureDirectory}/FastVS_House_character_directional_cast_shadow_soft.png";
            if (!File.Exists(path))
            {
                return null;
            }

            var bytes = File.ReadAllBytes(path);
            var texture = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            if (!texture.LoadImage(bytes, false))
            {
                UnityEngine.Object.DestroyImmediate(texture);
                throw new InvalidOperationException($"House slice validation failed: directional cast shadow PNG could not be read at {path}.");
            }

            texture.name = "FastVS_House_character_directional_cast_shadow_soft";
            return texture;
        }

        private static Texture2D LoadStaticDirectionalCastShadowTextureForValidation()
        {
            var path = $"{TextureDirectory}/FastVS_House_static_directional_cast_shadow_soft.png";
            if (!File.Exists(path))
            {
                return null;
            }

            var bytes = File.ReadAllBytes(path);
            var texture = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            if (!texture.LoadImage(bytes, false))
            {
                UnityEngine.Object.DestroyImmediate(texture);
                throw new InvalidOperationException($"House slice validation failed: static directional cast shadow PNG could not be read at {path}.");
            }

            texture.name = "FastVS_House_static_directional_cast_shadow_soft";
            return texture;
        }

        private static void ValidateStaticDirectionalCastShadowTexture()
        {
            var path = $"{TextureDirectory}/FastVS_House_static_directional_cast_shadow_soft.png";
            var validationTexture = LoadStaticDirectionalCastShadowTextureForValidation();
            if (validationTexture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: static directional cast shadow PNG asset is missing at {path}.");
            }

            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer == null ||
                !importer.alphaIsTransparency ||
                importer.mipmapEnabled ||
                importer.filterMode != FilterMode.Bilinear ||
                importer.wrapMode != TextureWrapMode.Clamp ||
                !importer.isReadable ||
                importer.textureCompression != TextureImporterCompression.Uncompressed)
            {
                throw new InvalidOperationException($"House slice validation failed: static directional cast shadow PNG importer settings are incorrect at {path}.");
            }

            if (validationTexture.width != 160 || validationTexture.height != 80)
            {
                throw new InvalidOperationException($"House slice validation failed: static directional cast shadow PNG must stay at 160x80: {path}");
            }

            if (TextureAlphaChannelIsEmpty(validationTexture))
            {
                throw new InvalidOperationException($"House slice validation failed: static directional shadow texture alpha must not be empty.");
            }

            ValidateStaticDirectionalCastShadowTextureMetrics(validationTexture, "static_directional_cast_shadow_soft");

            UnityEngine.Object.DestroyImmediate(validationTexture);
        }

