        private static void ValidateHd2dPlazaShadowMidtoneCycle107TextureMetrics()
        {
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(PlazaShadowMidtoneCycle107TexturePath);
            if (texture == null || texture.width != 192 || texture.height != 128)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 107 plaza shadow midtone texture must be generated at 192x128: {PlazaShadowMidtoneCycle107TexturePath}");
            }

            if (texture.filterMode != FilterMode.Bilinear || texture.wrapMode != TextureWrapMode.Clamp)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 107 plaza shadow midtone texture must stay bilinear and clamp-wrapped: {PlazaShadowMidtoneCycle107TexturePath}");
            }

            var cornerMax = Mathf.Max(
                Mathf.Max(texture.GetPixel(0, 0).a, texture.GetPixel(texture.width - 1, 0).a),
                Mathf.Max(texture.GetPixel(0, texture.height - 1).a, texture.GetPixel(texture.width - 1, texture.height - 1).a));
            if (cornerMax > 0.03f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 107 plaza shadow midtone texture corners must stay feathered.");
            }

            var edgeMidMax = Mathf.Max(
                Mathf.Max(texture.GetPixel(texture.width / 2, 0).a, texture.GetPixel(texture.width / 2, texture.height - 1).a),
                Mathf.Max(texture.GetPixel(0, texture.height / 2).a, texture.GetPixel(texture.width - 1, texture.height / 2).a));
            if (edgeMidMax > 0.05f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 107 plaza shadow midtone texture edges must stay feathered.");
            }

            var centerAlpha = texture.GetPixel(texture.width / 2, texture.height / 2).a;
            if (centerAlpha < 0.08f || centerAlpha > 0.20f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 107 plaza shadow midtone texture center must stay visible without becoming a board.");
            }

            float interiorTotal = 0f;
            float interiorMax = 0f;
            var interiorSamples = 0;
            var samplePoints = new[]
            {
                new Vector2Int(28, 24),
                new Vector2Int(48, 36),
                new Vector2Int(67, 48),
                new Vector2Int(88, 58),
                new Vector2Int(109, 71),
                new Vector2Int(133, 84),
                new Vector2Int(154, 94),
                new Vector2Int(172, 104)
            };

            foreach (var point in samplePoints)
            {
                var alpha = texture.GetPixel(point.x, point.y).a;
                interiorTotal += alpha;
                interiorMax = Mathf.Max(interiorMax, alpha);
                interiorSamples++;
            }

            var interiorAverage = interiorTotal / Mathf.Max(1, interiorSamples);
            if (interiorMax < 0.10f || interiorMax > 0.24f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 107 plaza shadow midtone texture must keep at least one visible broken patch without filling the tile.");
            }

            if (interiorAverage < 0.03f || interiorAverage > 0.11f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 107 plaza shadow midtone texture must stay low-alpha and broken.");
            }
        }

        private static void ValidateHd2dPlazaShadowPenumbraCycle108TextureMetrics()
        {
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(PlazaShadowPenumbraCycle108TexturePath);
            if (texture == null || texture.width != 192 || texture.height != 128)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 108 plaza shadow penumbra texture must be generated at 192x128: {PlazaShadowPenumbraCycle108TexturePath}");
            }

            if (texture.filterMode != FilterMode.Bilinear || texture.wrapMode != TextureWrapMode.Clamp)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 108 plaza shadow penumbra texture must stay bilinear and clamp-wrapped: {PlazaShadowPenumbraCycle108TexturePath}");
            }

            var cornerMax = Mathf.Max(
                Mathf.Max(texture.GetPixel(0, 0).a, texture.GetPixel(texture.width - 1, 0).a),
                Mathf.Max(texture.GetPixel(0, texture.height - 1).a, texture.GetPixel(texture.width - 1, texture.height - 1).a));
            if (cornerMax > 0.025f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 108 plaza shadow penumbra texture corners must stay feathered.");
            }

            var edgeMidMax = Mathf.Max(
                Mathf.Max(texture.GetPixel(texture.width / 2, 0).a, texture.GetPixel(texture.width / 2, texture.height - 1).a),
                Mathf.Max(texture.GetPixel(0, texture.height / 2).a, texture.GetPixel(texture.width - 1, texture.height / 2).a));
            if (edgeMidMax > 0.05f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 108 plaza shadow penumbra texture edges must stay feathered.");
            }

            var centerAlpha = texture.GetPixel(texture.width / 2, texture.height / 2).a;
            if (centerAlpha < 0.05f || centerAlpha > 0.18f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 108 plaza shadow penumbra texture center must stay visible without becoming a board.");
            }

            float interiorTotal = 0f;
            float interiorMax = 0f;
            float leftHalfTotal = 0f;
            float rightHalfTotal = 0f;
            var interiorSamples = 0;
            var samplePoints = new[]
            {
                new Vector2Int(24, 20),
                new Vector2Int(42, 32),
                new Vector2Int(61, 44),
                new Vector2Int(79, 55),
                new Vector2Int(97, 67),
                new Vector2Int(116, 78),
                new Vector2Int(139, 88),
                new Vector2Int(163, 98)
            };

            foreach (var point in samplePoints)
            {
                var alpha = texture.GetPixel(point.x, point.y).a;
                interiorTotal += alpha;
                interiorMax = Mathf.Max(interiorMax, alpha);
                if (point.x < texture.width / 2)
                {
                    leftHalfTotal += alpha;
                }
                else
                {
                    rightHalfTotal += alpha;
                }

                interiorSamples++;
            }

            var interiorAverage = interiorTotal / Mathf.Max(1, interiorSamples);
            if (interiorMax < 0.09f || interiorMax > 0.28f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 108 plaza shadow penumbra texture must keep visible broken patches without filling the tile.");
            }

            if (interiorAverage < 0.02f || interiorAverage > 0.09f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 108 plaza shadow penumbra texture must stay low-alpha and broken.");
            }

            var leftHalfAverage = leftHalfTotal / 4f;
            var rightHalfAverage = rightHalfTotal / 4f;
            if (Mathf.Abs(leftHalfAverage - rightHalfAverage) < 0.005f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 108 plaza shadow penumbra texture must keep an asymmetric streak and patch distribution.");
            }
        }

        private static void ValidateHd2dPlazaSunlitFloorIslandsCycle109TextureMetrics()
        {
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(PlazaSunlitIslandsCycle109TexturePath);
            if (texture == null || texture.width != 192 || texture.height != 128)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 109 plaza sunlit islands texture must be generated at 192x128: {PlazaSunlitIslandsCycle109TexturePath}");
            }

            if (texture.filterMode != FilterMode.Bilinear || texture.wrapMode != TextureWrapMode.Clamp)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 109 plaza sunlit islands texture must stay bilinear and clamp-wrapped: {PlazaSunlitIslandsCycle109TexturePath}");
            }

            var cornerMax = Mathf.Max(
                Mathf.Max(texture.GetPixel(0, 0).a, texture.GetPixel(texture.width - 1, 0).a),
                Mathf.Max(texture.GetPixel(0, texture.height - 1).a, texture.GetPixel(texture.width - 1, texture.height - 1).a));
            if (cornerMax > 0.025f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 109 plaza sunlit islands texture corners must stay feathered.");
            }

            var edgeMidMax = Mathf.Max(
                Mathf.Max(texture.GetPixel(texture.width / 2, 0).a, texture.GetPixel(texture.width / 2, texture.height - 1).a),
                Mathf.Max(texture.GetPixel(0, texture.height / 2).a, texture.GetPixel(texture.width - 1, texture.height / 2).a));
            if (edgeMidMax > 0.05f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 109 plaza sunlit islands texture edges must stay feathered.");
            }

            var islandCenters = new[]
            {
                new Vector2Int(37, 88),
                new Vector2Int(80, 69),
                new Vector2Int(113, 39),
                new Vector2Int(150, 63),
                new Vector2Int(128, 101)
            };

            float islandAlphaTotal = 0f;
            float islandAlphaMax = 0f;
            var strongIslandCount = 0;
            var visibleIslandCount = 0;
            foreach (var point in islandCenters)
            {
                var alpha = texture.GetPixel(point.x, point.y).a;
                islandAlphaTotal += alpha;
                islandAlphaMax = Mathf.Max(islandAlphaMax, alpha);
                if (alpha > 0.10f)
                {
                    visibleIslandCount++;
                }

                if (alpha > 0.18f)
                {
                    strongIslandCount++;
                }
            }

            if (islandAlphaMax < 0.18f || islandAlphaMax > 0.46f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 109 plaza sunlit islands texture must keep stronger warm island cores without turning into a slab.");
            }

            if (visibleIslandCount < 4)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 109 plaza sunlit islands texture must keep several separated visible islands.");
            }

            if (strongIslandCount < 3)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 109 plaza sunlit islands texture must keep several stronger island cores above the overview threshold.");
            }

            var gapSamples = new[]
            {
                new Vector2Int(18, 60),
                new Vector2Int(53, 24),
                new Vector2Int(95, 86),
                new Vector2Int(166, 32)
            };

            foreach (var point in gapSamples)
            {
                var alpha = texture.GetPixel(point.x, point.y).a;
                if (alpha > 0.05f)
                {
                    throw new InvalidOperationException("House slice validation failed: cycle 109 plaza sunlit islands texture must keep open gaps between islands.");
                }
            }

            var interiorAverage = islandAlphaTotal / Mathf.Max(1, islandCenters.Length);
            if (interiorAverage < 0.08f || interiorAverage > 0.32f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 109 plaza sunlit islands texture must stay broken rather than filling the tile.");
            }
        }

        private static void ValidateHd2dPlazaSunlitIslandsCycle109Material(Material material, Texture2D resolvedTexture, string objectName)
        {
            if (!string.Equals(AssetDatabase.GetAssetPath(material), PlazaSunlitIslandsCycle109MaterialPath, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must use the generated cycle 109 plaza sunlit islands material.");
            }

            if (material.name.IndexOf(PlazaSunlitIslandsCycle109MaterialId, StringComparison.OrdinalIgnoreCase) < 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep the cycle 109 plaza sunlit islands material name.");
            }

            if (!string.Equals(material.GetTag(MaterialRoleTagName, false, string.Empty), FastVsHd2dMaterialRole.OverlayGlow.ToString(), StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep the overlay-glow material role.");
            }

            if (material.renderQueue < 3021 || material.renderQueue > 3023)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep the cycle 109 transparent render queue above cycle 108.");
            }

            var tint = Color.white;
            if (material.HasProperty("_BaseColor"))
            {
                tint = material.GetColor("_BaseColor");
            }
            else if (material.HasProperty("_Color"))
            {
                tint = material.GetColor("_Color");
            }

            ValidateColorNear($"{objectName} material tint", tint, new Color(1.00f, 0.90f, 0.72f, 0.018f), 0.02f);

            if (resolvedTexture == null || !string.Equals(AssetDatabase.GetAssetPath(resolvedTexture), PlazaSunlitIslandsCycle109TexturePath, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must reference the generated cycle 109 plaza sunlit islands texture.");
            }

            if (!MaterialUsesTexture(material, resolvedTexture))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep the generated cycle 109 plaza sunlit islands texture assigned.");
            }
        }

