            ValidateColorNear($"{objectName} intended tint", intendedTintProperty.colorValue, new Color(0.18f, 0.16f, 0.14f, 0.96f), 0.03f);
        }

        private static void ValidateHd2dPlazaCastShadowContrastCycle114TextureMetrics()
        {
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(PlazaCastShadowContrastCycle114TexturePath);
            if (texture == null || texture.width != 192 || texture.height != 128)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 114 plaza cast-shadow contrast texture must be generated at 192x128: {PlazaCastShadowContrastCycle114TexturePath}");
            }

            if (texture.format != TextureFormat.RGBA32)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 114 plaza cast-shadow contrast texture must stay RGBA32: {PlazaCastShadowContrastCycle114TexturePath}");
            }

            if (texture.filterMode != FilterMode.Bilinear || texture.wrapMode != TextureWrapMode.Clamp)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 114 plaza cast-shadow contrast texture must stay bilinear and clamp-wrapped: {PlazaCastShadowContrastCycle114TexturePath}");
            }

            var cornerMax = Mathf.Max(
                Mathf.Max(texture.GetPixel(0, 0).a, texture.GetPixel(texture.width - 1, 0).a),
                Mathf.Max(texture.GetPixel(0, texture.height - 1).a, texture.GetPixel(texture.width - 1, texture.height - 1).a));
            if (cornerMax > 0.04f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 114 plaza cast-shadow contrast texture corners must stay feathered.");
            }

            var edgeMidMax = Mathf.Max(
                Mathf.Max(texture.GetPixel(texture.width / 2, 0).a, texture.GetPixel(texture.width / 2, texture.height - 1).a),
                Mathf.Max(texture.GetPixel(0, texture.height / 2).a, texture.GetPixel(texture.width - 1, texture.height / 2).a));
            if (edgeMidMax > 0.04f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 114 plaza cast-shadow contrast texture edges must stay feathered.");
            }

            var shadowSamplePoints = new[]
            {
                new Vector2Int(33, 21),
                new Vector2Int(49, 35),
                new Vector2Int(71, 47),
                new Vector2Int(101, 39),
                new Vector2Int(129, 55),
                new Vector2Int(151, 27),
                new Vector2Int(171, 61)
            };

            float shadowAverage = 0f;
            float shadowPeak = 0f;
            foreach (var point in shadowSamplePoints)
            {
                var alpha = texture.GetPixel(point.x, point.y).a;
                shadowAverage += alpha;
                shadowPeak = Mathf.Max(shadowPeak, alpha);
            }

            shadowAverage /= shadowSamplePoints.Length;
            if (shadowPeak < 0.28f || shadowPeak > 0.36f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 114 plaza cast-shadow contrast texture must preserve a visible shadow peak without turning into a slab (shadowPeak={shadowPeak:0.000}, shadowAverage={shadowAverage:0.000}).");
            }

            if (shadowAverage < 0.08f || shadowAverage > 0.16f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 114 plaza cast-shadow contrast texture must stay broken and airy rather than filling the tile (shadowPeak={shadowPeak:0.000}, shadowAverage={shadowAverage:0.000}).");
            }
        }

        private static void ValidateHd2dPlazaSunShadowGradeCycle115()
        {
            var directorObject = FindSceneObjectIncludingInactive("FastVS_HD2D_LightingDirector");
            var director = directorObject != null ? directorObject.GetComponent<FastVsHouseLightingDirector>() : null;
            var mainLight = FindSceneObjectIncludingInactive("Directional Light")?.GetComponent<Light>();
            var warmFill = FindSceneObjectIncludingInactive("FastVS_HD2D_WarmFillLight")?.GetComponent<Light>();
            var coolRim = FindSceneObjectIncludingInactive("FastVS_HD2D_CoolRimLight")?.GetComponent<Light>();
            var sceneCamera = Camera.main;
            var volumeObject = FindSceneObjectIncludingInactive("FastVS_HD2D_GlobalVolume");
            var volume = volumeObject != null ? volumeObject.GetComponent<Volume>() : null;
            var profileObject = FindSceneObjectIncludingInactive("FastVS_HD2D_CentralPlazaLightingProfile");
            var profile = profileObject != null ? profileObject.GetComponent<FastVsHd2dAreaLightingProfile>() : null;

            if (director == null ||
                !director.HasRequiredLightsForReview ||
                mainLight == null ||
                warmFill == null ||
                coolRim == null ||
                sceneCamera == null ||
                volume == null ||
                volume.sharedProfile == null ||
                profile == null)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 115 plaza sun shadow grade needs the lighting director, key lights, camera, global volume, and central plaza profile.");
            }

            if (AssetDatabase.GetAssetPath(volume.sharedProfile) != "Assets/Settings/DefaultVolumeProfile.asset")
            {
                throw new InvalidOperationException("House slice validation failed: cycle 115 global volume must keep Assets/Settings/DefaultVolumeProfile.asset.");
            }

            if (profile.AreaIdForReview != FastVsHouseArea.CentralPlaza)
            {
                throw new InvalidOperationException("House slice validation failed: central plaza lighting profile must keep area id CentralPlaza.");
            }

            if (Mathf.Abs(profile.KeyLightIntensityForReview - 1.84f) > 0.002f)
            {
                throw new InvalidOperationException($"House slice validation failed: central plaza lighting profile key intensity must stay at 1.840, but was {profile.KeyLightIntensityForReview:0.000}.");
            }

            ValidateColorApproximately(profile.KeyLightTintForReview, new Color(1.00f, 0.74f, 0.42f, 1f), "cycle 115 central plaza key tint");

            if (Mathf.Abs(profile.FillIntensityForReview - 0.012f) > 0.002f)
            {
                throw new InvalidOperationException($"House slice validation failed: central plaza lighting profile fill intensity must stay at 0.012, but was {profile.FillIntensityForReview:0.000}.");
            }

            ValidateColorApproximately(profile.FillTintForReview, new Color(1.00f, 0.55f, 0.26f, 1f), "cycle 115 central plaza fill tint");

            if (Mathf.Abs(profile.AmbientIntensityForReview - 0.045f) > 0.002f)
            {
                throw new InvalidOperationException($"House slice validation failed: central plaza lighting profile ambient intensity must stay at 0.045, but was {profile.AmbientIntensityForReview:0.000}.");
            }

            ValidateColorApproximately(profile.AmbientTintForReview, new Color(0.052f, 0.044f, 0.034f, 1f), "cycle 115 central plaza ambient tint");

            director.ApplyAreaForReview(FastVsHouseArea.CentralPlaza);

            if (director.LastAppliedAreaForReview != FastVsHouseArea.CentralPlaza || director.TargetAreaForReview != FastVsHouseArea.CentralPlaza || director.TransitionActiveForReview)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 115 central plaza must apply immediately without leaving a transition active.");
            }

            if (mainLight.type != LightType.Directional || mainLight.shadows != LightShadows.Soft)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 115 main light must remain a soft directional light.");
            }

            if (!IsMainDirectionalLightManagedBySunCycleForReview())
            {
                if (Mathf.Abs(mainLight.intensity - 1.84f) > 0.04f)
                {
                    throw new InvalidOperationException($"House slice validation failed: cycle 115 main light intensity must stay within 1.80..1.88 after applying CentralPlaza, but was {mainLight.intensity:0.000}.");
                }

                if (Mathf.Abs(mainLight.shadowStrength - 1.00f) > 0.02f)
                {
                    throw new InvalidOperationException($"House slice validation failed: cycle 115 main light shadow strength must stay within 0.98..1.02 after applying CentralPlaza, but was {mainLight.shadowStrength:0.000}.");
                }

                if (mainLight.color.r < mainLight.color.g || mainLight.color.g < mainLight.color.b || mainLight.color.b < 0.40f || mainLight.color.b > 0.44f)
                {
                    throw new InvalidOperationException($"House slice validation failed: cycle 115 main light color must stay hot and blue must remain around 0.40-0.44, but was ({mainLight.color.r:0.000}, {mainLight.color.g:0.000}, {mainLight.color.b:0.000}).");
                }
            }

            if (!IsMainDirectionalLightManagedBySunCycleForReview())
            {
                if (Mathf.Max(RenderSettings.ambientLight.r, Mathf.Max(RenderSettings.ambientLight.g, RenderSettings.ambientLight.b)) > 0.080f)
                {
                    throw new InvalidOperationException($"House slice validation failed: cycle 115 ambient light must stay below 0.080 per channel, but was ({RenderSettings.ambientLight.r:0.000}, {RenderSettings.ambientLight.g:0.000}, {RenderSettings.ambientLight.b:0.000}).");
                }

                if (RenderSettings.ambientMode != AmbientMode.Flat)
                {
                    throw new InvalidOperationException("House slice validation failed: cycle 115 ambient mode must remain Flat.");
                }
            }

            if (Mathf.Abs(warmFill.intensity - 0.012f) > 0.008f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 115 warm fill intensity must stay within 0.004..0.020, but was {warmFill.intensity:0.000}.");
            }

            if (Mathf.Abs(coolRim.intensity - 0.025f) > 0.010f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 115 cool rim intensity must stay within 0.015..0.035, but was {coolRim.intensity:0.000}.");
            }

            if (!IsMainDirectionalLightManagedBySunCycleForReview() && !RenderSettings.fog)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 115 fog must remain enabled.");
            }

            if (!IsMainDirectionalLightManagedBySunCycleForReview() && RenderSettings.fogMode != FogMode.Linear)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 115 fog mode must remain Linear.");
            }

            if (!IsMainDirectionalLightManagedBySunCycleForReview() &&
                (RenderSettings.fogStartDistance < 7f || RenderSettings.fogStartDistance > 9f || RenderSettings.fogEndDistance < 40f || RenderSettings.fogEndDistance > 48f))
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 115 fog distances must stay within 7-9 and 40-48, but were start={RenderSettings.fogStartDistance:0.000}, end={RenderSettings.fogEndDistance:0.000}.");
            }

            if (!IsMainDirectionalLightManagedBySunCycleForReview())
            {
                ValidateColorApproximately(RenderSettings.fogColor, new Color(0.265f, 0.205f, 0.138f, 1f), "cycle 115 fog color");
            }

            if (sceneCamera.backgroundColor.r >= 0.210f || sceneCamera.backgroundColor.b >= 0.120f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 115 camera background must stay below the reference fade thresholds, but was ({sceneCamera.backgroundColor.r:0.000}, {sceneCamera.backgroundColor.g:0.000}, {sceneCamera.backgroundColor.b:0.000}).");
            }

            ValidateColorApproximately(sceneCamera.backgroundColor, new Color(0.196f, 0.158f, 0.104f, 1f), "cycle 115 camera background");

            if (!volume.sharedProfile.TryGet<ColorAdjustments>(out var colorAdjustments) ||
                !volume.sharedProfile.TryGet<Bloom>(out var bloom) ||
                !volume.sharedProfile.TryGet<Vignette>(out var vignette) ||
                !volume.sharedProfile.TryGet<Tonemapping>(out var tonemapping) ||
                !volume.sharedProfile.TryGet<WhiteBalance>(out var whiteBalance) ||
                !volume.sharedProfile.TryGet<FilmGrain>(out var filmGrain) ||
                !volume.sharedProfile.TryGet<DepthOfField>(out var depthOfField))
            {
                throw new InvalidOperationException("House slice validation failed: cycle 115 global volume profile must include ColorAdjustments, Bloom, Vignette, Tonemapping, WhiteBalance, FilmGrain, and DepthOfField.");
            }

            if (!colorAdjustments.active || !bloom.active || !vignette.active || !tonemapping.active || !whiteBalance.active)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 115 color grade overrides must remain active.");
            }

            if (Mathf.Abs(colorAdjustments.postExposure.value) > 0.02f ||
                Mathf.Abs(colorAdjustments.contrast.value - 14f) > 1f ||
                Mathf.Abs(colorAdjustments.saturation.value) > 0.50f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 115 color adjustments must stay near postExposure=0, contrast=14, saturation=0, but were postExposure={colorAdjustments.postExposure.value:0.000}, contrast={colorAdjustments.contrast.value:0.000}, saturation={colorAdjustments.saturation.value:0.000}.");
            }

            ValidateColorApproximately(colorAdjustments.colorFilter.value, new Color(1.08f, 1.04f, 0.92f, 1f), "cycle 115 color filter");

            if (Mathf.Abs(bloom.intensity.value - 0.80f) > 0.03f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 115 bloom intensity must stay near 0.80, but was {bloom.intensity.value:0.000}.");
            }

            if (Mathf.Abs(vignette.intensity.value - 0.30f) > 0.025f ||
                Mathf.Abs(vignette.smoothness.value - 0.40f) > 0.025f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 115 vignette must stay near the Stage 1 shadow frame at intensity=0.30/smoothness=0.40, but was intensity={vignette.intensity.value:0.000}, smoothness={vignette.smoothness.value:0.000}.");
            }

            if (tonemapping.mode.value != TonemappingMode.ACES ||
                Mathf.Abs(whiteBalance.temperature.value - 8f) > 0.50f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 115 volume must use ACES tonemapping and WhiteBalance +8, found tonemapping={tonemapping.mode.value}, temperature={whiteBalance.temperature.value:0.000}.");
            }

            if (filmGrain.active || filmGrain.intensity.value > 0.001f)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 115 film grain must stay inactive or at zero intensity.");
            }

            if (!depthOfField.active || depthOfField.mode.value != DepthOfFieldMode.Bokeh)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 115 depth of field must stay active in Stage 7 Bokeh mode.");
            }
        }

