        private static void ValidateHd2dPlazaReferenceCameraGradeCycle145()
        {
            ValidateHd2dPlazaRealtimeSunLiftCycle144();

            var volumeObject = FindSceneObjectIncludingInactive("FastVS_HD2D_GlobalVolume");
            var volume = volumeObject != null ? volumeObject.GetComponent<Volume>() : null;
            if (volume == null || volume.sharedProfile == null)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 145 needs the HD-2D global volume profile.");
            }

            if (!volume.sharedProfile.TryGet<ColorAdjustments>(out var colorAdjustments) ||
                !volume.sharedProfile.TryGet<Bloom>(out var bloom) ||
                !volume.sharedProfile.TryGet<Vignette>(out var vignette) ||
                !volume.sharedProfile.TryGet<Tonemapping>(out var tonemapping) ||
                !volume.sharedProfile.TryGet<WhiteBalance>(out var whiteBalance) ||
                !volume.sharedProfile.TryGet<ColorLookup>(out var colorLookup) ||
                !volume.sharedProfile.TryGet<DepthOfField>(out var depthOfField))
            {
                throw new InvalidOperationException("House slice validation failed: cycle 145 needs ColorAdjustments, Bloom, Vignette, Tonemapping, WhiteBalance, ColorLookup, and DepthOfField on the global volume.");
            }

            if (!colorAdjustments.active ||
                Mathf.Abs(colorAdjustments.postExposure.value) > 0.01f ||
                Mathf.Abs(colorAdjustments.contrast.value - 14f) > 0.10f ||
                Mathf.Abs(colorAdjustments.saturation.value) > 0.10f ||
                !bloom.active ||
                Mathf.Abs(bloom.threshold.value - 0.85f) > 0.02f ||
                Mathf.Abs(bloom.intensity.value - 0.80f) > 0.02f ||
                Mathf.Abs(bloom.scatter.value - 0.72f) > 0.02f ||
                !bloom.highQualityFiltering.value ||
                !vignette.active ||
                Mathf.Abs(vignette.intensity.value - 0.30f) > 0.02f ||
                Mathf.Abs(vignette.smoothness.value - 0.40f) > 0.02f ||
                !tonemapping.active ||
                tonemapping.mode.value != TonemappingMode.ACES ||
                !whiteBalance.active ||
                Mathf.Abs(whiteBalance.temperature.value - 8f) > 0.10f ||
                !depthOfField.active ||
                depthOfField.mode.value != DepthOfFieldMode.Bokeh ||
                Mathf.Abs(depthOfField.focusDistance.value - 5.4f) > 0.60f ||
                Mathf.Abs(depthOfField.aperture.value - 2.4f) > 0.12f ||
                Mathf.Abs(depthOfField.focalLength.value - 85f) > 2.0f ||
                depthOfField.bladeCount.value != 6)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 145 reference camera grade values drifted.");
            }

            ValidateStage5LutColorLookup(colorLookup, "cycle 145");
        }

        private static void ValidateHd2dPlazaFacadeShadowLiftCycle146()
        {
            ValidateHd2dPlazaReferenceCameraGradeCycle145();

            var liftedFacadeCount = 0;
            var block = new MaterialPropertyBlock();
            foreach (var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None))
            {
                if (renderer == null || !renderer.gameObject.scene.IsValid() || !renderer.enabled || !renderer.receiveShadows)
                {
                    continue;
                }

                var surface = renderer.GetComponent<FastVsHd2dSurfaceProfile>();
                var objectName = renderer.gameObject.name;
                var isCurrentCentralFacade =
                    IsCycle139CurrentCentralPlazaFacadeReceiverName(objectName) ||
                    surface != null &&
                    surface.AreaIdForReview == FastVsHouseArea.CentralPlaza &&
                    surface.IsCurrentWorldForReview &&
                    (surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Wall ||
                     surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Door ||
                     surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Roof);
                if (!isCurrentCentralFacade)
                {
                    continue;
                }

                if (!IsStage7PlazaSoftLiftFacadeReceiver(renderer, block))
                {
                    continue;
                }

                liftedFacadeCount++;
            }

            if (liftedFacadeCount < 12)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 146 expected lifted facade realtime shadow receivers, found {liftedFacadeCount}.");
            }
        }

        private static bool IsStage7PlazaSoftLiftFacadeReceiver(Renderer renderer, MaterialPropertyBlock block)
        {
            var material = renderer.sharedMaterial;
            if (material == null || !material.HasProperty("_ShadowTextureStrength"))
            {
                return false;
            }

            renderer.GetPropertyBlock(block);
            if (block.GetFloat("_ShadowTextureStrength") > Stage7jCentralPlazaShadowTextureStrengthMax)
            {
                return false;
            }

            return !material.HasProperty("_ShadowReceiveStrength") ||
                   block.GetFloat("_ShadowReceiveStrength") <= Stage7jCentralPlazaShadowReceiveStrengthMax;
        }

        private static bool IsStage7PlazaSoftBalanceReceiver(Renderer renderer, MaterialPropertyBlock block)
        {
            var material = renderer.sharedMaterial;
            if (material == null ||
                !material.HasProperty("_DirectionalLightStrength") ||
                !material.HasProperty("_ShadowReceiveStrength") ||
                !material.HasProperty("_ShadowTextureStrength") ||
                !material.HasProperty("_SideShade") ||
                !material.HasProperty("_FloorShade"))
            {
                return false;
            }

            renderer.GetPropertyBlock(block);
            var sideShade = block.GetColor("_SideShade");
            var floorShade = block.GetColor("_FloorShade");
            var directionalLightStrength = block.GetFloat("_DirectionalLightStrength");
            var shadowReceiveStrength = block.GetFloat("_ShadowReceiveStrength");
            var shadowTextureStrength = block.GetFloat("_ShadowTextureStrength");
            return directionalLightStrength >= 0.90f &&
                   directionalLightStrength <= 0.94f &&
                   shadowReceiveStrength <= Stage7jCentralPlazaShadowReceiveStrengthMax &&
                   shadowTextureStrength <= Stage7jCentralPlazaShadowTextureStrengthMax &&
                   sideShade.r >= Stage7jCentralPlazaSideShadeMin &&
                   floorShade.r >= Stage7jCentralPlazaFloorShadeMin;
        }

        private static void ValidateHd2dPlazaRealtimeSunCookieCycle147()
        {
            ValidateHd2dPlazaFacadeShadowLiftCycle146();

            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            var director = UnityEngine.Object.FindFirstObjectByType<FastVsHouseLightingDirector>();
            var realtimeRig = UnityEngine.Object.FindFirstObjectByType<FastVsRealtimeLightShadowRig>();
            var camera = Camera.main;
            var mainLight = FindSceneObjectIncludingInactive("Directional Light")?.GetComponent<Light>();
            if (visibility == null || director == null || realtimeRig == null || camera == null || mainLight == null)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 147 needs visibility, director, camera, realtime rig, and directional light.");
            }

            visibility.SetActiveAreaForReview(FastVsHouseArea.CentralPlaza);
            director.ApplyAreaForReview(FastVsHouseArea.CentralPlaza);
            realtimeRig.ApplyNowForReview();

            if (!IsMainDirectionalLightManagedBySunCycleForReview() && RenderSettings.fog)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 147 must stay off RenderSettings fog and camera paint.");
            }

            if (!IsMainDirectionalLightManagedBySunCycleForReview() &&
                (mainLight.cookie == null ||
                mainLight.cookie.name != "FastVS_CentralPlazaRealtimeSunCookieCycle147" ||
                mainLight.cookie.width != 128 ||
                mainLight.cookie.height != 128 ||
                mainLight.cookie.filterMode != FilterMode.Bilinear ||
                mainLight.cookie.wrapMode != TextureWrapMode.Clamp ||
                mainLight.cookieSize < 9.0f ||
                mainLight.cookieSize > 9.5f ||
                mainLight.intensity < 2.28f))
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 147 directional light must carry the realtime plaza sun cookie, found cookie={mainLight.cookie}, size={mainLight.cookieSize:0.00}, intensity={mainLight.intensity:0.00}.");
            }

            var profile = FastVsVisualDirectionGuide.GetFollowCameraProfileForReview(FastVsHouseArea.CentralPlaza);
            ValidateVectorNear("cycle 147 central plaza runtime VS follow camera offset", profile.PositionOffset, RuntimeVsFollowCameraOffset);
            ValidateVectorNear("cycle 147 central plaza runtime VS follow look offset", profile.LookOffset, RuntimeVsFollowLookOffset);
            if (Mathf.Abs(profile.FieldOfView - RuntimeVsFollowCameraFov) > 0.01f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 147 central plaza runtime follow FOV must match shared VS {RuntimeVsFollowCameraFov:0}, found {profile.FieldOfView:0.0}.");
            }

            var shaderPath = Path.Combine(Application.dataPath, "Art", "Shaders", "FastVS", "FastVS_SurfaceRampLit.shader");
            var shaderText = File.ReadAllText(shaderPath);
            if (!shaderText.Contains("_LIGHT_COOKIES") ||
                !shaderText.Contains("GetMainLight(shadowCoord, input.positionWS"))
            {
                throw new InvalidOperationException("House slice validation failed: cycle 147 SurfaceRampLit must compile and sample URP realtime light cookies.");
            }

            var enabledFakeSkyCount = 0;
            foreach (var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None))
            {
                if (renderer == null || !renderer.gameObject.scene.IsValid() || !renderer.enabled || !renderer.gameObject.activeInHierarchy)
                {
                    continue;
                }

                var objectName = renderer.gameObject.name;
                if (objectName.Contains("Current_CentralPlaza") &&
                    (objectName.Contains("SkyWash") ||
                     objectName.Contains("SkyVeil") ||
                     objectName.Contains("Backdrop") ||
                     objectName.Contains("Haze") ||
                     objectName.Contains("Veil") ||
                     objectName.Contains("AirForeground") ||
                     objectName.Contains("AirFacade")))
                {
                    enabledFakeSkyCount++;
                }
            }

            if (enabledFakeSkyCount != 0)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 147 must not leave fake sky/haze plates enabled in central plaza, found {enabledFakeSkyCount}.");
            }
        }

        private static void ValidateHd2dPlazaRealtimeSoftShadowCycle148()
        {
            ValidateHd2dPlazaRealtimeSunCookieCycle147();

            var shaderPath = Path.Combine(Application.dataPath, "Art", "Shaders", "FastVS", "FastVS_SurfaceRampLit.shader");
            var shaderText = File.ReadAllText(shaderPath);
            if (!IsPhaseASurfaceRampShaderLightenedForReview(shaderText) &&
                (!shaderText.Contains("MainLightRealtimeShadow(TransformWorldToShadowCoord(input.positionWS + shadowTangent") ||
                !shaderText.Contains("MainLightRealtimeShadow(TransformWorldToShadowCoord(input.positionWS - shadowTangent") ||
                !shaderText.Contains("shadowSoftRadius") ||
                !shaderText.Contains("softShadowAttenuation *= 0.111111h")))
            {
                throw new InvalidOperationException("House slice validation failed: cycle 148 SurfaceRampLit must feather live realtime shadowmap samples, not painted map haze.");
            }

            var softenedReceiverCount = 0;
            var block = new MaterialPropertyBlock();
            foreach (var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None))
            {
                if (renderer == null || !renderer.gameObject.scene.IsValid() || !renderer.enabled || !renderer.receiveShadows)
                {
                    continue;
                }

                var material = renderer.sharedMaterial;
                if (material == null || !material.HasProperty("_ShadowTextureStrength"))
                {
                    continue;
                }

                renderer.GetPropertyBlock(block);
                if (block.GetFloat("_ShadowTextureStrength") <= Stage7jCentralPlazaShadowTextureStrengthMax)
                {
                    softenedReceiverCount++;
                }
            }

            if (softenedReceiverCount < 24)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 148 expected realtime receivers to drive live shadow softness, found {softenedReceiverCount}.");
            }
        }

        private static void ValidateHd2dPlazaRealtimeSpriteTrackingCycle149()
        {
            ValidateHd2dPlazaRealtimeSoftShadowCycle148();

            var shaderPath = Path.Combine(Application.dataPath, "Art", "Shaders", "FastVS", "FastVS_SpriteCardRampUnlit.shader");
            var shaderText = File.ReadAllText(shaderPath);
            if (!shaderText.Contains("_LIGHT_COOKIES") ||
                !shaderText.Contains("GetMainLight(shadowCoord, input.positionWS") ||
                !shaderText.Contains("lightCookieResponse"))
            {
                throw new InvalidOperationException("House slice validation failed: cycle 149 SpriteCard shader must sample realtime light cookies and shadows.");
            }

            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            var realtimeRig = UnityEngine.Object.FindFirstObjectByType<FastVsRealtimeLightShadowRig>();
            if (visibility == null || realtimeRig == null)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 149 needs visibility and realtime rig.");
            }

            visibility.SetActiveAreaForReview(FastVsHouseArea.CentralPlaza);
            realtimeRig.ApplyNowForReview();

            var trackedSpriteCount = 0;
            var block = new MaterialPropertyBlock();
            foreach (var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None))
            {
                if (renderer == null || !renderer.gameObject.scene.IsValid() || !renderer.enabled || !renderer.receiveShadows)
                {
                    continue;
                }

                var material = renderer.sharedMaterial;
                var role = material != null ? material.GetTag(MaterialRoleTagName, false, string.Empty) : string.Empty;
                if (role != FastVsHd2dMaterialRole.SpriteCard.ToString() &&
                    role != FastVsHd2dMaterialRole.PaperCard.ToString())
                {
                    continue;
                }

                if (!material.HasProperty("_WorldLightStrength") ||
                    !material.HasProperty("_WorldShadowReceiveStrength"))
                {
                    continue;
                }

                renderer.GetPropertyBlock(block);
                var worldShadowReceiveStrength = block.GetFloat("_WorldShadowReceiveStrength");
                if (block.GetFloat("_WorldLightStrength") >= 0.17f &&
                    worldShadowReceiveStrength >= 0.02f &&
                    worldShadowReceiveStrength <= 0.04f)
                {
                    trackedSpriteCount++;
                }
            }

            if (trackedSpriteCount < 4)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 149 expected central-plaza sprite/card renderers to receive realtime light tracking, found {trackedSpriteCount}.");
            }
        }

        private static void ValidateHd2dPlazaVisibleCasterCycle150()
        {
            ValidateHd2dPlazaRealtimeSpriteTrackingCycle149();

            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            var realtimeRig = UnityEngine.Object.FindFirstObjectByType<FastVsRealtimeLightShadowRig>();
            if (visibility == null || realtimeRig == null)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 150 needs visibility and realtime rig.");
            }

            visibility.SetActiveAreaForReview(FastVsHouseArea.CentralPlaza);
            realtimeRig.ApplyNowForReview();

            var visibleCasterCount = 0;
            var block = new MaterialPropertyBlock();
            foreach (var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None))
            {
                if (renderer == null || !renderer.gameObject.scene.IsValid() || !renderer.enabled)
                {
                    continue;
                }

                if (!IsCycle150VisibleCentralPlazaCaster(renderer))
                {
                    continue;
                }

                if (renderer.shadowCastingMode != ShadowCastingMode.On || !renderer.receiveShadows)
                {
                    continue;
                }

                var material = renderer.sharedMaterial;
                if (material != null && material.HasProperty("_ShadowReceiveStrength"))
                {
                    renderer.GetPropertyBlock(block);
                    var shadowReceiveStrength = block.GetFloat("_ShadowReceiveStrength");
                    if (shadowReceiveStrength <= 0f ||
                        shadowReceiveStrength > Stage7jCentralPlazaShadowReceiveStrengthMax)
                    {
                        continue;
                    }
                }

                visibleCasterCount++;
            }

            if (visibleCasterCount < 8)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 150 expected visible central-plaza props to cast and receive realtime shadows, found {visibleCasterCount}.");
            }
        }

        private static void ValidateHd2dPlazaVsSkyCameraCycle151()
