            }
        }

        private static void ValidateHd2dPlazaSkyRevealCameraCycle156()
        {
            ValidateHd2dPlazaTrimBroadRealtimeCastersCycle155();

            var controller = UnityEngine.Object.FindFirstObjectByType<TimeWindowPairedSpacePortalController>();
            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            var director = UnityEngine.Object.FindFirstObjectByType<FastVsHouseLightingDirector>();
            var guide = UnityEngine.Object.FindFirstObjectByType<FastVsVisualDirectionGuide>();
            var realtimeRig = UnityEngine.Object.FindFirstObjectByType<FastVsRealtimeLightShadowRig>();
            var camera = Camera.main;
            var mainLight = FindSceneObjectIncludingInactive("Directional Light")?.GetComponent<Light>();
            if (controller == null || visibility == null || director == null || guide == null || realtimeRig == null || camera == null || mainLight == null)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 156 needs controller, visibility, director, guide, realtime rig, camera, and directional light.");
            }

            visibility.SetActiveAreaForReview(FastVsHouseArea.CentralPlaza);
            controller.ForcePlayerCurrentLocalForReview(PlazaFromLibraryTarget);
            guide.ApplyActiveTimeIsolationForReview();
            director.ApplyAreaForReview(FastVsHouseArea.CentralPlaza);
            realtimeRig.ApplyNowForReview();

            var profile = FastVsVisualDirectionGuide.GetFollowCameraProfileForReview(FastVsHouseArea.CentralPlaza);
            ValidateVectorNear("cycle 156 central plaza runtime VS camera offset", profile.PositionOffset, RuntimeVsFollowCameraOffset);
            ValidateVectorNear("cycle 156 central plaza runtime VS look offset", profile.LookOffset, RuntimeVsFollowLookOffset);
            if (Mathf.Abs(profile.FieldOfView - RuntimeVsFollowCameraFov) > 0.01f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 156 central plaza runtime FOV must stay {RuntimeVsFollowCameraFov:0} for shared VS follow, found {profile.FieldOfView:0.0}.");
            }

            var anchorWorld = guide.ResolveActiveCameraAnchorForReview();
            var anchorLocal = controller.CurrentSpaceRootForReview.InverseTransformPoint(anchorWorld);
            ValidateVectorNear("cycle 156 central plaza runtime VS follow anchor", anchorLocal, PlazaFromLibraryTarget);

            ValidateCentralPlazaRuntimeSkyForReview(camera, "cycle 156");
            if (mainLight.type != LightType.Directional ||
                mainLight.shadows != LightShadows.Soft ||
                mainLight.shadowResolution != LightShadowResolution.VeryHigh ||
                (!IsMainDirectionalLightManagedBySunCycleForReview() &&
                 (mainLight.cookie == null || mainLight.cookie.name != "FastVS_CentralPlazaRealtimeSunCookieCycle147")))
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 156 must preserve realtime Directional Light shadows and cookie, found type={mainLight.type}, shadows={mainLight.shadows}, resolution={mainLight.shadowResolution}, cookie={mainLight.cookie}.");
            }

            var enabledPaintedAirCount = 0;
            foreach (var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None))
            {
                if (renderer == null || !renderer.gameObject.scene.IsValid() || !renderer.enabled || !renderer.gameObject.activeInHierarchy)
                {
                    continue;
                }

                var objectName = renderer.gameObject.name;
                if (objectName.Contains("Current_CentralPlaza") &&
                    (objectName.Contains("Air") ||
                     objectName.Contains("Haze") ||
                     objectName.Contains("Veil") ||
                     objectName.Contains("SkyWash") ||
                     objectName.Contains("Sunbreak") ||
                     objectName.Contains("Sunlit") ||
                     objectName.Contains("Painted")))
                {
                    enabledPaintedAirCount++;
                }
            }

            if (enabledPaintedAirCount != 0)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 156 must not rely on enabled painted air/sun plates in central plaza, found {enabledPaintedAirCount}.");
            }
        }

        private static void ValidateHd2dPlazaSkyboxHorizonCycle157()
        {
            ValidateHd2dPlazaSkyRevealCameraCycle156();

            var camera = Camera.main;
            ValidateCentralPlazaRuntimeSkyForReview(camera, "cycle 157");

            var skybox = RenderSettings.skybox;
            if (skybox == null ||
                !skybox.HasProperty("_GroundColor") ||
                !skybox.HasProperty("_SkyTint") ||
                !skybox.HasProperty("_Exposure"))
            {
                throw new InvalidOperationException("House slice validation failed: cycle 157 needs a tunable procedural skybox with ground, tint, and exposure properties.");
            }

            var groundColor = skybox.GetColor("_GroundColor");
            var skyTint = skybox.GetColor("_SkyTint");
            var exposure = skybox.GetFloat("_Exposure");
            if (groundColor.r < 0.28f ||
                groundColor.g < 0.34f ||
                groundColor.b < 0.38f ||
                groundColor.b <= groundColor.r ||
                skyTint.b <= skyTint.r ||
                exposure < 0.60f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 157 skybox horizon must stay blue-gray instead of black/brown, found ground={groundColor}, tint={skyTint}, exposure={exposure:0.00}.");
            }
        }

        private static void ValidateHd2dPlazaRealtimeContrastCycle158()
        {
            ValidateHd2dPlazaSkyboxHorizonCycle157();

            var mainLight = FindSceneObjectIncludingInactive("Directional Light")?.GetComponent<Light>();
            if (mainLight == null)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 158 needs the realtime Directional Light.");
            }

            if (!IsMainDirectionalLightManagedBySunCycleForReview())
            {
                if (mainLight.intensity < 2.28f ||
                    mainLight.intensity > 2.36f ||
                    mainLight.shadowStrength < Stage7jCentralPlazaShadowStrengthMin ||
                    mainLight.shadowStrength > Stage7jCentralPlazaShadowStrengthMax ||
                    mainLight.color.g < 0.95f ||
                    mainLight.color.b < 0.84f)
                {
                    throw new InvalidOperationException($"House slice validation failed: cycle 158 central-plaza light must stay neutral and high-contrast, found intensity={mainLight.intensity:0.00}, shadowStrength={mainLight.shadowStrength:0.000}, color={mainLight.color}.");
                }

                var ambient = RenderSettings.ambientLight;
                if (ambient.r > 0.042f || ambient.g > 0.043f || ambient.b > 0.042f)
                {
                    throw new InvalidOperationException($"House slice validation failed: cycle 158 ambient must stay low so realtime shadows read, found {ambient}.");
                }
            }

            var contrastReceiverCount = 0;
            var block = new MaterialPropertyBlock();
            foreach (var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None))
            {
                if (renderer == null ||
                    !renderer.gameObject.scene.IsValid() ||
                    !renderer.enabled ||
                    !renderer.receiveShadows ||
                    !renderer.gameObject.name.Contains("Current_CentralPlaza"))
                {
                    continue;
                }

                var material = renderer.sharedMaterial;
                if (material == null ||
                    !material.HasProperty("_ShadowReceiveStrength") ||
                    !material.HasProperty("_ShadowTextureStrength") ||
                    !material.HasProperty("_TopLight") ||
                    !material.HasProperty("_FloorShade"))
                {
                    continue;
                }

                renderer.GetPropertyBlock(block);
                var topLight = block.GetColor("_TopLight");
                if (IsStage7PlazaSoftBalanceReceiver(renderer, block) &&
                    topLight.r <= 1.08f &&
                    topLight.b >= 0.92f)
                {
                    contrastReceiverCount++;
                }
            }

            if (contrastReceiverCount < 12)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 158 expected neutral high-contrast realtime receiver property blocks, found {contrastReceiverCount}.");
            }
        }

        private static void ValidateHd2dPlazaNeutralRealtimeShaderCycle159()
        {
            ValidateHd2dPlazaRealtimeContrastCycle158();

            var shaderPath = Path.Combine(Application.dataPath, "Art", "Shaders", "FastVS", "FastVS_SurfaceRampLit.shader");
            var shaderText = File.ReadAllText(shaderPath);
            if (!shaderText.Contains("half3(0.92h, 0.90h, 0.84h)") ||
                !shaderText.Contains("half3(0.54h, 0.55h, 0.52h)") ||
                !shaderText.Contains("lerp(0.76h, 1.08h"))
            {
                throw new InvalidOperationException("House slice validation failed: cycle 159 SurfaceRampLit must use neutral realtime sun/shadow tints.");
            }

            if (shaderText.Contains("half3(0.92h, 0.84h, 0.72h)") ||
                shaderText.Contains("half3(0.70h, 0.62h, 0.50h)") ||
                shaderText.Contains("lerp(0.78h, 1.14h"))
            {
                throw new InvalidOperationException("House slice validation failed: cycle 159 must not restore the previous yellow/brown realtime shader tint.");
            }
        }

        private static void ValidateHd2dPlazaNeutralBaseColorCycle160()
        {
            ValidateHd2dPlazaNeutralRealtimeShaderCycle159();

            var neutralFloorCount = 0;
            var block = new MaterialPropertyBlock();
            foreach (var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None))
            {
                if (renderer == null ||
                    !renderer.gameObject.scene.IsValid() ||
                    !renderer.enabled ||
                    !renderer.receiveShadows ||
                    !renderer.gameObject.name.Contains("Current_CentralPlaza"))
                {
                    continue;
                }

                var surface = renderer.GetComponent<FastVsHd2dSurfaceProfile>();
                var isSurfaceFloor =
                    surface != null &&
                    (surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Floor ||
                     surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Ground ||
                     surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Road);
                var objectName = renderer.gameObject.name;
                var isNamedFloor =
                    objectName.Contains("Floor") ||
                    objectName.Contains("Ground") ||
                    objectName.Contains("Road") ||
                    objectName.Contains("Path") ||
                    objectName.Contains("Stone") ||
                    objectName.Contains("Cobble") ||
                    objectName.Contains("Pavement") ||
                    objectName.Contains("Tile") ||
                    objectName.Contains("Step") ||
                    objectName.Contains("Terrace") ||
                    objectName.Contains("Lane") ||
                    objectName.Contains("Square");
                if (!isSurfaceFloor && !isNamedFloor)
                {
                    continue;
                }

                var material = renderer.sharedMaterial;
                if (material == null || !material.HasProperty("_BaseColor"))
                {
                    continue;
                }

                renderer.GetPropertyBlock(block);
                var baseColor = block.GetColor("_BaseColor");
                if (baseColor.r <= 0.68f &&
                    baseColor.g >= 0.66f &&
                    baseColor.b >= 0.72f &&
                    baseColor.b > baseColor.r)
                {
                    neutralFloorCount++;
                }
            }

            if (neutralFloorCount < 4)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 160 expected neutral base-color property blocks on central-plaza floor receivers, found {neutralFloorCount}.");
            }
        }

        private static void ValidateHd2dGlobalRealtimeLightingCycle161()
        {
            ValidateHd2dPlazaNeutralBaseColorCycle160();

            var controller = UnityEngine.Object.FindFirstObjectByType<TimeWindowPairedSpacePortalController>();
            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            var director = UnityEngine.Object.FindFirstObjectByType<FastVsHouseLightingDirector>();
            var guide = UnityEngine.Object.FindFirstObjectByType<FastVsVisualDirectionGuide>();
            var realtimeRig = UnityEngine.Object.FindFirstObjectByType<FastVsRealtimeLightShadowRig>();
            var mainLight = FindSceneObjectIncludingInactive("Directional Light")?.GetComponent<Light>();
            if (controller == null || visibility == null || director == null || guide == null || realtimeRig == null || mainLight == null)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 161 needs controller, visibility, lighting director, guide, realtime rig, and directional light.");
            }

            var block = new MaterialPropertyBlock();

            void ValidateArea(FastVsHouseArea area, Vector3 playerLocalPosition, int minReceiverCount, int minCasterCount, float minShadowStrength)
            {
                visibility.SetActiveAreaForReview(area);
                controller.ForcePlayerCurrentLocalForReview(playerLocalPosition);
                guide.ApplyActiveTimeIsolationForReview();
                director.ApplyAreaForReview(area);
                realtimeRig.ApplyNowForReview();

                if (mainLight.type != LightType.Directional ||
                    mainLight.shadows != LightShadows.Soft ||
                    mainLight.shadowResolution != LightShadowResolution.VeryHigh ||
                    (!IsMainDirectionalLightManagedBySunCycleForReview() && mainLight.shadowStrength < minShadowStrength) ||
                    mainLight.shadowBias > 0.014f ||
                    mainLight.shadowNormalBias > 0.11f)
                {
                    throw new InvalidOperationException($"House slice validation failed: cycle 161 {area} must use high-resolution realtime Directional Light shadows, found type={mainLight.type}, shadows={mainLight.shadows}, resolution={mainLight.shadowResolution}, strength={mainLight.shadowStrength:0.000}, bias={mainLight.shadowBias:0.000}, normalBias={mainLight.shadowNormalBias:0.000}.");
                }

                if (!IsMainDirectionalLightManagedBySunCycleForReview() && area == FastVsHouseArea.CentralPlaza)
                {
                    if (mainLight.cookie == null || mainLight.cookie.name != "FastVS_CentralPlazaRealtimeSunCookieCycle147")
                    {
                        throw new InvalidOperationException("House slice validation failed: cycle 161 central plaza must keep the realtime sun cookie.");
                    }
                }
                else if (!IsMainDirectionalLightManagedBySunCycleForReview() && area == FastVsHouseArea.Exterior)
                {
                    if (mainLight.cookie == null || mainLight.cookie.name != Stage3ExteriorSunCookieName)
                    {
                        throw new InvalidOperationException($"House slice validation failed: cycle 161 exterior must use the Stage 3 realtime sun cookie {Stage3ExteriorSunCookieName}.");
                    }
                }
                else if (!IsMainDirectionalLightManagedBySunCycleForReview() && mainLight.cookie != null && mainLight.cookie.name == "FastVS_CentralPlazaRealtimeSunCookieCycle147")
                {
                    throw new InvalidOperationException($"House slice validation failed: cycle 161 {area} must not borrow the central-plaza cookie.");
                }
                else if (!IsMainDirectionalLightManagedBySunCycleForReview() && mainLight.cookie != null && mainLight.cookie.name == Stage3ExteriorSunCookieName)
                {
                    throw new InvalidOperationException($"House slice validation failed: cycle 161 {area} must not borrow the exterior Stage 3 cookie.");
                }

                var ambientMax = area == FastVsHouseArea.CentralPlaza
                    ? 0.060f
                    : area == FastVsHouseArea.Exterior ? 0.205f : 0.225f;
                if (!IsMainDirectionalLightManagedBySunCycleForReview() &&
                    (RenderSettings.fog || RenderSettings.ambientLight.maxColorComponent > ambientMax))
                {
                    throw new InvalidOperationException($"House slice validation failed: cycle 161 {area} must use bounded review ambient realtime lighting, found fog={RenderSettings.fog}, ambient={RenderSettings.ambientLight}.");
                }

                var receiverCount = 0;
                var casterCount = 0;
                foreach (var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None))
                {
                    if (renderer == null ||
                        !renderer.gameObject.scene.IsValid() ||
                        !renderer.enabled ||
                        !renderer.gameObject.activeInHierarchy ||
                        !IsCycle161RendererInArea(renderer, area))
                    {
                        continue;
                    }

                    var material = renderer.sharedMaterial;
                    if (renderer.receiveShadows &&
                        material != null &&
                        material.HasProperty("_DirectionalLightStrength") &&
                        material.HasProperty("_ShadowReceiveStrength"))
                    {
                        renderer.GetPropertyBlock(block);
                        var baseColor = material.HasProperty("_BaseColor") ? block.GetColor("_BaseColor") : Color.clear;
                        var isCentralPlaza = area == FastVsHouseArea.CentralPlaza;
                        var isReceiverGrade = isCentralPlaza
                            ? IsStage7PlazaSoftBalanceReceiver(renderer, block)
                            : block.GetFloat("_DirectionalLightStrength") >= 0.90f &&
                              block.GetFloat("_ShadowReceiveStrength") > 0f &&
                              block.GetFloat("_ShadowReceiveStrength") <= Stage7jCentralPlazaShadowReceiveStrengthMax;
                        if (isReceiverGrade &&
                            (baseColor.a <= 0f || baseColor.b >= baseColor.r))
                        {
                            receiverCount++;
                        }
                    }

                    if ((renderer.shadowCastingMode == ShadowCastingMode.On ||
                         renderer.shadowCastingMode == ShadowCastingMode.ShadowsOnly) &&
                        IsCycle161LikelyRealtimeCaster(renderer.gameObject.name))
                    {
                        casterCount++;
                    }
                }

                if (receiverCount < minReceiverCount)
                {
                    throw new InvalidOperationException($"House slice validation failed: cycle 161 expected global realtime receiver grade in {area}, found {receiverCount}.");
                }

                if (casterCount < minCasterCount)
                {
                    throw new InvalidOperationException($"House slice validation failed: cycle 161 expected visible realtime casters in {area}, found {casterCount}.");
                }
            }

            ValidateArea(FastVsHouseArea.Exterior, HouseExteriorCenter + new Vector3(1.18f, 0.02f, 1.00f), 2, 1, 0.92f);
            ValidateArea(FastVsHouseArea.CentralPlaza, PlazaFromLibraryTarget, 4, 4, 0.98f);
            ValidateArea(FastVsHouseArea.Library, LibraryVsCenter + new Vector3(0.92f, 0.02f, -1.82f), 2, 1, 0.92f);
        }

        private static bool IsCycle161RendererInArea(Renderer renderer, FastVsHouseArea area)
        {
            var surface = renderer.GetComponent<FastVsHd2dSurfaceProfile>();
            if (surface != null)
            {
                return surface.IsCurrentWorldForReview && surface.AreaIdForReview == area;
            }

            var name = renderer.gameObject.name;
            if (area == FastVsHouseArea.Exterior)
            {
                return name.Contains("Current_HouseExterior");
            }

            if (area == FastVsHouseArea.CentralPlaza)
            {
                return name.Contains("Current_CentralPlaza");
            }

            return area == FastVsHouseArea.Library && name.Contains("Current_Library");
        }

        private static bool IsCycle161LikelyRealtimeCaster(string name)
        {
            if (string.IsNullOrEmpty(name) ||
                name.Contains("Shadow") ||
                name.Contains("Light") ||
                name.Contains("Sun") ||
                name.Contains("Haze") ||
                name.Contains("Veil") ||
                name.Contains("Wash") ||
                name.Contains("Sky") ||
                name.Contains("Backdrop") ||
                name.Contains("Painted") ||
                name.Contains("Reference"))
            {
                return false;
            }

            return name.Contains("Tree") ||
                   name.Contains("Fountain") ||
                   name.Contains("Market") ||
                   name.Contains("Crate") ||
                   name.Contains("Board") ||
                   name.Contains("Post") ||
                   name.Contains("Barrel") ||
                   name.Contains("Fence") ||
                   name.Contains("Shelf") ||
                   name.Contains("Book") ||
                   name.Contains("Table") ||
                   name.Contains("Chair") ||
                   name.Contains("Door") ||
                   name.Contains("Window") ||
                   name.Contains("Trim") ||
                   name.Contains("Frame");
        }

        private static void ValidateHd2dGlobalRealtimeCameraExposureCycle162()
        {
            ValidateHd2dGlobalRealtimeLightingCycle161();

            var controller = UnityEngine.Object.FindFirstObjectByType<TimeWindowPairedSpacePortalController>();
            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            var director = UnityEngine.Object.FindFirstObjectByType<FastVsHouseLightingDirector>();
            var guide = UnityEngine.Object.FindFirstObjectByType<FastVsVisualDirectionGuide>();
            var realtimeRig = UnityEngine.Object.FindFirstObjectByType<FastVsRealtimeLightShadowRig>();
            var camera = Camera.main;
            var mainLight = FindSceneObjectIncludingInactive("Directional Light")?.GetComponent<Light>();
            if (controller == null || visibility == null || director == null || guide == null || realtimeRig == null || camera == null || mainLight == null)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 162 needs controller, visibility, lighting director, guide, realtime rig, camera, and directional light.");
            }

            var exteriorProfile = FastVsVisualDirectionGuide.GetFollowCameraProfileForReview(FastVsHouseArea.Exterior);
            ValidateVectorNear("cycle 162 exterior runtime VS camera offset", exteriorProfile.PositionOffset, RuntimeVsFollowCameraOffset);
            ValidateVectorNear("cycle 162 exterior runtime VS camera look", exteriorProfile.LookOffset, RuntimeVsFollowLookOffset);
            if (Mathf.Abs(exteriorProfile.FieldOfView - RuntimeVsFollowCameraFov) > 0.01f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 162 exterior runtime FOV must be {RuntimeVsFollowCameraFov:0}, found {exteriorProfile.FieldOfView:0.0}.");
            }

            var libraryProfile = FastVsVisualDirectionGuide.GetFollowCameraProfileForReview(FastVsHouseArea.Library);
            ValidateVectorNear("cycle 162 library runtime VS camera offset", libraryProfile.PositionOffset, RuntimeVsFollowCameraOffset);
            ValidateVectorNear("cycle 162 library runtime VS camera look", libraryProfile.LookOffset, RuntimeVsFollowLookOffset);
            if (Mathf.Abs(libraryProfile.FieldOfView - RuntimeVsFollowCameraFov) > 0.01f)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 162 library runtime FOV must be {RuntimeVsFollowCameraFov:0}, found {libraryProfile.FieldOfView:0.0}.");
            }

            visibility.SetActiveAreaForReview(FastVsHouseArea.Exterior);
            controller.ForcePlayerCurrentLocalForReview(HouseExteriorCenter + new Vector3(1.18f, 0.02f, 1.00f));
            guide.ApplyActiveTimeIsolationForReview();
            director.ApplyAreaForReview(FastVsHouseArea.Exterior);
            realtimeRig.ApplyNowForReview();
            if (camera.clearFlags != CameraClearFlags.Skybox ||
                RenderSettings.skybox == null ||
                RenderSettings.skybox.name != "FastVS_ExteriorRuntimeSkyboxCycle162")
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 162 exterior must use the runtime procedural skybox instead of the flat gray background, found clear={camera.clearFlags}, skybox={RenderSettings.skybox}.");
            }

            visibility.SetActiveAreaForReview(FastVsHouseArea.Library);
            controller.ForcePlayerCurrentLocalForReview(LibraryVsCenter + new Vector3(0.92f, 0.02f, -1.82f));
            guide.ApplyActiveTimeIsolationForReview();
            director.ApplyAreaForReview(FastVsHouseArea.Library);
            realtimeRig.ApplyNowForReview();
            if (!IsMainDirectionalLightManagedBySunCycleForReview() &&
                (mainLight.intensity < 1.65f ||
                RenderSettings.ambientLight.r < 0.200f ||
                RenderSettings.ambientLight.maxColorComponent > 0.225f))
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 162 library must be readable without painted haze, found intensity={mainLight.intensity:0.00}, ambient={RenderSettings.ambientLight}.");
            }

            ValidateCycle162DirectReceiverGrade(FastVsHouseArea.Exterior, 2);
            ValidateCycle162DirectReceiverGrade(FastVsHouseArea.CentralPlaza, 4);
            ValidateCycle162DirectReceiverGrade(FastVsHouseArea.Library, 2);
        }

        private static void ValidateCycle162DirectReceiverGrade(FastVsHouseArea area, int minReceiverCount)
        {
            var block = new MaterialPropertyBlock();
            var receiverCount = 0;
            foreach (var renderer in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None))
            {
                if (renderer == null ||
                    !renderer.gameObject.scene.IsValid() ||
                    !renderer.enabled ||
                    !renderer.receiveShadows ||
                    !IsCycle161RendererInArea(renderer, area))
                {
                    continue;
                }

                var material = renderer.sharedMaterial;
                if (material == null ||
                    !material.HasProperty("_DirectionalLightStrength") ||
                    !material.HasProperty("_ShadowReceiveStrength") ||
                    !material.HasProperty("_ShadowTextureStrength"))
                {
                    continue;
                }

                renderer.GetPropertyBlock(block);
                var isCentralPlaza = area == FastVsHouseArea.CentralPlaza;
                if (isCentralPlaza
                        ? IsStage7PlazaSoftBalanceReceiver(renderer, block)
                        : block.GetFloat("_DirectionalLightStrength") >= 0.90f &&
                          block.GetFloat("_ShadowReceiveStrength") > 0f &&
                          block.GetFloat("_ShadowReceiveStrength") <= Stage7jCentralPlazaShadowReceiveStrengthMax &&
                          block.GetFloat("_ShadowTextureStrength") <= Stage7jCentralPlazaShadowTextureStrengthMax)
                {
                    receiverCount++;
                }
            }

            if (receiverCount < minReceiverCount)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 162 expected stronger realtime direct-light receiver grade in {area}, found {receiverCount}.");
            }
        }

        private static void ValidateHd2dGlobalRealtimeExteriorAnchorCycle163()
        {
            ValidateHd2dGlobalRealtimeCameraExposureCycle162();

            var controller = UnityEngine.Object.FindFirstObjectByType<TimeWindowPairedSpacePortalController>();
            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            var director = UnityEngine.Object.FindFirstObjectByType<FastVsHouseLightingDirector>();
            var guide = UnityEngine.Object.FindFirstObjectByType<FastVsVisualDirectionGuide>();
            var realtimeRig = UnityEngine.Object.FindFirstObjectByType<FastVsRealtimeLightShadowRig>();
            if (controller == null || visibility == null || director == null || guide == null || realtimeRig == null)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 163 needs controller, visibility, lighting director, guide, and realtime rig.");
            }

            visibility.SetActiveAreaForReview(FastVsHouseArea.Exterior);
            controller.ForcePlayerCurrentLocalForReview(HouseExteriorCenter + new Vector3(1.18f, 0.02f, 1.00f));
            guide.ApplyActiveTimeIsolationForReview();
            director.ApplyAreaForReview(FastVsHouseArea.Exterior);
            realtimeRig.ApplyNowForReview();

            var anchorWorld = guide.ResolveActiveCameraAnchorForReview();
            var anchorLocal = controller.CurrentSpaceRootForReview.InverseTransformPoint(anchorWorld);
            var playerLocal = HouseExteriorCenter + new Vector3(1.18f, 0.02f, 1.00f);
            ValidateVectorNear("cycle 163 exterior runtime VS follow anchor", anchorLocal, playerLocal);

            var exteriorProfile = FastVsVisualDirectionGuide.GetFollowCameraProfileForReview(FastVsHouseArea.Exterior);
            ValidateVectorNear("cycle 163 exterior runtime VS follow camera offset", exteriorProfile.PositionOffset, RuntimeVsFollowCameraOffset);
            ValidateVectorNear("cycle 163 exterior runtime VS follow camera look", exteriorProfile.LookOffset, RuntimeVsFollowLookOffset);
        }

        private static void ValidateHd2dExteriorExitTreeClearanceCycle164()
        {
            ValidateHd2dGlobalRealtimeCameraExposureCycle162();

            var controller = UnityEngine.Object.FindFirstObjectByType<TimeWindowPairedSpacePortalController>();
            var visibility = UnityEngine.Object.FindFirstObjectByType<FastVsHouseAreaVisibility>();
            var interiorToExterior = GameObject.Find("FastVS_DoorTransition_Interior_To_Exterior")?.GetComponent<FastVsAreaDoorTransition>();
            if (controller == null || visibility == null || interiorToExterior == null)
            {
                throw new InvalidOperationException("House slice validation failed: cycle 164 needs controller, visibility, and the interior-to-exterior door transition.");
            }

            ValidateExteriorDoorExitCameraClearance(controller, visibility, interiorToExterior);
        }

        private static void ValidateCycle155CasterMeshBounds(string objectName, float maxX, float maxZ)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            var renderer = sceneObject != null ? sceneObject.GetComponent<Renderer>() : null;
            var filter = sceneObject != null ? sceneObject.GetComponent<MeshFilter>() : null;
            var mesh = filter != null ? filter.sharedMesh : null;
            if (sceneObject == null || renderer == null || mesh == null)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 155 missing trimmed realtime caster {objectName}.");
            }

            var size = mesh.bounds.size;
            if (!renderer.enabled ||
                renderer.shadowCastingMode != ShadowCastingMode.ShadowsOnly ||
                renderer.receiveShadows ||
                size.x > maxX ||
                size.z > maxZ)
            {
                throw new InvalidOperationException($"House slice validation failed: cycle 155 caster {objectName} should stay realtime but no longer be a broad slab, found enabled={renderer.enabled}, casting={renderer.shadowCastingMode}, receive={renderer.receiveShadows}, bounds={size}.");
            }
        }

        private static bool IsCycle150VisibleCentralPlazaCaster(Renderer renderer)
        {
            var name = renderer.gameObject.name;
            var surface = renderer.GetComponent<FastVsHd2dSurfaceProfile>();
            if (surface != null &&
                surface.AreaIdForReview == FastVsHouseArea.CentralPlaza &&
                surface.IsCurrentWorldForReview &&
                (surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Furniture ||
                 surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Prop ||
                 surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Window ||
                 surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Bookshelf))
            {
                return !IsCycle150SuppressedVisibleCasterName(name);
            }

            return IsCycle150VisibleCentralPlazaCasterName(name);
        }

