        private static void ValidateStaticDirectionalCastShadowObject(string objectName, string expectedParentName, Vector3 expectedLocalPosition, Vector3 expectedLocalScale)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing static directional-cast-shadow object {objectName}.");
            }

            var renderer = sceneObject.GetComponent<MeshRenderer>();
            if (renderer == null || renderer.sharedMaterial == null || !renderer.enabled)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must have an enabled MeshRenderer with a material.");
            }

            if (sceneObject.GetComponent<Collider>() != null || sceneObject.GetComponentsInChildren<Collider>(true).Length > 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must remain non-colliding.");
            }

            if (sceneObject.transform.parent == null || sceneObject.transform.parent.name != expectedParentName)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must stay parented under {expectedParentName}.");
            }

            if (Quaternion.Angle(sceneObject.transform.localRotation, Quaternion.Euler(90f, 0f, StaticDirectionalCastShadowYawDegrees)) > 1.5f)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must stay horizontal with a local yaw near {StaticDirectionalCastShadowYawDegrees:0.#} degrees.");
            }

            ValidateVectorNear($"{objectName} local position", sceneObject.transform.localPosition, expectedLocalPosition);
            ValidateVectorNear($"{objectName} local scale", sceneObject.transform.localScale, expectedLocalScale);

            if (sceneObject.transform.localScale.x <= sceneObject.transform.localScale.y * 2f)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must stay stretched sideways rather than square.");
            }

            if (renderer.shadowCastingMode != ShadowCastingMode.Off || renderer.receiveShadows)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep real shadow casting disabled.");
            }

            var material = renderer.sharedMaterial;
            var materialName = material.name ?? string.Empty;
            if (materialName.IndexOf("static_directional_cast_shadow", StringComparison.OrdinalIgnoreCase) < 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must use the generated static directional cast shadow material.");
            }

            if (!string.Equals(material.GetTag(MaterialRoleTagName, false, string.Empty), FastVsHd2dMaterialRole.ContactShadow.ToString(), StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep the contact-shadow material role.");
            }

            if (material.renderQueue < 2992 || material.renderQueue > 2998)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep a transparent overlay renderQueue in the 2992-2998 range.");
            }

            var texture = ResolveMaterialTexture(material) as Texture2D;
            if (texture == null || !string.Equals(texture.name, "FastVS_House_static_directional_cast_shadow_soft", StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must reference the generated static directional cast shadow texture.");
            }

            var validationTexture = LoadStaticDirectionalCastShadowTextureForValidation();
            if (validationTexture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} static directional cast shadow PNG asset is missing.");
            }

            var importer = AssetImporter.GetAtPath($"{TextureDirectory}/FastVS_House_static_directional_cast_shadow_soft.png") as TextureImporter;
            if (importer == null ||
                !importer.alphaIsTransparency ||
                importer.mipmapEnabled ||
                importer.filterMode != FilterMode.Bilinear ||
                importer.wrapMode != TextureWrapMode.Clamp ||
                !importer.isReadable ||
                importer.textureCompression != TextureImporterCompression.Uncompressed)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} static directional cast shadow PNG importer settings are incorrect.");
            }

            if (validationTexture.width != 160 || validationTexture.height != 80)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} static directional cast shadow PNG must stay at 160x80.");
            }

            if (TextureAlphaChannelIsEmpty(validationTexture))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} static directional shadow texture alpha must not be empty.");
            }

            ValidateStaticDirectionalCastShadowTextureMetrics(validationTexture, $"{objectName} static_directional_cast_shadow_soft");

            UnityEngine.Object.DestroyImmediate(validationTexture);
        }

        private static void ValidateStaticDirectionalCastShadowTextureMetrics(Texture2D validationTexture, string context)
        {
            var centerX = validationTexture.width / 2;
            var centerY = validationTexture.height / 2;
            var coreX = Mathf.Min(64, validationTexture.width - 1);
            var coreY = Mathf.Min(42, validationTexture.height - 1);
            var tailX = Mathf.Min(108, validationTexture.width - 1);
            var tailY = Mathf.Min(40, validationTexture.height - 1);
            var centerAlpha = validationTexture.GetPixel(centerX, centerY).a;
            var coreAlpha = validationTexture.GetPixel(coreX, coreY).a;
            var tailAlpha = validationTexture.GetPixel(tailX, tailY).a;
            var leftEdgeAlpha = validationTexture.GetPixel(0, centerY).a;
            var rightEdgeAlpha = validationTexture.GetPixel(validationTexture.width - 1, centerY).a;
            var cornerAlpha = validationTexture.GetPixel(0, 0).a;
            var topRightCornerAlpha = validationTexture.GetPixel(validationTexture.width - 1, 0).a;
            var bottomLeftCornerAlpha = validationTexture.GetPixel(0, validationTexture.height - 1).a;
            var bottomRightCornerAlpha = validationTexture.GetPixel(validationTexture.width - 1, validationTexture.height - 1).a;
            var maxAlpha = 0f;

            foreach (var pixel in validationTexture.GetPixels32())
            {
                maxAlpha = Mathf.Max(maxAlpha, pixel.a / 255f);
            }

            if (centerAlpha < 0.22f || centerAlpha > 0.34f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} center alpha must stay in the 0.22-0.34 range, but was {centerAlpha:0.000}.");
            }

            if (coreAlpha < 0.22f || coreAlpha > 0.42f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} core alpha at ({coreX},{coreY}) must stay in the 0.22-0.42 range, but was {coreAlpha:0.000}.");
            }

            if (tailAlpha < leftEdgeAlpha + 0.025f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} tail alpha at ({tailX},{tailY}) must exceed the left edge alpha by at least 0.025, but tail={tailAlpha:0.000}, left={leftEdgeAlpha:0.000}.");
            }

            if (tailAlpha >= coreAlpha || tailAlpha >= maxAlpha)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} tail alpha at ({tailX},{tailY}) must stay softer than the core and max alpha, but tail={tailAlpha:0.000}, core={coreAlpha:0.000}, max={maxAlpha:0.000}.");
            }

            if (leftEdgeAlpha > centerAlpha * 0.55f || rightEdgeAlpha > centerAlpha * 0.55f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} edge alpha falloff looks broken. left={leftEdgeAlpha:0.000}, right={rightEdgeAlpha:0.000}, center={centerAlpha:0.000}.");
            }

            if (cornerAlpha > 0.02f || topRightCornerAlpha > 0.02f || bottomLeftCornerAlpha > 0.02f || bottomRightCornerAlpha > 0.02f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} corner alpha must stay near transparent. tl={cornerAlpha:0.000}, tr={topRightCornerAlpha:0.000}, bl={bottomLeftCornerAlpha:0.000}, br={bottomRightCornerAlpha:0.000}.");
            }

            if (maxAlpha < 0.34f || maxAlpha > 0.42f)
            {
                throw new InvalidOperationException($"House slice validation failed: {context} max alpha must stay in the 0.34-0.42 range, but was {maxAlpha:0.000}.");
            }
        }

        private static Texture2D LoadSurfaceDirectionalShadeOverlayTextureForValidation()
        {
            var path = $"{TextureDirectory}/FastVS_House_surface_directional_shade_overlay_soft.png";
            if (!File.Exists(path))
            {
                return null;
            }

            var bytes = File.ReadAllBytes(path);
            var texture = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            if (!texture.LoadImage(bytes, false))
            {
                UnityEngine.Object.DestroyImmediate(texture);
                throw new InvalidOperationException($"House slice validation failed: surface directional shade overlay PNG could not be read at {path}.");
            }

            texture.name = "FastVS_House_surface_directional_shade_overlay_soft";
            return texture;
        }

        private static void ValidateSurfaceDirectionalShadeOverlayTexture()
        {
            var path = $"{TextureDirectory}/FastVS_House_surface_directional_shade_overlay_soft.png";
            var validationTexture = LoadSurfaceDirectionalShadeOverlayTextureForValidation();
            if (validationTexture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: surface directional shade overlay PNG asset is missing at {path}.");
            }

            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer == null ||
                !importer.alphaIsTransparency ||
                importer.mipmapEnabled ||
                importer.filterMode != FilterMode.Bilinear ||
                importer.wrapMode != TextureWrapMode.Clamp ||
                !importer.isReadable ||
                importer.textureCompression != TextureImporterCompression.Uncompressed)
            {
                throw new InvalidOperationException($"House slice validation failed: surface directional shade overlay PNG importer settings are incorrect at {path}.");
            }

            if (validationTexture.width != 128 || validationTexture.height != 128)
            {
                throw new InvalidOperationException($"House slice validation failed: surface directional shade overlay PNG must stay at 128x128: {path}");
            }

            if (TextureAlphaChannelIsEmpty(validationTexture))
            {
                throw new InvalidOperationException("House slice validation failed: surface directional shade overlay texture alpha must not be empty.");
            }

            var centerAlpha = validationTexture.GetPixel(validationTexture.width / 2, validationTexture.height / 2).a;
            var leftEdgeAlpha = validationTexture.GetPixel(0, validationTexture.height / 2).a;
            var rightEdgeAlpha = validationTexture.GetPixel(validationTexture.width - 1, validationTexture.height / 2).a;
            var topLeftInteriorAlpha = validationTexture.GetPixel(32, 32).a;
            var lowerRightInteriorAlpha = validationTexture.GetPixel(96, 96).a;
            var topLeftCornerAlpha = validationTexture.GetPixel(0, 0).a;
            var topRightCornerAlpha = validationTexture.GetPixel(validationTexture.width - 1, 0).a;
            var bottomLeftCornerAlpha = validationTexture.GetPixel(0, validationTexture.height - 1).a;
            var bottomRightCornerAlpha = validationTexture.GetPixel(validationTexture.width - 1, validationTexture.height - 1).a;
            var maxAlpha = 0f;
            foreach (var pixel in validationTexture.GetPixels32())
            {
                maxAlpha = Mathf.Max(maxAlpha, pixel.a / 255f);
            }

            if (centerAlpha < 0.17f || centerAlpha > 0.21f)
            {
                throw new InvalidOperationException($"House slice validation failed: surface_directional_shade_overlay_soft center alpha must stay in the 0.17-0.21 range, but was {centerAlpha:0.000}.");
            }

            if (topLeftInteriorAlpha <= lowerRightInteriorAlpha + 0.015f)
            {
                throw new InvalidOperationException($"House slice validation failed: surface_directional_shade_overlay_soft must keep a stronger upper-left falloff than lower-right falloff. topLeftInterior={topLeftInteriorAlpha:0.000}, lowerRightInterior={lowerRightInteriorAlpha:0.000}.");
            }

            if (leftEdgeAlpha > centerAlpha * 0.60f || rightEdgeAlpha > centerAlpha * 0.60f)
            {
                throw new InvalidOperationException($"House slice validation failed: surface_directional_shade_overlay_soft alpha falloff looks broken. left={leftEdgeAlpha:0.000}, right={rightEdgeAlpha:0.000}, center={centerAlpha:0.000}.");
            }

            if (topLeftCornerAlpha > 0.012f || topRightCornerAlpha > 0.012f || bottomLeftCornerAlpha > 0.012f || bottomRightCornerAlpha > 0.012f)
            {
                throw new InvalidOperationException($"House slice validation failed: surface_directional_shade_overlay_soft corner alpha must stay near transparent. tl={topLeftCornerAlpha:0.000}, tr={topRightCornerAlpha:0.000}, bl={bottomLeftCornerAlpha:0.000}, br={bottomRightCornerAlpha:0.000}.");
            }

            if (maxAlpha < 0.27f || maxAlpha > 0.31f)
            {
                throw new InvalidOperationException($"House slice validation failed: surface_directional_shade_overlay_soft max alpha must stay in the 0.27-0.31 range, but was {maxAlpha:0.000}.");
            }

            UnityEngine.Object.DestroyImmediate(validationTexture);
        }

        private static void ValidateSurfaceDirectionalShadeOverlayObject(string objectName, string expectedParentName, Vector3 expectedLocalPosition, Vector3 expectedLocalScale)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing surface directional shade overlay object {objectName}.");
            }

            var renderer = sceneObject.GetComponent<MeshRenderer>();
            if (renderer == null || renderer.sharedMaterial == null || !renderer.enabled)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must have an enabled MeshRenderer with a material.");
            }

            if (sceneObject.GetComponent<Collider>() != null || sceneObject.GetComponentsInChildren<Collider>(true).Length > 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must remain non-colliding.");
            }

            if (sceneObject.transform.parent == null || sceneObject.transform.parent.name != expectedParentName)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must stay parented under {expectedParentName}.");
            }

            if (Mathf.Abs(Mathf.DeltaAngle(sceneObject.transform.localEulerAngles.x, 90f)) < 1.5f)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must stay vertical and not rotate onto the ground plane.");
            }

            ValidateVectorNear($"{objectName} local position", sceneObject.transform.localPosition, expectedLocalPosition);
            ValidateVectorNear($"{objectName} local scale", sceneObject.transform.localScale, expectedLocalScale);

            if (sceneObject.transform.localScale.y < 1.5f || sceneObject.transform.localScale.x < 0.9f)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must stay large enough to read as a vertical surface overlay.");
            }

            if (renderer.shadowCastingMode != ShadowCastingMode.Off || renderer.receiveShadows)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep real shadow casting disabled.");
            }

            var material = renderer.sharedMaterial;
            var materialName = material.name ?? string.Empty;
            if (materialName.IndexOf("surface_directional_shade_overlay", StringComparison.OrdinalIgnoreCase) < 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must use the generated surface directional shade overlay material.");
            }

            if (!string.Equals(material.GetTag(MaterialRoleTagName, false, string.Empty), FastVsHd2dMaterialRole.ContactShadow.ToString(), StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep the contact-shadow material role.");
            }

            if (material.renderQueue < 2997 || material.renderQueue > 3002)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep a transparent overlay renderQueue in the 2997-3002 range.");
            }

            var tint = Color.white;
            if (material.HasProperty("_BaseColor"))
            {
                tint = material.GetColor("_BaseColor");
            }
            else if (material.HasProperty("_Color"))
            {
                tint = material.GetColor("_Color");
            }

            if (tint.a < 0.75f || tint.a > 0.90f)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} material tint alpha must stay in the 0.75-0.90 range, but was {tint.a:0.000}.");
            }

            var texture = ResolveMaterialTexture(material) as Texture2D;
            if (texture == null || !string.Equals(texture.name, "FastVS_House_surface_directional_shade_overlay_soft", StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must reference the generated surface directional shade overlay texture.");
            }

            ValidateSurfaceDirectionalShadeOverlayTexture();
        }

        private static void ValidateFastVsHd2dSurfaceDirectionalShadeOverlays()
        {
            ValidateSurfaceDirectionalShadeOverlayTexture();

            ValidateSurfaceDirectionalShadeOverlayObject(
                "Current_HouseExterior_SurfaceDirectionalShade_FacadeLeft",
                "Current_HouseExteriorMap_SeparateSpace",
                HouseExteriorCenter + new Vector3(-2.60f, 1.10f, -1.44f),
                HouseSurfaceDirectionalShadeOverlayCurrentScale);

            ValidateSurfaceDirectionalShadeOverlayObject(
                "Past_HouseExterior_SurfaceDirectionalShade_FacadeLeft",
                "Past_HouseExteriorMap_SeparateSpace",
                HouseExteriorCenter + new Vector3(-2.60f, 1.10f, -1.44f),
                HouseSurfaceDirectionalShadeOverlayPastScale);

            ValidateSurfaceDirectionalShadeOverlayObject(
                "Current_CentralPlaza_SurfaceDirectionalShade_LibraryFacade",
                "Current_CentralPlazaMap_SeparateSpace",
                CentralPlazaVsCenter + new Vector3(0f, 1.46f, 7.89f),
                CentralPlazaSurfaceDirectionalShadeOverlayCurrentScale);

            ValidateSurfaceDirectionalShadeOverlayObject(
                "Past_CentralPlaza_SurfaceDirectionalShade_LibraryFacade",
                "Past_CentralPlazaMap_SeparateSpace",
                CentralPlazaVsCenter + new Vector3(0f, 1.46f, 7.89f),
                CentralPlazaSurfaceDirectionalShadeOverlayPastScale);

            ValidateSurfaceDirectionalShadeOverlayObject(
                "Current_Library_SurfaceDirectionalShade_BackShelf",
                "Current_LibraryMap_SeparateSpace",
                LibraryVsCenter + new Vector3(0f, 1.44f, 6.97f),
                LibrarySurfaceDirectionalShadeOverlayCurrentScale);

            ValidateSurfaceDirectionalShadeOverlayObject(
                "Past_Library_SurfaceDirectionalShade_BackShelf",
                "Past_LibraryMap_SeparateSpace",
                LibraryVsCenter + new Vector3(0f, 1.44f, 6.97f),
                LibrarySurfaceDirectionalShadeOverlayPastScale);
        }

        private static void ValidateHd2dOutdoorOcclusionGradientTexture()
        {
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(OutdoorOcclusionGradientTexturePath);
            if (texture == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing outdoor occlusion gradient texture asset at {OutdoorOcclusionGradientTexturePath}.");
            }

            if (texture.width != 192 || texture.height != 128)
            {
                throw new InvalidOperationException($"House slice validation failed: outdoor occlusion gradient texture must stay at 192x128, but was {texture.width}x{texture.height}.");
            }

            if (texture.filterMode != FilterMode.Bilinear || texture.wrapMode != TextureWrapMode.Clamp)
            {
                throw new InvalidOperationException("House slice validation failed: outdoor occlusion gradient texture must use bilinear clamp sampling.");
            }

            var centerAlpha = texture.GetPixel(texture.width / 2, texture.height / 2).a;
            var topCenterAlpha = texture.GetPixel(texture.width / 2, texture.height - 1).a;
            var bottomCenterAlpha = texture.GetPixel(texture.width / 2, 0).a;
            var maxAlpha = 0f;

            foreach (var pixel in texture.GetPixels32())
            {
                maxAlpha = Mathf.Max(maxAlpha, pixel.a / 255f);
            }

            if (centerAlpha < 0.16f || centerAlpha > 0.24f)
            {
                throw new InvalidOperationException($"House slice validation failed: outdoor occlusion gradient center alpha must stay in the 0.16-0.24 range, but was {centerAlpha:0.000}.");
            }

            if (topCenterAlpha < 0.30f || topCenterAlpha > 0.36f)
            {
                throw new InvalidOperationException($"House slice validation failed: outdoor occlusion gradient top alpha must stay in the 0.30-0.36 range, but was {topCenterAlpha:0.000}.");
            }

            if (bottomCenterAlpha > 0.03f)
            {
                throw new InvalidOperationException($"House slice validation failed: outdoor occlusion gradient bottom alpha must stay near transparent, but was {bottomCenterAlpha:0.000}.");
            }

            if (maxAlpha < 0.30f || maxAlpha > 0.36f)
            {
                throw new InvalidOperationException($"House slice validation failed: outdoor occlusion gradient max alpha must stay in the 0.30-0.36 range, but was {maxAlpha:0.000}.");
            }
        }

        private static void ValidateSceneObjectMaterialTexture(string objectName, string textureId)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing scene object {objectName}.");
            }

            var renderer = sceneObject.GetComponent<Renderer>();
            if (renderer == null || renderer.sharedMaterial == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must have a renderer with a material.");
            }

            var texture = ResolveMaterialTexture(renderer.sharedMaterial);
            var expectedName = $"FastVS_House_{textureId}";
            if (texture == null || !string.Equals(texture.name, expectedName, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must reference {expectedName}.");
            }
        }

        private static void ValidateHd2dDepthFramingObject(string objectName, string expectedMaterialToken, int minRenderQueue, int maxRenderQueue, string expectedParentName)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing depth-framing object {objectName}.");
            }

            var renderer = sceneObject.GetComponent<Renderer>();
            if (renderer == null || renderer.sharedMaterial == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must have a renderer with a material.");
            }

            if (sceneObject.GetComponent<Collider>() != null || sceneObject.GetComponentsInChildren<Collider>(true).Length > 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must not have a collider.");
            }

            if (sceneObject.transform.parent == null || sceneObject.transform.parent.name != expectedParentName)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must be parented under {expectedParentName}.");
            }

            var landmark = sceneObject.GetComponent<TimeWindowPairedSpaceLandmark>();
            if (landmark == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep a TimeWindowPairedSpaceLandmark.");
            }

            var landmarkSerialized = new SerializedObject(landmark);
            var kindProperty = landmarkSerialized.FindProperty("kind");
            if (kindProperty == null ||
                kindProperty.propertyType != SerializedPropertyType.Enum ||
                kindProperty.enumValueIndex != Convert.ToInt32(TimeWindowPairedSpaceLandmarkKind.PropOrFeature))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must use TimeWindowPairedSpaceLandmarkKind.PropOrFeature.");
            }

            if (sceneObject.transform.localScale.y > 0.08f)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must stay very thin on the Y axis.");
            }

            var materialName = renderer.sharedMaterial.name ?? string.Empty;
            if (materialName.IndexOf(expectedMaterialToken, StringComparison.OrdinalIgnoreCase) < 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must use a material containing {expectedMaterialToken} in its name.");
            }

            var renderQueue = renderer.sharedMaterial.renderQueue;
            if (renderQueue < minRenderQueue || renderQueue > maxRenderQueue)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep renderQueue in the {minRenderQueue}-{maxRenderQueue} range, but was {renderQueue}.");
            }
        }

        private static void ValidateLibraryWindowLightObject(string objectName, string expectedParentName, Vector3 expectedLocalPosition, Vector3 expectedLocalScale, string expectedLandmarkId)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing library window light object {objectName}.");
            }

            var renderer = sceneObject.GetComponent<Renderer>();
            if (renderer == null || renderer.sharedMaterial == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must have a renderer with a material.");
            }

            if (sceneObject.GetComponent<Collider>() != null || sceneObject.GetComponentsInChildren<Collider>(true).Length > 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must not have a collider.");
            }

            if (sceneObject.transform.parent == null || sceneObject.transform.parent.name != expectedParentName)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must be parented under {expectedParentName}.");
            }

            ValidateVectorNear($"{objectName} local position", sceneObject.transform.localPosition, expectedLocalPosition);
            ValidateVectorNear($"{objectName} local scale", sceneObject.transform.localScale, expectedLocalScale);
            if (sceneObject.transform.localScale.x <= 0f ||
                sceneObject.transform.localScale.y <= 0f ||
                Mathf.Abs(sceneObject.transform.localScale.z - 1f) > 0.01f)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must stay flat and non-degenerate.");
            }

            var landmark = sceneObject.GetComponent<TimeWindowPairedSpaceLandmark>();
            if (landmark == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep a TimeWindowPairedSpaceLandmark.");
            }

            var landmarkSerialized = new SerializedObject(landmark);
            var kindProperty = landmarkSerialized.FindProperty("kind");
            var arrivalProperty = landmarkSerialized.FindProperty("countsForArrival");
            var landmarkIdProperty = landmarkSerialized.FindProperty("landmarkId");
            if (kindProperty == null ||
                kindProperty.propertyType != SerializedPropertyType.Enum ||
                kindProperty.enumValueIndex != Convert.ToInt32(TimeWindowPairedSpaceLandmarkKind.PropOrFeature) ||
                arrivalProperty == null ||
                arrivalProperty.propertyType != SerializedPropertyType.Boolean ||
                !arrivalProperty.boolValue ||
                landmarkIdProperty == null ||
                landmarkIdProperty.propertyType != SerializedPropertyType.String ||
                !string.Equals(landmarkIdProperty.stringValue, expectedLandmarkId, StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep its paired-space landmark metadata.");
            }

            var materialName = renderer.sharedMaterial.name ?? string.Empty;
            if (materialName.IndexOf("hd2d_library_window_light", StringComparison.OrdinalIgnoreCase) < 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must use the hd2d_library_window_light material.");
            }

            ValidateSceneObjectMaterialTexture(objectName, "hd2d_library_window_light_soft");
        }

