            ValidateLandmarkExists("Current_HouseExterior_DoorClosedPanel", "Current_HouseExteriorMap_SeparateSpace");
            ValidateLandmarkExists("Past_HouseExterior_DoorClosedPanel", "Past_HouseExteriorMap_SeparateSpace");
        }

