        private static void ValidateHouseExteriorPorchOcclusionReadabilityObject(
            string objectName,
            string expectedParentName,
            string expectedMaterialToken,
            Vector3 minLocalPosition,
            Vector3 maxLocalPosition,
            Vector3 minLocalScale,
            Vector3 maxLocalScale,
            float maxScaleY)
        {
            ValidateNonArrivalLandmarkCubeObject(
                objectName,
                expectedParentName,
                HouseExteriorCenter,
                expectedMaterialToken,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                minLocalPosition,
                maxLocalPosition,
                minLocalScale,
                maxLocalScale);

            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            var renderer = sceneObject != null ? sceneObject.GetComponent<Renderer>() : null;
            if (renderer == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep a renderer.");
            }

            if (renderer.shadowCastingMode != ShadowCastingMode.Off || renderer.receiveShadows)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must stay shadow-safe.");
            }

            if (sceneObject.transform.localScale.y > maxScaleY)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must stay thin enough to read as occlusion, not a slab.");
            }
        }

        private static void ValidateForwardPorchPostObject(string objectName, string expectedParentName, string expectedMaterialToken, Vector3 minLocalPosition, Vector3 maxLocalPosition, Vector3 minLocalScale, Vector3 maxLocalScale)
        {
            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            if (sceneObject == null)
            {
                throw new InvalidOperationException($"House slice validation failed: missing forward porch post object {objectName}.");
            }

            var renderer = sceneObject.GetComponent<Renderer>();
            if (renderer == null || renderer.sharedMaterial == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep a visible renderer.");
            }

            if (sceneObject.GetComponent<Collider>() == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep its collider so the porch post remains physically present.");
            }

            if (sceneObject.transform.parent == null || sceneObject.transform.parent.name != expectedParentName)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must be parented under {expectedParentName}.");
            }

            var landmark = sceneObject.GetComponent<TimeWindowPairedSpaceLandmark>();
            if (landmark == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep a TimeWindowPairedSpaceLandmark.");
            }

            var landmarkSerialized = new SerializedObject(landmark);
            var kindProperty = landmarkSerialized.FindProperty("kind");
            var countsForArrivalProperty = landmarkSerialized.FindProperty("countsForArrival");
            if (kindProperty == null ||
                kindProperty.propertyType != SerializedPropertyType.Enum ||
                kindProperty.enumValueIndex != Convert.ToInt32(TimeWindowPairedSpaceLandmarkKind.PropOrFeature) ||
                countsForArrivalProperty == null ||
                countsForArrivalProperty.propertyType != SerializedPropertyType.Boolean ||
                !countsForArrivalProperty.boolValue)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep an arrival-counting PropOrFeature landmark.");
            }

            ValidateVectorWithinRange($"{objectName} local position", sceneObject.transform.localPosition - HouseExteriorCenter, minLocalPosition, maxLocalPosition);
            ValidateVectorWithinRange($"{objectName} local scale", sceneObject.transform.localScale, minLocalScale, maxLocalScale);

            var materialName = renderer.sharedMaterial.name ?? string.Empty;
            if (materialName.IndexOf(expectedMaterialToken, StringComparison.OrdinalIgnoreCase) < 0)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must use a material containing {expectedMaterialToken} in its name.");
            }
        }

        private static void ValidateArchitectureSurfaceDepthObject(string objectName, string expectedParentName, Vector3 referenceCenter, string expectedMaterialToken, TimeWindowPairedSpaceLandmarkKind expectedKind, Vector3 minLocalPosition, Vector3 maxLocalPosition, Vector3 minLocalScale, Vector3 maxLocalScale)
        {
            ValidateNonArrivalLandmarkCubeObject(objectName, expectedParentName, referenceCenter, expectedMaterialToken, expectedKind, minLocalPosition, maxLocalPosition, minLocalScale, maxLocalScale);

            var sceneObject = FindSceneObjectIncludingInactive(objectName);
            var renderer = sceneObject != null ? sceneObject.GetComponent<Renderer>() : null;
            if (renderer == null)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must keep a renderer.");
            }

            if (renderer.shadowCastingMode != ShadowCastingMode.Off || renderer.receiveShadows)
            {
                throw new InvalidOperationException($"House slice validation failed: {objectName} must remain shadow-safe.");
            }
        }

