        private static GameObject CreateCentralPlazaRealtimeShadowCasterCycle127(
            Transform root,
            string objectName,
            Vector3 localPosition,
            Vector3 localScale,
            Quaternion localRotation,
            Material material,
            string landmarkId)
        {
            var caster = CreateNonArrivalLandmarkCube(
                objectName,
                root,
                localPosition,
                localScale,
                localRotation,
                material,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                landmarkId);
            var renderer = caster.GetComponent<Renderer>();
            if (renderer != null)
            {
                renderer.shadowCastingMode = ShadowCastingMode.ShadowsOnly;
                renderer.receiveShadows = false;
            }

            var collider = caster.GetComponent<Collider>();
            if (collider != null)
            {
                UnityEngine.Object.DestroyImmediate(collider);
            }

            return caster;
        }

        private static void RewriteCentralPlazaRealtimeCasterMeshCycle141(Transform root, string objectName, Vector2 localSize, Vector2[] outline)
        {
            MeshFilter targetFilter = null;
            foreach (var filter in root.GetComponentsInChildren<MeshFilter>(true))
            {
                if (filter != null && string.Equals(filter.gameObject.name, objectName, StringComparison.Ordinal))
                {
                    targetFilter = filter;
                    break;
                }
            }

            if (targetFilter == null)
            {
                throw new InvalidOperationException($"House slice setup failed: cycle 141 could not find realtime caster {objectName}.");
            }

            targetFilter.sharedMesh = CreateCentralPlazaRealtimeShadowMeshCycle140(objectName + "_Cycle141Rewrite", localSize, outline);
            targetFilter.transform.localScale = Vector3.one;

            var renderer = targetFilter.GetComponent<Renderer>();
            if (renderer != null)
            {
                renderer.enabled = true;
                renderer.shadowCastingMode = ShadowCastingMode.ShadowsOnly;
                renderer.receiveShadows = false;
            }

            var collider = targetFilter.GetComponent<Collider>();
            if (collider != null)
            {
                UnityEngine.Object.DestroyImmediate(collider);
            }
        }

        private static GameObject CreateCentralPlazaRealtimeShadowMeshCasterCycle140(
            Transform root,
            string objectName,
            Vector3 localPosition,
            Vector2 localSize,
            Quaternion localRotation,
            Material material,
            string landmarkId,
            Vector2[] outline)
        {
            var caster = CreateNonArrivalLandmarkCube(
                objectName,
                root,
                localPosition,
                Vector3.one,
                localRotation,
                material,
                TimeWindowPairedSpaceLandmarkKind.PropOrFeature,
                landmarkId);

            var filter = caster.GetComponent<MeshFilter>();
            if (filter != null && outline != null && outline.Length >= 3)
            {
                filter.sharedMesh = CreateCentralPlazaRealtimeShadowMeshCycle140(objectName, localSize, outline);
            }

            var renderer = caster.GetComponent<Renderer>();
            if (renderer != null)
            {
                renderer.shadowCastingMode = ShadowCastingMode.ShadowsOnly;
                renderer.receiveShadows = false;
            }

            var collider = caster.GetComponent<Collider>();
            if (collider != null)
            {
                UnityEngine.Object.DestroyImmediate(collider);
            }

            return caster;
        }

        private static Mesh CreateCentralPlazaRealtimeShadowMeshCycle140(string objectName, Vector2 localSize, Vector2[] outline)
        {
            var vertexCount = outline.Length;
            var vertices = new Vector3[vertexCount * 2];
            var normals = new Vector3[vertexCount * 2];
            var uvs = new Vector2[vertexCount * 2];
            for (var i = 0; i < vertexCount; i++)
            {
                var x = outline[i].x * localSize.x;
                var z = outline[i].y * localSize.y;
                vertices[i] = new Vector3(x, 0f, z);
                vertices[i + vertexCount] = vertices[i];
                normals[i] = Vector3.up;
                normals[i + vertexCount] = Vector3.down;
                uvs[i] = new Vector2(outline[i].x + 0.5f, outline[i].y + 0.5f);
                uvs[i + vertexCount] = uvs[i];
            }

            var triangles = new int[(vertexCount - 2) * 6];
            var cursor = 0;
            for (var i = 1; i < vertexCount - 1; i++)
            {
                triangles[cursor++] = 0;
                triangles[cursor++] = i;
                triangles[cursor++] = i + 1;
                triangles[cursor++] = vertexCount;
                triangles[cursor++] = vertexCount + i + 1;
                triangles[cursor++] = vertexCount + i;
            }

            return new Mesh
            {
                name = objectName + "_RealtimeShadowMesh",
                vertices = vertices,
                normals = normals,
                uv = uvs,
                triangles = triangles,
                bounds = new Bounds(Vector3.zero, new Vector3(localSize.x, 0.08f, localSize.y))
            };
        }

        private static void ApplyCentralPlazaRealtimeRendererPolicyCycle127(Transform root)
        {
            foreach (var renderer in root.GetComponentsInChildren<Renderer>(true))
            {
                if (renderer == null)
                {
                    continue;
                }

                if (renderer.gameObject.name.Contains("RealtimeShadowCasterCycle"))
                {
                    renderer.enabled = true;
                    renderer.shadowCastingMode = ShadowCastingMode.ShadowsOnly;
                    renderer.receiveShadows = false;
                    continue;
                }

                if (ShouldDisableCentralPlazaStaticLightingRendererCycle127(renderer))
                {
                    renderer.enabled = true;
                    renderer.shadowCastingMode = ShadowCastingMode.Off;
                    renderer.receiveShadows = false;
                    continue;
                }

                if (renderer.GetComponentInParent<FastVsHd2dOverlayProfile>(true) != null)
                {
                    renderer.enabled = true;
                    renderer.shadowCastingMode = ShadowCastingMode.Off;
                    renderer.receiveShadows = false;
                    continue;
                }

                renderer.enabled = true;
                if (IsCentralPlazaRealtimeShadowReceiverCycle127(renderer))
                {
                    renderer.shadowCastingMode = ShadowCastingMode.Off;
                    renderer.receiveShadows = true;
                    continue;
                }

                var material = renderer.sharedMaterial;
                var role = material != null ? material.GetTag(MaterialRoleTagName, false, string.Empty) : string.Empty;
                if (!string.Equals(role, FastVsHd2dMaterialRole.SurfaceLit.ToString(), StringComparison.Ordinal))
                {
                    renderer.shadowCastingMode = ShadowCastingMode.Off;
                    renderer.receiveShadows = false;
                    continue;
                }

                renderer.shadowCastingMode = ShadowCastingMode.Off;
                renderer.receiveShadows = false;
            }
        }

        private static bool ShouldDisableCentralPlazaStaticLightingRendererCycle127(Renderer renderer)
        {
            if (renderer == null)
            {
                return false;
            }

            return false;
        }

        private static bool IsCentralPlazaRealtimeShadowReceiverCycle127(Renderer renderer)
        {
            var surface = renderer.GetComponent<FastVsHd2dSurfaceProfile>();
            if (surface != null &&
                (surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Floor ||
                 surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Ground ||
                 surface.SurfaceKindForReview == FastVsHd2dSurfaceKind.Road))
            {
                return true;
            }

            var name = renderer.gameObject.name;
            if (ContainsOrdinal(name, "Shadow") ||
                ContainsOrdinal(name, "Light") ||
                ContainsOrdinal(name, "Sun") ||
                ContainsOrdinal(name, "Air") ||
                ContainsOrdinal(name, "Haze") ||
                ContainsOrdinal(name, "Veil") ||
                ContainsOrdinal(name, "Wash") ||
                ContainsOrdinal(name, "Sky") ||
                ContainsOrdinal(name, "Backdrop") ||
                ContainsOrdinal(name, "Wall") ||
                ContainsOrdinal(name, "Roof") ||
                ContainsOrdinal(name, "Facade") ||
                ContainsOrdinal(name, "Wing") ||
                ContainsOrdinal(name, "Volume") ||
                ContainsOrdinal(name, "Door") ||
                ContainsOrdinal(name, "Window") ||
                ContainsOrdinal(name, "Mullion") ||
                ContainsOrdinal(name, "Pane") ||
                ContainsOrdinal(name, "Post") ||
                ContainsOrdinal(name, "Board") ||
                ContainsOrdinal(name, "Tree") ||
                ContainsOrdinal(name, "Silhouette") ||
                ContainsOrdinal(name, "Contact") ||
                ContainsOrdinal(name, "Seam") ||
                ContainsOrdinal(name, "Skirt") ||
                ContainsOrdinal(name, "Street") ||
                ContainsOrdinal(name, "Field") ||
                ContainsOrdinal(name, "Shelf") ||
                ContainsOrdinal(name, "Shoulder") ||
                ContainsOrdinal(name, "Horizon") ||
                ContainsOrdinal(name, "Continuation") ||
                ContainsOrdinal(name, "Strip"))
            {
                return false;
            }

            return ContainsOrdinal(name, "Ground") ||
                   ContainsOrdinal(name, "StoneSquare") ||
                   ContainsOrdinal(name, "Road") ||
                   ContainsOrdinal(name, "Path") ||
                   ContainsOrdinal(name, "Paving") ||
                   ContainsOrdinal(name, "FloorJoint") ||
                   ContainsOrdinal(name, "Approach") ||
                   ContainsOrdinal(name, "Step") ||
                   ContainsOrdinal(name, "Paver") ||
                   ContainsOrdinal(name, "Curb") ||
                   ContainsOrdinal(name, "Apron") ||
                   ContainsOrdinal(name, "Pebble") ||
                   ContainsOrdinal(name, "DustScuff") ||
                   ContainsOrdinal(name, "FountainDryBasinInnerFloor");
        }

        private static bool IsCentralPlazaFakeSkyObjectCycle127(string objectName)
        {
            return ContainsOrdinal(objectName, "_Cycle84_Cinematic") ||
                   ContainsOrdinal(objectName, "_Cycle90_") ||
                   ContainsOrdinal(objectName, "_Cycle91_") ||
                   ContainsOrdinal(objectName, "_ScenicBackdrop_") ||
                   ContainsOrdinal(objectName, "_BackdropFoundation_Sky") ||
                   ContainsOrdinal(objectName, "_OutdoorVoidBackground_") ||
                   ContainsOrdinal(objectName, "_OutdoorSky") ||
                   ContainsOrdinal(objectName, "_SkyAtmosphere");
        }

        private static bool ContainsOrdinal(string value, string token)
        {
            return value != null && value.IndexOf(token, StringComparison.Ordinal) >= 0;
        }

        private static bool IsCycle125SuppressedReferenceLightingObjectName(string objectName)
        {
            var suppressedPrefixes = new[]
            {
                "Current_CentralPlaza_Cycle84_",
                "Current_CentralPlaza_Cycle90_",
                "Current_CentralPlaza_Cycle103_",
                "Current_CentralPlaza_Cycle104_",
                "Current_CentralPlaza_Cycle106_",
                "Current_CentralPlaza_Cycle107_",
                "Current_CentralPlaza_Cycle108_",
                "Current_CentralPlaza_Cycle109_",
                "Current_CentralPlaza_Cycle111_",
                "Current_CentralPlaza_Cycle112_",
                "Current_CentralPlaza_Cycle113_",
                "Current_CentralPlaza_Cycle114_",
                "Current_CentralPlaza_Cycle116_",
                "Current_CentralPlaza_Cycle117_",
                "Current_CentralPlaza_Cycle118_",
                "Current_CentralPlaza_Cycle119_",
                "Current_CentralPlaza_Cycle120_",
                "Current_CentralPlaza_Cycle121_",
                "Current_CentralPlaza_Cycle122_",
                "Current_CentralPlaza_Cycle123_",
                "Current_CentralPlaza_Cycle124_"
            };

            for (var i = 0; i < suppressedPrefixes.Length; i++)
            {
                if (objectName.StartsWith(suppressedPrefixes[i], StringComparison.Ordinal))
