        private static void CreatePaperCardParts(Transform parent, string displayName, float height, Material body, Material accent, Material face, Material label)
        {
            CreateQuad($"{displayName}_PaperBody", parent, new Vector3(0f, height * 0.52f, 0f), new Vector3(height * 0.42f, height * 0.88f, 1f), body);
            CreateQuad($"{displayName}_PaperHead", parent, new Vector3(0f, height * 1.02f, -0.012f), new Vector3(height * 0.33f, height * 0.30f, 1f), face);
            CreateQuad($"{displayName}_PaperHatOrHair", parent, new Vector3(0f, height * 1.17f, -0.024f), new Vector3(height * 0.42f, height * 0.18f, 1f), accent);
            CreateQuad($"{displayName}_PaperFootLine", parent, new Vector3(0f, height * 0.08f, -0.026f), new Vector3(height * 0.48f, height * 0.08f, 1f), accent);
            CreateNameLabel(parent, displayName, new Vector3(0f, height * 1.45f, -0.035f), label);
        }

        private static Renderer CreateSpriteCardParts(Transform parent, string displayName, float height, Material spriteMaterial, bool showLabel, Material label)
        {
            var footPadding = height * (NiroTransparentFootPixels / NiroExpectedTextureHeight);
            var sprite = CreateQuad($"{displayName}_Sprite64x96", parent, new Vector3(0f, height * 0.50f - footPadding, 0f), new Vector3(height * 0.667f, height, 1f), spriteMaterial);
            if (showLabel)
            {
                CreateNameLabel(parent, displayName, new Vector3(0f, height * 1.08f, -0.035f), label);
            }

            return sprite.GetComponent<Renderer>();
        }

        private static GameObject CreateQuad(string name, Transform parent, Vector3 localPosition, Vector3 localScale, Material material)
        {
            var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
            quad.name = name;
            quad.transform.SetParent(parent, false);
            quad.transform.localPosition = localPosition;
            quad.transform.localScale = localScale;
            quad.GetComponent<Renderer>().sharedMaterial = material;
            var collider = quad.GetComponent<Collider>();
            if (collider != null)
            {
                UnityEngine.Object.DestroyImmediate(collider);
            }

            return quad;
        }

        private static FastVsHd2dOverlayProfile AddHd2dOverlayProfile(
            GameObject target,
            string overlayId,
            FastVsHouseArea area,
            FastVsHd2dOverlayKind kind,
            bool currentWorld,
            bool dynamicSubject,
            Vector2 opacityBand,
            Vector2 footprintWorldSize,
            Color intendedTint)
        {
            if (target == null)
            {
                throw new InvalidOperationException($"Cannot add HD2D overlay profile '{overlayId}' because the target object is null.");
            }

            var profile = target.GetComponent<FastVsHd2dOverlayProfile>();
            if (profile == null)
            {
                profile = target.AddComponent<FastVsHd2dOverlayProfile>();
            }

            var renderer = target.GetComponent<MeshRenderer>();
            if (renderer == null)
            {
                throw new InvalidOperationException($"Cannot add HD2D overlay profile '{overlayId}' because the target object is missing a MeshRenderer.");
            }

            renderer.enabled = true;
            renderer.shadowCastingMode = ShadowCastingMode.Off;
            renderer.receiveShadows = false;

            SerializedSet(profile, "overlayId", overlayId);
            SerializedSet(profile, "areaId", area);
            SerializedSet(profile, "overlayKind", kind);
            SerializedSet(profile, "currentWorld", currentWorld);
            SerializedSet(profile, "dynamicSubject", dynamicSubject);
            SerializedSet(profile, "opacityBand", opacityBand);
            SerializedSet(profile, "footprintWorldSize", footprintWorldSize);
            SerializedSet(profile, "intendedTint", intendedTint);
            return profile;
        }

        private static FastVsHd2dSurfaceProfile AddHd2dSurfaceProfile(
            GameObject target,
            string surfaceId,
            FastVsHouseArea areaId,
            FastVsHd2dSurfaceKind kind,
            bool currentWorld,
            Vector2 luminanceBand,
            Vector2 contrastBand,
            Vector2 textureDensityHint,
            bool acceptsOverlayShading,
            string intendedMaterialToken)
        {
            if (target == null)
            {
                return null;
            }

            var profile = target.GetComponent<FastVsHd2dSurfaceProfile>();
            if (profile == null)
            {
                profile = target.AddComponent<FastVsHd2dSurfaceProfile>();
            }

            SerializedSet(profile, "surfaceId", surfaceId);
            SerializedSet(profile, "areaId", areaId);
            SerializedSet(profile, "surfaceKind", kind);
            SerializedSet(profile, "currentWorld", currentWorld);
            SerializedSet(profile, "targetLuminanceBand", luminanceBand);
            SerializedSet(profile, "targetContrastBand", contrastBand);
            SerializedSet(profile, "textureDensityHint", textureDensityHint);
            SerializedSet(profile, "acceptsOverlayShading", acceptsOverlayShading);
            SerializedSet(profile, "intendedMaterialToken", intendedMaterialToken);
            return profile;
        }

        private static void ValidateTimewriterBrushIconTexture()
        {
            var texture = EnsureTimewriterBrushIconTexture();
            if (texture == null || texture.width != 256 || texture.height != 256)
            {
                throw new InvalidOperationException($"House slice validation failed: Timewriter brush icon texture must be generated at 256x256: {TimewriterBrushIconTexturePath}");
            }

            var importer = AssetImporter.GetAtPath(TimewriterBrushIconTexturePath) as TextureImporter;
            if (importer == null ||
                !importer.alphaIsTransparency ||
                importer.mipmapEnabled ||
                importer.filterMode != FilterMode.Point)
            {
                throw new InvalidOperationException($"House slice validation failed: Timewriter brush icon texture importer must use point-filtered alpha UI settings: {TimewriterBrushIconTexturePath}");
            }
        }

