                    var dy = (v - 0.56f) / 0.44f;
                    var ellipse = Mathf.Sqrt((dx * dx * 0.86f) + (dy * dy * 2.70f));
                    var core = Mathf.Clamp01(1f - ellipse);
                    var glow = Mathf.Clamp01(1f - ellipse * 0.78f);
