        private static Material EnsureChapter1ProductionSurfaceMaterial(string id, Chapter1ProductionSurfaceKind kind, bool past, Vector2 tiling)
        {
            if (!id.StartsWith("Ch1Ground_", StringComparison.Ordinal) &&
                !id.StartsWith("Ch1Surface_", StringComparison.Ordinal))
            {
                throw new InvalidOperationException($"House slice validation failed: Phase 3 production surface material must use Ch1Ground_/Ch1Surface_ naming, got {id}.");
            }

            var unlitTerrainQuilt = IsTerrainQuiltProductionSurfaceKind(kind);
            var material = FlatMaterial(id, Color.white, unlitTerrainQuilt, FastVsHd2dMaterialRole.SurfaceLit);
            var texture = EnsureChapter1ProductionSurfaceTexture(id, kind, past);
            AssignMaterialTexture(material, texture, tiling);
            ApplyChapter1ArchitecturalAccentMaterialTint(material, id, past);

            if (material.HasProperty("_Smoothness"))
            {
                material.SetFloat("_Smoothness", kind == Chapter1ProductionSurfaceKind.WeatheredRoof ? 0.20f : 0.13f);
            }

            if (material.HasProperty("_SpecularHighlights"))
            {
                material.SetFloat("_SpecularHighlights", 0f);
            }

            EditorUtility.SetDirty(material);
            return material;
        }

        private static void ApplyChapter1ArchitecturalAccentMaterialTint(Material material, string id, bool past)
        {
            if (id.IndexOf("ArchitecturalAccent", StringComparison.Ordinal) < 0)
            {
                return;
            }

            var tint = id.IndexOf("WeatheredRoof2K", StringComparison.Ordinal) >= 0
                ? (past ? new Color(0.68f, 0.55f, 0.44f, 1f) : new Color(0.82f, 0.74f, 0.66f, 1f))
                : (past ? new Color(0.62f, 0.58f, 0.48f, 1f) : new Color(0.76f, 0.72f, 0.64f, 1f));

            if (material.HasProperty("_BaseColor"))
            {
                material.SetColor("_BaseColor", tint);
            }

            if (material.HasProperty("_Color"))
            {
                material.SetColor("_Color", tint);
            }
        }

        private static bool IsTerrainQuiltProductionSurfaceKind(Chapter1ProductionSurfaceKind kind)
        {
            return kind == Chapter1ProductionSurfaceKind.TerrainQuiltSoilGrass ||
                   kind == Chapter1ProductionSurfaceKind.TerrainQuiltFieldFurrow ||
                   kind == Chapter1ProductionSurfaceKind.TerrainQuiltGrassEdge ||
                   kind == Chapter1ProductionSurfaceKind.TerrainQuiltStonePath;
        }

        private static Texture2D EnsureChapter1ProductionSurfaceTexture(string id, Chapter1ProductionSurfaceKind kind, bool past)
        {
            EnsureFolder(TextureDirectory);
            var path = $"{TextureDirectory}/FastVS_House_{id}_2k.png";
            var imported = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (imported != null && imported.width == Chapter1ProductionSurfaceTextureSize && imported.height == Chapter1ProductionSurfaceTextureSize)
            {
                ConfigureChapter1ProductionSurfaceTextureImporter(path);
                return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            }

            var texture = new Texture2D(Chapter1ProductionSurfaceTextureSize, Chapter1ProductionSurfaceTextureSize, TextureFormat.RGBA32, false)
            {
                name = $"FastVS_House_{id}_2k",
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Repeat
            };
            var outdoorSurface = id.IndexOf("Outdoor", StringComparison.Ordinal) >= 0;
            var pixels = new Color32[Chapter1ProductionSurfaceTextureSize * Chapter1ProductionSurfaceTextureSize];
            for (var y = 0; y < Chapter1ProductionSurfaceTextureSize; y++)
            {
                for (var x = 0; x < Chapter1ProductionSurfaceTextureSize; x++)
                {
                    pixels[y * Chapter1ProductionSurfaceTextureSize + x] = SampleChapter1ProductionSurfacePixel(x, y, kind, past, outdoorSurface);
                }
            }

            texture.SetPixels32(pixels);
            texture.Apply(false, false);
            File.WriteAllBytes(path, texture.EncodeToPNG());
            UnityEngine.Object.DestroyImmediate(texture);
            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceSynchronousImport);
            ConfigureChapter1ProductionSurfaceTextureImporter(path);
            imported = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (imported == null || imported.width != Chapter1ProductionSurfaceTextureSize || imported.height != Chapter1ProductionSurfaceTextureSize)
            {
                throw new InvalidOperationException($"House slice validation failed: Phase 3 production texture generation failed for {path}.");
            }

            return imported;
        }

        private static void ConfigureChapter1ProductionSurfaceTextureImporter(string path)
        {
            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer == null)
            {
                return;
            }

            importer.textureType = TextureImporterType.Default;
            importer.alphaIsTransparency = false;
            importer.isReadable = true;
            importer.mipmapEnabled = false;
            importer.npotScale = TextureImporterNPOTScale.None;
            importer.filterMode = FilterMode.Bilinear;
            importer.wrapMode = TextureWrapMode.Repeat;
            importer.textureCompression = TextureImporterCompression.Uncompressed;
            importer.SaveAndReimport();
        }

        private static Color32 SampleChapter1ProductionSurfacePixel(int x, int y, Chapter1ProductionSurfaceKind kind, bool past, bool outdoorSurface)
        {
            var u = x / (float)(Chapter1ProductionSurfaceTextureSize - 1);
            var v = y / (float)(Chapter1ProductionSurfaceTextureSize - 1);
            var fine = Chapter1SurfaceHash01(x, y, 31) - 0.5f;
            var medium = Chapter1SurfaceHash01(x / 12, y / 12, 47) - 0.5f;
            var broad = Chapter1SurfaceHash01(x / 96, y / 96, 61) - 0.5f;

            Color color;
            switch (kind)
            {
                case Chapter1ProductionSurfaceKind.FieldFurrow:
                    color = SampleChapter1FieldFurrowSurface(u, v, x, y, fine, medium, broad, past);
                    break;
                case Chapter1ProductionSurfaceKind.GrassEdge:
                    color = SampleChapter1GrassEdgeSurface(u, v, x, y, fine, medium, broad, past);
                    break;
                case Chapter1ProductionSurfaceKind.StonePath:
                    color = SampleChapter1StonePathSurface(x, y, fine, medium, broad, past);
                    break;
                case Chapter1ProductionSurfaceKind.TerrainQuiltSoilGrass:
                    color = SampleChapter1TerrainQuiltSoilGrassSurface(u, v, x, y, fine, medium, broad, past);
                    break;
                case Chapter1ProductionSurfaceKind.TerrainQuiltFieldFurrow:
                    color = SampleChapter1TerrainQuiltFieldFurrowSurface(u, v, x, y, fine, medium, broad, past);
                    break;
                case Chapter1ProductionSurfaceKind.TerrainQuiltGrassEdge:
                    color = SampleChapter1TerrainQuiltGrassEdgeSurface(u, v, x, y, fine, medium, broad, past);
                    break;
                case Chapter1ProductionSurfaceKind.TerrainQuiltStonePath:
                    color = SampleChapter1TerrainQuiltStonePathSurface(x, y, fine, medium, broad, past);
                    break;
                case Chapter1ProductionSurfaceKind.AgedPlaster:
                    color = SampleChapter1AgedPlasterSurface(u, v, x, y, fine, medium, broad, past, outdoorSurface);
                    break;
                case Chapter1ProductionSurfaceKind.WeatheredRoof:
                    color = SampleChapter1WeatheredRoofSurface(x, y, fine, medium, broad, past, outdoorSurface);
                    break;
                default:
                    color = SampleChapter1SoilGrassSurface(u, v, x, y, fine, medium, broad, past);
                    break;
            }

            return (Color32)color;
        }

        private static Color SampleChapter1SoilGrassSurface(float u, float v, int x, int y, float fine, float medium, float broad, bool past)
        {
            var soil = past ? new Color(0.30f, 0.32f, 0.20f, 1f) : new Color(0.22f, 0.21f, 0.17f, 1f);
            var grass = past ? new Color(0.34f, 0.47f, 0.23f, 1f) : new Color(0.20f, 0.31f, 0.22f, 1f);
            var dry = past ? new Color(0.43f, 0.41f, 0.26f, 1f) : new Color(0.36f, 0.31f, 0.23f, 1f);
            var grassMask = Mathf.Clamp01(0.48f + broad * 0.52f + Mathf.Sin((u * 14.0f) + (v * 7.4f)) * 0.10f);
            var color = Color.Lerp(soil, grass, grassMask);
            var scuff = Mathf.Clamp01(0.34f + medium * 0.62f + Mathf.Sin((u * 25.0f) - (v * 12.0f)) * 0.08f);
            color = Color.Lerp(color, dry, past ? scuff * 0.18f : scuff * 0.30f);

            if ((x + y * 3) % 127 < 3 || Chapter1SurfaceHash01(x / 6, y / 6, 71) > 0.965f)
            {
                color = Color.Lerp(color, past ? new Color(0.50f, 0.49f, 0.36f, 1f) : new Color(0.46f, 0.42f, 0.34f, 1f), 0.36f);
            }

            return Chapter1SurfaceAdjust(color, fine * 0.13f + medium * 0.08f);
        }

        private static Color SampleChapter1FieldFurrowSurface(float u, float v, int x, int y, float fine, float medium, float broad, bool past)
        {
            var soil = past ? new Color(0.34f, 0.32f, 0.20f, 1f) : new Color(0.24f, 0.22f, 0.17f, 1f);
            var ridge = past ? new Color(0.49f, 0.45f, 0.26f, 1f) : new Color(0.36f, 0.32f, 0.22f, 1f);
            var crop = past ? new Color(0.36f, 0.49f, 0.21f, 1f) : new Color(0.18f, 0.32f, 0.20f, 1f);
            var dark = past ? new Color(0.20f, 0.23f, 0.15f, 1f) : new Color(0.12f, 0.16f, 0.13f, 1f);
            var wave = Mathf.Abs(Mathf.Sin((v * 78f) + Mathf.Sin(u * 12.5f) * 0.72f + broad * 1.6f));
            var ridgeMask = Mathf.SmoothStep(0.32f, 0.92f, wave);
            var cropMask = Mathf.Clamp01(0.30f + Mathf.Sin((u * 9.2f) - (v * 3.8f)) * 0.12f + medium * 0.42f);
            var color = Color.Lerp(soil, ridge, ridgeMask * (past ? 0.62f : 0.54f));
            color = Color.Lerp(color, crop, cropMask * (past ? 0.34f : 0.22f));
            color = Color.Lerp(color, dark, (1f - ridgeMask) * (past ? 0.16f : 0.30f));

            if ((y + Mathf.FloorToInt(Mathf.Sin(u * 21f) * 18f)) % 137 < 5 ||
                Chapter1SurfaceHash01(x / 9, y / 9, 149) > (past ? 0.960f : 0.940f))
            {
                color = Color.Lerp(color, past ? new Color(0.58f, 0.54f, 0.34f, 1f) : new Color(0.43f, 0.38f, 0.27f, 1f), past ? 0.22f : 0.28f);
            }

            return Chapter1SurfaceAdjust(color, fine * 0.12f + medium * 0.13f + broad * 0.08f);
        }

        private static Color SampleChapter1GrassEdgeSurface(float u, float v, int x, int y, float fine, float medium, float broad, bool past)
        {
            var baseGrass = past ? new Color(0.30f, 0.49f, 0.22f, 1f) : new Color(0.19f, 0.33f, 0.22f, 1f);
            var darkGrass = past ? new Color(0.18f, 0.34f, 0.18f, 1f) : new Color(0.12f, 0.22f, 0.17f, 1f);
            var soil = past ? new Color(0.36f, 0.34f, 0.21f, 1f) : new Color(0.26f, 0.23f, 0.18f, 1f);
            var clump = Mathf.Clamp01(0.52f + broad * 0.44f + Mathf.Sin((u * 31f) + (v * 5f)) * 0.13f);
            var color = Color.Lerp(darkGrass, baseGrass, clump);
            var dirtThread = (y + Mathf.FloorToInt(Mathf.Sin(u * 18f) * 24f)) % 181;
            if (dirtThread < 7 || Chapter1SurfaceHash01(x / 10, y / 10, 83) > 0.952f)
            {
                color = Color.Lerp(color, soil, past ? 0.18f : 0.34f);
            }

            return Chapter1SurfaceAdjust(color, fine * 0.16f + medium * 0.09f);
        }

        private static Color SampleChapter1StonePathSurface(int x, int y, float fine, float medium, float broad, bool past)
        {
            const int tileWidth = 148;
            const int tileHeight = 94;
            var row = y / tileHeight;
            var offsetX = (row % 2) * (tileWidth / 2);
            var localX = (x + offsetX) % tileWidth;
            var localY = y % tileHeight;
            var baseStone = past ? new Color(0.48f, 0.44f, 0.34f, 1f) : new Color(0.35f, 0.34f, 0.30f, 1f);
            var warmStone = past ? new Color(0.62f, 0.56f, 0.42f, 1f) : new Color(0.45f, 0.41f, 0.34f, 1f);
            var mortar = past ? new Color(0.27f, 0.25f, 0.21f, 1f) : new Color(0.18f, 0.18f, 0.17f, 1f);
            var color = Color.Lerp(baseStone, warmStone, Mathf.Clamp01(0.46f + broad * 0.42f + fine * 0.16f));
            if (localX < 5 || localX > tileWidth - 5 || localY < 5 || localY > tileHeight - 5)
            {
                color = Color.Lerp(color, mortar, 0.76f);
            }

            if (Chapter1SurfaceHash01((x + 19) / 18, (y + 7) / 18, 97) > (past ? 0.970f : 0.935f))
            {
                color = Color.Lerp(color, past ? new Color(0.30f, 0.38f, 0.24f, 1f) : new Color(0.20f, 0.24f, 0.18f, 1f), 0.34f);
            }

            return Chapter1SurfaceAdjust(color, medium * 0.10f);
        }

        private static Color SampleChapter1TerrainQuiltSoilGrassSurface(float u, float v, int x, int y, float fine, float medium, float broad, bool past)
        {
            var soil = past ? new Color(0.39f, 0.37f, 0.25f, 1f) : new Color(0.29f, 0.30f, 0.25f, 1f);
            var grass = past ? new Color(0.43f, 0.54f, 0.28f, 1f) : new Color(0.25f, 0.36f, 0.25f, 1f);
            var dry = past ? new Color(0.55f, 0.49f, 0.32f, 1f) : new Color(0.39f, 0.36f, 0.28f, 1f);
            var grassMask = Mathf.Clamp01(0.50f + broad * 0.30f + Mathf.Sin((u * 11.2f) + (v * 6.1f)) * 0.08f);
            var color = Color.Lerp(soil, grass, grassMask);
            var scuff = Mathf.Clamp01(0.30f + medium * 0.38f + Mathf.Sin((u * 18.0f) - (v * 9.0f)) * 0.05f);
            color = Color.Lerp(color, dry, past ? scuff * 0.12f : scuff * 0.18f);

            if ((x + y * 3) % 173 < 3 || Chapter1SurfaceHash01(x / 8, y / 8, 307) > 0.975f)
            {
                color = Color.Lerp(color, past ? new Color(0.58f, 0.54f, 0.38f, 1f) : new Color(0.44f, 0.41f, 0.33f, 1f), 0.22f);
            }

            return Chapter1SurfaceAdjust(color, fine * 0.06f + medium * 0.05f);
        }

        private static Color SampleChapter1TerrainQuiltFieldFurrowSurface(float u, float v, int x, int y, float fine, float medium, float broad, bool past)
        {
            var soil = past ? new Color(0.40f, 0.37f, 0.24f, 1f) : new Color(0.28f, 0.27f, 0.22f, 1f);
            var ridge = past ? new Color(0.55f, 0.50f, 0.31f, 1f) : new Color(0.39f, 0.34f, 0.25f, 1f);
            var crop = past ? new Color(0.43f, 0.56f, 0.27f, 1f) : new Color(0.26f, 0.36f, 0.22f, 1f);
            var shadowSoil = past ? new Color(0.29f, 0.31f, 0.20f, 1f) : new Color(0.23f, 0.26f, 0.20f, 1f);
            var wave = Mathf.Abs(Mathf.Sin((v * 62f) + Mathf.Sin(u * 10.5f) * 0.58f + broad * 1.1f));
            var ridgeMask = Mathf.SmoothStep(0.30f, 0.88f, wave);
            var cropMask = Mathf.Clamp01(0.30f + Mathf.Sin((u * 8.0f) - (v * 3.2f)) * 0.08f + medium * 0.28f);
            var color = Color.Lerp(soil, ridge, ridgeMask * (past ? 0.54f : 0.44f));
            color = Color.Lerp(color, crop, cropMask * (past ? 0.26f : 0.18f));
            color = Color.Lerp(color, shadowSoil, (1f - ridgeMask) * (past ? 0.08f : 0.10f));

            if ((y + Mathf.FloorToInt(Mathf.Sin(u * 17f) * 14f)) % 149 < 4 ||
                Chapter1SurfaceHash01(x / 11, y / 11, 331) > (past ? 0.976f : 0.966f))
            {
                color = Color.Lerp(color, past ? new Color(0.61f, 0.56f, 0.36f, 1f) : new Color(0.43f, 0.38f, 0.29f, 1f), past ? 0.16f : 0.16f);
            }

            return Chapter1SurfaceAdjust(color, fine * 0.055f + medium * 0.065f + broad * 0.035f);
        }

        private static Color SampleChapter1TerrainQuiltGrassEdgeSurface(float u, float v, int x, int y, float fine, float medium, float broad, bool past)
        {
            var baseGrass = past ? new Color(0.41f, 0.57f, 0.29f, 1f) : new Color(0.24f, 0.38f, 0.24f, 1f);
            var deepGrass = past ? new Color(0.28f, 0.44f, 0.23f, 1f) : new Color(0.19f, 0.31f, 0.20f, 1f);
            var soil = past ? new Color(0.43f, 0.39f, 0.26f, 1f) : new Color(0.30f, 0.28f, 0.22f, 1f);
            var clump = Mathf.Clamp01(0.54f + broad * 0.30f + Mathf.Sin((u * 25f) + (v * 4f)) * 0.09f);
            var color = Color.Lerp(deepGrass, baseGrass, clump);
            var dirtThread = (y + Mathf.FloorToInt(Mathf.Sin(u * 15f) * 18f)) % 191;
            if (dirtThread < 6 || Chapter1SurfaceHash01(x / 12, y / 12, 353) > 0.970f)
            {
                color = Color.Lerp(color, soil, past ? 0.12f : 0.18f);
            }

            return Chapter1SurfaceAdjust(color, fine * 0.065f + medium * 0.045f);
        }

        private static Color SampleChapter1TerrainQuiltStonePathSurface(int x, int y, float fine, float medium, float broad, bool past)
        {
            const int tileWidth = 132;
            const int tileHeight = 84;
            var row = y / tileHeight;
            var offsetX = (row % 2) * (tileWidth / 2);
            var localX = (x + offsetX) % tileWidth;
            var localY = y % tileHeight;
            var baseStone = past ? new Color(0.51f, 0.47f, 0.36f, 1f) : new Color(0.36f, 0.34f, 0.29f, 1f);
            var warmStone = past ? new Color(0.65f, 0.58f, 0.44f, 1f) : new Color(0.45f, 0.40f, 0.34f, 1f);
            var mortar = past ? new Color(0.35f, 0.32f, 0.27f, 1f) : new Color(0.30f, 0.29f, 0.25f, 1f);
            var color = Color.Lerp(baseStone, warmStone, Mathf.Clamp01(0.46f + broad * 0.30f + fine * 0.08f));
            if (localX < 5 || localX > tileWidth - 5 || localY < 5 || localY > tileHeight - 5)
            {
                color = Color.Lerp(color, mortar, 0.48f);
            }

            if (Chapter1SurfaceHash01((x + 23) / 22, (y + 11) / 22, 379) > (past ? 0.982f : 0.965f))
            {
                color = Color.Lerp(color, past ? new Color(0.38f, 0.44f, 0.28f, 1f) : new Color(0.24f, 0.29f, 0.21f, 1f), 0.16f);
            }

            return Chapter1SurfaceAdjust(color, medium * 0.055f);
        }

        private static Color SampleChapter1AgedPlasterSurface(float u, float v, int x, int y, float fine, float medium, float broad, bool past, bool outdoorSurface)
        {
            var plaster = past ? new Color(0.39f, 0.36f, 0.29f, 1f) : outdoorSurface ? new Color(0.43f, 0.39f, 0.32f, 1f) : new Color(0.34f, 0.31f, 0.26f, 1f);
            var lime = past ? new Color(0.52f, 0.47f, 0.36f, 1f) : outdoorSurface ? new Color(0.60f, 0.54f, 0.42f, 1f) : new Color(0.46f, 0.42f, 0.34f, 1f);
            var stain = past ? new Color(0.23f, 0.22f, 0.18f, 1f) : outdoorSurface ? new Color(0.24f, 0.23f, 0.20f, 1f) : new Color(0.18f, 0.17f, 0.15f, 1f);
            var color = Color.Lerp(plaster, lime, Mathf.Clamp01(0.38f + broad * 0.32f + fine * 0.18f + medium * 0.12f));
            var verticalStain = Mathf.Clamp01(1f - Mathf.Abs(Mathf.Sin((u * 23f) + broad * 1.5f)) * 2.8f) * Mathf.Clamp01(1f - v);
            color = Color.Lerp(color, stain, verticalStain * (past ? 0.26f : outdoorSurface ? 0.24f : 0.38f));
            if ((x + y * 2) % 251 < 3 || Chapter1SurfaceHash01(x / 11, y / 11, 109) > 0.975f)
            {
                color = Color.Lerp(color, stain, past ? 0.24f : outdoorSurface ? 0.26f : 0.40f);
            }

            if (Chapter1SurfaceHash01(x / 8, y / 8, 113) > 0.76f)
            {
                color = Color.Lerp(color, stain, past ? 0.16f : outdoorSurface ? 0.15f : 0.22f);
            }

            if (Chapter1SurfaceHash01((x + 5) / 16, (y + 3) / 16, 131) > 0.82f)
            {
                color = Color.Lerp(color, lime, past ? 0.12f : outdoorSurface ? 0.24f : 0.16f);
            }

            return Chapter1SurfaceAdjust(color, fine * 0.18f + medium * 0.15f + broad * (outdoorSurface && !past ? 0.10f : 0.05f));
        }

        private static Color SampleChapter1WeatheredRoofSurface(int x, int y, float fine, float medium, float broad, bool past, bool outdoorSurface)
        {
            const int tileWidth = 112;
            const int tileHeight = 72;
            var row = y / tileHeight;
            var localX = (x + (row % 2) * (tileWidth / 2)) % tileWidth;
            var localY = y % tileHeight;
            var roof = past ? new Color(0.56f, 0.27f, 0.15f, 1f) : outdoorSurface ? new Color(0.40f, 0.18f, 0.12f, 1f) : new Color(0.34f, 0.16f, 0.11f, 1f);
            var warm = past ? new Color(0.80f, 0.42f, 0.20f, 1f) : outdoorSurface ? new Color(0.58f, 0.27f, 0.16f, 1f) : new Color(0.48f, 0.22f, 0.14f, 1f);
            var dark = past ? new Color(0.28f, 0.18f, 0.13f, 1f) : outdoorSurface ? new Color(0.18f, 0.11f, 0.08f, 1f) : new Color(0.12f, 0.09f, 0.08f, 1f);
            var color = Color.Lerp(roof, warm, Mathf.Clamp01(0.36f + broad * 0.44f + fine * 0.10f));
            if (localY < 5 || localX < 4 || localX > tileWidth - 4)
            {
                color = Color.Lerp(color, dark, 0.68f);
            }

            if (Chapter1SurfaceHash01(x / 20, y / 20, 127) > (past ? 0.970f : 0.925f))
            {
                color = Color.Lerp(color, dark, past ? 0.24f : outdoorSurface ? 0.32f : 0.44f);
            }

            return Chapter1SurfaceAdjust(color, medium * (outdoorSurface && !past ? 0.16f : 0.12f));
        }

        private static Color Chapter1SurfaceAdjust(Color color, float amount)
        {
            var scale = Mathf.Clamp(1f + amount, 0.62f, 1.34f);
            return new Color(
                Mathf.Clamp01(color.r * scale),
                Mathf.Clamp01(color.g * scale),
                Mathf.Clamp01(color.b * scale),
                1f);
        }

        private static float Chapter1SurfaceHash01(int x, int y, int salt)
        {
            unchecked
            {
                var hash = 2166136261u ^ (uint)salt;
                hash ^= (uint)x + 0x9E3779B9u + (hash << 6) + (hash >> 2);
                hash *= 16777619u;
                hash ^= (uint)y + 0x85EBCA6Bu + (hash << 6) + (hash >> 2);
                hash *= 2246822519u;
                hash ^= hash >> 13;
                hash *= 3266489917u;
                return (hash & 0x00FFFFFFu) / 16777215f;
            }
        }

        private static Material PixelMaterial(string id, Color32 a, Color32 b, Color32 c, PixelPattern pattern, bool unlit, Vector2 tiling, FastVsHd2dMaterialRole role = FastVsHd2dMaterialRole.SurfaceLit)
        {
            var texture = EnsurePixelTexture(id, a, b, c, pattern);
            var material = FlatMaterial(id, Color.white, unlit, role);
            if (material.HasProperty("_BaseMap"))
            {
                material.SetTexture("_BaseMap", texture);
                material.SetTextureScale("_BaseMap", tiling);
            }

            if (material.HasProperty("_MainTex"))
            {
                material.SetTexture("_MainTex", texture);
                material.SetTextureScale("_MainTex", tiling);
            }

            return material;
        }

        private static Texture2D EnsurePixelTexture(string id, Color32 a, Color32 b, Color32 c, PixelPattern pattern)
        {
            var path = $"{TextureDirectory}/FastVS_House_{id}.asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (texture == null)
            {
                texture = new Texture2D(32, 32, TextureFormat.RGBA32, false);
                AssetDatabase.CreateAsset(texture, path);
            }

            texture.name = $"FastVS_House_{id}";
            texture.filterMode = FilterMode.Point;
            texture.wrapMode = TextureWrapMode.Repeat;

            for (var y = 0; y < 32; y++)
            {
                for (var x = 0; x < 32; x++)
                {
                    texture.SetPixel(x, y, ResolvePixel(pattern, x, y, a, b, c));
                }
            }

            texture.Apply();
            EditorUtility.SetDirty(texture);
            return texture;
        }

        private static Color32 ResolvePixel(PixelPattern pattern, int x, int y, Color32 a, Color32 b, Color32 c)
        {
            switch (pattern)
            {
                case PixelPattern.Planks:
                    return y % 8 == 0 || x % 15 == 0 ? c : ((x + y) % 5 == 0 ? b : a);
                case PixelPattern.Bricks:
                    return y % 8 == 0 || (x + (y / 8 % 2) * 8) % 16 == 0 ? c : ((x + y) % 7 == 0 ? b : a);
                case PixelPattern.Grass:
                    return (x * 3 + y * 5) % 11 < 3 ? b : ((x + y) % 13 == 0 ? c : a);
                case PixelPattern.Stone:
                    return x % 8 == 0 || y % 8 == 0 ? c : ((x * 7 + y * 3) % 17 < 4 ? b : a);
                case PixelPattern.Roof:
                    return (x + y) % 9 < 2 ? b : (y % 6 == 0 ? c : a);
                case PixelPattern.Cloth:
                    return x % 7 == 0 || y % 7 == 0 ? b : ((x + y) % 6 == 0 ? c : a);
                case PixelPattern.Book:
                    var spineWidth = 6 + ((x / 19) % 4);
                    var spineX = x % spineWidth;
                    var group = x / spineWidth;
                    if (spineX == 0 || spineX == spineWidth - 1)
                    {
                        return c;
                    }

                    var spineColor = group % 3 == 0 ? a : (group % 3 == 1 ? b : c);
                    if (spineX > 1 && spineX < spineWidth - 2 && (y % 18 == 5 || y % 18 == 6))
                    {
                        return group % 2 == 0 ? b : a;
                    }

                    return spineColor;
                case PixelPattern.Window:
                    if (x < 2 || x > 29 || y < 2 || y > 29)
                    {
                        return c;
                    }

                    if ((x + y * 2) % 13 < 2)
                    {
                        return b;
                    }

                    return (x * 5 + y * 3) % 23 < 3 ? c : a;
                case PixelPattern.Checker:
                    return ((x / 4) + (y / 4)) % 2 == 0 ? a : b;
                case PixelPattern.Water:
                    return (x + y * 2) % 10 < 2 ? b : ((x * 3 + y) % 17 < 3 ? c : a);
                case PixelPattern.DistantLandform:
                    var rowWarp = y + (x * 3 + (x / 5) * 7 + (y / 6) * 5) % 13;
                    var contour = rowWarp % 23 == 0 || (rowWarp + x / 9 + y / 11) % 41 == 0;
                    var rockShadow = (x * 11 + y * 17 + (x / 4) * 7 + (y / 9) * 5) % 53 < 5;
                    var ridgedHighlight = (x * 5 + y * 11 + (y / 4) * 7 + (x / 9) * 3) % 67 < 4;
                    var brokenCanopy = (x * 17 + y * 3 + (x / 6) * 5 + (y / 7) * 11) % 47 < 4;
                    if (contour)
                    {
                        return c;
                    }

                    if (rockShadow)
                    {
                        return c;
                    }

                    return ridgedHighlight || brokenCanopy ? b : a;
                case PixelPattern.DistantCanopy:
                    var canopyClump = (x * 7 + y * 13 + (x / 3) * 5 + (y / 5) * 3) % 43;
                    var canopyShadow = (x * 11 + y * 5 + (y / 4) * 7 + (x / 8) * 3) % 59 < 7;
                    var needleShadow = (x * 19 + y * 7 + (x / 5) * 11) % 71 < 4;
                    if (canopyShadow)
                    {
                        return c;
                    }

                    if (needleShadow)
                    {
                        return c;
                    }

                    return canopyClump < 6 ? b : a;
                case PixelPattern.DistantRockStrata:
                    var strataWarp = y + ((x * 2 + (x / 7) * 5 + (y / 5) * 3) % 11) - 5;
                    var bedding = strataWarp % 9 == 0 || (strataWarp + x / 6) % 17 == 0;
                    var fracture = (x * 13 + y * 7 + (x / 4) * 19) % 61 < 5;
                    var scree = (x * 5 + y * 23 + (y / 3) * 11) % 73 < 6;
                    if (bedding || fracture)
                    {
                        return c;
                    }

                    return scree ? b : a;
                case PixelPattern.DistantNeedleCanopy:
                    var needleLine = (x * 5 + y * 2 + (x / 3) * 11) % 37 < 5;
                    var deepPocket = (x * 7 + y * 17 + (y / 4) * 13) % 67 < 7;
                    var crownTip = (x * 19 + y * 3 + (x / 5) * 7) % 53 < 5;
                    if (deepPocket)
                    {
                        return c;
                    }

                    return needleLine || crownTip ? b : a;
                default:
                    return (x * 13 + y * 7) % 19 < 5 ? b : ((x * 5 + y * 11) % 23 < 4 ? c : a);
            }
        }

        private static Material FlatMaterial(string id, Color color, bool unlit, FastVsHd2dMaterialRole role = FastVsHd2dMaterialRole.SurfaceLit)
        {
            var path = $"{MaterialDirectory}/FastVS_House_{id}.mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            Shader shader;
            var useStage2EmissionSpriteShader = ShouldUseStage2EmissionSpriteShader(id, role, unlit);
            var useSurfaceRampShader = !useStage2EmissionSpriteShader && ShouldUseSurfaceRampShader(id, role, unlit);
            if (useStage2EmissionSpriteShader)
            {
                shader = Shader.Find(SpriteCardRampShaderName) ?? Shader.Find(URPUnlitShaderName);
            }
            else if (useSurfaceRampShader)
            {
                shader = Shader.Find(SurfaceRampLitShaderName);
                if (shader == null)
                {
                    shader = Shader.Find(unlit ? URPUnlitShaderName : URPLitShaderName);
                }
            }
            else
            {
                shader = Shader.Find(unlit ? URPUnlitShaderName : URPLitShaderName);
            }

            if (shader == null)
            {
                throw new InvalidOperationException($"Required shader not found: {id}");
            }

            if (material == null)
            {
                material = new Material(shader);
                AssetDatabase.CreateAsset(material, path);
            }

            material.shader = shader;
            material.doubleSidedGI = true;
            if (material.HasProperty("_BaseColor"))
            {
                material.SetColor("_BaseColor", color);
            }

            if (material.HasProperty("_Color"))
            {
                material.SetColor("_Color", color);
            }

            if (material.HasProperty("_BaseMap"))
            {
                material.SetTexture("_BaseMap", null);
            }

            if (material.HasProperty("_MainTex"))
            {
                material.SetTexture("_MainTex", null);
            }

            if (material.HasProperty("_Cull"))
            {
                material.SetFloat("_Cull", 0f);
            }

            if (useStage2EmissionSpriteShader && string.Equals(shader.name, SpriteCardRampShaderName, StringComparison.Ordinal))
            {
                ConfigureTransparentMaterial(material, Stage2EmissionRenderQueue, SpriteCardRampShaderName, URPUnlitShaderName);
                ApplySpriteCardRampProfile(material);
            }
            else
            {
                ConfigureOpaqueMaterial(material);
            }

            if (useSurfaceRampShader && string.Equals(shader.name, SurfaceRampLitShaderName, StringComparison.Ordinal))
            {
                ApplySurfaceRampProfile(material, id);
            }
            else if (!unlit && ShouldApplyHd2dMatteMaterial(id))
            {
                if (material.HasProperty("_Metallic"))
                {
                    material.SetFloat("_Metallic", 0f);
                }

                if (material.HasProperty("_Smoothness"))
                {
                    material.SetFloat("_Smoothness", 0.16f);
                }

                if (material.HasProperty("_SpecularHighlights"))
                {
                    material.SetFloat("_SpecularHighlights", 0f);
                }
            }

            ApplyMaterialRole(material, id, role);
            return material;
        }

        private static bool ShouldUseStage2EmissionSpriteShader(string id, FastVsHd2dMaterialRole role, bool unlit)
        {
            if (!unlit || role != FastVsHd2dMaterialRole.PortalWindow)
            {
                return false;
            }

            return id == Stage2WindowLightMaterialId ||
                   id == Stage2LibraryWindowLightMaterialId;
        }

        private static bool ShouldUseSurfaceRampShader(string id, FastVsHd2dMaterialRole role, bool unlit)
        {
            if (role != FastVsHd2dMaterialRole.SurfaceLit)
            {
                return false;
            }

            if (IsCurrentInteriorSurfaceReadabilityMaterial(id))
            {
                return false;
            }

            if (!unlit)
            {
                return true;
            }

            return id.StartsWith("bookshelf_front_painted_hd2d_", StringComparison.Ordinal) ||
                   id.StartsWith("current_empty_bookshelf_front_hd2d_", StringComparison.Ordinal);
        }

        private static void ApplySurfaceRampProfile(Material material, string id)
        {
            var exteriorWallProfile = IsExteriorWallSurfaceMaterial(id);
            if (material.HasProperty("_SurfaceRampStrength"))
            {
                material.SetFloat("_SurfaceRampStrength", SurfaceRampStrength);
            }

            if (material.HasProperty("_TopLight"))
            {
                material.SetColor("_TopLight", SurfaceRampTopLight);
            }

            if (material.HasProperty("_SideShade"))
            {
                material.SetColor("_SideShade", exteriorWallProfile ? SurfaceRampExteriorWallSideShade : SurfaceRampSideShade);
            }

            if (material.HasProperty("_FloorShade"))
            {
                material.SetColor("_FloorShade", exteriorWallProfile ? SurfaceRampExteriorWallFloorShade : SurfaceRampFloorShade);
            }

            if (material.HasProperty("_Metallic"))
            {
                material.SetFloat("_Metallic", 0f);
            }

            if (material.HasProperty("_Smoothness"))
            {
                material.SetFloat("_Smoothness", 0.16f);
            }

            if (material.HasProperty("_SpecularHighlights"))
            {
                material.SetFloat("_SpecularHighlights", 0f);
            }

            if (material.HasProperty("_DirectionalLightStrength"))
            {
                material.SetFloat("_DirectionalLightStrength", exteriorWallProfile ? SurfaceRampExteriorWallDirectionalLightStrength : SurfaceRampDirectionalLightStrength);
            }

            if (material.HasProperty("_ShadowReceiveStrength"))
            {
                material.SetFloat("_ShadowReceiveStrength", exteriorWallProfile ? SurfaceRampExteriorWallShadowReceiveStrength : SurfaceRampShadowReceiveStrength);
            }

        }

        private static bool IsExteriorWallSurfaceMaterial(string id)
        {
            return string.Equals(id, "current_exterior_wall", StringComparison.Ordinal) ||
                   string.Equals(id, "past_exterior_wall", StringComparison.Ordinal);
        }

        private static void ApplySpriteCardRampProfile(Material material)
        {
            if (material.HasProperty("_RampStrength"))
            {
                material.SetFloat("_RampStrength", SpriteCardRampStrength);
            }

            if (material.HasProperty("_TopLight"))
            {
                material.SetColor("_TopLight", SpriteCardTopLight);
            }

            if (material.HasProperty("_SideShade"))
            {
                material.SetColor("_SideShade", SpriteCardSideShade);
            }

            if (material.HasProperty("_FloorShade"))
            {
                material.SetColor("_FloorShade", SpriteCardFloorShade);
            }

            if (material.HasProperty("_PaperEdgeStrength"))
            {
                material.SetFloat("_PaperEdgeStrength", SpriteCardPaperEdgeStrength);
            }

            if (material.HasProperty("_PaperRimStrength"))
            {
                material.SetFloat("_PaperRimStrength", SpriteCardPaperRimStrength);
            }

            if (material.HasProperty("_PaperLowerShadeStrength"))
            {
                material.SetFloat("_PaperLowerShadeStrength", SpriteCardPaperLowerShadeStrength);
            }

            if (material.HasProperty("_WorldLightStrength"))
            {
                material.SetFloat("_WorldLightStrength", SpriteCardWorldLightStrength);
            }

            if (material.HasProperty("_WorldShadowReceiveStrength"))
            {
                material.SetFloat("_WorldShadowReceiveStrength", SpriteCardWorldShadowReceiveStrength);
            }

            ApplyStage2EmissionDefaults(material);
        }

        private static bool IsCurrentInteriorSurfaceReadabilityMaterial(string id)
        {
            return id == "current_interior_floor" ||
                   id == "current_interior_wall" ||
                   id == "current_furniture";
        }

        private static Material CreateSpriteCardMaterial(string id, Color tint, int renderQueue)
        {
            var path = $"{MaterialDirectory}/FastVS_House_{id}.mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            var shader = Shader.Find(SpriteCardRampLitShaderName) ?? Shader.Find(SpriteCardRampShaderName) ?? Shader.Find(URPUnlitShaderName);
            if (shader == null)
            {
                throw new InvalidOperationException($"Required sprite card shader not found: {id}");
            }

            if (material == null)
            {
                material = new Material(shader);
                AssetDatabase.CreateAsset(material, path);
            }

            if (string.Equals(shader.name, SpriteCardRampLitShaderName, StringComparison.Ordinal))
            {
                ConfigureSpriteCardCutoutMaterial(material, SpriteCardCutoutRenderQueue);
            }
            else
            {
                ConfigureTransparentMaterial(material, renderQueue, SpriteCardRampShaderName, URPUnlitShaderName);
            }

            material.doubleSidedGI = true;

            if (material.HasProperty("_BaseColor"))
            {
                material.SetColor("_BaseColor", tint);
            }

            if (material.HasProperty("_Color"))
            {
                material.SetColor("_Color", tint);
            }

            if (material.HasProperty("_RampStrength"))
            {
                material.SetFloat("_RampStrength", SpriteCardRampStrength);
            }

            if (material.HasProperty("_TopLight"))
            {
                material.SetColor("_TopLight", SpriteCardTopLight);
            }

            if (material.HasProperty("_SideShade"))
            {
                material.SetColor("_SideShade", SpriteCardSideShade);
            }

            if (material.HasProperty("_FloorShade"))
            {
                material.SetColor("_FloorShade", SpriteCardFloorShade);
            }

            if (material.HasProperty("_PaperEdgeStrength"))
            {
                material.SetFloat("_PaperEdgeStrength", SpriteCardPaperEdgeStrength);
            }

            if (material.HasProperty("_PaperRimStrength"))
            {
                material.SetFloat("_PaperRimStrength", SpriteCardPaperRimStrength);
            }

            if (material.HasProperty("_PaperLowerShadeStrength"))
            {
                material.SetFloat("_PaperLowerShadeStrength", SpriteCardPaperLowerShadeStrength);
            }

            if (material.HasProperty("_WorldLightStrength"))
            {
                material.SetFloat("_WorldLightStrength", SpriteCardWorldLightStrength);
            }

            if (material.HasProperty("_WorldShadowReceiveStrength"))
            {
                material.SetFloat("_WorldShadowReceiveStrength", SpriteCardWorldShadowReceiveStrength);
            }

            ApplyStage2EmissionDefaults(material);
            ApplyMaterialRole(material, id, FastVsHd2dMaterialRole.SpriteCard);
            return material;
        }

        private static void ConfigureSpriteCardCutoutMaterial(Material material, int renderQueue)
        {
            var shader = Shader.Find(SpriteCardRampLitShaderName);
            if (shader == null)
            {
                throw new InvalidOperationException($"Required sprite card cutout shader not found: {SpriteCardRampLitShaderName}");
            }

            material.shader = shader;
            material.doubleSidedGI = true;

            if (material.HasProperty("_Surface"))
            {
                material.SetFloat("_Surface", 0f);
            }

            if (material.HasProperty("_AlphaClip"))
            {
                material.SetFloat("_AlphaClip", 1f);
            }

            if (material.HasProperty("_Cutoff"))
            {
                material.SetFloat("_Cutoff", SpriteCardAlphaCutoff);
            }

            if (material.HasProperty("_Blend"))
            {
                material.SetFloat("_Blend", 0f);
            }

            if (material.HasProperty("_SrcBlend"))
            {
                material.SetFloat("_SrcBlend", 1f);
            }

            if (material.HasProperty("_DstBlend"))
            {
                material.SetFloat("_DstBlend", 0f);
            }

            if (material.HasProperty("_ZWrite"))
            {
                material.SetFloat("_ZWrite", 1f);
            }

            if (material.HasProperty("_Cull"))
            {
                material.SetFloat("_Cull", 0f);
            }

            if (material.HasProperty("_QueueControl"))
            {
                material.SetFloat("_QueueControl", 1f);
            }

            if (material.HasProperty("_QueueOffset"))
            {
                material.SetFloat("_QueueOffset", renderQueue - 2450f);
            }

            material.SetOverrideTag("RenderType", "TransparentCutout");
            material.SetShaderPassEnabled("DepthOnly", false);
            material.SetShaderPassEnabled("SHADOWCASTER", true);
            material.SetShaderPassEnabled("ShadowCaster", true);
            material.DisableKeyword("_SURFACE_TYPE_TRANSPARENT");
            material.EnableKeyword("_ALPHATEST_ON");
            material.renderQueue = renderQueue;
            EditorUtility.SetDirty(material);
        }

        private static void ApplyStage2EmissionDefaults(Material material)
        {
            if (material == null)
            {
                return;
            }

            if (material.HasProperty(Stage2EmissionMapPropertyName))
            {
                material.SetTexture(Stage2EmissionMapPropertyName, null);
            }

            if (material.HasProperty(Stage2EmissionColorPropertyName))
            {
                material.SetColor(Stage2EmissionColorPropertyName, Color.black);
            }

            if (material.HasProperty(Stage2EmissionIntensityPropertyName))
            {
                material.SetFloat(Stage2EmissionIntensityPropertyName, 0f);
            }
        }

        private static void ApplyStage2EmissionProfile(Material material, Texture2D texture)
        {
            if (!TryResolveStage2EmissionProfile(material, out var color, out var intensity))
            {
                return;
            }

            if (!material.HasProperty(Stage2EmissionMapPropertyName) ||
                !material.HasProperty(Stage2EmissionColorPropertyName) ||
                !material.HasProperty(Stage2EmissionIntensityPropertyName))
            {
                return;
            }

            material.SetTexture(Stage2EmissionMapPropertyName, texture);
            material.SetColor(Stage2EmissionColorPropertyName, color);
            material.SetFloat(Stage2EmissionIntensityPropertyName, intensity);
            material.EnableKeyword("_EMISSION");
            EditorUtility.SetDirty(material);
        }

        private static bool TryResolveStage2EmissionProfile(Material material, out Color color, out float intensity)
        {
            color = Color.black;
            intensity = 0f;

            if (material == null)
            {
                return false;
            }

            var assetPath = AssetDatabase.GetAssetPath(material);
            if (string.Equals(assetPath, $"{MaterialDirectory}/FastVS_House_{Stage2WindowLightMaterialId}.mat", StringComparison.Ordinal) ||
                string.Equals(material.name, $"FastVS_House_{Stage2WindowLightMaterialId}", StringComparison.Ordinal))
            {
                color = Stage2WindowLightEmissionColor;
                intensity = Stage2WindowLightEmissionIntensity;
                return true;
            }

            if (string.Equals(assetPath, $"{MaterialDirectory}/FastVS_House_{Stage2LibraryWindowLightMaterialId}.mat", StringComparison.Ordinal) ||
                string.Equals(material.name, $"FastVS_House_{Stage2LibraryWindowLightMaterialId}", StringComparison.Ordinal))
            {
                color = Stage2LibraryWindowLightEmissionColor;
                intensity = Stage2LibraryWindowLightEmissionIntensity;
                return true;
            }

            return false;
        }

        private static void ConfigureOpaqueMaterial(Material material)
        {
            if (material.HasProperty("_Surface"))
            {
                material.SetFloat("_Surface", 0f);
            }

            if (material.HasProperty("_AlphaClip"))
            {
                material.SetFloat("_AlphaClip", 0f);
            }

            if (material.HasProperty("_Blend"))
            {
                material.SetFloat("_Blend", 0f);
            }

            if (material.HasProperty("_SrcBlend"))
            {
                material.SetFloat("_SrcBlend", 1f);
            }

            if (material.HasProperty("_DstBlend"))
            {
                material.SetFloat("_DstBlend", 0f);
            }

            if (material.HasProperty("_ZWrite"))
            {
                material.SetFloat("_ZWrite", 1f);
            }

            if (material.HasProperty("_SrcBlendAlpha"))
            {
                material.SetFloat("_SrcBlendAlpha", 1f);
            }

            if (material.HasProperty("_DstBlendAlpha"))
            {
                material.SetFloat("_DstBlendAlpha", 0f);
            }

            if (material.HasProperty("_QueueOffset"))
            {
                material.SetFloat("_QueueOffset", 0f);
            }

            material.SetOverrideTag("RenderType", "Opaque");
            material.SetShaderPassEnabled("DepthOnly", true);
            material.SetShaderPassEnabled("SHADOWCASTER", true);
            material.DisableKeyword("_SURFACE_TYPE_TRANSPARENT");
            material.renderQueue = -1;
        }

        private static bool ShouldApplyHd2dMatteMaterial(string id)
        {
            return id != "current_frame" &&
                id != "past_frame" &&
                id != "preview_frame" &&
                id != "threshold";
        }

        private static Material ApertureMaterial(string id)
        {
            var path = $"{MaterialDirectory}/FastVS_House_{id}.mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            var shader = Shader.Find("Anemora/Review/PortalApertureOverlay");
            if (shader == null)
            {
                shader = Shader.Find("Universal Render Pipeline/Unlit");
            }

            if (shader == null)
            {
                throw new InvalidOperationException("Portal aperture shader not found.");
            }

            if (material == null)
            {
                material = new Material(shader);
                AssetDatabase.CreateAsset(material, path);
            }

            material.shader = shader;
            if (material.HasProperty("_Color"))
            {
                material.SetColor("_Color", Color.white);
            }

            ApplyMaterialRole(material, id, FastVsHd2dMaterialRole.PortalWindow);
            return material;
        }

        private static void ApplyMaterialRole(Material material, string materialId, FastVsHd2dMaterialRole role)
        {
            var roleToken = role.ToString();
            material.name = $"FastVS_House_{materialId}";
            material.SetOverrideTag(MaterialRoleTagName, roleToken);
            EditorUtility.SetDirty(material);
        }

        private static void SerializedSet(UnityEngine.Object target, string fieldName, object value)
        {
            var serialized = new SerializedObject(target);
            var property = serialized.FindProperty(fieldName);
            if (property == null)
            {
                throw new InvalidOperationException($"Serialized field not found: {target.GetType().Name}.{fieldName}");
            }

            switch (property.propertyType)
            {
                case SerializedPropertyType.ObjectReference:
                    property.objectReferenceValue = value as UnityEngine.Object;
                    break;
                case SerializedPropertyType.Vector2:
                    property.vector2Value = (Vector2)value;
                    break;
                case SerializedPropertyType.Vector3:
                    property.vector3Value = (Vector3)value;
                    break;
                case SerializedPropertyType.Float:
                    property.floatValue = Convert.ToSingle(value);
                    break;
                case SerializedPropertyType.Integer:
                    property.intValue = Convert.ToInt32(value);
                    break;
                case SerializedPropertyType.Boolean:
                    property.boolValue = Convert.ToBoolean(value);
                    break;
                case SerializedPropertyType.String:
                    property.stringValue = value as string;
                    break;
                case SerializedPropertyType.Color:
                    property.colorValue = (Color)value;
                    break;
                case SerializedPropertyType.Enum:
                    property.enumValueIndex = Convert.ToInt32(value);
                    break;
                default:
                    throw new InvalidOperationException($"Unsupported property type for {fieldName}: {property.propertyType}");
            }

            serialized.ApplyModifiedPropertiesWithoutUndo();
        }

        private static void EnsureExternalCharacterAssets()
        {
            if (!File.Exists(AriaNormalLoopStripPath))
            {
                Debug.LogWarning($"Fast VS bundled Aria character asset missing: {AriaNormalLoopStripPath}");
            }
            else
            {
                AssetDatabase.ImportAsset(AriaNormalLoopStripPath, ImportAssetOptions.ForceSynchronousImport);
                EnsureTextureImporter(AriaNormalLoopStripPath);
            }

            EnsurePromotedCharacterAssets();
        }

        private static void EnsurePromotedCharacterAssets()
        {
            foreach (var path in EnumeratePromotedCharacterAssetPaths())
            {
                if (!File.Exists(path))
                {
                    throw new InvalidOperationException($"Fast VS promoted character asset missing: {path}");
                }

                EnsureTextureImporter(path);
            }
        }

        private static IEnumerable<string> EnumeratePromotedCharacterAssetPaths()
        {
            yield return MiaNormalLoopStripPath;
            yield return MiaTalkLoopStripPath;
            yield return MiaNormalToTalkStripPath;
            yield return MiaTalkToNormalStripPath;
            yield return MiaFrontStillPath;
            yield return MiaBackStillPath;
            yield return MiaLeftStillPath;
            yield return MiaRightStillPath;
            yield return KaiaNormalLoopStripPath;
            yield return KaiaTalkLoopStripPath;
            yield return KaiaNormalToTalkStripPath;
            yield return KaiaTalkToNormalStripPath;
            yield return KaiaFrontStillPath;
            yield return KaiaBackStillPath;
            yield return KaiaLeftStillPath;
            yield return KaiaRightStillPath;
            yield return DarioNormalLoopStripPath;
            yield return DarioTalkLoopStripPath;
            yield return DarioNormalToTalkStripPath;
            yield return DarioTalkToNormalStripPath;
            yield return DarioFrontStillPath;
            yield return DarioBackStillPath;
            yield return DarioLeftStillPath;
            yield return DarioRightStillPath;
            yield return KarlaNormalLoopStripPath;
            yield return KarlaTalkLoopStripPath;
            yield return KarlaNormalToTalkStripPath;
            yield return KarlaTalkToNormalStripPath;
            yield return KarlaFrontStillPath;
            yield return KarlaBackStillPath;
            yield return KarlaLeftStillPath;
            yield return KarlaRightStillPath;
            yield return KairoNormalLoopStripPath;
            yield return KairoTalkLoopStripPath;
            yield return KairoNormalToTalkStripPath;
            yield return KairoTalkToNormalStripPath;
            yield return KairoFrontStillPath;
            yield return KairoBackStillPath;
            yield return KairoLeftStillPath;
            yield return KairoRightStillPath;
            yield return LunaNormalLoopStripPath;
            yield return LunaTalkLoopStripPath;
            yield return LunaNormalToTalkStripPath;
            yield return LunaTalkToNormalStripPath;
            yield return LunaFrontStillPath;
            yield return LunaBackStillPath;
            yield return LunaLeftStillPath;
            yield return LunaRightStillPath;

            var variants = new[]
            {
                "generic_adult_male_a",
                "generic_adult_male_b",
                "generic_adult_female_a",
                "generic_adult_female_b",
                "generic_elder_male",
                "generic_elder_female",
                "generic_child_a",
                "generic_child_b"
            };
            var directions = new[] { "front", "back", "left", "right" };
            foreach (var variant in variants)
            {
                foreach (var direction in directions)
                {
                    yield return CharacterDirectory + $"/Generic/Directions/{variant}_{direction}_v59_recovery_64x96_review_only.png";
                    yield return CharacterDirectory + $"/Generic/IdleBreath/{variant}_{direction}_idle_breath_v59_recovery_4f_64x96_review_only.png";
                }

                yield return CharacterDirectory + $"/Generic/Selected/{variant}_v59_recovery_64x96_review_only.png";
            }
        }

        private static void EnsureFolder(string path)
        {
            if (AssetDatabase.IsValidFolder(path))
            {
                return;
            }

            var parts = path.Split('/');
            var current = parts[0];
            for (var index = 1; index < parts.Length; index++)
            {
                var next = $"{current}/{parts[index]}";
                if (!AssetDatabase.IsValidFolder(next))
                {
                    AssetDatabase.CreateFolder(current, parts[index]);
                }

                current = next;
            }
        }

